INSERT INTO topics (id, saga_id, position, slug, title, concept_md, learning_objective, key_vocabulary, prior_knowledge, status) VALUES ('08a1006e-d9fe-4a0c-865a-7c147399dfe9', '3467f69b-7248-4910-aec2-720d49b2db00', '8', 'tipos-maker', '{"en-US": "Market Stall Builders", "es-MX": "Constructores del Puesto", "pt-BR": "Construtores da Barraca"}', 'Construir y calibrar las herramientas del puesto: la ruta del repartidor, la balanza de trueques, la jarra medidora y la máquina registradora.', '{"en-US": "Resolver retos de construcción y medición aplicados al puesto: ordenar instrucciones, leer medidas y balancear cantidades.", "es-MX": "Resolver retos de construcción y medición aplicados al puesto: ordenar instrucciones, leer medidas y balancear cantidades.", "pt-BR": "Resolver retos de construcción y medición aplicados al puesto: ordenar instrucciones, leer medidas y balancear cantidades."}', '["medir", "construir", "balanza"]', 'Conteos y sumas del puesto.', 'published') ON CONFLICT (id) DO NOTHING;
