INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "count-objects", "title": "Conte as moedas do Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Contar de relance quantas moedas caíram do pote virado, sem recontar", "Entender que cada moeda representa um copo de 5 reais vendido", "Relacionar a contagem com a soma em direção à meta de 80 reais"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-count-coins", "xp": 10, "type": "count_objects", "hints": ["Procure apenas as moedas com o símbolo de dinheiro, ignore os biscoitos e o copo.", "Conte baixinho enquanto toca em cada moeda."], "title": "Conte as moedas", "payload": {"scene": [{"icon": "monetization_on", "tint": "primary", "count": 7}, {"icon": "cookie", "tint": "warning", "count": 3}, {"icon": "local_drink", "tint": "accent", "count": 1}], "ask_icon": "monetization_on"}, "narrator": {"emotion": "surprised", "character": "liruf"}, "prompt_md": "Liruf estimou que da jarra sairiam uns 8 copos de limonada. Mas ele derrubou o pote das vendas! As moedas rolaram entre as migalhas de biscoito. Toque em cada moeda para contá-las. Quantas moedas há? Assim saberemos se ele vendeu mais ou menos dos 8 copos que estimou.", "difficulty": 1, "explanation_md": "Há 7 moedas. Liruf estimou ~8 copos, mas só vendeu 7. Cada moeda é um copo de 5 reais. Isso soma 35 reais para o violão de 80!", "audio_segment_id": "s1-count-coins.prompt"}], "schema_version": 1}', '{"s1-count-coins": {"value": 7}}', '{"units": {"s1-count-coins.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ef7cda770278fb1d380d9ab6ac93ba0dae52b74bd3bf0cc50372f423321f6861.mp3", "hash": "d5c863f01619878d77011027fd5e42916ba0c80e519a0a3909aec86b86262a33", "bytes": 34848, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/ef7cda770278fb1d380d9ab6ac93ba0dae52b74bd3bf0cc50372f423321f6861.mp3", "duration_ms": 5760}, "s1-count-coins.hint.1": {"url": "http://localhost:4006/files/lesson-audio/528d8597bd71a78aad265ffd83614a15a7a866a2ae3dd86382d5dbaf040bcf7e.mp3", "hash": "2fe402572a314afe2c9a937a5008bad8ad7f999e0e2c7a2d027a9777101f9be3", "bytes": 19008, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/528d8597bd71a78aad265ffd83614a15a7a866a2ae3dd86382d5dbaf040bcf7e.mp3", "duration_ms": 3120}, "s1-count-coins.prompt": {"url": "http://localhost:4006/files/lesson-audio/a65456c64eb840a0145ecead5b0c223d0be403f23f53da92c7d66cc15fdc772d.mp3", "hash": "76e62a15ee5113e7118c246abe2fbb34503cbcb2b263b13b797944c691e36a31", "bytes": 116496, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/a65456c64eb840a0145ecead5b0c223d0be403f23f53da92c7d66cc15fdc772d.mp3", "duration_ms": 19360}, "s1-count-coins.explanation": {"url": "http://localhost:4006/files/lesson-audio/7f9344fe04d09847d23f6b11cd34f2f13a676f233c30399a05df09902b8f19ff.mp3", "hash": "341f7b293d0ff560f10fc2e608d793cfc28e93172fe8d0aebc51053cebbf5ddc", "bytes": 69408, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/7f9344fe04d09847d23f6b11cd34f2f13a676f233c30399a05df09902b8f19ff.mp3", "duration_ms": 11520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'es-MX', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "fact-opinion", "title": "Hechos vs. Opiniones en el Puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Separar hechos de opiniones en frases del puesto de limonada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 10, "type": "fact_opinion", "hints": ["Un hecho se puede medir o contar, como el precio de un vaso.", "Una opinión es lo que alguien piensa o siente, no se puede comprobar."], "title": "Hecho u Opinión", "payload": {"statements": [{"id": "f1", "text_md": "El vaso de limonada cuesta 5 pesos."}, {"id": "f2", "text_md": "Mi limonada es la más rica del mundo."}, {"id": "f3", "text_md": "Hoy vendí 12 vasos de limonada."}, {"id": "f4", "text_md": "Esta limonada sabe mejor que la de Dina."}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho y Dina están en el puesto de Liruf. Liruf dice: ''¡Mi limonada es la mejor! ¡Cuesta 5 pesos y hoy vendí 12 vasos!'' Pero Rho recuerda que un desconocido también dijo ''esta oferta es increíble'' y resultó ser un engaño. Ayuda a Rho a separar lo que se puede comprobar (hechos) de lo que es solo una opinión. Toca las frases que son hechos.", "difficulty": 1, "explanation_md": "El vaso cuesta 5 pesos es un hecho porque puedes ver el precio. ''La más rica'' es una opinión, no se puede medir. Así como el desconocido exageraba, Liruf también puede estar exagerando.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["f1", "f3"]}}', '{"units": {"s1-fact-opinion.hint.0": {"url": "http://localhost:4006/files/lesson-audio/dfb539bf1cf2b921879dd5fa6ec2535ceb5f57cbaf74034858633103dbe6c200.mp3", "hash": "19f3425d3996e9789da4e5a92e460f9c175dea3cc3910018431516f269b4c912", "bytes": 26208, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/dfb539bf1cf2b921879dd5fa6ec2535ceb5f57cbaf74034858633103dbe6c200.mp3", "duration_ms": 4320}, "s1-fact-opinion.hint.1": {"url": "http://localhost:4006/files/lesson-audio/eb842f26e332e44afde83f4e22aed36c1c415809d33e448fb256040b50d57731.mp3", "hash": "81f14cc56b70a992c9156cc2f276302aa02a99de4755f40ec6424f8ef575c500", "bytes": 29664, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/eb842f26e332e44afde83f4e22aed36c1c415809d33e448fb256040b50d57731.mp3", "duration_ms": 4880}, "s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/ae723e9182da7ddbacade3368e242a14531de62b36d32c62100a1e19c305b2ce.mp3", "hash": "bac389f521f212b6517c6bfd13d485e82096ecdc0c5ca1e4febe1546d32ee099", "bytes": 148176, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/ae723e9182da7ddbacade3368e242a14531de62b36d32c62100a1e19c305b2ce.mp3", "duration_ms": 24640}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/c00801a31a874b9a815d699202c6a1d64e02bfdadc84c69277547526bb257ee8.mp3", "hash": "e03aa2efdc7f2526281180718746901cbce67c6f15116aa1318206c8b99a3e28", "bytes": 79488, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/c00801a31a874b9a815d699202c6a1d64e02bfdadc84c69277547526bb257ee8.mp3", "duration_ms": 13200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "repaso-quiz-mcq", "title": "Revisão: Preço justo e lucro", "locale": "pt-BR", "subject": "mixed", "objectives": ["Revisar com uma pergunta direta o coração do negócio: se o copo custa 5 e os ingredientes 2, qual é o lucro por copo?"], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-por-vaso", "xp": 10, "type": "quiz_mcq", "hints": ["O lucro é o que sobra depois de pagar os ingredientes.", "Subtraia o custo dos ingredientes do preço do copo."], "title": "Lucro por copo", "payload": {"options": [{"id": "a", "text_md": "3 reais", "rationale_md": "Correto: 5 (preço) - 2 (custo) = 3 reais de lucro. Muito bem!"}, {"id": "b", "text_md": "2 reais", "rationale_md": "Essa é a quantia que você gastou em ingredientes, não o que você ganha. O lucro é o preço menos o custo."}, {"id": "c", "text_md": "5 reais", "rationale_md": "Esse é o preço do copo, mas você não considerou que os ingredientes custam dinheiro. O lucro é o que sobra depois de pagá-los."}, {"id": "d", "text_md": "7 reais", "rationale_md": "Você somou o preço e o custo, mas o lucro é calculado subtraindo, não somando."}], "shuffle": true}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Ontem você montou a barraca com a Dina: colocou preço em cada copo (5 reais) e calculou que os ingredientes custam 2 reais por copo. Hoje você vendeu seu primeiro copo. Dina diz: «Parabéns! Você vendeu um copo. Agora, quanto dinheiro você GANHOU de verdade? Lembre-se de que os ingredientes não são grátis…» Quanto dinheiro sobra depois de pagar os ingredientes desse copo?", "difficulty": 1, "explanation_md": "Você ganhou 3 reais: vendeu o copo por 5 reais, mas os ingredientes custaram 2 reais, então sobram 3 reais. Esse é o seu lucro! Com esses 3 reais você poderá comprar mais limões amanhã.", "audio_segment_id": "s1-ganancia-por-vaso.prompt"}], "schema_version": 1}', '{"s1-ganancia-por-vaso": {"correct_option_id": "a"}}', '{"units": {"s1-ganancia-por-vaso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/bac911bfa53e78e8dbe666aabdff8f99c8b8c1a8078a570b2d27b87ed8cf709a.mp3", "hash": "691b73329038b85e0fac7c0b5fc558b6342cbb6fc64b53721bb8de311dac8869", "bytes": 22896, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/bac911bfa53e78e8dbe666aabdff8f99c8b8c1a8078a570b2d27b87ed8cf709a.mp3", "duration_ms": 3760}, "s1-ganancia-por-vaso.hint.1": {"url": "http://localhost:4006/files/lesson-audio/60fb324f808b01d56d27f024a7636f47edbb850f83769d3371dbf7ea5d2c8f78.mp3", "hash": "f1e6f23316f7979bc177667229884af29fe4de510743abbb18dcb69df3ed448e", "bytes": 21888, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/60fb324f808b01d56d27f024a7636f47edbb850f83769d3371dbf7ea5d2c8f78.mp3", "duration_ms": 3600}, "s1-ganancia-por-vaso.prompt": {"url": "http://localhost:4006/files/lesson-audio/14699d64feb959db3949bd8aec33c54e01eb25d352e4bdf6d0c52e1db6df4856.mp3", "hash": "fa947b4f0d8539030c9e60fdca43b5262b496e83ddd603c45fb5d2239105a90c", "bytes": 153504, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/14699d64feb959db3949bd8aec33c54e01eb25d352e4bdf6d0c52e1db6df4856.mp3", "duration_ms": 25520}, "s1-ganancia-por-vaso.choices": {"url": "http://localhost:4006/files/lesson-audio/c4cbc35b6418bcb30872bd928bf3561ad5df051c3b2d2532b272f1568c93cfd9.mp3", "hash": "dfb1208f38f404cd4ac0d655bd0ad063ee622e1fc84b83621cf648dfd46f84ff", "bytes": 35856, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c4cbc35b6418bcb30872bd928bf3561ad5df051c3b2d2532b272f1568c93cfd9.mp3", "duration_ms": 5920}, "s1-ganancia-por-vaso.explanation": {"url": "http://localhost:4006/files/lesson-audio/88aa849e2ce3007c4708b9f3d87e59265c0b0adc5adadc5e89d2193726dd4115.mp3", "hash": "5e66e7b3388ad5c034e94c786df86b7a619f908e10306149e73b94a2acf62779", "bytes": 92016, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/88aa849e2ce3007c4708b9f3d87e59265c0b0adc5adadc5e89d2193726dd4115.mp3", "duration_ms": 15280}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-dinero", "title": "Cerrar la caja del domingo", "locale": "es-MX", "subject": "mixed", "objectives": ["Contar monedas de 1, 5 y 10 para saber el total de ventas del día.", "Calcular el cambio correcto al pagar con billete de 20 un vaso de 5 pesos.", "Determinar cuántos domingos más se necesita ahorrar 20 pesos para llegar a 80."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-contar-monedas", "xp": 10, "type": "coin_count", "hints": ["Empieza con las monedas de 10, luego las de 5 y al final las de 1."], "title": "Cerrar la caja", "payload": {"target": 20, "currency": "MXN", "denominations": [1, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¿Recuerdas a los dos clientes de ayer? Hoy volvieron y pagaron con estas monedas. Dina está preocupada: si no juntan 20 pesos, no podrán comprar las tazas para el domingo. Ayúdala a contar las monedas. Toca cada moneda para sumarlas.", "difficulty": 1, "explanation_md": "Las monedas suman 20 pesos: una de 10, dos de 5 y cinco de 1. ¡Justo lo que necesitaban para las tazas! Dina sonríe aliviada.", "audio_segment_id": "s1-contar-monedas.prompt"}, {"id": "s2-cambio-cliente", "xp": 10, "type": "make_change", "hints": ["Si pagó con 20 y el vaso cuesta 5, ¿cuánto te sobra?"], "title": "Dar cambio", "payload": {"price": 5, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "La clienta de ayer regresa y pide un vaso de 5 pesos. Paga con un billete de 20. Dina está nerviosa: si le das mal el cambio, la clienta se enojará y no volverá. ¿Cuánto cambio le tienes que dar?", "difficulty": 1, "explanation_md": "El cambio es 15 pesos: 20 menos 5 es 15. La clienta sonríe y dice que volverá el domingo. ¡Bien hecho!", "audio_segment_id": "s2-cambio-cliente.prompt"}, {"id": "s3-ahorro-guitarra", "xp": 15, "type": "savings_goal", "hints": ["Primero calcula cuánto le falta: 80 menos 40 son 40.", "Luego divide lo que falta entre lo que ahorra cada domingo: 40 entre 20."], "title": "¿Cuántos domingos faltan?", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [20]}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "Liruf quiere comprar una guitarra de 80 pesos. Ya tiene 40 en su alcancía. Cada domingo gana 20 pesos vendiendo limonada. Dina le dice: ''Si ahorras todo, ¿cuántos domingos más necesitas para la guitarra?'' Ayuda a Liruf a averiguarlo.", "difficulty": 2, "explanation_md": "Le faltan 40 pesos y cada domingo ahorra 20, así que necesita 2 domingos más. ¡Liruf estará tocando la guitarra muy pronto!", "audio_segment_id": "s3-ahorro-guitarra.prompt"}], "schema_version": 1}', '{"s1-contar-monedas": {}, "s2-cambio-cliente": {}, "s3-ahorro-guitarra": {"correct": {"20": 4}}}', '{"units": {"s1-contar-monedas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/539ff5996ce686741922fb7d314337d5f6d604d7604edd39969112ae161ec271.mp3", "hash": "cfb2c018a27ec5a7bec4b9c3f888ae51bc05e0f35c6970628f39bfcba1424bfa", "bytes": 28656, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/539ff5996ce686741922fb7d314337d5f6d604d7604edd39969112ae161ec271.mp3", "duration_ms": 4720}, "s1-contar-monedas.prompt": {"url": "http://localhost:4006/files/lesson-audio/50839e91d7d1fe6efa12e5cf3c33801533265f185376a2bb8e40a34b1b093166.mp3", "hash": "375f6050e5dc884ae93109851e95b49a5eb9e036a1f5a34c1cc61a74d701d0b5", "bytes": 91584, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/50839e91d7d1fe6efa12e5cf3c33801533265f185376a2bb8e40a34b1b093166.mp3", "duration_ms": 15200}, "s2-cambio-cliente.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f0e3eb54011f7b5e3f3224581bb4844899f3600831eadee8dc1f259343db3037.mp3", "hash": "b52f73d83dbba437887d8f0536140cf7d4e51c14a71f2aa6a933a2b9f223fe20", "bytes": 29088, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f0e3eb54011f7b5e3f3224581bb4844899f3600831eadee8dc1f259343db3037.mp3", "duration_ms": 4800}, "s2-cambio-cliente.prompt": {"url": "http://localhost:4006/files/lesson-audio/2ea17f7eb5d22f16699992c42c797a8899cefae5ef5e5a3fb450161139ea2efe.mp3", "hash": "42f21ea1d71e03748a2101fec556d03be86e5a12b10be99af1deb07ab108d839", "bytes": 82944, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2ea17f7eb5d22f16699992c42c797a8899cefae5ef5e5a3fb450161139ea2efe.mp3", "duration_ms": 13760}, "s3-ahorro-guitarra.hint.0": {"url": "http://localhost:4006/files/lesson-audio/020b80180fbeef98f55923385da78d4415555763110aca296a6e6ce54a204362.mp3", "hash": "ea81b72b363625b29a1dd38b704ff6e062df9c7da30159bed8463d3d3bbb97d6", "bytes": 27648, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/020b80180fbeef98f55923385da78d4415555763110aca296a6e6ce54a204362.mp3", "duration_ms": 4560}, "s3-ahorro-guitarra.hint.1": {"url": "http://localhost:4006/files/lesson-audio/1db016037cabda4386bf89ad8c3c48b72b6e26e68f81a98b58435fcd7af37fe2.mp3", "hash": "b85377acf9b710c5385bb753824ad226a90a07d0c8e884bcc058e13e8eaffa7e", "bytes": 33408, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/1db016037cabda4386bf89ad8c3c48b72b6e26e68f81a98b58435fcd7af37fe2.mp3", "duration_ms": 5520}, "s3-ahorro-guitarra.prompt": {"url": "http://localhost:4006/files/lesson-audio/27e300e820aa6a3bfdf09d0c003338438a27234e9ef6760bef5004ed891cc9ed.mp3", "hash": "8bb2f38ece7388f60742c30b2b671351dce801c7b240771c462d82f4b6f8ae84", "bytes": 105984, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/27e300e820aa6a3bfdf09d0c003338438a27234e9ef6760bef5004ed891cc9ed.mp3", "duration_ms": 17600}, "s1-contar-monedas.explanation": {"url": "http://localhost:4006/files/lesson-audio/bbf2d24ef8538e53ffbfdd17be36b2934a5ee3f338fdba9578d4c38ac0f3f594.mp3", "hash": "3f268c7f555ae2b1078cc8abef74d76b6dcddb5c1305a437b2f1425a2301e389", "bytes": 61776, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/bbf2d24ef8538e53ffbfdd17be36b2934a5ee3f338fdba9578d4c38ac0f3f594.mp3", "duration_ms": 10240}, "s2-cambio-cliente.explanation": {"url": "http://localhost:4006/files/lesson-audio/3f03d1e9bb78abc12e473f9e1462406ed02b828314a67bcb6f2678647dc918ef.mp3", "hash": "8f15055b65969ae6a955c7f7413733d44c19d8a1aabed416f18e5696eb3c43fc", "bytes": 51696, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3f03d1e9bb78abc12e473f9e1462406ed02b828314a67bcb6f2678647dc918ef.mp3", "duration_ms": 8560}, "s3-ahorro-guitarra.explanation": {"url": "http://localhost:4006/files/lesson-audio/90e38d34ccb3efd7c039db7630bc3fb7b23f7de8e573cd11d86522aa2830a971.mp3", "hash": "089d06f31551d2642528fd0d6dd9261e3427eab487a6c04e864323eafd9cfb6e", "bytes": 54576, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/90e38d34ccb3efd7c039db7630bc3fb7b23f7de8e573cd11d86522aa2830a971.mp3", "duration_ms": 9040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'en-US', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "story-branch", "title": "The Fair Price", "locale": "en-US", "subject": "mixed", "objectives": ["Choosing the price of lemonade considering the cost per cup and the savings goal", "Observing how each price decision affects sales and progress toward the guitar"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-limonada", "xp": 20, "type": "story_branch", "hints": ["Think: if the price is too low, you earn little per cup. If it''s too high, maybe no one will buy.", "Remember that each cup costs 2 pesos. What you actually earn is the price minus those 2 pesos."], "title": "Choose today''s price", "payload": {"nodes": [{"id": "inicio", "choices": [{"id": "precio5", "next": "final5", "text_md": "5 pesos (the usual price)"}, {"id": "precio3", "next": "final3", "text_md": "3 pesos (cheaper)"}, {"id": "precio10", "next": "final10", "text_md": "10 pesos (double)"}], "emotion": "thinking", "text_md": "It''s super hot! Here come 6 thirsty neighbors. What price should I sell each cup for?", "character": "liruf"}, {"id": "final5", "choices": [{"id": "fin5", "next": null, "text_md": "End"}], "emotion": "happy", "text_md": "All 6 buy! Each cup gives you 3 pesos profit (5 - 2 = 3). That''s 6 × 3 = 18 pesos. Great progress toward the guitar!", "character": "liruf"}, {"id": "final3", "choices": [{"id": "fin3", "next": null, "text_md": "End"}], "emotion": "surprised", "text_md": "They sell out fast, but you only earn 1 peso per cup (3 - 2 = 1). That''s 6 × 1 = 6 pesos. Barely any progress toward the guitar...", "character": "liruf"}, {"id": "final10", "choices": [{"id": "fin10", "next": null, "text_md": "End"}], "emotion": "neutral", "text_md": "The neighbors make a face and go get ice cream. You''re left with a full pitcher and 0 pesos. The guitar seems far away...", "character": "liruf"}], "start_node": "inicio"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf has already separated facts from opinions at his stand. Now comes the hard part: **deciding the price of TODAY''S lemonade**. Each cup costs **2 pesos** to make. His goal is to save **80 pesos** for a guitar. What price do you set?", "difficulty": 2, "explanation_md": "The price decision changes how much you progress toward the 80-peso guitar. At 5 pesos per cup, all 6 neighbors buy and you earn 3 pesos per cup, 18 pesos total! At 3 pesos, they also all buy but you only earn 1 peso per cup, just 6 pesos. At 10 pesos, no one buys and you earn nothing.", "audio_segment_id": "s1-precio-limonada.prompt"}], "schema_version": 1}', '{"s1-precio-limonada": {"qualities": [{"score": 100, "node_id": "inicio", "choice_id": "precio5"}, {"score": 30, "node_id": "inicio", "choice_id": "precio3"}, {"score": 0, "node_id": "inicio", "choice_id": "precio10"}]}}', '{"units": {"s1-precio-limonada.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c779b400f5cb50d22ffe5bd4c2f14f76cd75960d680534cfd267231ad7a5d0cf.mp3", "hash": "a730a4f35bf73634a18726371c2a13a1e225e0669277fa21ff30963b7af0aef6", "bytes": 37296, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/c779b400f5cb50d22ffe5bd4c2f14f76cd75960d680534cfd267231ad7a5d0cf.mp3", "duration_ms": 6160}, "s1-precio-limonada.hint.1": {"url": "http://localhost:4006/files/lesson-audio/88d35e5dea3a537d40427170be9c412ba8eaa74a30b21baa96aa2c9feb0323b6.mp3", "hash": "020799aef48d91e7446d67745fbb7f97021a9141843240a8ba44b8db603cb082", "bytes": 38736, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/88d35e5dea3a537d40427170be9c412ba8eaa74a30b21baa96aa2c9feb0323b6.mp3", "duration_ms": 6400}, "s1-precio-limonada.prompt": {"url": "http://localhost:4006/files/lesson-audio/5a4deacf818497f923a8d98aa0ac671d2233b7aee20dee37b7a30a4125a697aa.mp3", "hash": "d568485cca9a97a9f9b5eee2f3f3b00dc7b78203a44eddc1c3e00c1eb9016928", "bytes": 85824, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/5a4deacf818497f923a8d98aa0ac671d2233b7aee20dee37b7a30a4125a697aa.mp3", "duration_ms": 14240}, "s1-precio-limonada.explanation": {"url": "http://localhost:4006/files/lesson-audio/6d77066a7ba567ba734ea5779c6b7dc0afac294051e13434565a40d44909589b.mp3", "hash": "8709d99770b7f3ea0c7d719c2cdb76241fb98e321090d377a294995f7bbf32a7", "bytes": 117504, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/6d77066a7ba567ba734ea5779c6b7dc0afac294051e13434565a40d44909589b.mp3", "duration_ms": 19520}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "dialogue-choice", "title": "Você me deixa por 3?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher uma resposta gentil, mas firme, diante de um cliente que pede desconto, sem abrir mão do lucro."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-negocia-cliente", "xp": 15, "type": "dialogue_choice", "hints": ["Pense: se você baixar muito o preço, quanto você ganha por copo?", "O cliente vai embora feliz se você oferecer algo justo, mas sem perder dinheiro."], "title": "O cliente pede desconto", "payload": {"turns": [{"id": "t1", "npc_md": "—Olá, Liruf. Você me vende um copo de limonada? Mas… você me deixa por 3 reais?", "replies": [{"id": "r1", "text_md": "—Claro, leve por 3 reais."}, {"id": "r2", "text_md": "—Desculpe, o preço é 5 reais. Mas posso te oferecer um copo menor por 4 reais."}, {"id": "r3", "text_md": "—Não, o preço é 5 reais, nem um real a menos."}]}, {"id": "t2", "npc_md": "O cliente pensa um momento e responde:", "replies": [{"id": "r4", "text_md": "—Está bem, levo o copo de 4 reais. Obrigado!"}, {"id": "r5", "text_md": "—Não, obrigado, é muito caro. Vou embora."}, {"id": "r6", "text_md": "—Está bem, levo o copo de 4 reais. Obrigado!"}]}], "persona": {"name": "Liruf", "role_md": "dono da barraca de limonada", "character": "liruf"}, "opening_md": "Você está na sua barraca. Um cliente sorri e diz:"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf está atendendo sua barraca de limonada. Um cliente se aproxima e diz:", "difficulty": 2, "explanation_md": "Liruf ofereceu um copo a 5 reais. Se ele deixar por 3, ganha só 3 reais, mas se oferecer por 4, o cliente economiza 1 real e Liruf ainda ganha 4. Todos ganham!", "audio_segment_id": "s1-negocia-cliente.prompt"}], "schema_version": 1}', '{"s1-negocia-cliente": {"turns": [{"turn_id": "t1", "qualities": {"r1": 20, "r2": 90, "r3": 30}, "reactions": {"r1": "El cliente se va feliz, pero Liruf ganó solo 3 pesos. Perdió 2 pesos de ganancia.", "r2": "El cliente duda, pero acepta la oferta. ¡Buen trato!", "r3": "El cliente se ofende y se va sin comprar. Liruf no vende nada."}}, {"turn_id": "t2", "qualities": {"r4": 100, "r5": 0, "r6": 100}, "reactions": {"r4": "¡Vendiste un vaso! Ganaste 4 pesos y el cliente se fue contento.", "r5": "El cliente se fue. No hubo venta. Tal vez otra oferta funcione mejor.", "r6": "¡Vendiste un vaso! Ganaste 4 pesos y el cliente se fue contento."}}]}}', '{"units": {"s1-negocia-cliente.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e25a7b1742f1dbe324d29f1b16a8a8e6d9d7e5c8f4bb01287e6cca17ba69ad2f.mp3", "hash": "46c6177f491b49f05e9dc3b5d99abc9b4f6bbab68711649f9c8ab1fba939a4d6", "bytes": 30528, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e25a7b1742f1dbe324d29f1b16a8a8e6d9d7e5c8f4bb01287e6cca17ba69ad2f.mp3", "duration_ms": 5040}, "s1-negocia-cliente.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5764a4b9b65713c83e9322a8ea4ea11dbea22302868c90023449fcb6e71b91ad.mp3", "hash": "717d8600cc6f1762aec9fe8d62a0f192bd3e70b432671ba4707de8741516feb1", "bytes": 37728, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5764a4b9b65713c83e9322a8ea4ea11dbea22302868c90023449fcb6e71b91ad.mp3", "duration_ms": 6240}, "s1-negocia-cliente.prompt": {"url": "http://localhost:4006/files/lesson-audio/cf5bb23d35795ba82ae6f5d49db39a8f5bbcc0a568f49d11baef6613f0d86750.mp3", "hash": "a4b7cc253559f3ee185111059fbe376d21a9cb0f96e1beb5a18b7a0e71c3f235", "bytes": 36288, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/cf5bb23d35795ba82ae6f5d49db39a8f5bbcc0a568f49d11baef6613f0d86750.mp3", "duration_ms": 6000}, "s1-negocia-cliente.explanation": {"url": "http://localhost:4006/files/lesson-audio/162fb15e4fc6ce7375257db780394421adb3edf59b1d6d8f0b4421370db9ac7c.mp3", "hash": "39e06e791c3146bcfabe6682803f77b82ac61de61d5fd7c07a874cadc7e4252d", "bytes": 87264, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/162fb15e4fc6ce7375257db780394421adb3edf59b1d6d8f0b4421370db9ac7c.mp3", "duration_ms": 14480}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'en-US', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "combo-narrativa-choice", "title": "A Saturday at the stand", "locale": "en-US", "subject": "money", "objectives": ["Deciding the price of lemonade in a realistic situation with customers and change"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-apertura", "xp": 0, "type": "story_scene", "hints": [], "title": "Here come the customers!", "payload": {"art": {"icon": "storefront", "tint": "primary"}, "action": "idle", "body_md": "The sun is shining. Liruf has the lemons ready, the sugar, and the cups. But… he hasn''t put up the sign with the price! Customers are asking: ''How much is a cup?'' Liruf needs to decide quickly. Just like the tip machine doubled the coins, here Liruf can double his money if he sets the right price.", "emotion": "thinking", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "It''s Saturday morning. Liruf opens his lemonade stand. There''s already a line of customers waiting. A cup costs 5 pesos, but Liruf hasn''t set the price for the day. What price should he set?", "difficulty": 1, "explanation_md": "Liruf remembers that each cup costs 5 pesos to make. Just like the tip machine doubled the coins, here Liruf can double his money if he sets a price higher than 5 pesos.", "audio_segment_id": "s1-apertura.prompt"}, {"id": "s2-decision-precio", "xp": 10, "type": "quiz_mcq", "hints": ["Think: if the cup costs 5 pesos, the price must be higher to earn something.", "If you set 5 pesos, you only recover what you spent, you don''t earn anything."], "title": "Choose the price", "payload": {"options": [{"id": "a", "text_md": "3 pesos", "rationale_md": "3 pesos is less than what it costs to make the cup. Liruf would lose money!"}, {"id": "b", "text_md": "5 pesos", "rationale_md": "5 pesos is exactly what it costs to make, but he earns nothing. That''s not good business."}, {"id": "c", "text_md": "7 pesos", "rationale_md": "7 pesos is more than 5, so Liruf earns 2 pesos per cup. Good profit!"}, {"id": "d", "text_md": "10 pesos", "rationale_md": "10 pesos is much more expensive. Maybe customers won''t want to pay that much and will leave."}], "shuffle": true}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf knows each cup costs him 5 pesos to make. What price should he put on the sign to make money? Look at this example: if Liruf sells a cup for 7 pesos, he spends 5 pesos, so he earns 2 pesos. That''s profit!", "difficulty": 1, "explanation_md": "Liruf needs to make money, so the price must be higher than 5 pesos. 7 pesos is a good option: he earns 2 pesos per cup. If you had chosen 3 pesos, you''d lose money. If 5 pesos, you earn nothing. If 10 pesos, maybe customers won''t buy.", "audio_segment_id": "s2-decision-precio.prompt"}], "schema_version": 1}', '{"s2-decision-precio": {"correct_option_id": "c"}}', '{"units": {"s1-apertura.body": {"url": "http://localhost:4006/files/lesson-audio/605087fc67bd56578546ed78f93425ea3d854611a8ab47fa536815b2083ccd83.mp3", "hash": "48ff79a6a2d313c9a828380c3af4f1b17c9a05ed7997233907bafd3b2644b1b2", "bytes": 106416, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/605087fc67bd56578546ed78f93425ea3d854611a8ab47fa536815b2083ccd83.mp3", "duration_ms": 17680}, "s1-apertura.prompt": {"url": "http://localhost:4006/files/lesson-audio/f4bb4fa2be8f8e91e8181ec8dc814c42481b5f356f253f7b6032ba448831411e.mp3", "hash": "5fddc41f5a394c5f5310608660b7a6da6e308971e33d7986b014535ad6ecec41", "bytes": 68544, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f4bb4fa2be8f8e91e8181ec8dc814c42481b5f356f253f7b6032ba448831411e.mp3", "duration_ms": 11360}, "s1-apertura.explanation": {"url": "http://localhost:4006/files/lesson-audio/3bc33dd049d5d8d1910bf82ee7d5f63878c0d030bd32d75e804dff5f3f77e296.mp3", "hash": "4ff462d9cbde1bc59664bb33c3419e118418a9b23725618fb76729d7f0deed82", "bytes": 57024, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3bc33dd049d5d8d1910bf82ee7d5f63878c0d030bd32d75e804dff5f3f77e296.mp3", "duration_ms": 9440}, "s2-decision-precio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5ae7baf51e1c7a72237ef7e05869c031dc0d1cd7bafa1302ea9be92e8706dc20.mp3", "hash": "98ee637ee1544152fa46a35d7f7f7a1f0d7419bc021d8b59060995f52d9fa787", "bytes": 28656, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5ae7baf51e1c7a72237ef7e05869c031dc0d1cd7bafa1302ea9be92e8706dc20.mp3", "duration_ms": 4720}, "s2-decision-precio.hint.1": {"url": "http://localhost:4006/files/lesson-audio/4683c3f38c58245292a19ecaa049c82a395d496060a93ae3cdaef56dceea2013.mp3", "hash": "2f3ea8b86f5b2c3a0f30e397e34b5ed39bdf5b7aeb2a68a89dce5027b7f25df0", "bytes": 28224, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4683c3f38c58245292a19ecaa049c82a395d496060a93ae3cdaef56dceea2013.mp3", "duration_ms": 4640}, "s2-decision-precio.prompt": {"url": "http://localhost:4006/files/lesson-audio/0c43cbee033dbec61382b87dde4cbadfdad99431ba29e71bf0d55a75add2ba95.mp3", "hash": "c5758b9bff90abe622eb483b9b11ea23143419515f055b5511eaf003ce195607", "bytes": 78624, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0c43cbee033dbec61382b87dde4cbadfdad99431ba29e71bf0d55a75add2ba95.mp3", "duration_ms": 13040}, "s2-decision-precio.choices": {"url": "http://localhost:4006/files/lesson-audio/1103899c0a020f1b0e42039a6aee034965c09e1f891772d0c69db91f52032305.mp3", "hash": "c69ce389155514b3cc7f86b2acfe844782db147c7e0c6d9a062cf87e862b3fc0", "bytes": 28656, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1103899c0a020f1b0e42039a6aee034965c09e1f891772d0c69db91f52032305.mp3", "duration_ms": 4720}, "s2-decision-precio.explanation": {"url": "http://localhost:4006/files/lesson-audio/ff27108ab5c96d41c8f04f5bd51d3d83beb597b517ecb8397890f26809cc12ac.mp3", "hash": "c6e3642d569b9d90b2e4b09949534d6c69be1342c69d2ccacc453c4ee982cb17", "bytes": 88704, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ff27108ab5c96d41c8f04f5bd51d3d83beb597b517ecb8397890f26809cc12ac.mp3", "duration_ms": 14720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "timeline-order", "title": "Order the sale day", "locale": "en-US", "subject": "mixed", "objectives": ["Order the steps of the sale day in chronological order"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline", "xp": 10, "type": "timeline_order", "hints": ["Think: what do you do before preparing the lemonade?", "What do you do at the end of the day with the money?"], "title": "Liruf''s first day", "payload": {"events": [{"id": "comprar", "icon": "shopping_cart", "text_md": "Buy ingredients in the morning"}, {"id": "preparar", "icon": "blender", "text_md": "Prepare the lemonade"}, {"id": "vender", "icon": "storefront", "text_md": "Sell lemonade at noon"}, {"id": "contar", "icon": "savings", "text_md": "Count the money and put it away at closing"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "After hanging his sign ''Cold lemonade for 5 pesos'', Liruf gets ready for his first full day. Touch the photos in the correct order: what happened first, second, third, and fourth? If you order them wrong, customers get confused and you don''t sell!", "difficulty": 1, "explanation_md": "First you buy the ingredients, then you prepare the lemonade, then you sell it at noon, and finally you count the money and put it away. That way Liruf doesn''t get confused and sells all his lemonade!", "audio_segment_id": "s1-timeline.prompt"}], "schema_version": 1}', '{"s1-timeline": {"order": ["comprar", "preparar", "vender", "contar"]}}', '{"units": {"s1-timeline.hint.0": {"url": "http://localhost:4006/files/lesson-audio/019bab561311f76ec3e7b8dfc8e57aff533b817d5223e0002d1414e22e761091.mp3", "hash": "09b7b581f88c9cfecd48f17cb3d6d6c5cb5bed9bbaecbb4253178febba224403", "bytes": 18144, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/019bab561311f76ec3e7b8dfc8e57aff533b817d5223e0002d1414e22e761091.mp3", "duration_ms": 2960}, "s1-timeline.hint.1": {"url": "http://localhost:4006/files/lesson-audio/00b3613d2276725c7798932af3749e7c5cb6fcd29cada575452060ee7ceb44bd.mp3", "hash": "41574dc2dc3ec710b5f9233753575a2b396e5320a40f0ee2819e37a328e0b5d5", "bytes": 16128, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/00b3613d2276725c7798932af3749e7c5cb6fcd29cada575452060ee7ceb44bd.mp3", "duration_ms": 2640}, "s1-timeline.prompt": {"url": "http://localhost:4006/files/lesson-audio/880020c171279c5fc3ed6f9809d685bd8bf97dbe67328e91eed072b2b37c92a5.mp3", "hash": "74b903826b937592f023cbca503d01589c0fd476d05215c5599f2bdb486b6099", "bytes": 85248, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/880020c171279c5fc3ed6f9809d685bd8bf97dbe67328e91eed072b2b37c92a5.mp3", "duration_ms": 14160}, "s1-timeline.explanation": {"url": "http://localhost:4006/files/lesson-audio/bc2cdccf9fc113cd393559c0a51f1c9aad4d5a161e82277929384195049f2bd0.mp3", "hash": "983ad9e50841de0f65de9fd3b6937fc3a9416036325beb846ad0333565d79732", "bytes": 70416, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/bc2cdccf9fc113cd393559c0a51f1c9aad4d5a161e82277929384195049f2bd0.mp3", "duration_ms": 11680}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "concept-reveal", "title": "Costo y ganancia", "locale": "es-MX", "subject": "mixed", "objectives": ["Identificar que el costo es lo que gastas para hacer el producto", "Identificar que la ganancia es lo que te queda después de pagar el costo"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": [], "title": "Costo y ganancia", "payload": {"cards": [{"icon": "receipt_long", "back_md": "Lo que gastas para hacer el producto: limones, azúcar, vasos.", "front_md": "Costo"}, {"icon": "savings", "back_md": "Lo que te queda después de restar el costo de lo que vendiste.", "front_md": "Ganancia"}]}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Liruf quiere ahorrar para una patineta de 80 pesos. Vendió 10 vasos de limonada a 5 pesos cada uno. Gastó 2 pesos en limones y azúcar por cada vaso. ¿Puede comprar la patineta con lo que le queda?", "difficulty": 1, "explanation_md": "Liruf ganó 50 pesos por vender 10 vasos. Pero gastó 20 pesos en limones y azúcar (costo). Lo que le queda es la ganancia: 50 - 20 = 30 pesos. ¡Aún le faltan 50 pesos para la patineta!", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/d6ebf7b723f6a0f22aafabc0e420b8017010c7aa84d6666c24e62e0c4330fd69.mp3", "hash": "05bae16abf60545f13d9653050e52854668c31deaa27fcf9d5fe1d5e29b6e4e7", "bytes": 76176, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/d6ebf7b723f6a0f22aafabc0e420b8017010c7aa84d6666c24e62e0c4330fd69.mp3", "duration_ms": 12640}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/62126306412cab08697e68d9308cec49642b0e89eb0067b66d7d491230dd6c49.mp3", "hash": "a7af8080450732ee83038f3b4ed522423f9bd8696101dcf8c0183bdfed0d7691", "bytes": 25776, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/62126306412cab08697e68d9308cec49642b0e89eb0067b66d7d491230dd6c49.mp3", "duration_ms": 4240}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/c05c6e90c6a4a000d40ca1e430a620f08ca00d35635e9565cb45a076f0487d5d.mp3", "hash": "7637491e3df743fc580028bcdff2d19429a5931125426783ca61efdc316ab074", "bytes": 20016, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/c05c6e90c6a4a000d40ca1e430a620f08ca00d35635e9565cb45a076f0487d5d.mp3", "duration_ms": 3280}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/ec217bba9bb05b7110874ffd449ff5be050999f26ceb9e0d8b7b37d1ad420c68.mp3", "hash": "472bb0b75861c95896a690abe1dd9aae0497813c601e18214088c68babc7f83a", "bytes": 83376, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/ec217bba9bb05b7110874ffd449ff5be050999f26ceb9e0d8b7b37d1ad420c68.mp3", "duration_ms": 13840}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'pt-BR', '1', '{"meta": {"cast": ["rho"], "slug": "odd-one-out", "title": "O ingrediente estranho", "locale": "pt-BR", "subject": "mixed", "objectives": ["Identificar quais itens não são ingredientes da limonada para distinguir gastos reais de produção."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-ingredient", "xp": 10, "type": "odd_one_out", "hints": ["Pense no que você precisa para fazer limonada: limões, água, açúcar... mais alguma coisa?", "Se não se come nem se bebe, provavelmente não é um ingrediente."], "title": "O que não vai na limonada?", "payload": {"items": [{"id": "item-limones", "text_md": "Limões ($3)"}, {"id": "item-azucar", "text_md": "Açúcar ($2)"}, {"id": "item-agua", "text_md": "Água ($1)"}, {"id": "item-pelota", "text_md": "Bola ($5)"}], "reasons": [{"id": "reason-ingrediente", "text_md": "Sim, é um ingrediente da limonada."}, {"id": "reason-no-ingrediente", "text_md": "Não é um ingrediente da limonada."}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho tem $10 guardados no cofrinho para comprar ingredientes. Na lista ele escreveu: limões ($3), açúcar ($2), água ($1) e uma bola ($5). Mas a bola não é um ingrediente. Qual destes ele NÃO deve comprar com o dinheiro da limonada?", "difficulty": 1, "explanation_md": "A bola não é um ingrediente da limonada. Os ingredientes são coisas que se misturam para fazer a bebida: limões, açúcar e água. A bola é um brinquedo, não custa dinheiro para produzir a limonada. Rho deve guardar seus $5 para a bola se quiser, mas não para a receita.", "audio_segment_id": "s1-odd-ingredient.prompt"}], "schema_version": 1}', '{"s1-odd-ingredient": {"odd_item_id": "item-pelota", "correct_reason_id": "reason-no-ingrediente"}}', '{"units": {"s1-odd-ingredient.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4cb8be69e9c4667b244036b6d383f971c32ff6edca8b4dac83d1b8b980ed2dfe.mp3", "hash": "7ed49d7ba54536e7c368c6f4f632c653c500737b9a49bf47b775da367a5f7876", "bytes": 44496, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/4cb8be69e9c4667b244036b6d383f971c32ff6edca8b4dac83d1b8b980ed2dfe.mp3", "duration_ms": 7360}, "s1-odd-ingredient.hint.1": {"url": "http://localhost:4006/files/lesson-audio/fdeb59c624c11887e27dc702f3302068e95da2ee60db8d307ecb1687ef7b65f5.mp3", "hash": "e9ec7e4e80bc551df6c83f63a3c1d9c8e87cb0c3db88bf28fb6fe57ccaa04887", "bytes": 28224, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/fdeb59c624c11887e27dc702f3302068e95da2ee60db8d307ecb1687ef7b65f5.mp3", "duration_ms": 4640}, "s1-odd-ingredient.prompt": {"url": "http://localhost:4006/files/lesson-audio/04525baf9424c8ed64e80d51ba917861f871278065d4b2f076ca74e305e0187b.mp3", "hash": "2a763396f248a1ae8fe0220f93f72ec2294de94f18cb395c43470dbadc75242a", "bytes": 129456, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/04525baf9424c8ed64e80d51ba917861f871278065d4b2f076ca74e305e0187b.mp3", "duration_ms": 21520}, "s1-odd-ingredient.choices": {"url": "http://localhost:4006/files/lesson-audio/245398bfd26f3ed5786984db78bfe1bb3816daccb13053db9effb4a7236a96bf.mp3", "hash": "bc9d843c79c3c50b623dcff4af0dd254851e49b2960f666b40ceabd807c1eafb", "bytes": 53136, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/245398bfd26f3ed5786984db78bfe1bb3816daccb13053db9effb4a7236a96bf.mp3", "duration_ms": 8800}, "s1-odd-ingredient.explanation": {"url": "http://localhost:4006/files/lesson-audio/c7774167fed02a0bf0c1c310c3da56c3f478c89dd4121f1c4855ab403191c907.mp3", "hash": "e9a7499a041840d785206d9b7bd55bc828b324b88026a22e5bbe19b28c901fe0", "bytes": 118368, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/c7774167fed02a0bf0c1c310c3da56c3f478c89dd4121f1c4855ab403191c907.mp3", "duration_ms": 19680}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'es-MX', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "type-answer", "title": "Escribe la respuesta exacta", "locale": "es-MX", "subject": "mixed", "objectives": ["Aplicar el concepto de ahorro decidiendo cuánto dinero guardar para una meta"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ahorro", "xp": 10, "type": "type_answer", "hints": ["Primero calcula cuánto ganó en total: 2 vasos × 5 pesos cada uno.", "Luego resta el dulce: total ganado menos 2 pesos."], "title": "¿Cuánto ahorró Dina?", "payload": {"max_chars": 2, "placeholder": "Escribe el número"}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Dina vendió 2 vasos de limonada a 5 pesos cada uno. Con el dinero que ganó, compró un dulce de 2 pesos. Quiere guardar el resto en su alcancía para comprar una patineta de 10 pesos. ¿Cuánto dinero guardó Dina en su alcancía?", "difficulty": 1, "explanation_md": "Dina ganó 10 pesos (2 × 5) y gastó 2 en un dulce, así que guardó 8 pesos. ¡Eso es ahorrar! El dinero que guardas para después se llama ahorro.", "audio_segment_id": "s1-ahorro.prompt"}], "schema_version": 1}', '{"s1-ahorro": {"accept": ["8", "ocho"], "keywords": ["8", "ocho"], "case_sensitive": false}}', '{"units": {"s1-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/83d58f1bd6074fa8ffce925613a816ee839c43885a29b2192c8e85ec6dbe3c4a.mp3", "hash": "9f8339274956331127a474350d93fd12f6d57d4cb51f431fe437cfc3ce765382", "bytes": 33408, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/83d58f1bd6074fa8ffce925613a816ee839c43885a29b2192c8e85ec6dbe3c4a.mp3", "duration_ms": 5520}, "s1-ahorro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0364d27c905ff354474c411bfb794afa57272e0394ffafbb3380cdae001c2827.mp3", "hash": "4138470db0479a1e8f6c50e813a5b4114bd3e30bf6d8f8f81e2c22de415694f5", "bytes": 25776, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/0364d27c905ff354474c411bfb794afa57272e0394ffafbb3380cdae001c2827.mp3", "duration_ms": 4240}, "s1-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/fc7296bdfdf9ecf8afe3e5d904fb12c74c762f441fc0a94123d91f8fc43fb964.mp3", "hash": "e4ddf5fcbf2bb8cbd357b1174cca1dc4168d6983ec74c45ef2281fbb1c022984", "bytes": 106416, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/fc7296bdfdf9ecf8afe3e5d904fb12c74c762f441fc0a94123d91f8fc43fb964.mp3", "duration_ms": 17680}, "s1-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/3027f6789daf9cb4b1056e8f92699561f9b8723989cbbe340491577b0aa223e2.mp3", "hash": "676c722e6b35b0fb01f1d16bc3d09c837fab4a955e2dbbfcab3b5a3b50fa0976", "bytes": 72288, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/3027f6789daf9cb4b1056e8f92699561f9b8723989cbbe340491577b0aa223e2.mp3", "duration_ms": 12000}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'pt-BR', '1', E'{"meta": {"cast": ["dina"], "slug": "would-you-rather", "title": "Viver a barraca em histórias jogáveis", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher entre dois caminhos do vendedor e defendê-lo: ganhar 10 reais hoje ou 20 na próxima semana? Não há resposta única, há razões."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-would-you-rather", "xp": 0, "type": "would_you_rather", "hints": ["Calcule quanto dinheiro cada plano dá. Qual deles te dá o suficiente para o skate?"], "title": "Ganhar hoje ou amanhã?", "payload": {"a": {"icon": "local_cafe", "text_md": "Plano A: vender 3 copos hoje a R$5 cada"}, "b": {"icon": "calendar_month", "text_md": "Plano B: esperar uma semana e vender 6 copos a R$4 cada"}, "followup_md": "Por que você escolheu esse plano? Conte para a Dina a sua razão."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Ontem você contou copos e trocos. Hoje a Dina tem dois planos para sua barraca de limonada:\\n\\n**Plano A:** Vender 3 copos HOJE a R$5 cada. Dinheiro rápido!\\n**Plano B:** Preparar 6 copos para a próxima semana a R$4 cada. Mais dinheiro, mas tem que esperar.\\n\\nDina quer comprar um skate que custa R$20. Qual plano a aproxima mais do seu objetivo?", "difficulty": 1, "explanation_md": "O Plano A dá R$15, que não é suficiente para o skate de R$20. O Plano B dá R$24, que é suficiente e ainda sobra. Dina escolhe o Plano B porque a aproxima do seu objetivo.", "audio_segment_id": "s1-would-you-rather.prompt"}], "schema_version": 1}', '{"s1-would-you-rather": {"qualities": {"a": 0, "b": 100}, "reveal_md": "Dina sonríe: «¡Bien pensado! Usaste lo que aprendiste ayer de sumar vasos. El Plan B da $24, justo para la patineta. Si elegiste el Plan A, recuerda que $15 no alcanzan para la patineta; necesitas $5 más.»"}}', '{"units": {"s1-would-you-rather.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2141236932c2d9a377969790267d6dc0d87062451ca49dc7619c5b82787d28b1.mp3", "hash": "5a4dd1df699514e53fc15837202894e77f6832cc54cdab0bf0ffd319fe8d3a16", "bytes": 37296, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2141236932c2d9a377969790267d6dc0d87062451ca49dc7619c5b82787d28b1.mp3", "duration_ms": 6160}, "s1-would-you-rather.prompt": {"url": "http://localhost:4006/files/lesson-audio/51451a73ed72f8ef19c659a4467eed8e3333b8cc6168ce51feb541f02a36445b.mp3", "hash": "741fd32d1b1d76a5e8c8a75513061d58f4a5ef4a828da5998719d79b53f91c8e", "bytes": 150048, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/51451a73ed72f8ef19c659a4467eed8e3333b8cc6168ce51feb541f02a36445b.mp3", "duration_ms": 24960}, "s1-would-you-rather.choices": {"url": "http://localhost:4006/files/lesson-audio/92602e51dfc1c6efc783e225f52b7504d17bb9f348e9c0f8d5a54ff808747aab.mp3", "hash": "64a1aaf029e5b442d8b24317cd3bf5bafdd97a947972fa8183bd80c84702259e", "bytes": 65664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/92602e51dfc1c6efc783e225f52b7504d17bb9f348e9c0f8d5a54ff808747aab.mp3", "duration_ms": 10880}, "s1-would-you-rather.explanation": {"url": "http://localhost:4006/files/lesson-audio/b0d8fea92d7e5ab40ff69ed46b9d56eaeb0523be50f40e948233f4e970b59672.mp3", "hash": "1a44fa04a1dcfef3e78de86fea22e5459ceec5d98eba88a9bc06825a16b12ab2", "bytes": 85824, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b0d8fea92d7e5ab40ff69ed46b9d56eaeb0523be50f40e948233f4e970b59672.mp3", "duration_ms": 14240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "debug-hunt", "title": "Cacería de errores", "locale": "es-MX", "subject": "mixed", "objectives": ["Encontrar el error en el cartel de promoción y corregirlo"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug", "xp": 15, "type": "debug_hunt", "hints": ["¿Cuánto cuesta un vaso normal?", "Compara el precio de 2 vasos sueltos con el de la promoción."], "title": "El cartel equivocado", "payload": {"blocks": [{"id": "b1", "text_md": "2 vasos por 8 pesos"}, {"id": "b2", "text_md": "¡sale más caro que comprarlos sueltos!"}, {"id": "b3", "text_md": "Precio normal: 5 pesos cada vaso"}], "intro_md": "Liruf colgó un cartel con una promoción. Pero algo no cuadra. Ayúdale a encontrar el error."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Después de ayudar al carrito a ahorrar pasos, ahora ayúdalo a ahorrar dinero. Liruf puso un cartel que dice: ''2 vasos por 8 pesos''. Pero los clientes se ríen. ¿Cuál es el error?", "difficulty": 2, "explanation_md": "Un vaso cuesta 5 pesos. Dos vasos sueltos cuestan 5 + 5 = 10 pesos. La promoción de 8 pesos es más barata, no más cara. El error está en decir ''sale más caro''.", "audio_segment_id": "s1-debug.prompt"}], "schema_version": 1}', '{"s1-debug": {"fix_md": "¡sale más barato que comprarlos sueltos!", "bug_ids": ["b2"]}}', '{"units": {"s1-debug.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4760742cb6d9ae13cbd6e8b0fd3b4628de2176fcdb7485de373fbf91af0f3378.mp3", "hash": "5361d6fbfa0114d6d51b9fd75f7b0c7a6f06c319ef4d9f206aaac94ae54be9f2", "bytes": 17568, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4760742cb6d9ae13cbd6e8b0fd3b4628de2176fcdb7485de373fbf91af0f3378.mp3", "duration_ms": 2880}, "s1-debug.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b0beaf74ce095765908889d3f2b877906d24ac0cb945b2998c43cefb44b94992.mp3", "hash": "050e6a191df9c7762865ef4c17400ee63882f014597229168eecdd3cbb2fadf1", "bytes": 27648, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b0beaf74ce095765908889d3f2b877906d24ac0cb945b2998c43cefb44b94992.mp3", "duration_ms": 4560}, "s1-debug.prompt": {"url": "http://localhost:4006/files/lesson-audio/a355279bc33638af1eae2f693cd7a9a743eb729bec7e130d42d4d3479654c352.mp3", "hash": "e2e5838024675a838ecc3dbe4af8a79302d0bab30ab7cc2ddce6e345807c5005", "bytes": 77616, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a355279bc33638af1eae2f693cd7a9a743eb729bec7e130d42d4d3479654c352.mp3", "duration_ms": 12880}, "s1-debug.explanation": {"url": "http://localhost:4006/files/lesson-audio/dd3bc44122c15afdec050d9ed73236f1ea5eca8cbe1110d3164c8a20218321ab.mp3", "hash": "b2477eb38bba730ad417391f326c723e5bf091af1fd579b8ad0116ea6c672fa2", "bytes": 76176, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/dd3bc44122c15afdec050d9ed73236f1ea5eca8cbe1110d3164c8a20218321ab.mp3", "duration_ms": 12640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'es-MX', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "combo-narrativa-choice", "title": "Un sábado en el puesto", "locale": "es-MX", "subject": "money", "objectives": ["Decidir el precio de la limonada en una situación realista con clientes y cambio"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-apertura", "xp": 0, "type": "story_scene", "hints": [], "title": "¡Llegan los clientes!", "payload": {"art": {"icon": "storefront", "tint": "primary"}, "action": "idle", "body_md": "El sol brilla. Liruf tiene los limones listos, el azúcar y los vasos. Pero… ¡no ha puesto el cartel con el precio! Los clientes preguntan: ''¿Cuánto cuesta un vaso?'' Liruf necesita decidir rápido. Igual que la máquina de propinas duplicaba las monedas, aquí Liruf puede duplicar su dinero si pone el precio correcto.", "emotion": "thinking", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Es sábado por la mañana. Liruf abre su puesto de limonada. Ya hay una fila de clientes esperando. El vaso cuesta 5 pesos, pero Liruf no ha puesto el precio del día. ¿Qué precio debe poner?", "difficulty": 1, "explanation_md": "Liruf recuerda que cada vaso cuesta 5 pesos de prepararlo. Igual que la máquina de propinas duplicaba las monedas, aquí Liruf puede duplicar su dinero si pone un precio mayor a 5 pesos.", "audio_segment_id": "s1-apertura.prompt"}, {"id": "s2-decision-precio", "xp": 10, "type": "quiz_mcq", "hints": ["Piensa: si el vaso cuesta 5 pesos, el precio debe ser mayor para ganar algo.", "Si pones 5 pesos, solo recuperas lo que gastaste, no ganas nada."], "title": "Elige el precio", "payload": {"options": [{"id": "a", "text_md": "3 pesos", "rationale_md": "3 pesos es menos de lo que cuesta hacer el vaso. ¡Liruf perdería dinero!"}, {"id": "b", "text_md": "5 pesos", "rationale_md": "5 pesos es justo lo que cuesta hacerlo, pero no gana nada. No es un buen negocio."}, {"id": "c", "text_md": "7 pesos", "rationale_md": "7 pesos es más que 5, así que Liruf gana 2 pesos por vaso. ¡Buena ganancia!"}, {"id": "d", "text_md": "10 pesos", "rationale_md": "10 pesos es mucho más caro. Tal vez los clientes no quieran pagar tanto y se vayan."}], "shuffle": true}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf sabe que cada vaso le cuesta 5 pesos hacerlo. ¿Qué precio debería poner en el cartel para ganar dinero? Mira este ejemplo: si Liruf vende un vaso a 7 pesos, gasta 5 pesos, entonces gana 2 pesos. ¡Eso es ganancia!", "difficulty": 1, "explanation_md": "Liruf necesita ganar dinero, así que el precio debe ser mayor que 5 pesos. 7 pesos es una buena opción: gana 2 pesos por vaso. Si hubieras elegido 3 pesos, perderías dinero. Si 5 pesos, no ganas nada. Si 10 pesos, tal vez los clientes no compren.", "audio_segment_id": "s2-decision-precio.prompt"}], "schema_version": 1}', '{"s2-decision-precio": {"correct_option_id": "c"}}', '{"units": {"s1-apertura.body": {"url": "http://localhost:4006/files/lesson-audio/5daadda7964f75e493aa5b7d3b3bd564bb13dc74fbc4f7ef2fde681bb6df8ecb.mp3", "hash": "73af67f3c0cdfb339c54cc1884459abb871f9a11f5007f89c9e42f5688479f9f", "bytes": 137664, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/5daadda7964f75e493aa5b7d3b3bd564bb13dc74fbc4f7ef2fde681bb6df8ecb.mp3", "duration_ms": 22880}, "s1-apertura.prompt": {"url": "http://localhost:4006/files/lesson-audio/968ee9ef99a7b85893b5f4f6aa5f4b606aebc1d812ebc07a831140b6f7fbda6e.mp3", "hash": "4d241f1e8f65afd9fe1510293c9927d59c694f668f71279cb93a923428c22066", "bytes": 86256, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/968ee9ef99a7b85893b5f4f6aa5f4b606aebc1d812ebc07a831140b6f7fbda6e.mp3", "duration_ms": 14320}, "s1-apertura.explanation": {"url": "http://localhost:4006/files/lesson-audio/629e2dceda2ed2b542661a434160362d1bd7cb5ad170c3d202efa8f29159b122.mp3", "hash": "2adb9eda2305eecedbd1b4ed7be04db1f998e62effe1981ec31e602fa3b75d65", "bytes": 73296, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/629e2dceda2ed2b542661a434160362d1bd7cb5ad170c3d202efa8f29159b122.mp3", "duration_ms": 12160}, "s2-decision-precio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f124e348a56b54a8290ce50d33a56b334322a1e2c94ac99dfe1a65c4b3f4ee9c.mp3", "hash": "843fc7f07d29b1381e612a572234c0a3c339823040f39cadbd15135b67999813", "bytes": 34848, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f124e348a56b54a8290ce50d33a56b334322a1e2c94ac99dfe1a65c4b3f4ee9c.mp3", "duration_ms": 5760}, "s2-decision-precio.hint.1": {"url": "http://localhost:4006/files/lesson-audio/18bd4d96ea01a3bbb8120233ea93f5ff8f21620092d421dbd9d6f6597ee57840.mp3", "hash": "e43476f9d1094658b46a29dc88d5d13acab562af23d2590ccac650bd5b771c60", "bytes": 31104, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/18bd4d96ea01a3bbb8120233ea93f5ff8f21620092d421dbd9d6f6597ee57840.mp3", "duration_ms": 5120}, "s2-decision-precio.prompt": {"url": "http://localhost:4006/files/lesson-audio/137b7eb415d70dfa880e15b6331e1b43a5771cf8a700a584883ba6d690e41e71.mp3", "hash": "f87a513d8537ce70f7a8dd28e24004662e7b30aa0e57710e11ddba4672f8d69d", "bytes": 94896, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/137b7eb415d70dfa880e15b6331e1b43a5771cf8a700a584883ba6d690e41e71.mp3", "duration_ms": 15760}, "s2-decision-precio.choices": {"url": "http://localhost:4006/files/lesson-audio/2da5d9edad3730f2a306ffa8f54df0d1f443e7f94b65d61904f8ea72e61a2f6b.mp3", "hash": "d3c5f44bb15272cfebd2aa7deef32f9c9a32abc2a4f148a25d88513e0d1e3c0f", "bytes": 34416, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2da5d9edad3730f2a306ffa8f54df0d1f443e7f94b65d61904f8ea72e61a2f6b.mp3", "duration_ms": 5680}, "s2-decision-precio.explanation": {"url": "http://localhost:4006/files/lesson-audio/d0c74fdc0a5f3035760f16e75011940e7bccc9a454359f6374260b8aefb5266d.mp3", "hash": "1da5510a3ab5a2e05ca71eb0cc037570082dcade88d3be97d8f43ea750592192", "bytes": 111744, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d0c74fdc0a5f3035760f16e75011940e7bccc9a454359f6374260b8aefb5266d.mp3", "duration_ms": 18560}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'pt-BR', '1', E'{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "O plano de Liruf", "locale": "pt-BR", "subject": "money", "objectives": ["Ver o plano completo: vender copos de limonada a 5 reais até juntar 80 para o violão"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan", "xp": 0, "type": "story_scene", "hints": ["Cada copo dá 5 reais. Quanto ele já juntou com 10 copos?", "Se ele já tem 50 reais, quanto falta para 80?"], "title": "O plano de Liruf", "payload": {"art": {"icon": "emoji_events", "tint": "primary"}, "action": "idle", "body_md": "Liruf desenhou seu plano em um cartaz. Escreveu: **1 copo = 5 reais**. Depois desenhou muitos copos e no final um violão de 80 reais. \\"Vou vender limonada até ter meu violão!\\" Como descobriram ontem com Dina, não precisa esperar um presente!", "emotion": "excited", "backdrop": "band", "character": "dina"}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Liruf já vendeu 10 copos de limonada a 5 reais cada. Quantos copos ele precisa vender a mais para juntar os 80 reais do violão?", "difficulty": 1, "explanation_md": "Muito bem! Com 10 copos ele juntou 50 reais. Faltam 30 reais para o violão. Como cada copo dá 5 reais, ele precisa de mais 6 copos (porque 6 × 5 = 30). Assim o plano dele se torna real!", "audio_segment_id": "s1-plan.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-plan.body": {"url": "http://localhost:4006/files/lesson-audio/0329acc7054532cfaf45c2fad83cc71c281cd5dae5b45757235de41f0004f9c6.mp3", "hash": "290392db81224ca5bf705c29dd7d51dba53d4e0184a3955fec53809e95d4ccb1", "bytes": 117504, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0329acc7054532cfaf45c2fad83cc71c281cd5dae5b45757235de41f0004f9c6.mp3", "duration_ms": 19520}, "s1-plan.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2a27aa77ddb74ae8dfd24e86e3f0ce1e8a3886641852a6c2ab24c9a395fd2e9c.mp3", "hash": "ff95c6dd612f770256a7ca43f33c8ac48940ca1c09496c1bc7f85a889b991721", "bytes": 30096, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2a27aa77ddb74ae8dfd24e86e3f0ce1e8a3886641852a6c2ab24c9a395fd2e9c.mp3", "duration_ms": 4960}, "s1-plan.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a8d296cf6ecece121eff3c84240e40b544e9f64d3b67ba19d36e7c8adff9f6fa.mp3", "hash": "594a3744701fc2842b3f33572a35e8cbaf13f6b3e1a6e9e10f71cbc8cc28ce95", "bytes": 25776, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a8d296cf6ecece121eff3c84240e40b544e9f64d3b67ba19d36e7c8adff9f6fa.mp3", "duration_ms": 4240}, "s1-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/c32ed9074494198f95d6d6b82320a2c8f5ae4467e106c23aebb10e2928dd5595.mp3", "hash": "ad0a4a808e04b687e9d837fd7097b066eddef21ec8511a01714d9851090bb6b8", "bytes": 55008, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c32ed9074494198f95d6d6b82320a2c8f5ae4467e106c23aebb10e2928dd5595.mp3", "duration_ms": 9120}, "s1-plan.explanation": {"url": "http://localhost:4006/files/lesson-audio/dd01d9908a714dfc7c67f5c838a003e441a93ee6abaa848092244f3b6a35e500.mp3", "hash": "6ab14c5d93d0a5e7e0c75b49fa7a9912c20ee49f3b6cc2a1fcf1ece74de27f1f", "bytes": 103104, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/dd01d9908a714dfc7c67f5c838a003e441a93ee6abaa848092244f3b6a35e500.mp3", "duration_ms": 17120}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "group-sets", "title": "Organize the cash box", "locale": "en-US", "subject": "money", "objectives": ["Group coins and bills to count money more easily"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-sets", "xp": 10, "type": "group_sets", "hints": ["Coins are round and made of metal; bills are paper and rectangular.", "Look for the currency symbol ($) to identify bills."], "title": "Separate the money", "payload": {"items": [{"id": "moneda-1", "text_md": "🪙 5-peso coin"}, {"id": "moneda-2", "text_md": "🪙 2-peso coin"}, {"id": "moneda-3", "text_md": "🪙 10-peso coin"}, {"id": "billete-1", "text_md": "💵 20-peso bill"}, {"id": "billete-2", "text_md": "💵 50-peso bill"}, {"id": "billete-3", "text_md": "💵 100-peso bill"}], "set_a": "Coins", "set_b": "Bills"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Just like you organized the small-large cups, now organize Liruf''s money. After selling lemonade, the cash box has mixed coins and bills. If you group them well, you''ll know if there''s enough to buy more lemons. Tap each coin and put it in the coin group, and each bill in the bill group. Then add up how much is in coins and how much in bills to see if Liruf can buy more lemons (they cost 15 pesos).", "difficulty": 1, "explanation_md": "Separating coins and bills helps count money faster. Liruf has 17 pesos in coins and 170 pesos in bills. Yes, there''s enough to buy more lemons!", "audio_segment_id": "s1-group-sets.prompt"}], "schema_version": 1}', '{"s1-group-sets": {"zones": {"moneda-1": "a", "moneda-2": "a", "moneda-3": "a", "billete-1": "b", "billete-2": "b", "billete-3": "b"}}}', '{"units": {"s1-group-sets.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e0b13f0126d2d68d903afff23b02c133fd62b5a89a5a8033d586b504b4c0f604.mp3", "hash": "4cbf792475426479822124a97fd336a33513cb487a02cfc4a9d36b80c37eb03a", "bytes": 21888, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e0b13f0126d2d68d903afff23b02c133fd62b5a89a5a8033d586b504b4c0f604.mp3", "duration_ms": 3600}, "s1-group-sets.hint.1": {"url": "http://localhost:4006/files/lesson-audio/e21734cd4d94a4caf412cb7e80edbd4e178e8cef2a4d71296c8e205813a4077a.mp3", "hash": "786d8c505ec5c8648aa8dea8d1e799955dd371900b1c81d937ac3f39d27c4e0d", "bytes": 15696, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e21734cd4d94a4caf412cb7e80edbd4e178e8cef2a4d71296c8e205813a4077a.mp3", "duration_ms": 2560}, "s1-group-sets.prompt": {"url": "http://localhost:4006/files/lesson-audio/c6f7d4312e97979e279147b4418a200e43645e20d65e51036db091cc2a49e15f.mp3", "hash": "b46f80a9d67bc9e7036a8ae56a56c5008aee71abfc76727ec50a52a078655667", "bytes": 123696, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c6f7d4312e97979e279147b4418a200e43645e20d65e51036db091cc2a49e15f.mp3", "duration_ms": 20560}, "s1-group-sets.explanation": {"url": "http://localhost:4006/files/lesson-audio/9819fa29364db449dc50618f4804ccd1c5a0ec8f7f5d473e4be03fe341fa416f.mp3", "hash": "40d1062640050c26646668c11a4207f92c2a341f7b2690d688d2ef62091ee862", "bytes": 56016, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9819fa29364db449dc50618f4804ccd1c5a0ec8f7f5d473e4be03fe341fa416f.mp3", "duration_ms": 9280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'pt-BR', '1', E'{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "cause-effect", "title": "Causa e efeito na barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Conectar causas e efeitos da barraca: dia ensolarado → mais sede → mais copos vendidos; aumentar o preço ao dobro → menos clientes."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cause-effect", "xp": 10, "type": "cause_effect", "hints": ["Pense: quando faz calor, as pessoas têm mais sede e compram mais limonada.", "Se o preço sobe muito, alguns clientes deixam de comprar."], "title": "O que aconteceu na barraca?", "payload": {"slots": 4, "events": [{"id": "e1", "text_md": "Segunda-feira: dia ensolarado e quente"}, {"id": "e2", "text_md": "Terça-feira: Liruf aumenta o preço de 5 para 10 pesos"}, {"id": "e3", "text_md": "Segunda-feira: vende 8 copos"}, {"id": "e4", "text_md": "Terça-feira: vende apenas 3 copos"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Na segunda-feira fez muito calor e Liruf vendeu 8 copos de limonada a 5 pesos cada. Na terça-feira, Liruf pensou: \\"Se eu dobrar o preço, ganharei o dobro\\". Aumentou o preço para 10 pesos, mas vendeu apenas 3 copos. O que aconteceu? Ajude Rho a conectar cada causa com seu efeito. Lembre-se: Liruf já errou antes ao somar 5+5+5 e pensar que dava 20. Agora errou de novo ao pensar que aumentar o preço sempre dá mais dinheiro!", "difficulty": 1, "explanation_md": "Na segunda-feira, com calor, vendeu 8 copos. Na terça-feira, ao dobrar o preço, vendeu apenas 3. Liruf pensou que ganharia o dobro, mas esqueceu que com preço alto vende menos. Como quando somou errado 5+5+5!", "audio_segment_id": "s1-cause-effect.prompt"}], "schema_version": 1}', '{"s1-cause-effect": {"chain": ["e1", "e3", "e2", "e4"]}}', '{"units": {"s1-cause-effect.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f8fd4b7002acdb0ebdbaa13d921c1ded79571c957e335cb9c3845a5b903cdea8.mp3", "hash": "cfa1a21051b3fae3a381a4c8deca2d7e46701f4f151b82ace5e9bceb48017afb", "bytes": 32976, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f8fd4b7002acdb0ebdbaa13d921c1ded79571c957e335cb9c3845a5b903cdea8.mp3", "duration_ms": 5440}, "s1-cause-effect.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f0f854c0a92bb8d316082f5c497f192d8e4fb241dc7bc91105fe7d997e7aa9a2.mp3", "hash": "082db6e5c82712772b46fa16049167f5e5acfdadd3e84884adacf33382121a21", "bytes": 23328, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f0f854c0a92bb8d316082f5c497f192d8e4fb241dc7bc91105fe7d997e7aa9a2.mp3", "duration_ms": 3840}, "s1-cause-effect.prompt": {"url": "http://localhost:4006/files/lesson-audio/3f58ed6229a24e805ad33b66aa118748d7097bf0f3aca124af414c1b26d54ce5.mp3", "hash": "0c8331bf3feb66dfbf5c21710c387feac059fcffa665d91d201b6b4e79ab1567", "bytes": 211104, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3f58ed6229a24e805ad33b66aa118748d7097bf0f3aca124af414c1b26d54ce5.mp3", "duration_ms": 35120}, "s1-cause-effect.explanation": {"url": "http://localhost:4006/files/lesson-audio/1cc9832368d430d74c898cee13099d3db6e08748964b1ce80dab6b075082069f.mp3", "hash": "5819c4ea246a7b4cfadaaf04b045cf070dc348831d4dd34b39b563970ed1cdd4", "bytes": 107424, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1cc9832368d430d74c898cee13099d3db6e08748964b1ce80dab6b075082069f.mp3", "duration_ms": 17840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "timeline-order", "title": "Organize the sale day", "locale": "pt-BR", "subject": "mixed", "objectives": ["Order the steps of the sale day chronologically"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline", "xp": 10, "type": "timeline_order", "hints": ["Think: what do you do before preparing the lemonade?", "What do you do at the end of the day with the money?"], "title": "Liruf''s first day", "payload": {"events": [{"id": "comprar", "icon": "shopping_cart", "text_md": "Buy ingredients in the morning"}, {"id": "preparar", "icon": "blender", "text_md": "Prepare the lemonade"}, {"id": "vender", "icon": "storefront", "text_md": "Sell lemonade at noon"}, {"id": "contar", "icon": "savings", "text_md": "Count the money and put it away at closing"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "After hanging his ''Cold lemonade for 5 pesos'' sign, Liruf gets ready for his first full day. Tap the photos in the correct order: what happened first, second, third, and fourth? If you order them wrong, customers get confused and you don''t sell!", "difficulty": 1, "explanation_md": "First you buy the ingredients, then you prepare the lemonade, then you sell at noon, and at the end you count the money and put it away. That way Liruf doesn''t get confused and sells all his lemonade!", "audio_segment_id": "s1-timeline.prompt"}], "schema_version": 1}', '{"s1-timeline": {"order": ["comprar", "preparar", "vender", "contar"]}}', '{"units": {"s1-timeline.hint.0": {"url": "http://localhost:4006/files/lesson-audio/71edfd46b4b168e678a9b520af69ae196f44ee4cbe8cb6bf72f704dd6e4aa667.mp3", "hash": "ff64e0dbb784e1ea883c85c3901c786fc06dc84166c15621525daf63611c519e", "bytes": 19008, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/71edfd46b4b168e678a9b520af69ae196f44ee4cbe8cb6bf72f704dd6e4aa667.mp3", "duration_ms": 3120}, "s1-timeline.hint.1": {"url": "http://localhost:4006/files/lesson-audio/9f465aa92dc951f9ebd4c29186e0e2c3311da4f8ba40dac85f98ba5f1da1ceb8.mp3", "hash": "931fde74308bba54fbdfd0df67eecb64f28ae42a475d1c982d6ce945e994759c", "bytes": 21888, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/9f465aa92dc951f9ebd4c29186e0e2c3311da4f8ba40dac85f98ba5f1da1ceb8.mp3", "duration_ms": 3600}, "s1-timeline.prompt": {"url": "http://localhost:4006/files/lesson-audio/8b119ff699d29ec21db39116a474029a6b880d7199dd5b0eaea0430ce184c90a.mp3", "hash": "08d49cb52e3aca20c00cd3519d93e5627ee6b24c78ce33289894d9679baf86ef", "bytes": 107424, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/8b119ff699d29ec21db39116a474029a6b880d7199dd5b0eaea0430ce184c90a.mp3", "duration_ms": 17840}, "s1-timeline.explanation": {"url": "http://localhost:4006/files/lesson-audio/19fc6bb2609a7571be871a22fc3401809aa84b9f6fb661e1ce9faf90ee320535.mp3", "hash": "da20e8675df77775411b9acc70d17a2401e2dc2cfa782708a87e91be342010a8", "bytes": 74736, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/19fc6bb2609a7571be871a22fc3401809aa84b9f6fb661e1ce9faf90ee320535.mp3", "duration_ms": 12400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'en-US', '1', '{"meta": {"cast": ["rho"], "slug": "odd-one-out", "title": "The Strange Ingredient", "locale": "en-US", "subject": "mixed", "objectives": ["Identify which items are not lemonade ingredients to distinguish real production costs."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-ingredient", "xp": 10, "type": "odd_one_out", "hints": ["Think about what you need to make lemonade: lemons, water, sugar... anything else?", "If you can''t eat it or drink it, it''s probably not an ingredient."], "title": "What doesn''t go in the lemonade?", "payload": {"items": [{"id": "item-limones", "text_md": "Lemons ($3)"}, {"id": "item-azucar", "text_md": "Sugar ($2)"}, {"id": "item-agua", "text_md": "Water ($1)"}, {"id": "item-pelota", "text_md": "Ball ($5)"}], "reasons": [{"id": "reason-ingrediente", "text_md": "Yes, it is a lemonade ingredient."}, {"id": "reason-no-ingrediente", "text_md": "No, it is not a lemonade ingredient."}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho has $10 saved in his piggy bank to buy ingredients. On his list he wrote: lemons ($3), sugar ($2), water ($1), and a ball ($5). But the ball is not an ingredient. Which of these should he NOT buy with his lemonade money?", "difficulty": 1, "explanation_md": "The ball is not a lemonade ingredient. Ingredients are things you mix to make the drink: lemons, sugar, and water. The ball is a toy, it doesn''t cost money to produce the lemonade. Rho should save his $5 for the ball if he wants, but not for the recipe.", "audio_segment_id": "s1-odd-ingredient.prompt"}], "schema_version": 1}', '{"s1-odd-ingredient": {"odd_item_id": "item-pelota", "correct_reason_id": "reason-no-ingrediente"}}', '{"units": {"s1-odd-ingredient.hint.0": {"url": "http://localhost:4006/files/lesson-audio/795ee369e48503147276827b74d8c7733ae5fad79fc258303c9b49700f7b7676.mp3", "hash": "73bcaae748e4138815ce4aa84eb4cc551fef341506aa1e6447e9fbec4e5727e0", "bytes": 40176, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/795ee369e48503147276827b74d8c7733ae5fad79fc258303c9b49700f7b7676.mp3", "duration_ms": 6640}, "s1-odd-ingredient.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0d25d78a9e0f59d1e8d13396737f852f3818e1399839003f3616b4d823bc9230.mp3", "hash": "9657f2d7c1ef346669968151a8c1ad286e5b3bcff99e67696c54f14f8934b07c", "bytes": 22896, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/0d25d78a9e0f59d1e8d13396737f852f3818e1399839003f3616b4d823bc9230.mp3", "duration_ms": 3760}, "s1-odd-ingredient.prompt": {"url": "http://localhost:4006/files/lesson-audio/9051b8b75d12dbb1da0f140500a89e5e24afaac0fb4fcbc529bdd15238225677.mp3", "hash": "0922f93d5e1f214e0c8852a404fd2a46d908415c609a9281a1bb87d1d5a03274", "bytes": 116928, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/9051b8b75d12dbb1da0f140500a89e5e24afaac0fb4fcbc529bdd15238225677.mp3", "duration_ms": 19440}, "s1-odd-ingredient.choices": {"url": "http://localhost:4006/files/lesson-audio/71494521e0b30ed2b1900aa8f6356df335aba75ccbc7b4b903406e76a41d53a9.mp3", "hash": "3c8556945c7a3cb63fc7870d50dbd18e4dc9c69dcb2995686c7cb89709df3ae0", "bytes": 40608, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/71494521e0b30ed2b1900aa8f6356df335aba75ccbc7b4b903406e76a41d53a9.mp3", "duration_ms": 6720}, "s1-odd-ingredient.explanation": {"url": "http://localhost:4006/files/lesson-audio/ae1efb2ea5f25cac0a6cf2202c72695e86ebb83afb94351f199f8a9b3c6076d6.mp3", "hash": "c6ae6a2338576148c91d10bc299fb4af73c36db5b75c0dcc258b8750d6274716", "bytes": 104544, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/ae1efb2ea5f25cac0a6cf2202c72695e86ebb83afb94351f199f8a9b3c6076d6.mp3", "duration_ms": 17360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "evidence-hunt", "title": "Cacería de evidencia: el recibo del mercado", "locale": "es-MX", "subject": "mixed", "objectives": ["Buscar en el recibo del mercado la evidencia exacta de cuánto costaron los limones"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 10, "type": "evidence_hunt", "hints": ["Busca en el recibo la línea que dice ''limones''.", "Fíjate bien en el número junto a ''limones''."], "title": "El recibo arrugado", "payload": {"claim_md": "Liruf dice: ''Gasté 20 pesos en limones.''", "sentences": [{"id": "s1", "text_md": "Limones: 15 pesos"}, {"id": "s2", "text_md": "Azúcar: 10 pesos"}, {"id": "s3", "text_md": "Total: 25 pesos"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "La semana pasada viste en una gráfica cuál fue el mejor día de ventas de limonada. Hoy, Liruf te necesita: compró limones y azúcar para hacer más limonada, pero perdió la cuenta. Solo tiene este recibo arrugado. Dice: ''Gasté 20 pesos en limones.'' Pero el recibo dice otra cosa. ¿Cuánto costaron realmente los limones? Ayuda a Liruf a encontrar la evidencia exacta en el recibo. Elige la línea del recibo que muestra el costo real de los limones.", "difficulty": 1, "explanation_md": "El recibo muestra que los limones costaron 15 pesos, no 20. Liruf se equivocó al recordar. La evidencia está en la línea ''Limones: 15 pesos''.", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1"]}}', '{"units": {"s1-evidence-hunt.hint.0": {"url": "http://localhost:4006/files/lesson-audio/dba2084138ba45e75b6d9825e4b44bab081b06b5cecb002a9257838a25b4d1d1.mp3", "hash": "744ca2ffdfbc1d893495d3bea238bf5b0bf287cdbb75019a013e11949e933527", "bytes": 21456, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/dba2084138ba45e75b6d9825e4b44bab081b06b5cecb002a9257838a25b4d1d1.mp3", "duration_ms": 3520}, "s1-evidence-hunt.hint.1": {"url": "http://localhost:4006/files/lesson-audio/30db13791f2ef06570630ce245520284b17b0cc2d43de9ec445a549041272a3e.mp3", "hash": "92ec468f5c59b9f3f055f1ef4c7fd2fe90e9a4ecbe3bf72697289fbe8961409f", "bytes": 18576, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/30db13791f2ef06570630ce245520284b17b0cc2d43de9ec445a549041272a3e.mp3", "duration_ms": 3040}, "s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/e173360158844f7e98ec47c8287695219041eedfbcf543d1fe249a4ef3451b67.mp3", "hash": "4c42d6d174a3b9759e8fc5bc0fdbd461a95bd688982da50aea9d3e28b995b098", "bytes": 167328, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/e173360158844f7e98ec47c8287695219041eedfbcf543d1fe249a4ef3451b67.mp3", "duration_ms": 27840}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/de612daa2a5d551dd87416624377ec6a85f7f9b868f855a254ae90294fafe405.mp3", "hash": "9ca60a289d5c046c7f01d9c0ee74b32b99231a67f3b55c74fac959db0f47be42", "bytes": 72288, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/de612daa2a5d551dd87416624377ec6a85f7f9b868f855a254ae90294fafe405.mp3", "duration_ms": 12000}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'en-US', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "type-answer", "title": "Write the exact answer", "locale": "en-US", "subject": "mixed", "objectives": ["Apply the concept of saving by deciding how much money to set aside for a goal"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ahorro", "xp": 10, "type": "type_answer", "hints": ["First, calculate how much she earned in total: 2 glasses × 5 pesos each.", "Then subtract the candy: total earned minus 2 pesos."], "title": "How much did Dina save?", "payload": {"max_chars": 2, "placeholder": "Write the number"}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Dina sold 2 glasses of lemonade for 5 pesos each. With the money she earned, she bought a candy for 2 pesos. She wants to put the rest in her piggy bank to buy a skateboard that costs 10 pesos. How much money did Dina put in her piggy bank?", "difficulty": 1, "explanation_md": "Dina earned 10 pesos (2 × 5) and spent 2 on a candy, so she saved 8 pesos. That''s saving! The money you keep for later is called savings.", "audio_segment_id": "s1-ahorro.prompt"}], "schema_version": 1}', '{"s1-ahorro": {"accept": ["8", "ocho"], "keywords": ["8", "ocho"], "case_sensitive": false}}', '{"units": {"s1-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a98ad6dbc629ce3bd404e5921a3eb69b78584a7b80103d69b6a6d0aee8974276.mp3", "hash": "f585f2242ad2f20723307d621dd44bfee9ffe040711fd05328404ab88b3afd72", "bytes": 36864, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/a98ad6dbc629ce3bd404e5921a3eb69b78584a7b80103d69b6a6d0aee8974276.mp3", "duration_ms": 6080}, "s1-ahorro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/4ceb37e422e96e0cd9b5224daf39ae4e7746f2796a8fb3ca87f165b6e1f85ee2.mp3", "hash": "2266e8b774465624abafb66b3a0db6acc37d2dde0c806eb7a0bce6e640ed3023", "bytes": 26784, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/4ceb37e422e96e0cd9b5224daf39ae4e7746f2796a8fb3ca87f165b6e1f85ee2.mp3", "duration_ms": 4400}, "s1-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/8c06351fec025fc186e61b042c75baef25c4b6cced59cd91fea51d5e5b14a86a.mp3", "hash": "aecbc50272ddb5112ce4440732365e37386a492cfad3f2c476bc2bf82bca39e0", "bytes": 97344, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/8c06351fec025fc186e61b042c75baef25c4b6cced59cd91fea51d5e5b14a86a.mp3", "duration_ms": 16160}, "s1-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/1464cfdf22ed581d4638a6e64605440fec6bfd3b98b10cbd5de0b039203dffe6.mp3", "hash": "44b9dec71c16dd9b6fc729cdefaf4b5a7784582bf13a3a00d9cdb7f5463d7c2b", "bytes": 71856, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/1464cfdf22ed581d4638a6e64605440fec6bfd3b98b10cbd5de0b039203dffe6.mp3", "duration_ms": 11920}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'es-MX', '1', E'{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "cause-effect", "title": "Causa y efecto en el puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Conectar causas y efectos del puesto: día soleado → más sed → más vasos vendidos; subir el precio al doble → menos clientes."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cause-effect", "xp": 10, "type": "cause_effect", "hints": ["Piensa: cuando hace calor, la gente tiene más sed y compra más limonada.", "Si el precio sube mucho, algunos clientes ya no compran."], "title": "¿Qué pasó en el puesto?", "payload": {"slots": 4, "events": [{"id": "e1", "text_md": "Lunes: día soleado y caluroso"}, {"id": "e2", "text_md": "Martes: Liruf sube el precio de 5 a 10 pesos"}, {"id": "e3", "text_md": "Lunes: se venden 8 vasos"}, {"id": "e4", "text_md": "Martes: solo se venden 3 vasos"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "El lunes hizo mucho calor y Liruf vendió 8 vasos de limonada a 5 pesos cada uno. El martes, Liruf pensó: \\"Si duplico el precio, ganaré el doble\\". Subió el precio a 10 pesos, pero solo vendió 3 vasos. ¿Qué pasó? Ayuda a Rho a conectar cada causa con su efecto. Recuerda: Liruf ya se equivocó antes al sumar 5+5+5 y pensar que daba 20. ¡Ahora volvió a equivocarse al pensar que subir el precio siempre da más dinero!", "difficulty": 1, "explanation_md": "El lunes, con calor, vendió 8 vasos. El martes, al subir el precio al doble, solo vendió 3. Liruf pensó que ganaría el doble, pero olvidó que con precio alto vende menos. ¡Como cuando sumó mal 5+5+5!", "audio_segment_id": "s1-cause-effect.prompt"}], "schema_version": 1}', '{"s1-cause-effect": {"chain": ["e1", "e3", "e2", "e4"]}}', '{"units": {"s1-cause-effect.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3de50a5177bf7cb05fadb30990c304075834a63c216d1bccaa57ce7b73e4768c.mp3", "hash": "c49345d561a7d48f20fd37f0ff78a7b94cb58a67362b347a36ab28f710a7ad74", "bytes": 33984, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3de50a5177bf7cb05fadb30990c304075834a63c216d1bccaa57ce7b73e4768c.mp3", "duration_ms": 5600}, "s1-cause-effect.hint.1": {"url": "http://localhost:4006/files/lesson-audio/40a0cda2c9bbd41058aa6c031aacf1246617b361d3f51a5692b0b0bc8f405cf2.mp3", "hash": "7dc57112de5ad6776569ea5274dc8e3f3ebbc35163e291500d5652199e04e61d", "bytes": 22896, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/40a0cda2c9bbd41058aa6c031aacf1246617b361d3f51a5692b0b0bc8f405cf2.mp3", "duration_ms": 3760}, "s1-cause-effect.prompt": {"url": "http://localhost:4006/files/lesson-audio/57993138e496206f326fa5e84e814bc081f045f23c44df4c3cefa00d21a90f58.mp3", "hash": "7afa796d6e0e046224d867882bd1e39a0174c0a5cc215984084955db6554f3c1", "bytes": 170208, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/57993138e496206f326fa5e84e814bc081f045f23c44df4c3cefa00d21a90f58.mp3", "duration_ms": 28320}, "s1-cause-effect.explanation": {"url": "http://localhost:4006/files/lesson-audio/f898535f909450f87c6ade40782e932e0486d1e858a5c69c5e0eaa6140b33b9d.mp3", "hash": "8b7d10b24095a6b42ba269f85cf5de5d64de2da3a443e0a95b646a13c00f6140", "bytes": 93024, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f898535f909450f87c6ade40782e932e0486d1e858a5c69c5e0eaa6140b33b9d.mp3", "duration_ms": 15440}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'pt-BR', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "robot-path", "title": "A rota do carrinho entregador", "locale": "pt-BR", "subject": "mixed", "objectives": ["Guiar o carrinho entregador pela grade do bairro até a casa do cliente gastando a menor quantidade de passos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 10, "type": "robot_path", "hints": ["O carrinho começa olhando para cima. Para onde fica a casa de Leo?", "Tente com uma única curva e depois avance direto."], "title": "A rota do carrinho", "payload": {"goal": {"x": 2, "y": 0}, "grid": {"h": 4, "w": 4}, "start": {"x": 0, "y": 0, "dir": "up"}, "walls": [{"x": 1, "y": 1}, {"x": 2, "y": 1}], "commands": ["forward", "left", "right"], "max_commands": 3}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Assim como você organizou os passos para a registradora, agora organize os passos do carrinho. Zara tem um carrinho entregador que deve levar um brinquedo para a casa de seu amigo Leo. O carrinho começa na esquina da grade, olhando para cima. A casa de Leo está à direita, a 2 quadras. Toque nos comandos para guiá-lo: **forward** (avança 1 quadra), **left** (vira à esquerda), **right** (vira à direita). Use a menor quantidade de passos!", "difficulty": 1, "explanation_md": "O carrinho virou à direita (1 comando) e avançou 2 passos (2 comandos) para chegar à casa de Leo. Você usou apenas 3 comandos! Assim como na registradora, organizar os passos corretos economiza tempo.", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.hint.0": {"url": "http://localhost:4006/files/lesson-audio/bfd938e675379041a2c88f7d65b4ac33cb01f1d170e2ac310071191a3da953cb.mp3", "hash": "4e53306357db9dad0934774c801947c00fa7eac9620e67897c7dafa2e81de2ea", "bytes": 29088, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/bfd938e675379041a2c88f7d65b4ac33cb01f1d170e2ac310071191a3da953cb.mp3", "duration_ms": 4800}, "s1-robot-path.hint.1": {"url": "http://localhost:4006/files/lesson-audio/3a3fbc18c6a8cd47849b7146c9268f3eee705f0d862e800c484020be692224d6.mp3", "hash": "a7d131a019890beaa08ba5e1a37917ebb1b26e50331c0d5660af63314c4d6988", "bytes": 23328, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3a3fbc18c6a8cd47849b7146c9268f3eee705f0d862e800c484020be692224d6.mp3", "duration_ms": 3840}, "s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/025386b4d65fc597da08abadb75079c54b0d91ba97e3b0bdbb7284fea65bf513.mp3", "hash": "92ddb087d1546223820baa29a2cf8fbed07e1eba2f918c1e4a74f9f041b78c77", "bytes": 163008, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/025386b4d65fc597da08abadb75079c54b0d91ba97e3b0bdbb7284fea65bf513.mp3", "duration_ms": 27120}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/95fa3d2c311490dbd2fadf212bf7d3265e622be78a12b9b245149d4d39644017.mp3", "hash": "02b0310535c72d9fb4ff784f4ab504c31e698ac883893e4bfeb5dc8386379137", "bytes": 90576, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/95fa3d2c311490dbd2fadf212bf7d3265e622be78a12b9b245149d4d39644017.mp3", "duration_ms": 15040}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "group-sets", "title": "Organize the stand''s cash box", "locale": "pt-BR", "subject": "money", "objectives": ["Group coins and bills to count money more easily"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-sets", "xp": 10, "type": "group_sets", "hints": ["Coins are round and made of metal; bills are paper and rectangular.", "Look for the currency symbol ($) to identify bills."], "title": "Separate the money", "payload": {"items": [{"id": "moneda-1", "text_md": "🪙 5-peso coin"}, {"id": "moneda-2", "text_md": "🪙 2-peso coin"}, {"id": "moneda-3", "text_md": "🪙 10-peso coin"}, {"id": "billete-1", "text_md": "💵 20-peso bill"}, {"id": "billete-2", "text_md": "💵 50-peso bill"}, {"id": "billete-3", "text_md": "💵 100-peso bill"}], "set_a": "Coins", "set_b": "Bills"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Just like you organized the small-large cups, now organize Liruf''s money. After selling lemonade, the cash box has mixed coins and bills. If you group them well, you''ll know if there''s enough to buy more lemons. Tap each coin and put it in the coin group, and each bill in the bill group. Then add up how much is in coins and how much in bills to see if Liruf can buy more lemons (they cost 15 pesos).", "difficulty": 1, "explanation_md": "Separating coins and bills helps count money faster. Liruf has 17 pesos in coins and 170 pesos in bills. Yes, there''s enough to buy more lemons!", "audio_segment_id": "s1-group-sets.prompt"}], "schema_version": 1}', '{"s1-group-sets": {"zones": {"moneda-1": "a", "moneda-2": "a", "moneda-3": "a", "billete-1": "b", "billete-2": "b", "billete-3": "b"}}}', '{"units": {"s1-group-sets.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f26bb2794154156f1e17cdd57b22d61fbd978e9fc8401af932d833fa0c56a117.mp3", "hash": "3dfc844d10fe8b2730a257b908045c258e70984db6a299ee21a8afca0b60f0db", "bytes": 30096, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f26bb2794154156f1e17cdd57b22d61fbd978e9fc8401af932d833fa0c56a117.mp3", "duration_ms": 4960}, "s1-group-sets.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c52e19b85fe9d298caaee88871bf76dc02e1af0066d1c9eba6c41eacb38616f8.mp3", "hash": "4986f8bd3c191dc835f83abdf0004de634d9ce609653401d88893e5903108fb4", "bytes": 19008, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c52e19b85fe9d298caaee88871bf76dc02e1af0066d1c9eba6c41eacb38616f8.mp3", "duration_ms": 3120}, "s1-group-sets.prompt": {"url": "http://localhost:4006/files/lesson-audio/5604ff69b73fea89496fe0bedb41b36a7d86742fbb205bf9b827bdf7e3730d9a.mp3", "hash": "075d3f14bba7e6f05e07089d11048803d7b79b71198cdc18054a61290ce3da5e", "bytes": 160128, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5604ff69b73fea89496fe0bedb41b36a7d86742fbb205bf9b827bdf7e3730d9a.mp3", "duration_ms": 26640}, "s1-group-sets.explanation": {"url": "http://localhost:4006/files/lesson-audio/7f73627b3a1837ea3565c1b300846917365acd8c0e07989fab0798170e066510.mp3", "hash": "62d57e0e91917159c362edcd7280fb0dedaca12d97fd321014439b92d5f092fd", "bytes": 67968, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7f73627b3a1837ea3565c1b300846917365acd8c0e07989fab0798170e066510.mp3", "duration_ms": 11280}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "Say yes or no, case by case", "locale": "en-US", "subject": "mixed", "objectives": ["Decide whether an expense helps the lemonade stand or not, based on whether it is a need or a temptation."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 10, "type": "yes_no_cases", "hints": ["Think: does this help sell more lemonade or make it better?", "If it''s for the stand today, maybe yes. If it''s a personal treat, better wait."], "title": "Helpful expense or temptation?", "payload": {"cases": [{"id": "case-limones", "text_md": "Buying more lemons to make more lemonade."}, {"id": "case-juguete", "text_md": "Buying a new toy today at the store."}, {"id": "case-vasos", "text_md": "Buying disposable cups to serve the lemonade."}, {"id": "case-dulces", "text_md": "Buying candy to eat while you work."}], "rule_md": "Ask yourself: **does this help the stand work better or sell more?** If the answer is yes, it''s a worthwhile expense. If it''s just a craving, better save the money."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Now that Liruf knows how to give the correct change for a $20 bill for a $5 lemonade, Dina asks: ''Should we spend on this for the stand or is it a temptation?'' Help Liruf decide for each case.", "difficulty": 1, "explanation_md": "Buying more lemons helps make more lemonade and earn more money. A new toy does not help the stand today.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["case-limones", "case-vasos"]}}', '{"units": {"s1-yes-no-cases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/11b06d081c92764b6494b383a0461f332b7e8f8ea10dede05aa6068b5479cfb0.mp3", "hash": "c06e994ff61ffc2c60d9c90065de66d11957847bae122e847ed0e05c1413ed42", "bytes": 20448, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/11b06d081c92764b6494b383a0461f332b7e8f8ea10dede05aa6068b5479cfb0.mp3", "duration_ms": 3360}, "s1-yes-no-cases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f4f0829e0e4c816232a4b1b2115b359daeb612a5938f537968a1fcd87a580d51.mp3", "hash": "7d5c959530bdf1e5c1d513609cac438be97b233dae1197584ec62aa9394030c4", "bytes": 28656, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f4f0829e0e4c816232a4b1b2115b359daeb612a5938f537968a1fcd87a580d51.mp3", "duration_ms": 4720}, "s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/96f17f669a878b9850015276b311eb7642a8abd066d672c30175e65c054021f7.mp3", "hash": "a8b5a4b641218d989f80e0cbdaf40faa3bd5798ffc2045ffe0e424b731f51006", "bytes": 67968, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/96f17f669a878b9850015276b311eb7642a8abd066d672c30175e65c054021f7.mp3", "duration_ms": 11280}, "s1-yes-no-cases.choices": {"url": "http://localhost:4006/files/lesson-audio/967dd3dcf8220f1128501d761ca4444cb5559af05f04676b0a83f19dd2d6a93b.mp3", "hash": "92f02152b7ed61a05d97fa3114386fe0b33d9e6455a172c35666a58046c2cab7", "bytes": 51264, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/967dd3dcf8220f1128501d761ca4444cb5559af05f04676b0a83f19dd2d6a93b.mp3", "duration_ms": 8480}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/bf817d691a2dd59ffb9520788f4c0accadadd8a9da0e5986872b5c79034b81d2.mp3", "hash": "f30e61134cf71841539c78533197e0e72fce0464be29cfc07367b279306aa1b2", "bytes": 34848, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/bf817d691a2dd59ffb9520788f4c0accadadd8a9da0e5986872b5c79034b81d2.mp3", "duration_ms": 5760}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'pt-BR', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "type-answer", "title": "Escreva a resposta exata", "locale": "pt-BR", "subject": "mixed", "objectives": ["Aplicar o conceito de poupança decidindo quanto dinheiro guardar para uma meta"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ahorro", "xp": 10, "type": "type_answer", "hints": ["Primeiro calcule quanto ela ganhou no total: 2 copos × 5 pesos cada.", "Depois subtraia o doce: total ganho menos 2 pesos."], "title": "Quanto Dina economizou?", "payload": {"max_chars": 2, "placeholder": "Escreva o número"}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Dina vendeu 2 copos de limonada a 5 pesos cada. Com o dinheiro que ganhou, comprou um doce de 2 pesos. Ela quer guardar o restante no cofrinho para comprar um skate de 10 pesos. Quanto dinheiro Dina guardou no cofrinho?", "difficulty": 1, "explanation_md": "Dina ganhou 10 pesos (2 × 5) e gastou 2 em um doce, então guardou 8 pesos. Isso é poupar! O dinheiro que você guarda para depois se chama poupança.", "audio_segment_id": "s1-ahorro.prompt"}], "schema_version": 1}', '{"s1-ahorro": {"accept": ["8", "ocho"], "keywords": ["8", "ocho"], "case_sensitive": false}}', '{"units": {"s1-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f667a4f1f3e5127f3aa6fdbc34899ec6f3ca86f2e329e4ba1c0a2d27bda3dcdd.mp3", "hash": "001a7e7c765d8f5a5f333f5f796686a77e13ea07b81f58ee69b412d4ae32b1bb", "bytes": 35424, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/f667a4f1f3e5127f3aa6fdbc34899ec6f3ca86f2e329e4ba1c0a2d27bda3dcdd.mp3", "duration_ms": 5840}, "s1-ahorro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/068a07bea70d0f5ced92bb14fae1441f9f59f3e6e6d4180c3a0b18cb8db20c67.mp3", "hash": "e3fc17f4829024ffcc308afd2a1c233746eea64fa967220bf5c2b0e29c60cdf8", "bytes": 25344, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/068a07bea70d0f5ced92bb14fae1441f9f59f3e6e6d4180c3a0b18cb8db20c67.mp3", "duration_ms": 4160}, "s1-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/98ae367deedbd3bd67053155d719debe92481ae7b092b62a2e898365fa757acf.mp3", "hash": "4fc24c4f82f7e0c670dcd7000d3ec2cccda0bc70b37a88de1fb7548a4bf8b9fe", "bytes": 99648, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/98ae367deedbd3bd67053155d719debe92481ae7b092b62a2e898365fa757acf.mp3", "duration_ms": 16560}, "s1-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/9f7d4fa2c69185b123cb100b6ff8cffd02da1eb54443f4147fa51d4a21b44594.mp3", "hash": "6074c32cdcd963eac353f5634133cc853645c372185dbc2b8467e4076cea22c4", "bytes": 81504, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/9f7d4fa2c69185b123cb100b6ff8cffd02da1eb54443f4147fa51d4a21b44594.mp3", "duration_ms": 13520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "number-line", "title": "The savings line", "locale": "en-US", "subject": "mixed", "objectives": ["Place on the number line from 0 to 100 where Liruf''s savings (20 pesos) are and where the goal (80) is: see how much is missing."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 10, "type": "number_line", "hints": ["Liruf''s savings are closer to 0 than to the goal.", "Count by 10s from 0: 10, 20, 30… up to 80."], "title": "Mark the savings and the goal", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": false}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf saved 20 pesos by grouping coins as you learned. She''s almost at her 80-peso skateboard! But if she marks incorrectly on the line, she''ll think she already has enough. Help her: first mark where her savings are (20) and then where the goal is (80). That way she''ll know how much she still needs.", "difficulty": 1, "explanation_md": "Liruf has saved 20 pesos and her goal is 80 pesos. On the number line, 20 is closer to 0 and 80 is farther. She needs 60 more pesos to get her skateboard!", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 20, "full_credit_delta": 5, "zero_credit_delta": 15}}', '{"units": {"s1-number-line.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2bd2330bbe9e3d4c265edf2b920af0328228be3e9fadb4535f0939a689e8edd2.mp3", "hash": "6c26e3f612b815a12fedcd9fb1fe05e5a3812676321f5e6a2e123d098d335f8c", "bytes": 22896, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/2bd2330bbe9e3d4c265edf2b920af0328228be3e9fadb4535f0939a689e8edd2.mp3", "duration_ms": 3760}, "s1-number-line.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5ddf1c3799d88f590bf5390e69aea2d323e3e56e2e02cdcc73e2309a491823de.mp3", "hash": "91c3e96c952676cf270f3337d489e1e82e62037d436a18209b9d0eb79189ec33", "bytes": 37728, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/5ddf1c3799d88f590bf5390e69aea2d323e3e56e2e02cdcc73e2309a491823de.mp3", "duration_ms": 6240}, "s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/3d3aec7f6f5a7aac627f0e47f023b3bf5988cc51b5bd2cb0c622a318c95574ff.mp3", "hash": "b8b4e5a606955f82f390d45c33ed04101115ae6cd43a5e0261b9042f047a636d", "bytes": 132768, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/3d3aec7f6f5a7aac627f0e47f023b3bf5988cc51b5bd2cb0c622a318c95574ff.mp3", "duration_ms": 22080}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/41f32a750354874601d370ffc8777dcc994a6cffeacf5f25453e8e27b615adda.mp3", "hash": "8606f5d851ed32d805c7c196ff388673e3fcf920fdd464eff02031bc1ab31915", "bytes": 81936, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/41f32a750354874601d370ffc8777dcc994a6cffeacf5f25453e8e27b615adda.mp3", "duration_ms": 13600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'en-US', '1', E'{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "order-steps", "title": "Order the stand purchases", "locale": "en-US", "subject": "money", "objectives": ["Order market purchases by sales priority: first what generates profit today, then what improves sales, and finally luxury."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-compras", "xp": 10, "type": "order_steps", "hints": ["Ask yourself: can I sell lemonade TODAY without this?", "What makes money today goes first, what is just a treat goes last."], "title": "Order the stand purchases", "payload": {"items": [{"id": "limones", "text_md": "Lemons — 8 pesos"}, {"id": "vasos", "text_md": "Cups — 6 pesos"}, {"id": "azucar", "text_md": "Sugar — 4 pesos"}, {"id": "calcomanias", "text_md": "Stickers — 2 pesos"}]}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Liruf has **20 pesos** and needs to buy these 4 things for his lemonade stand. **Order them from the MOST necessary to sell today to the one that can wait.**\\n\\n- Lemons (without them, no lemonade)\\n- Cups (without them, you can''t serve)\\n- Sugar (to make it taste good so they come back)\\n- Stickers (to decorate, but not urgent)", "difficulty": 1, "explanation_md": "First the lemons (without them, no lemonade), then the cups (to serve it), then the sugar (improves taste), and finally the stickers (a luxury that can wait).", "audio_segment_id": "s1-ordenar-compras.prompt"}], "schema_version": 1}', '{"s1-ordenar-compras": {"order": ["limones", "vasos", "azucar", "calcomanias"]}}', '{"units": {"s1-ordenar-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c9dd9cb44cd8019c5a085019056d0351286b7c149b47229ddd9aec4ebf84521b.mp3", "hash": "fcf06c29ca375ded1402ed1535dc538559c8be3b15206a9a9e11624fdf71ebd5", "bytes": 21456, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/c9dd9cb44cd8019c5a085019056d0351286b7c149b47229ddd9aec4ebf84521b.mp3", "duration_ms": 3520}, "s1-ordenar-compras.hint.1": {"url": "http://localhost:4006/files/lesson-audio/be4f17981326b945e2bc86aecc9737e6bf0ab594f5f35bd33e9f199031e22083.mp3", "hash": "af12377a85aa7654d6c64f522aa8f8feeb232988a0addcbe042810b17d76849c", "bytes": 27648, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/be4f17981326b945e2bc86aecc9737e6bf0ab594f5f35bd33e9f199031e22083.mp3", "duration_ms": 4560}, "s1-ordenar-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/d81c2a5f61089d42c220f73a904904e7bb4334b6d0b19a4c986b01112f5f3f43.mp3", "hash": "fc0cb34ba7da3b1451bd73b9dd7df382c1474f18325018ac9da33dbdd4bb323a", "bytes": 119376, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/d81c2a5f61089d42c220f73a904904e7bb4334b6d0b19a4c986b01112f5f3f43.mp3", "duration_ms": 19840}, "s1-ordenar-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/e714862f641bec1c59ce180a397a44301e1a82800c6d83fe88752a4f87201b35.mp3", "hash": "304a86bf37813b2747a11889f123680d73f7fc4d5704d8a612e1e0abdde9f7c2", "bytes": 66096, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/e714862f641bec1c59ce180a397a44301e1a82800c6d83fe88752a4f87201b35.mp3", "duration_ms": 10960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fill-blank", "title": "Completar as contas da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Completar frases numéricas sobre lucros usando adição e subtração simples."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia", "xp": 10, "type": "fill_blank", "hints": ["Subtraia o custo dos ingredientes do preço do copo."], "title": "O lucro de Liruf", "payload": {"bank": [{"id": "b1", "text_md": "3"}, {"id": "b2", "text_md": "2"}, {"id": "b3", "text_md": "5"}, {"id": "b4", "text_md": "7"}], "mode": "typed", "text_md": "Vendi um copo por 5 reais, os ingredientes custaram 2, meu lucro é {{1}} reais."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf quer economizar para um skate que custa 10 reais. Já economizou 3 reais. Hoje vendeu um copo de limonada por 5 reais, mas os ingredientes custaram 2 reais. Quanto dinheiro ele pode ECONOMIZAR dessa venda?", "difficulty": 1, "explanation_md": "Liruf ganhou 3 reais (5 - 2 = 3). Esse dinheiro ele pode economizar para o skate. Agora ele tem 3 + 3 = 6 reais! Se você escolheu 2, confundiu o custo com o lucro. Se escolheu 5, esqueceu de subtrair o custo. Se escolheu 7, somou em vez de subtrair.", "audio_segment_id": "s1-ganancia.prompt"}], "schema_version": 1}', '{"s1-ganancia": {"gaps": [{"gap": 1, "accept": ["3"], "bank_id": "b1"}]}}', '{"units": {"s1-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/05b01458d3f00d1ec323f0f7f296def344562695b47f0dc5940bd89b877ad8fc.mp3", "hash": "f1e6f23316f7979bc177667229884af29fe4de510743abbb18dcb69df3ed448e", "bytes": 21888, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/05b01458d3f00d1ec323f0f7f296def344562695b47f0dc5940bd89b877ad8fc.mp3", "duration_ms": 3600}, "s1-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/82a906525b2651eebe0b41f10613c2eebb83e31bdfa8d2763c49840496237d0b.mp3", "hash": "03565e09d795e4c5e6a7075c1964f85b1725451b7ddba65861e8fd1b4f98d75f", "bytes": 101664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/82a906525b2651eebe0b41f10613c2eebb83e31bdfa8d2763c49840496237d0b.mp3", "duration_ms": 16880}, "s1-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/2a5ce9cba64cd25971be1f8d687e01c53c9e39c05724a14ab4c0818b71d1684a.mp3", "hash": "1158e56a11bc182e356617430ea2e0e6a6f7e1d46fe89db9337ffe68fa65d800", "bytes": 134784, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2a5ce9cba64cd25971be1f8d687e01c53c9e39c05724a14ab4c0818b71d1684a.mp3", "duration_ms": 22400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "count-objects", "title": "Cuenta las monedas de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Contar de un vistazo cuántas monedas cayeron del frasco volcado, sin recontar", "Entender que cada moneda representa un vaso de 5 pesos vendido", "Relacionar el conteo con la suma hacia la meta de 80 pesos"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-count-coins", "xp": 10, "type": "count_objects", "hints": ["Busca solo las monedas con el símbolo de dinero, ignora las galletas y el vaso.", "Cuenta en voz baja mientras tocas cada moneda."], "title": "Cuenta las monedas", "payload": {"scene": [{"icon": "monetization_on", "tint": "primary", "count": 7}, {"icon": "cookie", "tint": "warning", "count": 3}, {"icon": "local_drink", "tint": "accent", "count": 1}], "ask_icon": "monetization_on"}, "narrator": {"emotion": "surprised", "character": "liruf"}, "prompt_md": "Liruf estimó que de la jarra saldrían unos 8 vasos de limonada. ¡Pero se le cayó el frasco de las ventas! Las monedas rodaron entre las migas de galleta. Toca cada moneda para contarlas. ¿Cuántas monedas hay? Así sabremos si vendió más o menos de los 8 vasos que estimó.", "difficulty": 1, "explanation_md": "Hay 7 monedas. Liruf estimó ~8 vasos, pero solo vendió 7. Cada moneda es un vaso de 5 pesos. ¡Eso suma 35 pesos para la guitarra de 80!", "audio_segment_id": "s1-count-coins.prompt"}], "schema_version": 1}', '{"s1-count-coins": {"value": 7}}', '{"units": {"s1-count-coins.hint.0": {"url": "http://localhost:4006/files/lesson-audio/43509145e8c6a73b42a26d462a46d65f37b602aeaef4ebfb5b0463d3c0add809.mp3", "hash": "32010888c2d98e6902ae27df22b3570b228003fcd7b70e0fe3b68d6f43f884a1", "bytes": 31968, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/43509145e8c6a73b42a26d462a46d65f37b602aeaef4ebfb5b0463d3c0add809.mp3", "duration_ms": 5280}, "s1-count-coins.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0fade15b9a28ebdb04212aa647bea89b4a565a19c6bca495be998c5ce7f64f3f.mp3", "hash": "30c4c48118d3af7120532ae1f2f136b83d5ea848fcd83989f14f3bea7107c9e0", "bytes": 20448, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/0fade15b9a28ebdb04212aa647bea89b4a565a19c6bca495be998c5ce7f64f3f.mp3", "duration_ms": 3360}, "s1-count-coins.prompt": {"url": "http://localhost:4006/files/lesson-audio/cd44513098a673ef8671f6f34d044ce3d670b5f07916e97d678740d53ad2d566.mp3", "hash": "da125eb73dfe9b6bd31a49c82f5994b6ad2bfb96adfd401ba1fb431e53126131", "bytes": 108864, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/cd44513098a673ef8671f6f34d044ce3d670b5f07916e97d678740d53ad2d566.mp3", "duration_ms": 18080}, "s1-count-coins.explanation": {"url": "http://localhost:4006/files/lesson-audio/316f71f18237830dc51f99728cc77c0ea98673c131376e21246966fa2685d389.mp3", "hash": "7229222a8b9ee4fbae05aa2c43a35510c1fab1561146d6489bac247d7a4cab26", "bytes": 75168, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/316f71f18237830dc51f99728cc77c0ea98673c131376e21246966fa2685d389.mp3", "duration_ms": 12480}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-dinero", "title": "Close the Sunday cash box", "locale": "en-US", "subject": "mixed", "objectives": ["Count 1, 5, and 10 coins to find the day''s total sales.", "Calculate the correct change when paying with a 20-peso bill for a 5-peso glass.", "Determine how many more Sundays you need to save 20 pesos to reach 80."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-contar-monedas", "xp": 10, "type": "coin_count", "hints": ["Start with the 10-peso coins, then the 5-peso coins, and finally the 1-peso coins."], "title": "Close the cash box", "payload": {"target": 20, "currency": "MXN", "denominations": [1, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Do you remember the two customers from yesterday? They came back today and paid with these coins. Dina is worried: if they don''t collect 20 pesos, they won''t be able to buy the cups for Sunday. Help her count the coins. Tap each coin to add them up.", "difficulty": 1, "explanation_md": "The coins add up to 20 pesos: one 10-peso coin, two 5-peso coins, and five 1-peso coins. Just what they needed for the cups! Dina smiles with relief.", "audio_segment_id": "s1-contar-monedas.prompt"}, {"id": "s2-cambio-cliente", "xp": 10, "type": "make_change", "hints": ["If she paid with 20 and the glass costs 5, how much is left over?"], "title": "Give change", "payload": {"price": 5, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "The customer from yesterday returns and asks for a 5-peso glass. She pays with a 20-peso bill. Dina is nervous: if you give the wrong change, the customer will get angry and won''t come back. How much change do you need to give her?", "difficulty": 1, "explanation_md": "The change is 15 pesos: 20 minus 5 is 15. The customer smiles and says she''ll come back on Sunday. Well done!", "audio_segment_id": "s2-cambio-cliente.prompt"}, {"id": "s3-ahorro-guitarra", "xp": 15, "type": "savings_goal", "hints": ["First, calculate how much he needs: 80 minus 40 is 40.", "Then divide what he needs by what he saves each Sunday: 40 divided by 20."], "title": "How many Sundays are left?", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [20]}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "Liruf wants to buy a guitar that costs 80 pesos. He already has 40 in his piggy bank. Every Sunday he earns 20 pesos selling lemonade. Dina says: ''If you save it all, how many more Sundays do you need for the guitar?'' Help Liruf figure it out.", "difficulty": 2, "explanation_md": "He needs 40 pesos and saves 20 each Sunday, so he needs 2 more Sundays. Liruf will be playing the guitar very soon!", "audio_segment_id": "s3-ahorro-guitarra.prompt"}], "schema_version": 1}', '{"s1-contar-monedas": {}, "s2-cambio-cliente": {}, "s3-ahorro-guitarra": {"correct": {"20": 4}}}', '{"units": {"s1-contar-monedas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/459c3ff3ebe225c8dab26519c9dd234ab2b1d5a7e64bcc1b436af657179c0556.mp3", "hash": "23e7e8d33e070feeb9438a7b9fc7e2fb4d0940840a821a06d10cd16fa2a08812", "bytes": 32976, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/459c3ff3ebe225c8dab26519c9dd234ab2b1d5a7e64bcc1b436af657179c0556.mp3", "duration_ms": 5440}, "s1-contar-monedas.prompt": {"url": "http://localhost:4006/files/lesson-audio/001783fb1a86fd181cc1089c0f028666aefe4fdd44932870cf7d2d7fe9e15353.mp3", "hash": "afccf9b4f542fdbe4729e20614d30cae91b0170e70693d0cfe3c998ac7f272bf", "bytes": 81504, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/001783fb1a86fd181cc1089c0f028666aefe4fdd44932870cf7d2d7fe9e15353.mp3", "duration_ms": 13520}, "s2-cambio-cliente.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4346b47037ce0a6ac55e021c734f240e89349ce364e030de87648e071522de13.mp3", "hash": "c2d79dbb24b98e5bd5f5216a1b57e95158642e292a77cd4372e8916d1cd1c4f3", "bytes": 23328, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4346b47037ce0a6ac55e021c734f240e89349ce364e030de87648e071522de13.mp3", "duration_ms": 3840}, "s2-cambio-cliente.prompt": {"url": "http://localhost:4006/files/lesson-audio/880e3db18c8db7b56462b90a696217cd0b20dce621e8c2fadb4096a5dd19ecb5.mp3", "hash": "dbf934b0c8e0a120d3ca30d186c3c3503c7c5d1b067ba47071f8bfaa3690a2ef", "bytes": 73728, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/880e3db18c8db7b56462b90a696217cd0b20dce621e8c2fadb4096a5dd19ecb5.mp3", "duration_ms": 12240}, "s3-ahorro-guitarra.hint.0": {"url": "http://localhost:4006/files/lesson-audio/bc4db224bd251883825588c8633405f57b5ea8d36b157fba81e675da89d659ed.mp3", "hash": "db9b66699a92b4cfa0e8e0700f3707203ed2b204cf7d4ed1d371138171dd57bd", "bytes": 26208, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/bc4db224bd251883825588c8633405f57b5ea8d36b157fba81e675da89d659ed.mp3", "duration_ms": 4320}, "s3-ahorro-guitarra.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a884b6eb40e2aa360c0bd317ebbab84f59ab86f791eb4a5c176117ed1130fe3d.mp3", "hash": "8651daa745d1e10e284611747fb6b2bac3e165af31d1071320e988bf0bc95b4c", "bytes": 30096, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/a884b6eb40e2aa360c0bd317ebbab84f59ab86f791eb4a5c176117ed1130fe3d.mp3", "duration_ms": 4960}, "s3-ahorro-guitarra.prompt": {"url": "http://localhost:4006/files/lesson-audio/5c7c8fe824641121a72e6b0b271ef75a209e0b2e36f0961c185c96949de9db6c.mp3", "hash": "08c4b65614049c647b349d0d1fe60cf35216655a9244ecf7ea099168b993c3b4", "bytes": 91008, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/5c7c8fe824641121a72e6b0b271ef75a209e0b2e36f0961c185c96949de9db6c.mp3", "duration_ms": 15120}, "s1-contar-monedas.explanation": {"url": "http://localhost:4006/files/lesson-audio/05668119862f5eec228f9a973391c3efcb121a408e3dd5d8e01569c306e1c5c9.mp3", "hash": "6e916657916dfca86b438cbf7ea7044d37575a8652f80c9d9b812023323ecc9c", "bytes": 64656, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/05668119862f5eec228f9a973391c3efcb121a408e3dd5d8e01569c306e1c5c9.mp3", "duration_ms": 10720}, "s2-cambio-cliente.explanation": {"url": "http://localhost:4006/files/lesson-audio/7b263f7282e57752ae97e6cf5b5309623a21c10649be114a42a4206be68a983b.mp3", "hash": "a3fb3fbcb8e8ee4e425a0e909d7daee61e4aba490b7225ef7a5ecec996d89ae9", "bytes": 43056, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/7b263f7282e57752ae97e6cf5b5309623a21c10649be114a42a4206be68a983b.mp3", "duration_ms": 7120}, "s3-ahorro-guitarra.explanation": {"url": "http://localhost:4006/files/lesson-audio/a9fb3a8c5e3aed13fc7ca425a853827f2333af181086f62b091779c3e1459193.mp3", "hash": "dfe23478ac6d06ccd349a606ef8e88b318619242ec806461627243d9740afe9a", "bytes": 49248, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/a9fb3a8c5e3aed13fc7ca425a853827f2333af181086f62b091779c3e1459193.mp3", "duration_ms": 8160}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "checkpoint", "title": "La noche antes de abrir", "locale": "es-MX", "subject": "mixed", "objectives": ["Repasar la meta de la guitarra de 80 pesos, el precio de la limonada a 5 pesos el vaso, y que la ganancia es lo que sobra tras pagar el costo.", "Cerrar con un enganche emocional: ¿qué tan cerca se siente la guitarra?"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "hints": [], "title": "La noche antes de abrir", "payload": {"recap_md": "La meta está pegada en la pared: guitarra, 80 pesos. El cartel de la limonada dice 5 pesos el vaso. Y el secreto que aprendieron: de cada vaso, lo que sobra después del costo es la ganancia que empuja el frasco hacia los 80.", "mood_prompt_md": "Liruf mira el frasco vacío y sonríe. Dina le pregunta: ''¿qué tan cerca sientes ya esa guitarra?''"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina se sienta junto a Liruf y su frasco vacío de la guitarra. En vez de un examen, señalan las tres cosas que ya tienen listas.", "difficulty": 1, "explanation_md": "Liruf respira: la idea ya no es solo un sueño, mañana se prueba de verdad.", "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/485bee4844284cc28d09635cf1121b68a6cf40b92407dce67d7fd39081c327e1.mp3", "hash": "328d33fe106ff47df1ce8a432302c9963b212e62a9de61b19f297fce534fbbd8", "bytes": 98784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/485bee4844284cc28d09635cf1121b68a6cf40b92407dce67d7fd39081c327e1.mp3", "duration_ms": 16400}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/d0b5071f58cfd044c9a6cdaabe15c927538db246c845e1dc8794c66b1389f43d.mp3", "hash": "acf77c0e6f39e4978ba99c5d48561186358dd2ce3149cfe42aeb5bcf71c93d93", "bytes": 52704, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d0b5071f58cfd044c9a6cdaabe15c927538db246c845e1dc8794c66b1389f43d.mp3", "duration_ms": 8720}, "s1-checkpoint.explanation": {"url": "http://localhost:4006/files/lesson-audio/26aae39121d0fc7719e6b0922c0a070e18c77089961d0eeb17652573d62855d2.mp3", "hash": "6b9cbf09da5b0938ad65efd3e08794a213506f3fad36c269dbed96db7744aaff", "bytes": 34416, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/26aae39121d0fc7719e6b0922c0a070e18c77089961d0eeb17652573d62855d2.mp3", "duration_ms": 5680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "number-line", "title": "A reta da economia", "locale": "pt-BR", "subject": "mixed", "objectives": ["Localizar na reta numérica de 0 a 100 onde está a economia de Liruf (20 reais) e onde está a meta (80): ver quanto falta."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 10, "type": "number_line", "hints": ["A economia de Liruf está mais perto do 0 do que da meta.", "Conte de 10 em 10 a partir de 0: 10, 20, 30… até 80."], "title": "Marque a economia e a meta", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": false}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf juntou 20 reais agrupando moedas como você aprendeu. Ela já está quase chegando ao skate de 80 reais! Mas se marcar errado na reta, vai pensar que já tem o suficiente. Ajude-a: primeiro marque onde está a economia dela (20) e depois onde está a meta (80). Assim ela saberá quanto falta.", "difficulty": 1, "explanation_md": "Liruf tem 20 reais economizados e a meta dela são 80 reais. Na reta, 20 está mais perto do 0 e 80 mais longe. Faltam 60 reais para ela chegar ao skate!", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 20, "full_credit_delta": 5, "zero_credit_delta": 15}}', '{"units": {"s1-number-line.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ac776c5162c3d72c03cae95a910e5d505d7ebea1814f394a48a5ac8fbfb2c79f.mp3", "hash": "a12e3015cf49e4e26257b705721e794fa9b8ed71cb11db0f2b591a9f13882f7c", "bytes": 26208, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/ac776c5162c3d72c03cae95a910e5d505d7ebea1814f394a48a5ac8fbfb2c79f.mp3", "duration_ms": 4320}, "s1-number-line.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c3ebc0793724c1739ed2e34cde6f37d7cc9d8a9f6262c9f987c991c691894bc1.mp3", "hash": "29deecee83b347d9e279e77fd8f9dfe5a287e5f6f19963aad296be8fe5e3c351", "bytes": 39168, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/c3ebc0793724c1739ed2e34cde6f37d7cc9d8a9f6262c9f987c991c691894bc1.mp3", "duration_ms": 6480}, "s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/e0f66dfa2a9775fd8923c7c3b6baaa17a1d9fa9131b5feb2069e7ec6804e971a.mp3", "hash": "0a18042b3915e289cbb42a01c4b732384edeb4ea32fd29abe8e6195c2d50603d", "bytes": 138528, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/e0f66dfa2a9775fd8923c7c3b6baaa17a1d9fa9131b5feb2069e7ec6804e971a.mp3", "duration_ms": 23040}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/763df717456672b68d5140f80c3b655f03252f850590c79ed1868bba7a88d6b5.mp3", "hash": "4f2bb061aced8256fca5758406fc434870e3b44efbd6d2cc2cedbeea06d26c51", "bytes": 83376, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/763df717456672b68d5140f80c3b655f03252f850590c79ed1868bba7a88d6b5.mp3", "duration_ms": 13840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'en-US', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "estimate-slider", "title": "Estimate how many glasses come out of the pitcher", "locale": "en-US", "subject": "mixed", "objectives": ["Estimate quantities using a slider bar", "Relate the size of a pitcher to the number of glasses it can fill"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-jar", "xp": 8, "type": "estimate_slider", "hints": ["Think: Liruf''s pitcher filled 4 glasses. Zara''s is twice as big, so it can fill more glasses.", "If twice 4 is 8, then Zara''s pitcher could fill about 8 glasses."], "title": "How many glasses come out of the pitcher?", "payload": {"max": 20, "min": 1, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Liruf sold 4 glasses of lemonade at 5 pesos each and earned 20 pesos. Now Zara wants to sell lemonade like Liruf. Her pitcher is much bigger than Liruf''s: Liruf''s pitcher filled 4 glasses, but Zara''s looks twice as big. If each glass sells for 5 pesos, how much could Zara earn if she sells all the glasses? First, slide the bar to estimate how many glasses come out of Zara''s pitcher.", "difficulty": 1, "explanation_md": "Exactly! Zara''s pitcher is twice as big as Liruf''s, so it fills about 8 glasses. If she sells each glass for 5 pesos, she would earn 8 × 5 = 40 pesos. That''s twice what Liruf earned!", "audio_segment_id": "s1-estimate-jar.prompt"}], "schema_version": 1}', '{"s1-estimate-jar": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 6}}', '{"units": {"s1-estimate-jar.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a87f4b63b5d8f40892301396f0df7244a339b9700cb2b24902bd25343a9f9588.mp3", "hash": "f9308789c71070667cd173cdb5e05fcc89f38bd57dfccc296533af6ad79af1d4", "bytes": 41616, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/a87f4b63b5d8f40892301396f0df7244a339b9700cb2b24902bd25343a9f9588.mp3", "duration_ms": 6880}, "s1-estimate-jar.hint.1": {"url": "http://localhost:4006/files/lesson-audio/854dfd075ccf4c79bc4450748d576699bf95ef6ddd19dc3b6233ff3168637b38.mp3", "hash": "75ff1c77e04fbefd8117f91ce8781e7a7d7842ca20805f1b0544d6beff26677a", "bytes": 31968, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/854dfd075ccf4c79bc4450748d576699bf95ef6ddd19dc3b6233ff3168637b38.mp3", "duration_ms": 5280}, "s1-estimate-jar.prompt": {"url": "http://localhost:4006/files/lesson-audio/96eee59d2c3784487db08b97135e49c1af8f998f1eee5cffe19198e909951bf7.mp3", "hash": "c0c2433d8e772ff95ee7a41a7d3a94142a6d51883703b1c436361a852ce117c7", "bytes": 151056, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/96eee59d2c3784487db08b97135e49c1af8f998f1eee5cffe19198e909951bf7.mp3", "duration_ms": 25120}, "s1-estimate-jar.explanation": {"url": "http://localhost:4006/files/lesson-audio/4e75b09ee5fb039dd0b44e54656e1fcf8a08973e9d3881064d9aa3f9ec4ba5ed.mp3", "hash": "226a187d9d8885007f9a62113cbfb83f80e64dbd819848d564011ca49cfc39e6", "bytes": 79488, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/4e75b09ee5fb039dd0b44e54656e1fcf8a08973e9d3881064d9aa3f9ec4ba5ed.mp3", "duration_ms": 13200}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "machine-io", "title": "La máquina de propinas", "locale": "es-MX", "subject": "mixed", "objectives": ["Descubrir que la máquina duplica la entrada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 10, "type": "machine_io", "hints": ["Observa: 1 → 2, 3 → 6. ¿Qué operación se repite?"], "title": "La máquina de propinas", "payload": {"options": [{"id": "opt1", "text_md": "7"}, {"id": "opt2", "text_md": "10"}, {"id": "opt3", "text_md": "8"}], "examples": [{"in": 1, "out": 2}, {"in": 3, "out": 6}], "probe_in": 5}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Al igual que Dina midió con precisión en la jarra, ahora observa cómo la máquina transforma cantidades. La abuela de Dina tiene una maquinita misteriosa. Si metes 1 moneda, ¡salen 2! Si metes 3, salen 6. ¿Cuántas salen si metes 5?", "difficulty": 1, "explanation_md": "La máquina duplica lo que entra: 5 × 2 = 10. Por eso salen 10 monedas.", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 10, "correct_option_id": "opt2"}}', '{"units": {"s1-machine-io.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d4430ca29a3035b6ee99e6348310b2bf9367501174c4347e1803c29e5d6d4705.mp3", "hash": "a88a01aa084bc236484abe15ff293e65d49d92ac17d24e2d225fb954b12868ba", "bytes": 37296, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d4430ca29a3035b6ee99e6348310b2bf9367501174c4347e1803c29e5d6d4705.mp3", "duration_ms": 6160}, "s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/87a14e20d4b4ea4c15bc35078d984a5fc404a0cd02af194868939b9a3ef39a1f.mp3", "hash": "c20a8770c05fe4434bf70d5d1bb8c947b22af3969aa25e018e0dd75a28fee371", "bytes": 103968, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/87a14e20d4b4ea4c15bc35078d984a5fc404a0cd02af194868939b9a3ef39a1f.mp3", "duration_ms": 17280}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/0e9e14c55428bf601fccdb55a8bdc232138dbc75ffd980a48792e6a4b1b01b27.mp3", "hash": "60afeb033fac57028914ed2410f8d2382c3e59d1ce9404dd4a4fa27498eb51ed", "bytes": 41184, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0e9e14c55428bf601fccdb55a8bdc232138dbc75ffd980a48792e6a4b1b01b27.mp3", "duration_ms": 6800}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dialogo-doble-choice", "title": "Un día real del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Escuchar una conversación entre clientes sobre el puesto de limonada", "Identificar si una afirmación sobre la conversación es verdadera o falsa", "Elegir la imagen correcta que corresponde a la conversación"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo-clientes", "xp": 0, "type": "story_dialogue", "hints": [], "title": "Vecinos opinan del puesto", "payload": {"lines": [{"action": "idle", "emotion": "neutral", "text_md": "Mira, el puesto de limonada de Liruf. El vaso cuesta 5 pesos, ¿no?", "character": "rho"}, {"action": "idle", "emotion": "happy", "text_md": "Sí, y está bien fría. Ayer compré uno y me encantó.", "character": "zara"}, {"action": "idle", "emotion": "surprised", "text_md": "¿Solo 5 pesos? ¡Qué ganga! Con 10 pesos me compro dos.", "character": "rho"}, {"action": "idle", "emotion": "encouraging", "text_md": "Exacto. Y si pagas con 20, te dan 15 de cambio.", "character": "zara"}, {"action": "idle", "emotion": "proud", "text_md": "(Escucha sonriente) ¡Qué bien que les guste mi limonada!", "character": "liruf"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Ayer decidiste que el precio sería 5 pesos. Hoy, escucha lo que dicen los vecinos sobre tu puesto.", "difficulty": 1, "explanation_md": "Liruf escucha atento lo que dicen los vecinos sobre su puesto de limonada.", "audio_segment_id": "s1-dialogo-clientes.prompt"}, {"id": "s2-verdadero-falso", "xp": 10, "type": "true_false", "hints": ["Cada vaso cuesta 5 pesos. ¿Cuánto cuestan dos vasos?"], "title": "¿Cierto o falso?", "payload": {"statement_md": "Con 10 pesos puedes comprar dos vasos de limonada.", "justifications": [{"id": "j1", "text_md": "Es verdad, porque cada vaso cuesta 5 pesos y 5+5=10."}, {"id": "j2", "text_md": "Es falso, porque cada vaso cuesta 5 pesos y 5+5=10, pero no alcanza."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Según la conversación, Rho dice: ''Con 10 pesos me compro dos vasos''. ¿Es verdad que con 10 pesos alcanza para dos vasos?", "difficulty": 1, "explanation_md": "Dos vasos cuestan 5 + 5 = 10 pesos. ¡Sí alcanza! La afirmación es verdadera.", "audio_segment_id": "s2-verdadero-falso.prompt"}, {"id": "s3-eleccion-imagen", "xp": 10, "type": "picture_choice", "hints": ["El vaso cuesta 5 pesos. Si pagas con 20, ¿cuánto te sobra?"], "title": "Elige la imagen correcta", "payload": {"options": [{"id": "opt1", "icon": "monetization_on", "label": "15 pesos", "image_url": "http://localhost:4006/files/lesson-images/39cba6776663f9980ee6f2193dcb061e955be6fad1009f8164bc9bcb8b403ccf.png"}, {"id": "opt2", "icon": "monetization_on", "label": "10 pesos", "image_url": "http://localhost:4006/files/lesson-images/5c0865eee4b9d624201a489a58d597b5c72ebb0d520f2b7e491bc5254d18c924.png", "rationale_md": "Puede que hayas restado 20 menos 10, pero el precio es 5, no 10. El cambio correcto es 15."}, {"id": "opt3", "icon": "monetization_on", "label": "5 pesos", "image_url": "http://localhost:4006/files/lesson-images/c980ecfc0eb971bd7fbcb29004a4c0a1bba2db2f4a268b11d80ae7ed0090be46.png", "rationale_md": "5 pesos es el precio del vaso, no el cambio. El cambio es 20 menos 5 = 15."}]}, "narrator": {"emotion": "happy", "character": "liruf"}, "prompt_md": "Rho da 20 pesos por un vaso. ¿Cuánto cambio debe recibir? Elige la imagen que muestra la cantidad correcta.", "difficulty": 1, "explanation_md": "El vaso cuesta 5 pesos. Si pagas con 20, el cambio es 20 menos 5 = 15 pesos.", "audio_segment_id": "s3-eleccion-imagen.prompt"}], "schema_version": 1}', '{"s2-verdadero-falso": {"is_true": true, "correct_justification_id": "j1"}, "s3-eleccion-imagen": {"correct_option_id": "opt1"}}', '{"units": {"s2-verdadero-falso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a0cd3e3d8766e1e5b3b74b7e97b5a210e96870309731f81c77b9992005e507b8.mp3", "hash": "b04615dd03afc60490fe203f7768f3c72841c5ebac1d5d76f90ba745c65a00ed", "bytes": 30528, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/a0cd3e3d8766e1e5b3b74b7e97b5a210e96870309731f81c77b9992005e507b8.mp3", "duration_ms": 5040}, "s2-verdadero-falso.prompt": {"url": "http://localhost:4006/files/lesson-audio/175ea2962387c747edb5f646e9aae70dda4bf0fb1811c25989614a3098419788.mp3", "hash": "507965abc892375bcf2113ab6f53d78e38aebe167ed1cb1357db216eca869110", "bytes": 53568, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/175ea2962387c747edb5f646e9aae70dda4bf0fb1811c25989614a3098419788.mp3", "duration_ms": 8880}, "s3-eleccion-imagen.hint.0": {"url": "http://localhost:4006/files/lesson-audio/60cb935d39835169396fb75d02bd0a71651bd219ddd58ecaac91b7790820a4d0.mp3", "hash": "0335c02229048ec8b591920a774fc3957026d3d8311b1efda082e1248b5cfd8d", "bytes": 35424, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/60cb935d39835169396fb75d02bd0a71651bd219ddd58ecaac91b7790820a4d0.mp3", "duration_ms": 5840}, "s3-eleccion-imagen.prompt": {"url": "http://localhost:4006/files/lesson-audio/b8e1333202fec2de197cd9fad59444410773900de88de55c2543acfb6a501bad.mp3", "hash": "ba42724494ff9ec1578b836e34b5fcb0bc0c3f08c8a006d099356d11382aa171", "bytes": 48384, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/b8e1333202fec2de197cd9fad59444410773900de88de55c2543acfb6a501bad.mp3", "duration_ms": 8000}, "s1-dialogo-clientes.line.0": {"url": "http://localhost:4006/files/lesson-audio/bb5c7d6ff7951822bf783294faf7a3dbacfa7460e729687e73ba3c0ec23bd0d6.mp3", "hash": "2d6be18c5998daab1af1de6cb