files/lesson-audio/de0faf7dc8002d4dac155d0f390da4220228459c882a454c66cf4f08ad50ffdf.mp3", "hash": "dff194213ed5b5ac8e90a0141592cb643db04cb799ff9335e88afe950f78c690", "bytes": 44928, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/de0faf7dc8002d4dac155d0f390da4220228459c882a454c66cf4f08ad50ffdf.mp3", "duration_ms": 7440}, "s3-eleccion-imagen.choices": {"url": "http://localhost:4006/files/lesson-audio/d75e17ad9f2f40521be69a5fa097e055101c2ba35572b8ddd0125a01165485d7.mp3", "hash": "0bbae0961b2951725d9590f23452e12b48d5b3cb4a76c412e2d677483270f621", "bytes": 25776, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/d75e17ad9f2f40521be69a5fa097e055101c2ba35572b8ddd0125a01165485d7.mp3", "duration_ms": 4240}, "s2-verdadero-falso.explanation": {"url": "http://localhost:4006/files/lesson-audio/f4e00542f613e414c42698e7aee1673c2c2748daa015c1d2175b2a58cdd00b06.mp3", "hash": "a73c252538fcae826564e1568a03b7c92bd2dfb4277faf2050ff52d4a7e3fc74", "bytes": 51696, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/f4e00542f613e414c42698e7aee1673c2c2748daa015c1d2175b2a58cdd00b06.mp3", "duration_ms": 8560}, "s3-eleccion-imagen.explanation": {"url": "http://localhost:4006/files/lesson-audio/32cda8c1cbf3862c538cd04d1bd3e69abc8ccdf1888907d27792384628579ec8.mp3", "hash": "079d50e5f294e67fdd303db2d5a731ca5d14c58c027ae960d803c47974ea7262", "bytes": 45504, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/32cda8c1cbf3862c538cd04d1bd3e69abc8ccdf1888907d27792384628579ec8.mp3", "duration_ms": 7520}, "s1-dialogo-clientes.explanation": {"url": "http://localhost:4006/files/lesson-audio/ac520d307d30018c1fa25de9b3e3b8402e71d0fc5672f57234f8caa276cb9a7c.mp3", "hash": "2c4454ff0be55d9201f6b0c0e6cf78913f1aedb78f1f9c5e5e4e4d4d57f75d26", "bytes": 29088, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/ac520d307d30018c1fa25de9b3e3b8402e71d0fc5672f57234f8caa276cb9a7c.mp3", "duration_ms": 4800}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dialogo-doble-choice", "title": "A real day at the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Listen to a conversation between customers about the lemonade stand", "Identify whether a statement about the conversation is true or false", "Choose the correct picture that matches the conversation"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo-clientes", "xp": 0, "type": "story_dialogue", "hints": [], "title": "Neighbors talk about the stand", "payload": {"lines": [{"action": "idle", "emotion": "neutral", "text_md": "Look, Liruf''s lemonade stand. The cup costs 5 pesos, right?", "character": "rho"}, {"action": "idle", "emotion": "happy", "text_md": "Yes, and it''s very cold. Yesterday I bought one and I loved it.", "character": "zara"}, {"action": "idle", "emotion": "surprised", "text_md": "Only 5 pesos? What a bargain! With 10 pesos I can buy two.", "character": "rho"}, {"action": "idle", "emotion": "encouraging", "text_md": "Exactly. And if you pay with 20, they give you 15 in change.", "character": "zara"}, {"action": "idle", "emotion": "proud", "text_md": "(Listens smiling) How nice that they like my lemonade!", "character": "liruf"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Yesterday you decided the price would be 5 pesos. Today, listen to what the neighbors say about your stand.", "difficulty": 1, "explanation_md": "Liruf listens carefully to what the neighbors say about his lemonade stand.", "audio_segment_id": "s1-dialogo-clientes.prompt"}, {"id": "s2-verdadero-falso", "xp": 10, "type": "true_false", "hints": ["Each cup costs 5 pesos. How much do two cups cost?"], "title": "True or false?", "payload": {"statement_md": "With 10 pesos you can buy two cups of lemonade.", "justifications": [{"id": "j1", "text_md": "It''s true, because each cup costs 5 pesos and 5+5=10."}, {"id": "j2", "text_md": "It''s false, because each cup costs 5 pesos and 5+5=10, but it''s not enough."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "According to the conversation, Rho says: ''With 10 pesos I can buy two cups.'' Is it true that 10 pesos is enough for two cups?", "difficulty": 1, "explanation_md": "Two cups cost 5 + 5 = 10 pesos. Yes, it''s enough! The statement is true.", "audio_segment_id": "s2-verdadero-falso.prompt"}, {"id": "s3-eleccion-imagen", "xp": 10, "type": "picture_choice", "hints": ["The cup costs 5 pesos. If you pay with 20, how much is left over?"], "title": "Choose the correct picture", "payload": {"options": [{"id": "opt1", "icon": "monetization_on", "label": "15 pesos", "image_url": "http://localhost:4006/files/lesson-images/39cba6776663f9980ee6f2193dcb061e955be6fad1009f8164bc9bcb8b403ccf.png"}, {"id": "opt2", "icon": "monetization_on", "label": "10 pesos", "image_url": "http://localhost:4006/files/lesson-images/5c0865eee4b9d624201a489a58d597b5c72ebb0d520f2b7e491bc5254d18c924.png", "rationale_md": "You might have subtracted 20 minus 10, but the price is 5, not 10. The correct change is 15."}, {"id": "opt3", "icon": "monetization_on", "label": "5 pesos", "image_url": "http://localhost:4006/files/lesson-images/c980ecfc0eb971bd7fbcb29004a4c0a1bba2db2f4a268b11d80ae7ed0090be46.png", "rationale_md": "5 pesos is the price of the cup, not the change. The change is 20 minus 5 = 15."}]}, "narrator": {"emotion": "happy", "character": "liruf"}, "prompt_md": "Rho gives 20 pesos for one cup. How much change should he receive? Choose the picture that shows the correct amount.", "difficulty": 1, "explanation_md": "The cup costs 5 pesos. If you pay with 20, the change is 20 minus 5 = 15 pesos.", "audio_segment_id": "s3-eleccion-imagen.prompt"}], "schema_version": 1}', '{"s2-verdadero-falso": {"is_true": true, "correct_justification_id": "j1"}, "s3-eleccion-imagen": {"correct_option_id": "opt1"}}', '{"units": {"s2-verdadero-falso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/21c8c226ca987848db3bfcb29a9aafe00b3ff9674a2c773cf0a1dd5c74f93d0a.mp3", "hash": "f4585bf305651c506af63453ceb1478df59af93c2ca3b7e255ae0e2cba22ad4e", "bytes": 24336, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/21c8c226ca987848db3bfcb29a9aafe00b3ff9674a2c773cf0a1dd5c74f93d0a.mp3", "duration_ms": 4000}, "s2-verdadero-falso.prompt": {"url": "http://localhost:4006/files/lesson-audio/119d4ca53d32b856a8db05b41a3bceaee314c9e02c054a033436c85e4f1884a2.mp3", "hash": "d0d51056dc00526c2cd0ffe7d0e472886bbfd8cb3d869574e7a9a086fc726de3", "bytes": 53136, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/119d4ca53d32b856a8db05b41a3bceaee314c9e02c054a033436c85e4f1884a2.mp3", "duration_ms": 8800}, "s3-eleccion-imagen.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f3aee7067b62fe93957d719ce27ce17b7fb6dfa17979685f961b481204ca5c67.mp3", "hash": "de8e9cb9420d31e2cfce3c7c80103ff4829a06ded396e9741f360a643d8d1f44", "bytes": 28224, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/f3aee7067b62fe93957d719ce27ce17b7fb6dfa17979685f961b481204ca5c67.mp3", "duration_ms": 4640}, "s3-eleccion-imagen.prompt": {"url": "http://localhost:4006/files/lesson-audio/1b8647155fd2caf9bc9aae1be481c8fadd5c6049dfa8ce81c777e414d252fe7d.mp3", "hash": "709681394093d185e1883a52722e6e9ac40148fde8467f0493cc7243e1e5d1d5", "bytes": 39168, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/1b8647155fd2caf9bc9aae1be481c8fadd5c6049dfa8ce81c777e414d252fe7d.mp3", "duration_ms": 6480}, "s1-dialogo-clientes.line.0": {"url": "http://localhost:4006/files/lesson-audio/fb3ba99098ee2877007756840abe164dcd6e5f474