}, "s1-dialogo-clientes.prompt": {"url": "http://localhost:4006/files/lesson-audio/fc206885f90969b8cf1fe615f038830c3486148045c1ea166ccf0bf530e638d4.mp3", "hash": "2cb36585ec116dbe1d6e1db1b308ffc6f3e697395dda9d551852ef7acdffcf0f", "bytes": 37296, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/fc206885f90969b8cf1fe615f038830c3486148045c1ea166ccf0bf530e638d4.mp3", "duration_ms": 6160}, "s3-eleccion-imagen.choices": {"url": "http://localhost:4006/files/lesson-audio/b63c4dba1133808d336e0f9dd0a88fe0c6f2119ff9377d745ed9521d7cbc1ff5.mp3", "hash": "929bcb1d34c5b6cd9bed9c7fe0e8708270c85e207a0103d70b860833d5c3cc98", "bytes": 22896, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/b63c4dba1133808d336e0f9dd0a88fe0c6f2119ff9377d745ed9521d7cbc1ff5.mp3", "duration_ms": 3760}, "s2-verdadero-falso.explanation": {"url": "http://localhost:4006/files/lesson-audio/af17597d1522731df340eeafd413d9e0f8335899af01a1f1299e68eda2c15aaf.mp3", "hash": "a8888a11e5700b4f34f1904d04ace7d3db226fb82625ac07d5dc9995bd16556d", "bytes": 38304, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/af17597d1522731df340eeafd413d9e0f8335899af01a1f1299e68eda2c15aaf.mp3", "duration_ms": 6320}, "s3-eleccion-imagen.explanation": {"url": "http://localhost:4006/files/lesson-audio/aac010e0140b6aa3e0219c25b7d504926c7cde29a5792f7db6c9e563bd814d90.mp3", "hash": "964cfdeb13c45f1ea76df6516164fbab724172fd7966c301683ce5a823e67a98", "bytes": 41616, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/aac010e0140b6aa3e0219c25b7d504926c7cde29a5792f7db6c9e563bd814d90.mp3", "duration_ms": 6880}, "s1-dialogo-clientes.explanation": {"url": "http://localhost:4006/files/lesson-audio/d79a72e04e758cb0c18a8ba5ab80a3ec0e41664fd4ef7996463c36d372c1dec9.mp3", "hash": "2a4eaf7d03dad2d90ebe18e7e759697733eaf9c062735f1058e56bf04fd280eb", "bytes": 24768, "voice": "qwen-tts-vc-liruf_en_us-voi