INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'pt-BR', '1', E'{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "order-steps", "title": "Organize the market purchases", "locale": "pt-BR", "subject": "money", "objectives": ["Organize market purchases by sales priority: first what generates profit today, then what improves sales, and finally luxury items."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-compras", "xp": 10, "type": "order_steps", "hints": ["Ask yourself: without this, can I sell lemonade TODAY?", "What makes money today goes first, what is just a treat goes last."], "title": "Organize the market purchases", "payload": {"items": [{"id": "limones", "text_md": "Lemons — 8 pesos"}, {"id": "vasos", "text_md": "Cups — 6 pesos"}, {"id": "azucar", "text_md": "Sugar — 4 pesos"}, {"id": "calcomanias", "text_md": "Stickers — 2 pesos"}]}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Liruf has **20 pesos** and needs to buy these 4 things for his lemonade stand. **Order them from the MOST necessary to sell today to what can wait.**\\n\\n- Lemons (without them, no lemonade)\\n- Cups (without them, you can''t serve)\\n- Sugar (to make it taste good so they come back)\\n- Stickers (to decorate, but not urgent)", "difficulty": 1, "explanation_md": "First the lemons (without them, no lemonade), then the cups (to serve it), then the sugar (improves the taste), and finally the stickers (they are a luxury that can wait).", "audio_segment_id": "s1-ordenar-compras.prompt"}], "schema_version": 1}', '{"s1-ordenar-compras": {"order": ["limones", "vasos", "azucar", "calcomanias"]}}', '{"units": {"s1-ordenar-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9db9841fc2f2dc7ee6acba0223885f546dcde5ff639d70b7e0182243ebcd7b55.mp3", "hash": "3344cd7b879f9d3c373c88e2477c4848e312148e6cf9f20d62564a275ebb3502", "bytes": 25344, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/9db9841fc2f2dc7ee6acba0223885f546dcde5ff639d70b7e0182243ebcd7b55.mp3", "duration_ms": 4160}, "s1-ordenar-compras.hint.1": {"url": "http://localhost:4006/files/lesson-audio/770eb0fa3594448329fa0dd3f4b12308fe5dd9f20b59d3a118bc3eaf9ef87c7f.mp3", "hash": "29b0682ef04d0fb7475b6c599969d9467dc9f940fcf66564cd550acc168319c3", "bytes": 29088, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/770eb0fa3594448329fa0dd3f4b12308fe5dd9f20b59d3a118bc3eaf9ef87c7f.mp3", "duration_ms": 4800}, "s1-ordenar-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/e24640da511d8b5b3f9aaa0e82c8157270ccbf999afeb6e91928711d1f27da1a.mp3", "hash": "80b9f565686086c2bc4e823d4090ddb71fa0e9a63b1cdffeaf613d0599dbd0d7", "bytes": 124128, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/e24640da511d8b5b3f9aaa0e82c8157270ccbf999afeb6e91928711d1f27da1a.mp3", "duration_ms": 20640}, "s1-ordenar-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/11f688af15620bb86e61fe41357918a438e0a886c6d93976218f5b6222b9a026.mp3", "hash": "8a65e27f5e215caab21efa4d4f0e31c27df83867b7d5584aaa57da20cc4e09e2", "bytes": 64224, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/11f688af15620bb86e61fe41357918a438e0a886c6d93976218f5b6222b9a026.mp3", "duration_ms": 10640}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "balance-scale", "title": "Equilibra a balança do escambo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Equilibrar a balança do escambo para conseguir uma troca justa", "Entender que quantidades iguais em ambos os pratos alcançam o equilíbrio"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance", "xp": 15, "type": "balance_scale", "hints": ["Cada copo vale 5 pesos. Quanto somam os 3 copos?", "Os biscoitos valem 3 pesos cada. Quantos você precisa para igualar o total dos copos?"], "title": "Escambo justo", "payload": {"weights": [{"id": "galleta1", "label": "Biscoito", "value": 3}, {"id": "galleta2", "label": "Biscoito", "value": 3}, {"id": "galleta3", "label": "Biscoito", "value": 3}, {"id": "galleta4", "label": "Biscoito", "value": 3}, {"id": "galleta5", "label": "Biscoito", "value": 3}, {"id": "galleta6", "label": "Biscoito", "value": 3}], "left_fixed": [{"label": "Copos de limonada", "value": 15}], "unknown_label": "Biscoitos"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf vendeu 3 copos de limonada a 5 pesos cada. O vendedor de biscoitos pagará com biscoitos de 3 pesos cada. Se Liruf receber menos biscoitos do que o justo, perderá dinheiro. Coloque biscoitos um por um no outro prato até a balança se equilibrar. Quantos biscoitos o vendedor deve dar para que a troca seja justa?", "difficulty": 2, "explanation_md": "3 copos de 5 pesos somam 15 pesos. 5 biscoitos de 3 pesos também somam 15 pesos. A balança se equilibra e Liruf recebe o pagamento justo!", "audio_segment_id": "s1-balance.prompt"}], "schema_version": 1}', '{"s1-balance": {}}', '{"units": {"s1-balance.hint.0": {"url": "http://localhost:4006/files/lesson-audio/95e3d973d257a9b7e4c9596be764cd7a3ca6adeeea0226c0e70df63d69751f8b.mp3", "hash": "cabe3705fbe22d310f2d4b7ccd547062c1d195fcb3edda2e83489221d73bb259", "bytes": 31536, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/95e3d973d257a9b7e4c9596be764cd7a3ca6adeeea0226c0e70df63d69751f8b.mp3", "duration_ms": 5200}, "s1-balance.hint.1": {"url": "http://localhost:4006/files/lesson-audio/25daaec8ec8c9c8aad6360e325b16649a6c1a6820042dfe2a8be44b5f7cae00e.mp3", "hash": "377c104192ea12e4c1a1c4346f279156d98e5b3c2c287be23f05962886d25fbc", "bytes": 38304, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/25daaec8ec8c9c8aad6360e325b16649a6c1a6820042dfe2a8be44b5f7cae00e.mp3", "duration_ms": 6320}, "s1-balance.prompt": {"url": "http://localhost:4006/files/lesson-audio/783650a88a51fde837b437be550ac320ac920ca0507cbc883babc7787bcd5dde.mp3", "hash": "22c4c3374b5cb5c60da63407b6bcc7372c0772bcae76011505d6e42bc68eb13d", "bytes": 125568, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/783650a88a51fde837b437be550ac320ac920ca0507cbc883babc7787bcd5dde.mp3", "duration_ms": 20880}, "s1-balance.explanation": {"url": "http://localhost:4006/files/lesson-audio/12b7b67a37aaa45796ebf785a821339a2f8663841100034bbf00540091585fe3.mp3", "hash": "f5d22f8adb0dd11bf7983bf8ddd717886d5bad9f910eed042705af499155d14c", "bytes": 69408, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/12b7b67a37aaa45796ebf785a821339a2f8663841100034bbf00540091585fe3.mp3", "duration_ms": 11520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "story-branch", "title": "O preço justo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher o preço da limonada considerando o custo por copo e a meta de economia", "Observar como cada decisão de preço afeta as vendas e o progresso em direção ao violão"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-limonada", "xp": 20, "type": "story_branch", "hints": ["Pense: se o preço for muito baixo, você ganha pouco por copo. Se for muito alto, talvez ninguém compre.", "Lembre-se de que cada copo custa 2 reais. O que você realmente ganha é o preço menos esses 2 reais."], "title": "Escolha o preço de hoje", "payload": {"nodes": [{"id": "inicio", "choices": [{"id": "precio5", "next": "final5", "text_md": "5 reais (o preço de sempre)"}, {"id": "precio3", "next": "final3", "text_md": "3 reais (mais barato)"}, {"id": "precio10", "next": "final10", "text_md": "10 reais (o dobro)"}], "emotion": "thinking", "text_md": "Está um calor enorme! Já vêm 6 vizinhos com sede. A que preço vendo cada copo?", "character": "liruf"}, {"id": "final5", "choices": [{"id": "fin5", "next": null, "text_md": "Fim"}], "emotion": "happy", "text_md": "Todos os 6 compram! Cada copo te dá 3 reais de lucro (5 - 2 = 3). São 6 × 3 = 18 reais. Bom progresso em direção ao violão!", "character": "liruf"}, {"id": "final3", "choices": [{"id": "fin3", "next": null, "text_md": "Fim"}], "emotion": "surprised", "text_md": "Acaba voando, mas você ganha só 1 real por copo (3 - 2 = 1). São 6 × 1 = 6 reais. Quase não sobe para o violão…", "character": "liruf"}, {"id": "final10", "choices": [{"id": "fin10", "next": null, "text_md": "Fim"}], "emotion": "neutral", "text_md": "Os vizinhos fazem careta e vão para o sorvete. Você fica com a jarra cheia e 0 reais. O violão parece distante…", "character": "liruf"}], "start_node": "inicio"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf já separou os fatos das opiniões em sua barraca. Agora vem o difícil: **decidir o preço da limonada de HOJE**. Cada copo custa **2 reais** para fazer. Sua meta é juntar **80 reais** para um violão. Que preço você coloca?", "difficulty": 2, "explanation_md": "A decisão do preço muda o quanto você avança em direção ao violão de 80 reais. Com 5 reais por copo, os 6 vizinhos compram e você ganha 3 reais por copo, 18 reais no total! Com 3 reais, também vendem todos, mas você ganha apenas 1 real por copo, só 6 reais. Com 10 reais, ninguém compra e você não ganha nada.", "audio_segment_id": "s1-precio-limonada.prompt"}], "schema_version": 1}', '{"s1-precio-limonada": {"qualities": [{"score": 100, "node_id": "inicio", "choice_id": "precio5"}, {"score": 30, "node_id": "inicio", "choice_id": "precio3"}, {"score": 0, "node_id": "inicio", "choice_id": "precio10"}]}}', '{"units": {"s1-precio-limonada.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3ab25e567fe4eb26d67696610f6f422453d5f1aa2813448b7a6bdca0c7a1f9bc.mp3", "hash": "afb85c86721a9af29281f8bb4dcd91b7ea09a55b55b86bfdc78e46a2f43dec83", "bytes": 47808, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/3ab25e567fe4eb26d67696610f6f422453d5f1aa2813448b7a6bdca0c7a1f9bc.mp3", "duration_ms": 7920}, "s1-precio-limonada.hint.1": {"url": "http://localhost:4006/files/lesson-audio/751db3ccae810133cede848985a86302a70f2760fc9b6866b54eea47d4e681af.mp3", "hash": "f37001a70a1842d9af0b359bbb360b7922d702f757a34916ec1a4cbbaa4a44f5", "bytes": 47376, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/751db3ccae810133cede848985a86302a70f2760fc9b6866b54eea47d4e681af.mp3", "duration_ms": 7840}, "s1-precio-limonada.prompt": {"url": "http://localhost:4006/files/lesson-audio/81525c242b50fc95e1b82770d52cb0976930a0ee8e69f96064174fb69ba7ebbc.mp3", "hash": "8c4eabc4f97f1c442a0a391b2d711d7f0615becf29c829cc22e60f181ec897da", "bytes": 109728, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/81525c242b50fc95e1b82770d52cb0976930a0ee8e69f96064174fb69ba7ebbc.mp3", "duration_ms": 18240}, "s1-precio-limonada.explanation": {"url": "http://localhost:4006/files/lesson-audio/40793a857331b5bfd79e3421e35721d30b4c9258a3272ac51ba2f2bc4fee5e9b.mp3", "hash": "21771d7d76db500acb3b501777d3fee0fd81dd64a6e60e9cda2288dc28a08c1b", "bytes": 142848, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/40793a857331b5bfd79e3421e35721d30b4c9258a3272ac51ba2f2bc4fee5e9b.mp3", "duration_ms": 23760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "coin-count", "title": "Contar monedas de la venta", "locale": "es-MX", "subject": "mixed", "objectives": ["Contar monedas de 1 y 2 pesos para sumar 5 pesos exactos"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 10, "type": "coin_count", "hints": ["Cuenta las monedas de 2 primero, luego las de 1.", "Suma: 2 + 2 = 4, luego 4 + 1 = 5."], "title": "¿Le alcanza para la calcomanía?", "payload": {"target": 5, "currency": "MXN", "denominations": [1, 2, 2]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina vendió limonada y le pagaron con estas monedas. Ella quiere comprar una calcomanía de 5 pesos. Recuerda que Liruf ahorró hasta llegar a 80 en la recta numérica. Ahora Dina cuenta sus monedas para ver si ya tiene los 5 pesos exactos. ¿Le alcanza para la calcomanía?", "difficulty": 1, "explanation_md": "¡Sí le alcanza! Dina tiene 5 pesos exactos: 2 + 2 = 4, más 1 = 5. Con eso puede comprar la calcomanía, igual que Liruf llegó a su meta en la recta numérica.", "audio_segment_id": "s1-coin-count.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}}', '{"units": {"s1-coin-count.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b3649237e0943811e45b7378158c916b9be1b402908364e8bd53c3f8dd0f9702.mp3", "hash": "c7562dcab16df1c59b0955d330f5453c1d25f652ec19f1c47b5e3e00a0d54c69", "bytes": 21888, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b3649237e0943811e45b7378158c916b9be1b402908364e8bd53c3f8dd0f9702.mp3", "duration_ms": 3600}, "s1-coin-count.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c4049faf86460845a198b3729d44a3189528c79b800193c5fd86fb6a489f5277.mp3", "hash": "c6787e491de3a3bdf9294cf432c67d0c5d97528a092c7f459803df30f77fb529", "bytes": 33984, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c4049faf86460845a198b3729d44a3189528c79b800193c5fd86fb6a489f5277.mp3", "duration_ms": 5600}, "s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/60ee307db9d5e411507c8b583a18c61c3ad586558d0936c79fde9b502578eb3e.mp3", "hash": "f86ab9566a55eb6550800d70175c93deac6fa711a459293106c9049cc391af0c", "bytes": 111168, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/60ee307db9d5e411507c8b583a18c61c3ad586558d0936c79fde9b502578eb3e.mp3", "duration_ms": 18480}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/29ca66a8a391785c25971b3f3cbc5cd10bf1afe1f7da9dfba71eec60b79fdbea.mp3", "hash": "19069187f5db12c8973b10ce9a9b727dc000b5bbc5ab46a108e4898e57ce2b43", "bytes": 79488, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/29ca66a8a391785c25971b3f3cbc5cd10bf1afe1f7da9dfba71eec60b79fdbea.mp3", "duration_ms": 13200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'es-MX', '1', '{"meta": {"cast": ["rho"], "slug": "equation-builder", "title": "Arma la suma de la tarde", "locale": "es-MX", "subject": "mixed", "objectives": ["Armar con fichas la suma de la tarde: 5 + 5 + 5 = 15 pesos (tres vasos vendidos)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-suma-tarde", "xp": 15, "type": "equation_builder", "hints": ["Cada vaso vale 5 pesos. Vendiste tres vasos. Pon el 5 tres veces con signos + entre ellos.", "La cuenta empieza con 5, luego +, luego 5, luego +, luego 5."], "title": "Arma la suma de la tarde", "payload": {"slots": 5, "tokens": [{"id": "t1", "text": "5"}, {"id": "t2", "text": "+"}, {"id": "t3", "text": "5"}, {"id": "t4", "text": "+"}, {"id": "t5", "text": "5"}, {"id": "t6", "text": "15"}], "target_result": 15}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Ayer contaste 15 limones en la cesta. Hoy Rho vendió limonada. Por cada vaso cobró 5 pesos. Vendió tres vasos. ¿Alcanza lo que ganó para comprar mañana 15 limones? Arma la cuenta con las fichas para saberlo.", "difficulty": 2, "explanation_md": "Tres vasos a 5 pesos cada uno suman 15 pesos. ¡Justo lo que cuestan los limones de mañana! La cuenta es 5 + 5 + 5 = 15.", "audio_segment_id": "s1-suma-tarde.prompt"}], "schema_version": 1}', '{"s1-suma-tarde": {"accepted": ["t1 t2 t3 t4 t5"]}}', '{"units": {"s1-suma-tarde.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8b508471b8a892c64c08265f19cc871ab86738a8a57184c1f27cd871cca87ec5.mp3", "hash": "56ba198ca84d63f3f382e36e3e8be72e757eaeb46ac71e712dfaf1f16ad6fb96", "bytes": 48816, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/8b508471b8a892c64c08265f19cc871ab86738a8a57184c1f27cd871cca87ec5.mp3", "duration_ms": 8080}, "s1-suma-tarde.hint.1": {"url": "http://localhost:4006/files/lesson-audio/8d9338444beb34bee61585b3b8d382c8e05a541973f3aceffe65c3dbfa02343e.mp3", "hash": "580687144d985e7390f05cee005b58cdd3dfa4695f7fd11f22e2715873884688", "bytes": 37728, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/8d9338444beb34bee61585b3b8d382c8e05a541973f3aceffe65c3dbfa02343e.mp3", "duration_ms": 6240}, "s1-suma-tarde.prompt": {"url": "http://localhost:4006/files/lesson-audio/2a424d79b1113dcfc7312e0e8b29fe28e18482cf5acde904c8cf0cd1f453f519.mp3", "hash": "56eaf3b2d0b0006f2b51c1400af1cd33a0acaf748ffa62138db48eb4530aa69b", "bytes": 97776, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/2a424d79b1113dcfc7312e0e8b29fe28e18482cf5acde904c8cf0cd1f453f519.mp3", "duration_ms": 16240}, "s1-suma-tarde.explanation": {"url": "http://localhost:4006/files/lesson-audio/0424b1343e19f9a6c21e018036e833ed061499d5f19376ec00efba0adccc97df.mp3", "hash": "521fce5ad186c1ff7868a3b6db7f72b1a6808b9d270de0c6e8a6937afc3f7f9b", "bytes": 71424, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/0424b1343e19f9a6c21e018036e833ed061499d5f19376ec00efba0adccc97df.mp3", "duration_ms": 11840}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'pt-BR', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "read-chart", "title": "Leia o gráfico de vendas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ler o gráfico de barras de copos vendidos por dia e responder qual foi o melhor dia da semana."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 10, "type": "read_chart", "hints": ["Procure a barra mais alta no gráfico.", "Cada barra mostra quantos copos foram vendidos naquele dia."], "title": "O melhor dia de Zara", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Copos vendidos", "points": [{"x": "Segunda-feira", "y": 3}, {"x": "Terça-feira", "y": 5}, {"x": "Quarta-feira", "y": 4}, {"x": "Quinta-feira", "y": 6}, {"x": "Sexta-feira", "y": 8}]}]}, "questions": [{"id": "q-best-day", "options": [{"id": "lunes", "text_md": "Segunda-feira"}, {"id": "martes", "text_md": "Terça-feira"}, {"id": "miercoles", "text_md": "Quarta-feira"}, {"id": "jueves", "text_md": "Quinta-feira"}, {"id": "viernes", "text_md": "Sexta-feira"}], "prompt_md": "Em que dia vendeu mais copos de limonada?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Zara quer saber em que dia venderá mais limonada na próxima semana para pedir limões suficientes. Como você escolheu o melhor fornecedor de limões, agora ajude-a a encontrar o melhor dia usando o gráfico de vendas desta semana. Em que dia ela vendeu mais copos?", "difficulty": 1, "explanation_md": "Na sexta-feira, a barra chega a 8, que é mais alto que os outros dias. Esse foi o melhor dia! Zara pedirá mais limões para a sexta-feira.", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q-best-day": "viernes"}}}', '{"units": {"s1-read-chart.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ffcdde5e3f25f05fb952d8c1136a7f4c448172bb749a109ba8c0fa771515145c.mp3", "hash": "03cb7f2899dd554f0b5a85553146d77e3ba561230fdb84802c430c020897b072", "bytes": 15264, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ffcdde5e3f25f05fb952d8c1136a7f4c448172bb749a109ba8c0fa771515145c.mp3", "duration_ms": 2480}, "s1-read-chart.hint.1": {"url": "http://localhost:4006/files/lesson-audio/e88fb190924812affba1f940c542aea92764b47f388f42c4da4721bfbffdbdbd.mp3", "hash": "300d224bc798939e3511f2563e38bff99fcf748da0c8f9b46c56b775657d9952", "bytes": 28224, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e88fb190924812affba1f940c542aea92764b47f388f42c4da4721bfbffdbdbd.mp3", "duration_ms": 4640}, "s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/8c159f4d76a0d27c72aa2a3f9a4dc542cfc34a2758ef376d900cf3d731122d77.mp3", "hash": "c6f0892ed19f1c2ad6ad9610c9ec09e7a0566a48e928de0b31c78fc1b878c946", "bytes": 106416, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8c159f4d76a0d27c72aa2a3f9a4dc542cfc34a2758ef376d900cf3d731122d77.mp3", "duration_ms": 17680}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/afdcd034521fcba47edcdfaf0e15dc79d2f33fff2399e57faef27cc8d4fb4176.mp3", "hash": "93ca6f9f0d20ede45ae88d427fb811fe0f194c6302d55148ba14b27ab10b98a4", "bytes": 56448, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/afdcd034521fcba47edcdfaf0e15dc79d2f33fff2399e57faef27cc8d4fb4176.mp3", "duration_ms": 9360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "pattern-complete", "title": "A escada de copos", "locale": "pt-BR", "subject": "mixed", "objectives": ["Organizar passos, combinar produtos com preços e classificar compras entre necessidades da barraca e desejos que podem esperar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-escalera", "xp": 15, "type": "pattern_complete", "hints": ["Observe o padrão: pequeno, médio, grande, pequeno… qual tamanho vem depois do grande?", "A escada sobe de preço: quanto maior, mais caro. Qual é o mais caro dos três?"], "title": "Qual copo vai aqui?", "payload": {"options": [{"id": "chico", "icon": "water_drop", "tint": "primary"}, {"id": "mediano", "icon": "water_drop", "tint": "accent"}, {"id": "grande", "icon": "water_drop", "tint": "success"}], "sequence": [{"icon": "water_drop", "tint": "primary"}, {"icon": "water_drop", "tint": "accent"}, {"icon": "water_drop", "tint": "success"}, {"icon": "water_drop", "tint": "primary"}, {"icon": "water_drop", "tint": "accent"}, {"icon": "water_drop", "tint": "success"}], "missing_slots": 1}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Ontem Zara comprou limões, fez a limonada, vendeu e guardou o lucro. Hoje ela prepara os copos para amanhã. Ela os organiza assim: pequeno ($5), médio ($10), grande ($15), e depois novamente pequeno, médio, grande… para que os clientes vejam que quanto maior, mais caro. Mas ela deixou um espaço vazio. Qual copo vai no lugar vazio para que a escada continue subindo?", "difficulty": 2, "explanation_md": "Depois do copo grande ($15) vem o pequeno ($5) novamente, porque a escada recomeça. Assim os clientes veem que quanto maior, mais caro, e podem escolher o que cabe no bolso. Se você escolheu ''grande'', pensou que continuava subindo, mas a escada se repete. Se escolheu ''médio'', confundiu a ordem do ciclo.", "audio_segment_id": "s1-escalera.prompt"}], "schema_version": 1}', '{"s1-escalera": {"correct": {"0": "chico"}}}', '{"units": {"s1-escalera.hint.0": {"url": "http://localhost:4006/files/lesson-audio/96a245179d27c04f44e1f7eca2fc15fd6bd732013e9eb7ec449c63ef27a9d925.mp3", "hash": "fe2a277709d09017cca255ef60719252065c39679b7c1579e172e03f08a24b0a", "bytes": 42048, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/96a245179d27c04f44e1f7eca2fc15fd6bd732013e9eb7ec449c63ef27a9d925.mp3", "duration_ms": 6960}, "s1-escalera.hint.1": {"url": "http://localhost:4006/files/lesson-audio/cb4861ba358f2387ec3438be781db4c8b7a67e253b3287778b4349662a4fcbea.mp3", "hash": "1704db181f5d9fc1e9a92e160ae88d8cc6c4077b21c83f0d6fdf8c1626e00366", "bytes": 35856, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/cb4861ba358f2387ec3438be781db4c8b7a67e253b3287778b4349662a4fcbea.mp3", "duration_ms": 5920}, "s1-escalera.prompt": {"url": "http://localhost:4006/files/lesson-audio/540972caac8d5e67f3f9d0da85ab718c96c77d963c06d7fdc3735fe1d27b3ac0.mp3", "hash": "7b17fdbe0d5076b6bcb35b7748db0aa9e9cc5221d5d90b7408bea8e0e9cbaa99", "bytes": 169776, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/540972caac8d5e67f3f9d0da85ab718c96c77d963c06d7fdc3735fe1d27b3ac0.mp3", "duration_ms": 28240}, "s1-escalera.explanation": {"url": "http://localhost:4006/files/lesson-audio/8873431c935bc75949240137352755c27e53f16a8a937256bb0c207a4526683d.mp3", "hash": "9b7f6147126e239302d2dc588bd3f71650b4d2a384656b40a1c3746fc0387b0e", "bytes": 132768, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/8873431c935bc75949240137352755c27e53f16a8a937256bb0c207a4526683d.mp3", "duration_ms": 22080}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'en-US', '1', '{"meta": {"cast": ["rho"], "slug": "equation-builder", "title": "Build the afternoon sum", "locale": "en-US", "subject": "mixed", "objectives": ["Build the afternoon sum with chips: 5 + 5 + 5 = 15 pesos (three cups sold)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-suma-tarde", "xp": 15, "type": "equation_builder", "hints": ["Each cup is worth 5 pesos. You sold three cups. Put the 5 three times with + signs between them.", "The account starts with 5, then +, then 5, then +, then 5."], "title": "Build the afternoon sum", "payload": {"slots": 5, "tokens": [{"id": "t1", "text": "5"}, {"id": "t2", "text": "+"}, {"id": "t3", "text": "5"}, {"id": "t4", "text": "+"}, {"id": "t5", "text": "5"}, {"id": "t6", "text": "15"}], "target_result": 15}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Yesterday you counted 15 lemons in the basket. Today Rho sold lemonade. For each cup she charged 5 pesos. She sold three cups. Is what she earned enough to buy 15 lemons tomorrow? Build the account with the chips to find out.", "difficulty": 2, "explanation_md": "Three cups at 5 pesos each add up to 15 pesos. Exactly what tomorrow''s lemons cost! The account is 5 + 5 + 5 = 15.", "audio_segment_id": "s1-suma-tarde.prompt"}], "schema_version": 1}', '{"s1-suma-tarde": {"accepted": ["t1 t2 t3 t4 t5"]}}', '{"units": {"s1-suma-tarde.hint.0": {"url": "http://localhost:4006/files/lesson-audio/fcad309bc006cc04f66c0088fcc0d11d2e0684776067663f3bfc39a3ee2a7969.mp3", "hash": "4feff9c103b1b5f0b3ed0fdfd25abe7f7b1ed95e386de75800b1890d49093ff7", "bytes": 47376, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/fcad309bc006cc04f66c0088fcc0d11d2e0684776067663f3bfc39a3ee2a7969.mp3", "duration_ms": 7840}, "s1-suma-tarde.hint.1": {"url": "http://localhost:4006/files/lesson-audio/22e584f608711adb56d2221e60204bc1689cd9577fe5ab1599449b8dffdb0e47.mp3", "hash": "f7994fd4f39d7e3d0f41c0a11ee36175a2f930daa4a39ff8b82e463c22998c18", "bytes": 41616, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/22e584f608711adb56d2221e60204bc1689cd9577fe5ab1599449b8dffdb0e47.mp3", "duration_ms": 6880}, "s1-suma-tarde.prompt": {"url": "http://localhost:4006/files/lesson-audio/fd7b4f0954e5354f410eb38405c9b553a26ea38c6b013d6c4ac62adce85c7c9e.mp3", "hash": "b03c54dce38a510d8b4667c070ffd58bf4d994b83f5fcc05f5e6abd4d8677218", "bytes": 96336, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/fd7b4f0954e5354f410eb38405c9b553a26ea38c6b013d6c4ac62adce85c7c9e.mp3", "duration_ms": 16000}, "s1-suma-tarde.explanation": {"url": "http://localhost:4006/files/lesson-audio/0d192c0aed4f9f23935d3aac8a8db71447a603e70c649f68c36ae87dcf358b5d.mp3", "hash": "67e3f212a7716857a505a6db42952a81b4d7b27ac24afa61254a493550a35370", "bytes": 74736, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/0d192c0aed4f9f23935d3aac8a8db71447a603e70c649f68c36ae87dcf358b5d.mp3", "duration_ms": 12400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-dinero", "title": "Fechar o caixa do domingo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Contar moedas de 1, 5 e 10 para saber o total de vendas do dia.", "Calcular o troco correto ao pagar com nota de 20 um copo de 5 pesos.", "Determinar quantos domingos a mais precisa economizar 20 pesos para chegar a 80."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-contar-monedas", "xp": 10, "type": "coin_count", "hints": ["Comece com as moedas de 10, depois as de 5 e por fim as de 1."], "title": "Fechar o caixa", "payload": {"target": 20, "currency": "MXN", "denominations": [1, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Lembra dos dois clientes de ontem? Hoje eles voltaram e pagaram com estas moedas. Dina está preocupada: se não juntarem 20 pesos, não poderão comprar as canecas para o domingo. Ajude-a a contar as moedas. Toque em cada moeda para somá-las.", "difficulty": 1, "explanation_md": "As moedas somam 20 pesos: uma de 10, duas de 5 e cinco de 1. Exatamente o que precisavam para as canecas! Dina sorri aliviada.", "audio_segment_id": "s1-contar-monedas.prompt"}, {"id": "s2-cambio-cliente", "xp": 10, "type": "make_change", "hints": ["Se ela pagou com 20 e o copo custa 5, quanto sobra?"], "title": "Dar troco", "payload": {"price": 5, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "A cliente de ontem volta e pede um copo de 5 pesos. Paga com uma nota de 20. Dina está nervosa: se você der o troco errado, a cliente vai ficar brava e não voltará. Quanto troco você precisa dar?", "difficulty": 1, "explanation_md": "O troco é 15 pesos: 20 menos 5 é 15. A cliente sorri e diz que voltará no domingo. Muito bem!", "audio_segment_id": "s2-cambio-cliente.prompt"}, {"id": "s3-ahorro-guitarra", "xp": 15, "type": "savings_goal", "hints": ["Primeiro calcule quanto falta: 80 menos 40 são 40.", "Depois divida o que falta pelo que ele economiza cada domingo: 40 dividido por 20."], "title": "Quantos domingos faltam?", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [20]}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "Liruf quer comprar um violão de 80 pesos. Ele já tem 40 no cofrinho. Cada domingo ele ganha 20 pesos vendendo limonada. Dina diz: ''Se você economizar tudo, quantos domingos a mais precisa para o violão?'' Ajude Liruf a descobrir.", "difficulty": 2, "explanation_md": "Faltam 40 pesos e cada domingo ele economiza 20, então precisa de mais 2 domingos. Liruf estará tocando violão muito em breve!", "audio_segment_id": "s3-ahorro-guitarra.prompt"}], "schema_version": 1}', '{"s1-contar-monedas": {}, "s2-cambio-cliente": {}, "s3-ahorro-guitarra": {"correct": {"20": 4}}}', '{"units": {"s1-contar-monedas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4aabd329e7d2a491059e8c9de731f73677c71bea66919d420fa58e81e9cc6935.mp3", "hash": "eb24de43588714eac951629750c9c99e9b475ba9c5937b29a0278bbf510e4d58", "bytes": 31104, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4aabd329e7d2a491059e8c9de731f73677c71bea66919d420fa58e81e9cc6935.mp3", "duration_ms": 5120}, "s1-contar-monedas.prompt": {"url": "http://localhost:4006/files/lesson-audio/aba104678da18bbc407d5172fb3f5a8c01a76f8a254decf71db8d69aa878ed8a.mp3", "hash": "4af3057d8793555b8834c0d978341b77241361eee7f547d81c7e9b518ca9a269", "bytes": 104976, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/aba104678da18bbc407d5172fb3f5a8c01a76f8a254decf71db8d69aa878ed8a.mp3", "duration_ms": 17440}, "s2-cambio-cliente.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ba6ab3bb92098060980f0ade5e199226f6b65877bb03cdb986a3279bc0cced29.mp3", "hash": "1e237dc44baa91a44bd7baed15fe3d09fcd0619448979dbac18e065683f683fb", "bytes": 25776, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ba6ab3bb92098060980f0ade5e199226f6b65877bb03cdb986a3279bc0cced29.mp3", "duration_ms": 4240}, "s2-cambio-cliente.prompt": {"url": "http://localhost:4006/files/lesson-audio/7d8914a52d1738ea1e8d19a03fc83a597575be19c3ea6ee90d96dc04609a9b15.mp3", "hash": "577e24ac61247e146a5e81d658e7fc38b1780da1b8adc23a1ec834cec5ba5440", "bytes": 91584, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7d8914a52d1738ea1e8d19a03fc83a597575be19c3ea6ee90d96dc04609a9b15.mp3", "duration_ms": 15200}, "s3-ahorro-guitarra.hint.0": {"url": "http://localhost:4006/files/lesson-audio/fd53a61148df9287937307da97750f621ce354a406e98b21cd606c3c0e057cd4.mp3", "hash": "15abb6d67a5b2ad777bd19558d8ff84a26c6d5cd216fc5568daeb1c1a0c58101", "bytes": 28656, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/fd53a61148df9287937307da97750f621ce354a406e98b21cd606c3c0e057cd4.mp3", "duration_ms": 4720}, "s3-ahorro-guitarra.hint.1": {"url": "http://localhost:4006/files/lesson-audio/fb683cac053259caa0266c6a04f40941fea2da8dee425489db56e16fb36e4478.mp3", "hash": "8494dd01a75a6fff3fd84b657a405e335cd2f128bc1961c5f0fe42a538eeaff3", "bytes": 35856, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/fb683cac053259caa0266c6a04f40941fea2da8dee425489db56e16fb36e4478.mp3", "duration_ms": 5920}, "s3-ahorro-guitarra.prompt": {"url": "http://localhost:4006/files/lesson-audio/6653e533066b486320f923f49d986d112af760633823316d93c630d5aa8e2712.mp3", "hash": "b700f61a0491bdc740f3e4b09f02eea3cbf238d290d412f9153359019c18c23c", "bytes": 100224, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/6653e533066b486320f923f49d986d112af760633823316d93c630d5aa8e2712.mp3", "duration_ms": 16640}, "s1-contar-monedas.explanation": {"url": "http://localhost:4006/files/lesson-audio/5dda1d9d8970b2ee9d560f1ea62bdac46aa17dd419ddf1ab50e413cefb5050ef.mp3", "hash": "1489e651d420506c5b7f1e9806a669e27b53bcb73b165c439545960dffe63408", "bytes": 63648, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5dda1d9d8970b2ee9d560f1ea62bdac46aa17dd419ddf1ab50e413cefb5050ef.mp3", "duration_ms": 10560}, "s2-cambio-cliente.explanation": {"url": "http://localhost:4006/files/lesson-audio/ba95ae55911f02215a38b3ec0bfb1cf4d618c392fad67f7b8607400a4a6c12c8.mp3", "hash": "dca66a918106f8379ed2c4a66d2d324f7df94dc0e9bbdacef55cbc9d38c7372a", "bytes": 54576, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ba95ae55911f02215a38b3ec0bfb1cf4d618c392fad67f7b8607400a4a6c12c8.mp3", "duration_ms": 9040}, "s3-ahorro-guitarra.explanation": {"url": "http://localhost:4006/files/lesson-audio/9160784f771fe4f735ec978f1240f8834ed3a9b375456348badbb9ec0ec36a31.mp3", "hash": "5a90c0ebebe072ed7dddca397b0a4c227ce3d10db0d64dca9fb448ace223a3e5", "bytes": 56448, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/9160784f771fe4f735ec978f1240f8834ed3a9b375456348badbb9ec0ec36a31.mp3", "duration_ms": 9360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "budget-fit", "title": "O mercado de Liruf", "locale": "pt-BR", "subject": "money", "objectives": ["Calcular o total de itens necessários e o dinheiro restante", "Decidir quais extras cabem em um orçamento de 20 reais"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 15, "type": "budget_fit", "hints": ["Some primeiro os necessários: 8 + 6 = 14. Sobram 6 reais.", "Veja os preços: gelo 5, canudos 3, jarra 8. Quais custam 6 ou menos?"], "title": "Encha o carrinho", "payload": {"items": [{"id": "limones", "icon": "nutrition", "need": true, "label": "Limões", "price": 8}, {"id": "azucar", "icon": "bakery_dining", "need": true, "label": "Açúcar", "price": 6}, {"id": "hielo", "icon": "ac_unit", "need": false, "label": "Gelo", "price": 5}, {"id": "popotes", "icon": "local_drink", "need": false, "label": "Canudos", "price": 3}, {"id": "jarra", "icon": "table_restaurant", "need": false, "label": "Jarra bonita", "price": 8}], "budget": 20, "currency": "MXN", "must_buy_needs": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf tem uma nota de **20 reais**. Precisa comprar **limões (8)** e **açúcar (6)**. Sem isso, amanhã não tem limonada. O que mais ele pode levar sem passar de 20? Toque nos que couberem.", "difficulty": 2, "explanation_md": "Liruf gasta 8+6=14 no necessário. Sobram 6 reais. O gelo custa 5 e os canudos 3, juntos somam 8 (não cabem). Só o gelo (5) cabe, ou só os canudos (3). A jarra custa 8, mais do que sobra.", "audio_segment_id": "s1-budget-fit.prompt"}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{"units": {"s1-budget-fit.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f6e4e3bdd9a6eeb216fd43d6689f0236ea4bf719913f66d83df5a017da1f202b.mp3", "hash": "37bf98f884ae8eed830a1dc6720093d14dbbfa1ae7fc92648b39a1b3dddefa88", "bytes": 37296, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f6e4e3bdd9a6eeb216fd43d6689f0236ea4bf719913f66d83df5a017da1f202b.mp3", "duration_ms": 6160}, "s1-budget-fit.hint.1": {"url": "http://localhost:4006/files/lesson-audio/754609d31e5a668a2222e3df15613503869af7c7c36779c3da10d2e0180ef98b.mp3", "hash": "ce48e553ea11f4788ab687108796e416cfee1d5535b066a6cd83e4cc033641c3", "bytes": 44928, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/754609d31e5a668a2222e3df15613503869af7c7c36779c3da10d2e0180ef98b.mp3", "duration_ms": 7440}, "s1-budget-fit.prompt": {"url": "http://localhost:4006/files/lesson-audio/414047729355e90caeafb450d253506c142f0e8e6bf251252947ec85fba222b9.mp3", "hash": "b8a263ca27d00a5e8f53ecc552110bacde128be473fef576c2d3220e83c62ce8", "bytes": 92448, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/414047729355e90caeafb450d253506c142f0e8e6bf251252947ec85fba222b9.mp3", "duration_ms": 15360}, "s1-budget-fit.explanation": {"url": "http://localhost:4006/files/lesson-audio/2faca41aae4e9d62c3b50a29edb55320b575b395ae1a17f754ab202b12333024.mp3", "hash": "f60f1f971eb842d97b5d53c3df80a68343eb7bc712b6900528019a7c190f1319", "bytes": 109296, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2faca41aae4e9d62c3b50a29edb55320b575b395ae1a17f754ab202b12333024.mp3", "duration_ms": 18160}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "confidence-quiz", "title": "Confiança nas suas contas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Somar dois copos de limonada (5+5) e avaliar seu nível de confiança no resultado."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confianza", "xp": 10, "type": "confidence_quiz", "hints": ["Lembre-se: só as moedas de verdade contam. A tampinha não é dinheiro.", "Conte as moedas de 5 pesos: uma são 5, duas são..."], "title": "Quanto dinheiro você ganhou?", "payload": {"options": [{"id": "opt-10", "text_md": "10 pesos", "rationale_md": "Você somou as duas moedas de 5 pesos e soube que a tampinha não conta. Correto!"}, {"id": "opt-5", "text_md": "5 pesos", "rationale_md": "Talvez você só contou uma moeda e esqueceu a outra. Liruf tem duas moedas de 5, não uma."}, {"id": "opt-15", "text_md": "15 pesos", "rationale_md": "Talvez você contou a tampinha como se fosse uma moeda de 5 pesos. Mas tampinhas não são dinheiro, só as moedas de verdade contam."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf tem duas moedas na mão. Uma é de 5 pesos, a outra é de 5 pesos. Mas entre seus brinquedos há uma tampinha de garrafa que parece moeda. Quanto dinheiro de verdade Liruf tem na mão? Depois escolha o quão certo você está da sua resposta.", "difficulty": 1, "explanation_md": "Liruf tem duas moedas de 5 pesos, então tem 10 pesos no total. A tampinha de garrafa não vale dinheiro, mesmo que se pareça. Bom por não se deixar enganar!", "audio_segment_id": "s1-confianza.prompt"}], "schema_version": 1}', '{"s1-confianza": {"correct_option_id": "opt-10"}}', '{"units": {"s1-confianza.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8a09f9b16d1a219c14690dcb40dc979743e69a9ec007cdb5531b926ade76916f.mp3", "hash": "15197af6543f345440c840e441c41ae123b56d55f4413f3174210c2339fc1bbb", "bytes": 30096, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8a09f9b16d1a219c14690dcb40dc979743e69a9ec007cdb5531b926ade76916f.mp3", "duration_ms": 4960}, "s1-confianza.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c3dedf058c62b485ff02d4c8f8dba7c4da80b519a2726c0113ff41b3b3dd4958.mp3", "hash": "cf0c555bb528279d70fc5e853a93128943f78e8edad593f32c117c56db1fb1a4", "bytes": 26784, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c3dedf058c62b485ff02d4c8f8dba7c4da80b519a2726c0113ff41b3b3dd4958.mp3", "duration_ms": 4400}, "s1-confianza.prompt": {"url": "http://localhost:4006/files/lesson-audio/edb085da2baa1b93b68854eed3ad83fca9be0f9f20f1134f806dad9c025e2107.mp3", "hash": "93286354f7d4d5003c9f231b40a07488a85acd963ab5c9055ab894e5ca18f291", "bytes": 106848, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/edb085da2baa1b93b68854eed3ad83fca9be0f9f20f1134f806dad9c025e2107.mp3", "duration_ms": 17760}, "s1-confianza.choices": {"url": "http://localhost:4006/files/lesson-audio/600a2610927c7e5f3c1a92265bbf70a0cda6dbb97a1b7977697db7f69e20b7bd.mp3", "hash": "d0fecd8807f0645af0cf574029a633559b97b8177b2ee13ad79d3008c764b388", "bytes": 22464, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/600a2610927c7e5f3c1a92265bbf70a0cda6dbb97a1b7977697db7f69e20b7bd.mp3", "duration_ms": 3680}, "s1-confianza.explanation": {"url": "http://localhost:4006/files/lesson-audio/d715a8e30fc18646fcf10a3b2b6e484186a472a3f8190d29b3cba7dd2eef45c2.mp3", "hash": "5fd05f22e8a3c3cb64f1f880aa26cfb850cb9a5f91282dc3f21880cd3c457fd8", "bytes": 66096, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d715a8e30fc18646fcf10a3b2b6e484186a472a3f8190d29b3cba7dd2eef45c2.mp3", "duration_ms": 10960}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'es-MX', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "story-branch", "title": "El precio justo", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir el precio de la limonada considerando el costo por vaso y la meta de ahorro", "Observar cómo cada decisión de precio afecta las ventas y el avance hacia la guitarra"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-limonada", "xp": 20, "type": "story_branch", "hints": ["Piensa: si el precio es muy bajo, ganas poco por vaso. Si es muy alto, quizá nadie compre.", "Recuerda que cada vaso cuesta 2 pesos. Lo que realmente ganas es el precio menos esos 2 pesos."], "title": "Elige el precio de hoy", "payload": {"nodes": [{"id": "inicio", "choices": [{"id": "precio5", "next": "final5", "text_md": "5 pesos (el precio de siempre)"}, {"id": "precio3", "next": "final3", "text_md": "3 pesos (más barato)"}, {"id": "precio10", "next": "final10", "text_md": "10 pesos (el doble)"}], "emotion": "thinking", "text_md": "¡Hace un calor enorme! Ya vienen 6 vecinos con sed. ¿A qué precio vendo cada vaso?", "character": "liruf"}, {"id": "final5", "choices": [{"id": "fin5", "next": null, "text_md": "Fin"}], "emotion": "happy", "text_md": "¡Los 6 compran! Cada vaso te deja 3 pesos de ganancia (5 - 2 = 3). Son 6 × 3 = 18 pesos. ¡Buen avance hacia la guitarra!", "character": "liruf"}, {"id": "final3", "choices": [{"id": "fin3", "next": null, "text_md": "Fin"}], "emotion": "surprised", "text_md": "Se acaba volando, pero solo ganas 1 peso por vaso (3 - 2 = 1). Son 6 × 1 = 6 pesos. Casi no subes para la guitarra…", "character": "liruf"}, {"id": "final10", "choices": [{"id": "fin10", "next": null, "text_md": "Fin"}], "emotion": "neutral", "text_md": "Los vecinos hacen mueca y se van a la nieve. Te quedas con la jarra llena y 0 pesos. La guitarra se ve lejana…", "character": "liruf"}], "start_node": "inicio"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf ya separó los hechos de las opiniones en su puesto. Ahora viene lo difícil: **decidir el precio de la limonada de HOY**. Cada vaso le cuesta **2 pesos** hacerlo. Su meta es juntar **80 pesos** para una guitarra. ¿Qué precio le pones?", "difficulty": 2, "explanation_md": "La decisión de precio cambia cuánto avanzas hacia la guitarra de 80 pesos. Con 5 pesos por vaso, los 6 vecinos compran y ganas 3 pesos por vaso, ¡18 pesos en total! Con 3 pesos, también venden todos pero solo ganas 1 peso por vaso, apenas 6 pesos. Con 10 pesos, nadie compra y no ganas nada.", "audio_segment_id": "s1-precio-limonada.prompt"}], "schema_version": 1}', '{"s1-precio-limonada": {"qualities": [{"score": 100, "node_id": "inicio", "choice_id": "precio5"}, {"score": 30, "node_id": "inicio", "choice_id": "precio3"}, {"score": 0, "node_id": "inicio", "choice_id": "precio10"}]}}', '{"units": {"s1-precio-limonada.hint.0": {"url": "http://localhost:4006/files/lesson-audio/bb22a26f3518b2b9bf806727a63e98bf587dc991196f11e6df6fc9f54d106da6.mp3", "hash": "f0cb8e4f575f2675b6d730baab11223f23871b1e2e274d5e4d0668d6e3096a03", "bytes": 44496, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/bb22a26f3518b2b9bf806727a63e98bf587dc991196f11e6df6fc9f54d106da6.mp3", "duration_ms": 7360}, "s1-precio-limonada.hint.1": {"url": "http://localhost:4006/files/lesson-audio/3760d7f4f90ae32d401bccc2447f98ffcb3db819e12ead7ce0ea452dd773ce87.mp3", "hash": "d273724d635c09b54040ae01f069e542fa0f2bdfcc4c6484e2851720536265a9", "bytes": 44496, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/3760d7f4f90ae32d401bccc2447f98ffcb3db819e12ead7ce0ea452dd773ce87.mp3", "duration_ms": 7360}, "s1-precio-limonada.prompt": {"url": "http://localhost:4006/files/lesson-audio/a1d74d3e5b4cb7ae56c4e3fc584d1089a6f640da0fe5ec137697b62284abecda.mp3", "hash": "c63bdc150406caaeddf9f005afb087da9745e67d7a70208094726534ebcf223e", "bytes": 88704, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/a1d74d3e5b4cb7ae56c4e3fc584d1089a6f640da0fe5ec137697b62284abecda.mp3", "duration_ms": 14720}, "s1-precio-limonada.explanation": {"url": "http://localhost:4006/files/lesson-audio/b1b964036aa7e245f51dc09f3c252b02b718de5b3b9850629a0a1c1513df8794.mp3", "hash": "85959823428b53cc41c556759441dc733f069bab334180e1d6ea7b31ad5bb0a6", "bytes": 134208, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/b1b964036aa7e245f51dc09f3c252b02b718de5b3b9850629a0a1c1513df8794.mp3", "duration_ms": 22320}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "piggy-split", "title": "Dividir o lucro", "locale": "pt-BR", "subject": "money", "objectives": ["Dividir um lucro de 10 reais entre dois cofrinhos: um para a meta do violão e outro para repor ingredientes."], "estimated_minutes": 4}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 15, "type": "piggy_split", "hints": ["Se você colocar 3 nos ingredientes, quanto sobra para o violão?", "Os dois números devem somar 10."], "title": "Dividir o lucro", "payload": {"jars": [{"id": "guitar", "icon": "savings", "label": "Cofrinho do violão", "hint_md": "Para o violão de 80 reais"}, {"id": "ingredients", "icon": "local_cafe", "label": "Cofrinho de ingredientes", "hint_md": "Para repor limões e copos"}], "step": 1, "unit": "MXN", "income": 10}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Ontem Liruf te deu 15 reais de troco. Hoje ganhou mais 10 reais. Precisa guardar pelo menos 3 reais para comprar limões amanhã, e o resto para o violão de 80 reais. Quanto você coloca em cada cofrinho? Você tem que dividir os 10 reais completos!", "difficulty": 2, "explanation_md": "Você dividiu 10 reais: 3 para ingredientes e 7 para o violão. Assim Liruf pode comprar limões amanhã e continua economizando para o violão.", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"guitar": {"max": 10, "min": 0}, "ingredients": {"max": 10, "min": 3}}, "rationale_md": "Los dos números deben sumar 10, y al menos 3 deben ir a ingredientes. Por ejemplo, 3 y 7 suman 10. Así Liruf asegura los limones y ahorra para la guitarra."}}', '{"units": {"s1-piggy-split.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b107fbeab2609fb04ea51fe825b00870c8002593bc7c507ba3365a466243b6af.mp3", "hash": "300414c4668d307391307f3ac0b43be72255981de0b7515ae16976c7d2620ff0", "bytes": 30528, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b107fbeab2609fb04ea51fe825b00870c8002593bc7c507ba3365a466243b6af.mp3", "duration_ms": 5040}, "s1-piggy-split.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b1ee335c76da5bca6f9ccac3e863f9fe030ddf9ef7b6b995fbe7ef9221c142d0.mp3", "hash": "8d4b0c7a177e52deeb12878c481b5bcedd36491fa318934cc649cf00b22bb701", "bytes": 14688, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b1ee335c76da5bca6f9ccac3e863f9fe030ddf9ef7b6b995fbe7ef9221c142d0.mp3", "duration_ms": 2400}, "s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/094ae1b77dadbc6cb4a52901d42b7727ca5f4a82ce8e85a5fb9c01453850ffd4.mp3", "hash": "6838b8e1f493156fcc8a47b0af093a6bd43c699b7a9cffbcf312623a5abb304f", "bytes": 107424, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/094ae1b77dadbc6cb4a52901d42b7727ca5f4a82ce8e85a5fb9c01453850ffd4.mp3", "duration_ms": 17840}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/45366cd6a97e52bb6c644b9a0eb9a79b9cf492c1531591efcab9491e8f611eef.mp3", "hash": "c3ff031e6909c2024d0cbf6307a2b5695071d1d3e60f336909dffefd411d9847", "bytes": 65664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/45366cd6a97e52bb6c644b9a0eb9a79b9cf492c1531591efcab9491e8f611eef.mp3", "duration_ms": 10880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "needs-wants", "title": "Necesidades y deseos en el puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Separar necesidades del puesto de limones y hielo de deseos personales como paleta o cómic."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 10, "type": "needs_wants", "hints": ["Piensa: ¿sin esto el puesto no puede hacer limonada?", "Lo que Liruf quiere para divertirse es un deseo, no una necesidad del puesto."], "title": "El puesto come primero", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Limones"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Hielo"}, {"id": "paleta", "icon": "icecream", "text_md": "Paleta de fresa"}, {"id": "comic", "icon": "menu_book", "text_md": "Cómic de superhéroes"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf ganó 10 pesos y ya separó 5 para su guitarra. Los otros 5 son para reponer ingredientes. Ayuda a Dina a decidir: ¿qué compras son para el puesto (necesidad) y cuáles son para Liruf (deseo)? Toca cada cosa y colócala en la categoría correcta.", "difficulty": 1, "explanation_md": "Los limones y el hielo son necesidades del puesto porque sin ellos no hay limonada. La paleta y el cómic son deseos de Liruf, no urgentes para el negocio.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["limones", "hielo"]}}', '{"units": {"s1-needs-wants.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b4da18fa9828bad79415b8309594d58acc51417260b03ebe0de4f2130d07a768.mp3", "hash": "6304cef554a073d5110118ccebaa5e7b1e193489240258ca90e8ce20ac5b858d", "bytes": 21024, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b4da18fa9828bad79415b8309594d58acc51417260b03ebe0de4f2130d07a768.mp3", "duration_ms": 3440}, "s1-needs-wants.hint.1": {"url": "http://localhost:4006/files/lesson-audio/315db4fbd9e8ee6ca3888f2dce7924b9050299bed3f2434c79b7481539b7b94e.mp3", "hash": "1f6fd1ac65ab4f9a63ae74033d500c91166031842396da72a7ccd606eab5b0e7", "bytes": 34848, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/315db4fbd9e8ee6ca3888f2dce7924b9050299bed3f2434c79b7481539b7b94e.mp3", "duration_ms": 5760}, "s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/8b2afce7931a8e2b621b4fab54f42c3df3623670d9c0f212baac5df5390ceae3.mp3", "hash": "d95d737270f0d5959b4e853707120c30e173932db61ee34c438b7f9fb7ece4f1", "bytes": 108288, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8b2afce7931a8e2b621b4fab54f42c3df3623670d9c0f212baac5df5390ceae3.mp3", "duration_ms": 18000}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/94c1dc9f598cc639961313dff814f75139f199c4c340aa8f945595b6c2b3f2e7.mp3", "hash": "4c26eb18da2fb45bef112c25a037018c52d5172b6c0f0715a9aa8a36486ee224", "bytes": 71424, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/94c1dc9f598cc639961313dff814f75139f199c4c340aa8f945595b6c2b3f2e7.mp3", "duration_ms": 11840}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "interest-peek", "title": "La alcancía que agradece la paciencia", "locale": "es-MX", "subject": "money", "objectives": ["Decidir si dejar dinero en una alcancía que da moneditas extra cada semana conviene más que gastarlo ya.", "Predecir el total después de esperar, entendiendo que crece un poco pero no se duplica."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 10, "type": "interest_peek", "hints": ["Cada semana la alcancía da 2 monedas de 1 peso. ¿Cuántas monedas extra da en 2 semanas?", "Empieza con 20. Suma las moneditas extra."], "title": "¿Dejar los 20 o sacarlos ya?", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 20, "prediction": {"kind": "choice", "options": [{"id": "opt1", "text_md": "Se queda en 20"}, {"id": "opt2", "text_md": "24 pesos"}, {"id": "opt3", "text_md": "Casi 40 pesos"}]}}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf tiene 20 pesos ahorrados para una guitarra que cuesta 80. Rho le dice: ''Si guardas tu dinero en esta alcancía especial, cada semana te da 2 monedas de 1 peso extra por dejarlo ahí.'' Liruf mete sus 20 pesos. Piensa: ''Si espero 2 semanas, ¿tendré más o menos que si gasto todo ahora?'' ¿Cuánto tendrá Liruf después de 2 semanas?", "difficulty": 1, "explanation_md": "La alcancía da 2 monedas de 1 peso cada semana, así que en 2 semanas da 4 pesos extra. 20 + 4 = 24. ¡El dinero crece poquito a poquito hacia la guitarra! Si hubiera gastado todo ahora, no tendría esos 4 pesos extra.", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 24, "tolerance": 1, "correct_option_id": "opt2"}}', '{"units": {"s1-interest-peek.hint.0": {"url": "http://localhost:4006/files/lesson-audio/668ab78163ee044ba3efd11e77b6e3eec662ac301caa366cdc069a4a6dc98a2b.mp3", "hash": "3dc18383d9a32c406d7fbe70048d4c251d4877228f2348bcfeef02d3057b0217", "bytes": 40608, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/668ab78163ee044ba3efd11e77b6e3eec662ac301caa366cdc069a4a6dc98a2b.mp3", "duration_ms": 6720}, "s1-interest-peek.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0ec9032c2aa437cfaaac7e397a9407c360275eb841b0372c911b3802ec3b3fd3.mp3", "hash": "ac7225036bac770feb6907a8d2cdac588fcdfe82d73be88200379222db2cac7f", "bytes": 21024, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0ec9032c2aa437cfaaac7e397a9407c360275eb841b0372c911b3802ec3b3fd3.mp3", "duration_ms": 3440}, "s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/4713ac3a791be4ee9f44e0de9ba4fa32ce5a19be02bf391a7b1aa0027b175ba5.mp3", "hash": "bb23ce2312a94c7ed78d3215c8a47b3b4ddc843eb4ca2970f9243cfe474e18df", "bytes": 131328, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4713ac3a791be4ee9f44e0de9ba4fa32ce5a19be02bf391a7b1aa0027b175ba5.mp3", "duration_ms": 21840}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/56ed1be12a6d3a85e0602e52b13ba8b9bb1a113b29b8de014b9331aa3ca45dbd.mp3", "hash": "e4009c6e87dc657fc8d8b2b77b6ceafab722fa548a5d58601a4ec344defe357a", "bytes": 100224, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/56ed1be12a6d3a85e0602e52b13ba8b9bb1a113b29b8de014b9331aa3ca45dbd.mp3", "duration_ms": 16640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "match-pairs", "title": "Match the prices", "locale": "en-US", "subject": "money", "objectives": ["Match each product from the stand with its correct price (small cup–5, pitcher–20, cookie–3)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-prices", "xp": 10, "type": "match_pairs", "hints": ["If 3 cups cost 15 pesos, each cup costs 5 pesos. The pitcher costs 20 and the cookie costs 3."], "title": "Dina''s Labels", "payload": {"left": [{"id": "vaso", "text_md": "Small cup"}, {"id": "jarra", "text_md": "Pitcher"}, {"id": "galleta", "text_md": "Cookie"}], "right": [{"id": "p5", "text_md": "5 pesos"}, {"id": "p20", "text_md": "20 pesos"}, {"id": "p3", "text_md": "3 pesos"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Yesterday Dina sold 3 small cups and earned 15 pesos. How much does ONE small cup cost? Use that to match each product with its price: tap the product and then its price.", "difficulty": 1, "explanation_md": "3 cups for 15 pesos means each cup costs 5 pesos (because 5+5+5=15). The pitcher costs 20 and the cookie costs 3. Well done!", "audio_segment_id": "s1-match-prices.prompt"}], "schema_version": 1}', '{"s1-match-prices": {"pairs": [["vaso", "p5"], ["jarra", "p20"], ["galleta", "p3"]]}}', '{"units": {"s1-match-prices.hint.0": {"url": "http://localhost:4006/files/lesson-audio/16ff184de5350c518249378edc07b66c14c4f3450d7f74320793c953cfeb3884.mp3", "hash": "20569d3a5b4346859047e6e8436c2d5e0550c9cf14db71b50b44ef5c56e66c6d", "bytes": 43056, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/16ff184de5350c518249378edc07b66c14c4f3450d7f74320793c953cfeb3884.mp3", "duration_ms": 7120}, "s1-match-prices.prompt": {"url": "http://localhost:4006/files/lesson-audio/a6690067104a6d24585246a6dd7871b15881f29ae8713668d9b8a1b698c75183.mp3", "hash": "975f244895f12e37992e2fbbb40d7702c9c8483454ca2a2f0f85d68d45260e66", "bytes": 62208, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a6690067104a6d24585246a6dd7871b15881f29ae8713668d9b8a1b698c75183.mp3", "duration_ms": 10320}, "s1-match-prices.explanation": {"url": "http://localhost:4006/files/lesson-audio/649cc4a894f6cec4851b783713f18e824e8aa72b8e54b2a8bf77fa6ed0932230.mp3", "hash": "f93de5a2024c9440113e0afd888d1e9fd4ae620d684103702ec2bfb0168db9dc", "bytes": 68976, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/649cc4a894f6cec4851b783713f18e824e8aa72b8e54b2a8bf77fa6ed0932230.mp3", "duration_ms": 11440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'en-US', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "code-order", "title": "Build the cardboard cash register", "locale": "en-US", "subject": "mixed", "objectives": ["Order the steps for the homemade cash register: receive payment, verify amount, give change, record the sale."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-registradora", "xp": 10, "type": "code_order", "hints": ["What do you do first when someone pays you?", "After receiving the money, what should you check to avoid giving too much change?"], "title": "The cardboard cash register", "payload": {"blocks": [{"id": "recibir", "text_md": "Receive payment"}, {"id": "verificar", "text_md": "Verify amount"}, {"id": "dar_cambio", "text_md": "Give change"}, {"id": "anotar", "text_md": "Record the sale"}], "language_hint": "Order the steps of the cash register."}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Last week you chose between earning 10 pesos today or 20 later. Today, Rho has a sale: Dina buys a notebook for 12 pesos and pays with a 20-peso bill. Rho knows she must give 8 pesos in change. But if she skips a step, she might give 10 instead of 8 and lose money! Help Rho order the steps so she doesn''t make a mistake. Tap the blocks in the correct order.", "difficulty": 1, "explanation_md": "The correct order is: receive payment, verify amount, give change, record the sale. If Rho checks the amount first, she knows how much change to give. If she records before giving change, she might get confused and give the wrong change. If you put ''record'' before ''give change'', Rho might give 10 instead of 8 and lose 2 pesos. That way Rho doesn''t lose money!", "audio_segment_id": "s1-ordenar-registradora.prompt"}], "schema_version": 1}', '{"s1-ordenar-registradora": {"order": ["recibir", "verificar", "dar_cambio", "anotar"]}}', '{"units": {"s1-ordenar-registradora.hint.0": {"url": "http://localhost:4006/files/lesson-audio/32ec8dcb93fec633c4f00950e38b8f4c498016b2f0aaf89ac3b01ac8429805f5.mp3", "hash": "99cbf8d8fb8495120b83c5f988420e66667e3f15ffbe51add2a2332f069b92c0", "bytes": 19008, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/32ec8dcb93fec633c4f00950e38b8f4c498016b2f0aaf89ac3b01ac8429805f5.mp3", "duration_ms": 3120}, "s1-ordenar-registradora.hint.1": {"url": "http://localhost:4006/files/lesson-audio/34961797c18425076e48007d0df72c1f1531983885d7ecfb0c518c1918abf2b3.mp3", "hash": "b5b95744a3fe9554bbc801480afa0b0d5469857a8f6bd1d8ea1c9060f75a88b1", "bytes": 31536, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/34961797c18425076e48007d0df72c1f1531983885d7ecfb0c518c1918abf2b3.mp3", "duration_ms": 5200}, "s1-ordenar-registradora.prompt": {"url": "http://localhost:4006/files/lesson-audio/1f1234eb795197f591238a7c61380ffa02114b932132f397c0411614972004d4.mp3", "hash": "9002c632123476c159c00c3ae2372f90991557dfbadfd3fd84ad3451b74bb07d", "bytes": 167328, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/1f1234eb795197f591238a7c61380ffa02114b932132f397c0411614972004d4.mp3", "duration_ms": 27840}, "s1-ordenar-registradora.explanation": {"url": "http://localhost:4006/files/lesson-audio/42f346adc4eb21ce7c701fdf96460f1856c75fa500fb43e95b136ccd02ad1539.mp3", "hash": "2cff38b406be7164091e84224c3c6fbd8d3a3750ef1175b227bb71526f897d64", "bytes": 140544, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/42f346adc4eb21ce7c701fdf96460f1856c75fa500fb43e95b136ccd02ad1539.mp3", "duration_ms": 23360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'en-US', '1', '{"meta": {"cast": ["rho", "liruf"], "slug": "savings-goal", "title": "How many weeks for the guitar?", "locale": "en-US", "subject": "money", "objectives": ["Calculate how many weeks you need to save to reach a goal of 80 pesos with different weekly savings.", "Compare the times with a 4-week deadline to decide which plan works."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-savings-goal", "xp": 15, "type": "savings_goal", "hints": ["Think about how many times the amount he sets aside each week fits into 80 pesos. For example, if he sets aside 10 pesos, he needs 8 weeks because 10+10+10+10+10+10+10+10 = 80."], "title": "Savings plans", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Liruf already earned **20 pesos** this weekend from his lemonade stand. He saves everything in his piggy bank for the **80-peso** guitar. But the band contest is in **4 weeks**. He can set aside **10**, **20**, or **40 pesos** each week. Help Liruf decide: tap each option to see how many weeks he needs. Does any plan make it in time for the contest?", "difficulty": 2, "explanation_md": "If he sets aside 10 pesos each week, he needs 8 weeks (10+10+10+10+10+10+10+10 = 80). With 20 pesos, he needs 4 weeks (20+20+20+20 = 80). With 40 pesos, he needs 2 weeks (40+40 = 80). Only the 20 and 40 peso plans make it before or exactly at 4 weeks. Liruf can play in the contest if he chooses one of those!", "audio_segment_id": "s1-savings-goal.prompt"}], "schema_version": 1}', '{"s1-savings-goal": {"correct": {"10": 8, "20": 4, "40": 2}}}', '{"units": {"s1-savings-goal.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1b25958260f52d9ed3a5ba07edae21563e84bb51a7b9fbbf14a0bc25afe02f1f.mp3", "hash": "ad8ff5bcd57a06c027c633724d2a3159e6d238a347453781d971dcda61faf033", "bytes": 106416, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/1b25958260f52d9ed3a5ba07edae21563e84bb51a7b9fbbf14a0bc25afe02f1f.mp3", "duration_ms": 17680}, "s1-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/6884de963a4ac3db366a94de6d0a75935b38d02068111af801b5ec438fb1b7ab.mp3", "hash": "05d6e0ad2a3d51c873316ec6dd19ce227d3374b70b43bbeeb325f792bc5192cd", "bytes": 145728, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/6884de963a4ac3db366a94de6d0a75935b38d02068111af801b5ec438fb1b7ab.mp3", "duration_ms": 24240}, "s1-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/881b8de2c5effa3fafd4fcb43e9c0c5786199c769efc2ddf7ae54dd1cea1f4ab.mp3", "hash": "a509a1e8f521ed4c55b9de8d577ca3827a192bb7a53b8c32cb7f4ec5275eae55", "bytes": 186624, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/881b8de2c5effa3fafd4fcb43e9c0c5786199c769efc2ddf7ae54dd1cea1f4ab.mp3", "duration_ms": 31040}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'es-MX', '1', E'{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "order-steps", "title": "Ordena las compras del puesto", "locale": "es-MX", "subject": "money", "objectives": ["Ordenar las compras del mercado por prioridad de venta: primero lo que genera ganancias hoy, luego lo que mejora la venta, al final el lujo."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-compras", "xp": 10, "type": "order_steps", "hints": ["Pregúntate: ¿sin esto puedo vender limonada HOY?", "Lo que deja ganar dinero hoy va primero, lo que es solo un gusto va al final."], "title": "Ordena las compras del puesto", "payload": {"items": [{"id": "limones", "text_md": "Limones — 8 pesos"}, {"id": "vasos", "text_md": "Vasos — 6 pesos"}, {"id": "azucar", "text_md": "Azúcar — 4 pesos"}, {"id": "calcomanias", "text_md": "Calcomanías — 2 pesos"}]}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Liruf tiene **20 pesos** y necesita comprar estas 4 cosas para su puesto de limonada. **Ordénalas de la MÁS necesaria para vender hoy a la que puede esperar.**\\n\\n- Limones (sin ellos no hay limonada)\\n- Vasos (sin ellos no se sirve)\\n- Azúcar (para que sepa rico y vuelvan)\\n- Calcomanías (para decorar, pero no urgentes)", "difficulty": 1, "explanation_md": "Primero los limones (sin ellos no hay limonada), luego los vasos (para servirla), después el azúcar (mejora el sabor) y al final las calcomanías (son un lujo que puede esperar).", "audio_segment_id": "s1-ordenar-compras.prompt"}], "schema_version": 1}', '{"s1-ordenar-compras": {"order": ["limones", "vasos", "azucar", "calcomanias"]}}', '{"units": {"s1-ordenar-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/21afd7d9db6251ec515b4b32ad103c229a70d93149d20e928f54b554424e14e8.mp3", "hash": "624a89e3ce43215709356f091941eea8b7a354a085fda53de01a7d4fe718da99", "bytes": 21456, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/21afd7d9db6251ec515b4b32ad103c229a70d93149d20e928f54b554424e14e8.mp3", "duration_ms": 3520}, "s1-ordenar-compras.hint.1": {"url": "http://localhost:4006/files/lesson-audio/48454c290b54e5cf05836108d49563fe532a7cd64611ff6645d4fb7d8ab548fe.mp3", "hash": "22d3a708afdd519a20095a86dcba3ccf19e5908d286a01c20720da46655348ea", "bytes": 29088, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/48454c290b54e5cf05836108d49563fe532a7cd64611ff6645d4fb7d8ab548fe.mp3", "duration_ms": 4800}, "s1-ordenar-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/d2d61574af2ed51063df2923b1d98d89087e00bccdfa6471e13caa515839ee64.mp3", "hash": "557bb2b61e933af4e99c5b625783ef059ce2c00b51471ec6b0e996a372bd3e22", "bytes": 115056, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/d2d61574af2ed51063df2923b1d98d89087e00bccdfa6471e13caa515839ee64.mp3", "duration_ms": 19120}, "s1-ordenar-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/acc2f521daf97639d3e8ec870f7eb0522d11d283c3c0b50a1a0adc0d4863fd91.mp3", "hash": "15d4bd9dfbe818f4649d476cbc654fdfca8c9a1453bd3fdb610f40e6e48b59da", "bytes": 65664, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/acc2f521daf97639d3e8ec870f7eb0522d11d283c3c0b50a1a0adc0d4863fd91.mp3", "duration_ms": 10880}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "make-change", "title": "Dar cambio exacto", "locale": "es-MX", "subject": "money", "objectives": ["Calcular el cambio de una compra de 8 pesos pagando con billete de 20 usando monedas de 1, 2, 5 y 10."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-make-change", "xp": 10, "type": "make_change", "hints": ["Primero suma cuánto cuesta todo lo que compró don Beto.", "El cambio es lo que sobra del billete después de pagar."], "title": "El cambio de don Beto", "payload": {"price": 8, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf acaba de contar monedas para pagar 5 pesos por su limonada. Ahora don Beto compra un vaso de limonada de 5 pesos y una galleta de 3 pesos. Paga con un billete de 20. Pero don Beto necesita cambio exacto para el camión. Si le das menos de lo que debe, ¡se quedará sin pasaje! ¿Cuánto cambio le tienes que dar? Arma el cambio con las monedas que tienes.", "difficulty": 1, "explanation_md": "El total es 5 + 3 = 8 pesos. Pagó con 20, así que el cambio es 20 - 8 = 12 pesos. Le diste 12 pesos en monedas. ¡Así don Beto puede tomar el camión!", "audio_segment_id": "s1-make-change.prompt"}], "schema_version": 1}', '{"s1-make-change": {}}', '{"units": {"s1-make-change.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a54c7dd395ae10ddcac656e5a19415950af2bfb1f73def9139e0929b3695db10.mp3", "hash": "a115edfdc2849747b8e038fa62e09e99e2f78fcf93f34543f209187386bcdc39", "bytes": 21456, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/a54c7dd395ae10ddcac656e5a19415950af2bfb1f73def9139e0929b3695db10.mp3", "duration_ms": 3520}, "s1-make-change.hint.1": {"url": "http://localhost:4006/files/lesson-audio/d66a21dc89c3269cc5147d5e6c1c355b0509cf6f9a8428958728d6d7962d92fe.mp3", "hash": "776ba98ba107d42ac7a0fb53c413dac27778400e93d3f40647ce4682f2c01fc6", "bytes": 24336, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/d66a21dc89c3269cc5147d5e6c1c355b0509cf6f9a8428958728d6d7962d92fe.mp3", "duration_ms": 4000}, "s1-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/1e8440170ee0eba5d530333a178a682777a2df09c5a46eeb091b93b4417c6829.mp3", "hash": "1bd958a390210d7f6dfc6c3a270781e39156335a9e5a32ace49ae61011776244", "bytes": 150048, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/1e8440170ee0eba5d530333a178a682777a2df09c5a46eeb091b93b4417c6829.mp3", "duration_ms": 24960}, "s1-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/c4f0a1fa679bc8c7f908913c2fe58af944de3ad7f4bab07e6d5352f34a28c658.mp3", "hash": "ba6ea7a6348eff5be9f2a8c2c55bea5ce3d339d3aa3228cf4dac2bb8cdb92959", "bytes": 76608, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/c4f0a1fa679bc8c7f908913c2fe58af944de3ad7f4bab07e6d5352f34a28c658.mp3", "duration_ms": 12720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "match-pairs", "title": "Combine os preços", "locale": "pt-BR", "subject": "money", "objectives": ["Combine cada produto da barraca com seu preço correto (copo pequeno–5, jarra–20, biscoito–3)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-prices", "xp": 10, "type": "match_pairs", "hints": ["Se 3 copos custam 15 pesos, cada copo custa 5 pesos. A jarra custa 20 e o biscoito 3."], "title": "As etiquetas da Dina", "payload": {"left": [{"id": "vaso", "text_md": "Copo pequeno"}, {"id": "jarra", "text_md": "Jarra"}, {"id": "galleta", "text_md": "Biscoito"}], "right": [{"id": "p5", "text_md": "5 pesos"}, {"id": "p20", "text_md": "20 pesos"}, {"id": "p3", "text_md": "3 pesos"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Ontem Dina vendeu 3 copos pequenos e ganhou 15 pesos. Quanto custa UM copo pequeno? Use isso para combinar cada produto com seu preço: toque no produto e depois no preço.", "difficulty": 1, "explanation_md": "3 copos por 15 pesos significa que cada copo custa 5 pesos (porque 5+5+5=15). A jarra custa 20 e o biscoito 3. Muito bem!", "audio_segment_id": "s1-match-prices.prompt"}], "schema_version": 1}', '{"s1-match-prices": {"pairs": [["vaso", "p5"], ["jarra", "p20"], ["galleta", "p3"]]}}', '{"units": {"s1-match-prices.hint.0": {"url": "http://localhost:4006/files/lesson-audio/76c08221d7e8bb8d28df66e4a107649ae6a8e43825a34d35e7136112ec60eae2.mp3", "hash": "5b7afc07fc7b4e1a4dd974ac75b1a44b28332b0aa85b7d3b07657c8cf9a3de7b", "bytes": 51696, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/76c08221d7e8bb8d28df66e4a107649ae6a8e43825a34d35e7136112ec60eae2.mp3", "duration_ms": 8560}, "s1-match-prices.prompt": {"url": "http://localhost:4006/files/lesson-audio/bb9297d4dec9967ee2b9d60788e1741d6c38efaecfaf88d0a1fe3451d194fe6c.mp3", "hash": "c80ba0ebae3c53837a50149a9a08c54d0aa538c87b1590948036ee846361bc6e", "bytes": 77616, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/bb9297d4dec9967ee2b9d60788e1741d6c38efaecfaf88d0a1fe3451d194fe6c.mp3", "duration_ms": 12880}, "s1-match-prices.explanation": {"url": "http://localhost:4006/files/lesson-audio/318e8531e70eeeab7f711838760733643c5f78fae99fca1d23aa70eafacb8a8b.mp3", "hash": "387362253eeb95a1ca7f8eb5f9a9c3de09297a3866a147921179212c193f036f", "bytes": 83376, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/318e8531e70eeeab7f711838760733643c5f78fae99fca1d23aa70eafacb8a8b.mp3", "duration_ms": 13840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "needs-wants", "title": "Necessidades e desejos na barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Separar necessidades da barraca de limões e gelo de desejos pessoais como picolé ou gibi."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 10, "type": "needs_wants", "hints": ["Pense: sem isso a barraca não consegue fazer limonada?", "O que Liruf quer para se divertir é um desejo, não uma necessidade da barraca."], "title": "A barraca come primeiro", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Limões"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Gelo"}, {"id": "paleta", "icon": "icecream", "text_md": "Picolé de morango"}, {"id": "comic", "icon": "menu_book", "text_md": "Gibi de super-heróis"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf ganhou 10 reais e já separou 5 para o violão dele. Os outros 5 são para repor ingredientes. Ajude a Dina a decidir: quais compras são para a barraca (necessidade) e quais são para o Liruf (desejo)? Toque em cada coisa e coloque na categoria correta.", "difficulty": 1, "explanation_md": "Os limões e o gelo são necessidades da barraca porque sem eles não há limonada. O picolé e o gibi são desejos do Liruf, não urgentes para o negócio.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["limones", "hielo"]}}', '{"units": {"s1-needs-wants.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f0436a16dbba5b2c6123703dfed0801eed302eeef0d429f938755d0b17a5be60.mp3", "hash": "d2ee65c9dd8a131dee8b88da7321e020db3d47af252b2ea3b6e8da5577f00d8a", "bytes": 24336, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f0436a16dbba5b2c6123703dfed0801eed302eeef0d429f938755d0b17a5be60.mp3", "duration_ms": 4000}, "s1-needs-wants.hint.1": {"url": "http://localhost:4006/files/lesson-audio/26656913dda0e8a5f3782f95384f7d96edb9475dee9dc10cc9c8969ed5103a25.mp3", "hash": "dbff4e344e9ef1e32d14adff0f376b9dbd0e7b45b09144312f77c9cfb45f8b83", "bytes": 32544, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/26656913dda0e8a5f3782f95384f7d96edb9475dee9dc10cc9c8969ed5103a25.mp3", "duration_ms": 5360}, "s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/ecc0d251200b3468a7b1c4c12f5a7032e653b100727d930be31584e8d0eeda30.mp3", "hash": "4f077e1ff357164c07a90c7b4eb667eba251c6467828afc140d38685ca5a7e34", "bytes": 110736, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ecc0d251200b3468a7b1c4c12f5a7032e653b100727d930be31584e8d0eeda30.mp3", "duration_ms": 18400}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/7f9dc220e42c2d3b6099039f63075019f5a0c71eb2eee88b81d189498b7a5ea3.mp3", "hash": "82360d44068698305b4a50b48114ad7f0d76a27a34cdaf3786b67d4f38c91ebf", "bytes": 68976, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7f9dc220e42c2d3b6099039f63075019f5a0c71eb2eee88b81d189498b7a5ea3.mp3", "duration_ms": 11440}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'pt-BR', '1', '{"meta": {"cast": ["rho", "liruf"], "slug": "savings-goal", "title": "Quantas semanas para o violão?", "locale": "pt-BR", "subject": "money", "objectives": ["Calcular quantas semanas são necessárias para economizar e atingir uma meta de 80 reais com diferentes economias semanais.", "Comparar os tempos com um prazo de 4 semanas para decidir qual plano funciona."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-savings-goal", "xp": 15, "type": "savings_goal", "hints": ["Pense em quantas vezes cabe o que ele separa a cada semana em 80 reais. Por exemplo, se ele separa 10 reais, precisa de 8 semanas porque 10+10+10+10+10+10+10+10 = 80."], "title": "Planos de economia", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Liruf já ganhou **20 reais** neste fim de semana com sua barraca de limonada. Ele guarda tudo no seu cofrinho para o violão de **80 reais**. Mas o concurso de bandas é em **4 semanas**. Ele pode separar **10**, **20** ou **40 reais** a cada semana. Ajude Liruf a decidir: toque em cada opção para ver quantas semanas ele precisa. Algum plano chega a tempo para o concurso?", "difficulty": 2, "explanation_md": "Se ele separar 10 reais a cada semana, precisa de 8 semanas (10+10+10+10+10+10+10+10 = 80). Com 20 reais, precisa de 4 semanas (20+20+20+20 = 80). Com 40 reais, precisa de 2 semanas (40+40 = 80). Apenas os planos de 20 e 40 reais chegam antes ou exatamente em 4 semanas. Liruf pode tocar no concurso se escolher um desses!", "audio_segment_id": "s1-savings-goal.prompt"}], "schema_version": 1}', '{"s1-savings-goal": {"correct": {"10": 8, "20": 4, "40": 2}}}', '{"units": {"s1-savings-goal.hint.0": {"url": "http://localhost:4006/files/lesson-audio/313f52bbee4ee1d1f30fa4de9a21298958389f41ac9af93d8b00bb41a0a4ede9.mp3", "hash": "9287fdb6edf1273b105b28287e7d7ed999f285e88a95d53596fe5387b85ae26c", "bytes": 107424, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/313f52bbee4ee1d1f30fa4de9a21298958389f41ac9af93d8b00bb41a0a4ede9.mp3", "duration_ms": 17840}, "s1-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/a4630f14b21c8ff405f0fdb208688850d5c64b7e76a724d1bfb0be6c0d9d322c.mp3", "hash": "601ccae972f291221eab88676f327855077fd15925fd7d028772ff102e4dac02", "bytes": 158256, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/a4630f14b21c8ff405f0fdb208688850d5c64b7e76a724d1bfb0be6c0d9d322c.mp3", "duration_ms": 26320}, "s1-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/820a43f5e596e1dfcdcc52bb5f7e089fde60bf2276f65cfe4cb7217a5489f0fd.mp3", "hash": "bf1bf24d63c2550139aa527ec35e9f781d59455dedd8c0d2910344d8604fe26f", "bytes": 206208, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/820a43f5e596e1dfcdcc52bb5f7e089fde60bf2276f65cfe4cb7217a5489f0fd.mp3", "duration_ms": 34320}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "count-objects", "title": "Count Liruf''s coins", "locale": "en-US", "subject": "mixed", "objectives": ["Count at a glance how many coins fell from the tipped jar, without recounting", "Understand that each coin represents a 5-peso cup sold", "Relate the count to the sum toward the goal of 80 pesos"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-count-coins", "xp": 10, "type": "count_objects", "hints": ["Look only for the coins with the money symbol, ignore the cookies and the cup.", "Count quietly as you tap each coin."], "title": "Count the coins", "payload": {"scene": [{"icon": "monetization_on", "tint": "primary", "count": 7}, {"icon": "cookie", "tint": "warning", "count": 3}, {"icon": "local_drink", "tint": "accent", "count": 1}], "ask_icon": "monetization_on"}, "narrator": {"emotion": "surprised", "character": "liruf"}, "prompt_md": "Liruf estimated that about 8 cups of lemonade would come out of the jar. But he dropped the sales jar! The coins rolled among the cookie crumbs. Tap each coin to count them. How many coins are there? That way we''ll know if he sold more or less than the 8 cups he estimated.", "difficulty": 1, "explanation_md": "There are 7 coins. Liruf estimated ~8 cups, but he only sold 7. Each coin is a 5-peso cup. That adds up to 35 pesos for the 80-peso guitar!", "audio_segment_id": "s1-count-coins.prompt"}], "schema_version": 1}', '{"s1-count-coins": {"value": 7}}', '{"units": {"s1-count-coins.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b9fa55d30babb7bf0ae8b4df3d00711b0c3d4ef1439875cdf8a3acb09f735967.mp3", "hash": "c30f0320606b04f5936c998e3bd88ed33e904a282c0e22b21d9c8dbdeb76a87e", "bytes": 24336, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/b9fa55d30babb7bf0ae8b4df3d00711b0c3d4ef1439875cdf8a3acb09f735967.mp3", "duration_ms": 4000}, "s1-count-coins.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b482c0609e34e9c544d9193a1808b50b027595e553ef65d6f5f7f05e224d3f78.mp3", "hash": "dd3c3e0b8d1f47ca9e97208e4e3732ac7615035e5b2784a183507ddcf23c778d", "bytes": 14688, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/b482c0609e34e9c544d9193a1808b50b027595e553ef65d6f5f7f05e224d3f78.mp3", "duration_ms": 2400}, "s1-count-coins.prompt": {"url": "http://localhost:4006/files/lesson-audio/d45e41af46e2de47611eb74ae00dd3cccbbd85660e60650b32cdf90ebf08d850.mp3", "hash": "a015b1f3aea6567a143fb8f167eccfa444a85181dcfe999bb92d29127bdbee0b", "bytes": 87264, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/d45e41af46e2de47611eb74ae00dd3cccbbd85660e60650b32cdf90ebf08d850.mp3", "duration_ms": 14480}, "s1-count-coins.explanation": {"url": "http://localhost:4006/files/lesson-audio/058e47cd42b8c92b00097108cc342418959034290f90990654dee4605a4c12f0.mp3", "hash": "760d25e892889f6ef138368fca22436edcbac3451cbd3ee1ca75972bb2cd01eb", "bytes": 68544, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/058e47cd42b8c92b00097108cc342418959034290f90990654dee4605a4c12f0.mp3", "duration_ms": 11360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fair-trade", "title": "Trueque justo", "locale": "es-MX", "subject": "mixed", "objectives": ["Decidir si un trueque es justo comparando valores", "Contar monedas de 1, 2, 5 y 10", "Calcular cambio de un billete de 20", "Planear semanas para ahorrar 80 pesos"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 10, "type": "fair_trade", "hints": ["¿Cuánto pagó Liruf por 2 vasos la semana pasada?", "Si el trueque es justo, Liruf no pierde dinero. ¿Cuánto vale la bolsa de limones?"], "title": "Trueque justo", "payload": {"offer_a": {"qty": 2, "icon": "local_cafe", "label": "2 vasos de limonada"}, "offer_b": {"qty": 1, "icon": "storefront", "label": "Bolsa de limones"}, "rate_md": "La semana pasada, Liruf pagó 10 pesos por 2 vasos de limonada. La bolsa de limones cuesta 10 pesos."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf está ahorrando 20 pesos cada semana para comprar una guitarra de 80 pesos. Ya lleva 3 semanas y tiene 60 pesos. El frutero le ofrece cambiar una bolsa de limones por 2 vasos de limonada. Liruf recuerda que la semana pasada pagó 10 pesos por 2 vasos de limonada. La bolsa de limones cuesta 10 pesos en la tienda. ¿El trueque es justo?", "difficulty": 1, "explanation_md": "La semana pasada, Liruf pagó 10 pesos por 2 vasos de limonada, y la bolsa de limones también cuesta 10 pesos. Ambos valen lo mismo, así que el trueque es justo. Liruf no pierde dinero y sigue con sus 60 pesos más los 20 que ahorrará esta semana, ¡tendrá 80 justo para la guitarra!", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "fair"}}', '{"units": {"s1-fair-trade.hint.0": {"url": "http://localhost:4006/files/lesson-audio/225c2f34ce9f5985637d1ba53d307cd47dfa3d8937537af9e9889ede03169bd9.mp3", "hash": "75ef15e0c180bf2af2b4c1409ad8f48b9eb5c790dbc36fc4a9527e2b3e96eab8", "bytes": 24336, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/225c2f34ce9f5985637d1ba53d307cd47dfa3d8937537af9e9889ede03169bd9.mp3", "duration_ms": 4000}, "s1-fair-trade.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a5dd3214ad7de502b951c4535ee5c8ed085f724260d48cbc43ad4d8e8ac076df.mp3", "hash": "32a0007ae81aa1c90a7ec28cde6d32cd7da4ec006e503a21793503ce4e718856", "bytes": 36864, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/a5dd3214ad7de502b951c4535ee5c8ed085f724260d48cbc43ad4d8e8ac076df.mp3", "duration_ms": 6080}, "s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/f775ca4521bf00edba9dd2a8bf1336b4e44bd0e1d4b9201eb901f8fe2135d92c.mp3", "hash": "7fa11ff3b1e8923f4c841d32cc16bfcdfe44fc32fa3b1049328e5c126973c1b8", "bytes": 138096, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/f775ca4521bf00edba9dd2a8bf1336b4e44bd0e1d4b9201eb901f8fe2135d92c.mp3", "duration_ms": 22960}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/2456feb4e90a8f6848d720fc0116abf1ccbb4fcaac1af7680f6401b467d5d12d.mp3", "hash": "54c864e809e6a750acd5f3b0cb2124ad3ae6e17ca155f34a3f2af3529683613f", "bytes": 113616, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/2456feb4e90a8f6848d720fc0116abf1ccbb4fcaac1af7680f6401b467d5d12d.mp3", "duration_ms": 18880}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'en-US', '1', E'{"meta": {"cast": ["dina"], "slug": "repaso-quiz-mcq", "title": "Review: Fair price and profit", "locale": "en-US", "subject": "mixed", "objectives": ["Review with a direct question the heart of the business: if the cup costs 5 and the ingredients 2, what is the profit per cup?"], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-por-vaso", "xp": 10, "type": "quiz_mcq", "hints": ["Profit is what''s left after paying for the ingredients.", "Subtract the cost of the ingredients from the price of the cup."], "title": "Profit per cup", "payload": {"options": [{"id": "a", "text_md": "3 pesos", "rationale_md": "Correct: 5 (price) - 2 (cost) = 3 pesos profit. Well done!"}, {"id": "b", "text_md": "2 pesos", "rationale_md": "That''s the amount you spent on ingredients, not what you earn. Profit is price minus cost."}, {"id": "c", "text_md": "5 pesos", "rationale_md": "That''s the price of the cup, but you didn''t consider that the ingredients cost money. Profit is what''s left after paying for them."}, {"id": "d", "text_md": "7 pesos", "rationale_md": "You added the price and the cost, but profit is calculated by subtracting, not adding."}], "shuffle": true}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Yesterday you set up the stand with Dina: you set a price for each cup (5 pesos) and calculated that the ingredients cost 2 pesos per cup. Today you sold your first cup. Dina tells you: \\"Congratulations! You sold a cup. Now, how much money did you actually EARN? Remember, the ingredients aren''t free...\\" How much money do you have left after paying for the ingredients of that cup?", "difficulty": 1, "explanation_md": "You earned 3 pesos: you sold the cup for 5 pesos, but the ingredients cost 2 pesos, so you have 3 pesos left. That''s your profit! With those 3 pesos you can buy more lemons tomorrow.", "audio_segment_id": "s1-ganancia-por-vaso.prompt"}], "schema_version": 1}', '{"s1-ganancia-por-vaso": {"correct_option_id": "a"}}', '{"units": {"s1-ganancia-por-vaso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f5785f234d72bc7553fdbc59aa3a9edab6d34ecc4e4c665ba1c7f36efc57d3f7.mp3", "hash": "08368e816742e656bf0c67c4b916466cd857eb081766b5b13e6b4ccea6416db1", "bytes": 16128, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f5785f234d72bc7553fdbc59aa3a9edab6d34ecc4e4c665ba1c7f36efc57d3f7.mp3", "duration_ms": 2640}, "s1-ganancia-por-vaso.hint.1": {"url": "http://localhost:4006/files/lesson-audio/3a3972072892e611f37dda8625422d94c2a3829df19038dcd76d553f3bfe8c25.mp3", "hash": "5502e7266234adc8d48c9f8a84e0a07093a42ad51b4cd698d38f0c7abc738a3d", "bytes": 17568, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3a3972072892e611f37dda8625422d94c2a3829df19038dcd76d553f3bfe8c25.mp3", "duration_ms": 2880}, "s1-ganancia-por-vaso.prompt": {"url": "http://localhost:4006/files/lesson-audio/f630277738a5f5a1b7ded077666e5cb3a4024135863269cebec2d91fb6710e96.mp3", "hash": "c27ebe54e9f2d1dd4e7af86ca0ec4fc28d4b9e7a58c2f0660ca6fe8a39c52d90", "bytes": 115056, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f630277738a5f5a1b7ded077666e5cb3a4024135863269cebec2d91fb6710e96.mp3", "duration_ms": 19120}, "s1-ganancia-por-vaso.choices": {"url": "http://localhost:4006/files/lesson-audio/5646880b46346397a1fcadec79a6fde13cb085884c41f22d6fe85da1b95fcae8.mp3", "hash": "902299e656cda40394e86c6e80a3e4ca6ce0323b8468f4dd2d01bedc883fab23", "bytes": 27216, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5646880b46346397a1fcadec79a6fde13cb085884c41f22d6fe85da1b95fcae8.mp3", "duration_ms": 4480}, "s1-ganancia-por-vaso.explanation": {"url": "http://localhost:4006/files/lesson-audio/3debe3f0d8111516f90eb3df8f780ae5ead313cc6b8c206325172d499eada766.mp3", "hash": "15a2042e71d17e36a37c36d7eb7279fea524e638c5490ef0be8458bf9cf60471", "bytes": 67536, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3debe3f0d8111516f90eb3df8f780ae5ead313cc6b8c206325172d499eada766.mp3", "duration_ms": 11200}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "machine-io", "title": "A máquina de gorjetas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Descobrir que a máquina dobra a entrada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 10, "type": "machine_io", "hints": ["Observe: 1 → 2, 3 → 6. Qual operação se repete?"], "title": "A máquina de gorjetas", "payload": {"options": [{"id": "opt1", "text_md": "7"}, {"id": "opt2", "text_md": "10"}, {"id": "opt3", "text_md": "8"}], "examples": [{"in": 1, "out": 2}, {"in": 3, "out": 6}], "probe_in": 5}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Assim como Dina mediu com precisão no jarro, agora observe como a máquina transforma quantidades. A avó de Dina tem uma maquininha misteriosa. Se você colocar 1 moeda, saem 2! Se colocar 3, saem 6. Quantas saem se colocar 5?", "difficulty": 1, "explanation_md": "A máquina dobra o que entra: 5 × 2 = 10. Por isso saem 10 moedas.", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 10, "correct_option_id": "opt2"}}', '{"units": {"s1-machine-io.hint.0": {"url": "http://localhost:4006/files/lesson-audio/fa87246c0f77526b1e8f062b6f82a1dddb1a71bc3a062f809a02399c0f949eee.mp3", "hash": "46a3a9e48d76f368205d3e1c9e1bc5720ed500ded6c7b1a7cb9b1e7e16c01893", "bytes": 36288, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/fa87246c0f77526b1e8f062b6f82a1dddb1a71bc3a062f809a02399c0f949eee.mp3", "duration_ms": 6000}, "s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/5744d5f01757763d9a3de49253b587910bf20e5e4ab3c69e6ef1e2139aeb5b14.mp3", "hash": "f311e5589f2932bc592ed8b62430776045f805a428eff07511fcdbee2f6ec5e5", "bytes": 107424, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5744d5f01757763d9a3de49253b587910bf20e5e4ab3c69e6ef1e2139aeb5b14.mp3", "duration_ms": 17840}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/82989aae771ca0a441369afe7413ea9d96387449e1d259c8b098bb1a01c9093b.mp3", "hash": "63ebe7606c9a8634ab2a3b3b2ef1316aba9a9c095ca4aab924c15c7bd2d48060", "bytes": 40608, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/82989aae771ca0a441369afe7413ea9d96387449e1d259c8b098bb1a01c9093b.mp3", "duration_ms": 6720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "balance-scale", "title": "Balance the barter scale", "locale": "en-US", "subject": "mixed", "objectives": ["Balance the barter scale to make a fair trade", "Understand that equal amounts on both sides achieve balance"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance", "xp": 15, "type": "balance_scale", "hints": ["Each glass is worth 5 pesos. How much do the 3 glasses add up to?", "Each cookie is worth 3 pesos. How many do you need to match the total of the glasses?"], "title": "Fair trade", "payload": {"weights": [{"id": "galleta1", "label": "Cookie", "value": 3}, {"id": "galleta2", "label": "Cookie", "value": 3}, {"id": "galleta3", "label": "Cookie", "value": 3}, {"id": "galleta4", "label": "Cookie", "value": 3}, {"id": "galleta5", "label": "Cookie", "value": 3}, {"id": "galleta6", "label": "Cookie", "value": 3}], "left_fixed": [{"label": "Lemonade glasses", "value": 15}], "unknown_label": "Cookies"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf sold 3 glasses of lemonade for 5 pesos each. The cookie seller will pay with cookies worth 3 pesos each. If Liruf gives fewer cookies than fair, he will lose money. Place cookies one by one on the other plate until the scale balances. How many cookies should the cookie seller give for the trade to be fair?", "difficulty": 2, "explanation_md": "3 glasses of 5 pesos add up to 15 pesos. 5 cookies of 3 pesos also add up to 15 pesos. The scale balances and Liruf receives fair payment!", "audio_segment_id": "s1-balance.prompt"}], "schema_version": 1}', '{"s1-balance": {}}', '{"units": {"s1-balance.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8706b78f239de4acc1beb836a8bcaf364873cb44dffba319177334ac834cf859.mp3", "hash": "b0d4002356d41d577bdbb91f6b182cba7ed6fb163b1171750a30dd4ec9429b93", "bytes": 30096, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/8706b78f239de4acc1beb836a8bcaf364873cb44dffba319177334ac834cf859.mp3", "duration_ms": 4960}, "s1-balance.hint.1": {"url": "http://localhost:4006/files/lesson-audio/1b704389928219a2bd45f9c011b3c869b639385da9d5b23ac30fef064b2e0f55.mp3", "hash": "ea746ec54344b832ab11f606c6e98454be25b28b7ad41cad9ebb1b71106a3648", "bytes": 32544, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/1b704389928219a2bd45f9c011b3c869b639385da9d5b23ac30fef064b2e0f55.mp3", "duration_ms": 5360}, "s1-balance.prompt": {"url": "http://localhost:4006/files/lesson-audio/bdb014c586d2ab0541ccf33b1d473883163fb0e18a459325cbf55ce0f42b2c15.mp3", "hash": "7522e4ff1d526a0a8898bea1df2df81e8e67c8abd5b464e4a42749f390998c94", "bytes": 103968, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/bdb014c586d2ab0541ccf33b1d473883163fb0e18a459325cbf55ce0f42b2c15.mp3", "duration_ms": 17280}, "s1-balance.explanation": {"url": "http://localhost:4006/files/lesson-audio/7b442bafe9b8e2c41780914e17b114ffeec25a6c1efb3968a00942f6eb0bd079.mp3", "hash": "9b18522f085525288fbd323df8c21ec573098928da50e32eb286763d0784dccc", "bytes": 67104, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/7b442bafe9b8e2c41780914e17b114ffeec25a6c1efb3968a00942f6eb0bd079.mp3", "duration_ms": 11120}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "timeline-order", "title": "Ordena el día de venta", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar los pasos del día de venta en orden cronológico"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline", "xp": 10, "type": "timeline_order", "hints": ["Piensa: ¿qué se hace antes de preparar la limonada?", "¿Qué haces al final del día con el dinero?"], "title": "El primer día de Liruf", "payload": {"events": [{"id": "comprar", "icon": "shopping_cart", "text_md": "Comprar ingredientes por la mañana"}, {"id": "preparar", "icon": "blender", "text_md": "Preparar la limonada"}, {"id": "vender", "icon": "storefront", "text_md": "Vender limonada al mediodía"}, {"id": "contar", "icon": "savings", "text_md": "Contar el dinero y guardarlo al cierre"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Después de colgar su letrero de ''Limonada fría a 5 pesos'', Liruf se prepara para su primer día completo. Toca las fotos en el orden correcto: ¿qué pasó primero, segundo, tercero y cuarto? Si ordenas mal, ¡los clientes se confunden y no vendes!", "difficulty": 1, "explanation_md": "Primero se compran los ingredientes, luego se prepara la limonada, después se vende al mediodía y al final se cuenta el dinero y se guarda. ¡Así Liruf no se confunde y vende toda su limonada!", "audio_segment_id": "s1-timeline.prompt"}], "schema_version": 1}', '{"s1-timeline": {"order": ["comprar", "preparar", "vender", "contar"]}}', '{"units": {"s1-timeline.hint.0": {"url": "http://localhost:4006/files/lesson-audio/115400895912a49d06db0e7aee98e154b5f7911e74b5afbd76efdac1073be939.mp3", "hash": "32c318d97a43c3413cbd67a1d9c58a1465daf1438fa34852cd81cbbaa564ccbd", "bytes": 23328, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/115400895912a49d06db0e7aee98e154b5f7911e74b5afbd76efdac1073be939.mp3", "duration_ms": 3840}, "s1-timeline.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b8e0a016357c5fc9b82c60f003569caeea2acfbe74c4fcf73e570b7f78d06e67.mp3", "hash": "2a8824b265cf9fac645a35114f517d62e113930ca58b9e9644df50051befe796", "bytes": 15264, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/b8e0a016357c5fc9b82c60f003569caeea2acfbe74c4fcf73e570b7f78d06e67.mp3", "duration_ms": 2480}, "s1-timeline.prompt": {"url": "http://localhost:4006/files/lesson-audio/544d44c803955b45e3d58e4d80cf1bf90fdfa889a138ec5491b3e0164b8af2e8.mp3", "hash": "4e6ecbd458ed2e631365dada3f787f9e2a289937d00fa425192f2abc637dd3ec", "bytes": 100224, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/544d44c803955b45e3d58e4d80cf1bf90fdfa889a138ec5491b3e0164b8af2e8.mp3", "duration_ms": 16640}, "s1-timeline.explanation": {"url": "http://localhost:4006/files/lesson-audio/f3b6aba2fcc3e2037db2c8f1d0fd64e9d72d3593768edf92b5c6bf3d5eef3151.mp3", "hash": "eef53b558fc61b1d9240bc8ebd4e8cd320f4732d4d4467815a4e135233a7be53", "bytes": 84816, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/f3b6aba2fcc3e2037db2c8f1d0fd64e9d72d3593768edf92b5c6bf3d5eef3151.mp3", "duration_ms": 14080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "measure-read", "title": "La jarra medidora: vasos parejos", "locale": "es-MX", "subject": "mixed", "objectives": ["Leer la línea del líquido en una jarra medidora para servir vasos iguales de 5 pesos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-measure-read", "xp": 10, "type": "measure_read", "hints": ["Observa las marcas: 200, 250, 300. ¿Hasta cuál llegó el agua?"], "title": "Lee la jarra", "payload": {"max": 300, "min": 200, "unit": "ml", "ticks": 3, "instrument": "beaker", "pointer_value": 250}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Ayer Liruf vendió 3 vasos de limonada a 5 pesos cada uno y ganó 15 pesos. Hoy quiere servir vasos iguales para que nadie se sienta engañado. Usa la jarra medidora: cada vaso debe tener 250 ml. El agua subió hasta una línea. ¿Cuántos ml hay en la jarra? Si le pones menos, los clientes se quejarán.", "difficulty": 1, "explanation_md": "El agua llegó hasta la línea de 250 ml. Así cada vaso de 5 pesos tendrá la misma cantidad, y Liruf puede servir 3 vasos para ganar 15 pesos, como ayer.", "audio_segment_id": "s1-measure-read.prompt"}], "schema_version": 1}', '{"s1-measure-read": {"value": 250, "tolerance": 0}}', '{"units": {"s1-measure-read.hint.0": {"url": "http://localhost:4006/files/lesson-audio/51cdeaed65c68718eb5187354ad80e8afd8ca52426d82da53469752a37e78b94.mp3", "hash": "b4640970ed041640b7f6ea3edd335ba45a45857a08cbfb28973df443d2e6009c", "bytes": 43488, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/51cdeaed65c68718eb5187354ad80e8afd8ca52426d82da53469752a37e78b94.mp3", "duration_ms": 7200}, "s1-measure-read.prompt": {"url": "http://localhost:4006/files/lesson-audio/bd141b90f13fa7e00540f753c61f0875dcae1ac0f200dff62cb1c4906e239c35.mp3", "hash": "4f7315964a7ea032d33ac2d69c4840b1731a272f48a144a93f1b200a1f253f60", "bytes": 144288, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/bd141b90f13fa7e00540f753c61f0875dcae1ac0f200dff62cb1c4906e239c35.mp3", "duration_ms": 24000}, "s1-measure-read.explanation": {"url": "http://localhost:4006/files/lesson-audio/f1194cdb1a0bab7c78cceafd64c4788d7062441c448bd84d166610abfed0d8b8.mp3", "hash": "0c05a60ad751b515d0ce487236af73a8ed7994026e74d6b4f136a093ccc458d6", "bytes": 71424, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/f1194cdb1a0bab7c78cceafd64c4788d7062441c448bd84d166610abfed0d8b8.mp3", "duration_ms": 11840}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "measure-read", "title": "The measuring cup: equal glasses", "locale": "en-US", "subject": "mixed", "objectives": ["Read the liquid line on a measuring cup to serve equal glasses of 5 pesos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-measure-read", "xp": 10, "type": "measure_read", "hints": ["Look at the marks: 200, 250, 300. Which one did the water reach?"], "title": "Read the cup", "payload": {"max": 300, "min": 200, "unit": "ml", "ticks": 3, "instrument": "beaker", "pointer_value": 250}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Yesterday Liruf sold 3 glasses of lemonade at 5 pesos each and earned 15 pesos. Today he wants to serve equal glasses so no one feels cheated. Use the measuring cup: each glass should have 250 ml. The water rose to a line. How many ml are in the cup? If you put less, customers will complain.", "difficulty": 1, "explanation_md": "The water reached the 250 ml line. So each 5-peso glass will have the same amount, and Liruf can serve 3 glasses to earn 15 pesos, like yesterday.", "audio_segment_id": "s1-measure-read.prompt"}], "schema_version": 1}', '{"s1-measure-read": {"value": 250, "tolerance": 0}}', '{"units": {"s1-measure-read.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6d78ae547e79cc243428fb4a1a12961742032d2d597faae14c617549935dc832.mp3", "hash": "be0ca2f9c2cfca0603baef6c7176c08afb95118334912d5d3ee127d1f0349024", "bytes": 42624, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/6d78ae547e79cc243428fb4a1a12961742032d2d597faae14c617549935dc832.mp3", "duration_ms": 7040}, "s1-measure-read.prompt": {"url": "http://localhost:4006/files/lesson-audio/33449642a5569cd4f6fd211dab3e99d558bf8ad353a04988ee47f1bff30130b5.mp3", "hash": "4c5793ccb13f7af381b7244fdd26d6c687a77db966894ee8d6cc237015166efa", "bytes": 146736, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/33449642a5569cd4f6fd211dab3e99d558bf8ad353a04988ee47f1bff30130b5.mp3", "duration_ms": 24400}, "s1-measure-read.explanation": {"url": "http://localhost:4006/files/lesson-audio/a33ca6edfae1164c697eac9c8072d03ed41f36d60aad54383784bb8818eb86c4.mp3", "hash": "546ec6f9b1e4d4252874f07f5b69ddf8e4dea9a04d02c2ab837282ebc1e580d0", "bytes": 76608, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/a33ca6edfae1164c697eac9c8072d03ed41f36d60aad54383784bb8818eb86c4.mp3", "duration_ms": 12720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Ordena las compras del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Clasificar las compras del día en dos cubetas: NECESIDAD del puesto (limones, vasos) o GUSTO que puede esperar (stickers, globos)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort-buckets", "xp": 10, "type": "sort_buckets", "hints": ["Piensa: ¿el puesto necesita esto para vender limonada, o es solo un gusto que puede esperar?"], "title": "Dos cubetas para las compras", "payload": {"items": [{"id": "limones", "text_md": "Limones 🍋"}, {"id": "vasos", "text_md": "Vasos 🥤"}, {"id": "stickers", "text_md": "Stickers ⭐"}, {"id": "globos", "text_md": "Globos 🎈"}, {"id": "panuelos", "text_md": "Pañuelos 🧻"}], "buckets": [{"id": "necesidad", "label": "NECESIDAD del puesto"}, {"id": "gusto", "label": "GUSTO que puede esperar"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Después de ayudar a Dina a ordenar sus monedas, ahora van al mercado. Dina dice: ''Necesito limones y vasos para la limonada, pero también quiero stickers y globos para decorar. Ayúdame a decidir: ¿qué es NECESIDAD para el puesto y qué es un GUSTO que puede esperar?'' Toca cada cosa y ponla en la cubeta correcta.", "difficulty": 1, "explanation_md": "Los limones y los vasos son necesidades del puesto porque sin ellos no se puede vender limonada. Los stickers y los globos son gustos que pueden esperar. ¡Y los pañuelos pueden ser necesidad si son para limpiar el puesto, o gusto si son solo decoración!", "audio_segment_id": "s1-sort-buckets.prompt"}], "schema_version": 1}', '{"s1-sort-buckets": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "panuelos": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-sort-buckets.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3650ffaf1f641b8a017682f0e9ce9929e3f79598a4f76a11903bbcf91028b599.mp3", "hash": "d79fdcd6f8f21f01ed9ed9cf8b5485e3db3ab0597a024f16b542828a234f6848", "bytes": 36864, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3650ffaf1f641b8a017682f0e9ce9929e3f79598a4f76a11903bbcf91028b599.mp3", "duration_ms": 6080}, "s1-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/94078b3ae9603da837bf5d4e2451fc9aa82d13a9db75a584283331117d29982a.mp3", "hash": "1306670d8500a63ce2b8ff928bf243a2a38a063a2a25507aef0771d4c2f24870", "bytes": 117936, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/94078b3ae9603da837bf5d4e2451fc9aa82d13a9db75a584283331117d29982a.mp3", "duration_ms": 19600}, "s1-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/961cd04f619ae0abfb849c54436847100dc6a746e415788421422caf9822f2fd.mp3", "hash": "a8d902ba941df4cf587e0cb52e0fd8e8ab9b85e2b0beb9b6d3f06da0e2054de8", "bytes": 96768, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/961cd04f619ae0abfb849c54436847100dc6a746e415788421422caf9822f2fd.mp3", "duration_ms": 16080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Sort the stand''s purchases", "locale": "en-US", "subject": "mixed", "objectives": ["Sort the day''s purchases into two buckets: NEED for the stand (lemons, cups) or WANT that can wait (stickers, balloons)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort-buckets", "xp": 10, "type": "sort_buckets", "hints": ["Think: does the stand need this to sell lemonade, or is it just a want that can wait?"], "title": "Two buckets for purchases", "payload": {"items": [{"id": "limones", "text_md": "Lemons 🍋"}, {"id": "vasos", "text_md": "Cups 🥤"}, {"id": "stickers", "text_md": "Stickers ⭐"}, {"id": "globos", "text_md": "Balloons 🎈"}, {"id": "panuelos", "text_md": "Tissues 🧻"}], "buckets": [{"id": "necesidad", "label": "NEED for the stand"}, {"id": "gusto", "label": "WANT that can wait"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "After helping Dina sort her coins, now they go to the market. Dina says: ''I need lemons and cups for lemonade, but I also want stickers and balloons to decorate. Help me decide: what is a NEED for the stand and what is a WANT that can wait?'' Tap each item and put it in the correct bucket.", "difficulty": 1, "explanation_md": "Lemons and cups are needs for the stand because without them you can''t sell lemonade. Stickers and balloons are wants that can wait. And tissues can be a need if they are for cleaning the stand, or a want if they are just decoration!", "audio_segment_id": "s1-sort-buckets.prompt"}], "schema_version": 1}', '{"s1-sort-buckets": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "panuelos": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-sort-buckets.hint.0": {"url": "http://localhost:4006/files/lesson-audio/70f020d930634b4443dc665897d75284d3f9e38c9354e8def95ca30c795e59fa.mp3", "hash": "c4f938744cd27afda4587b1f5b9d9695327f89d24534be59fc767eb8abb6b93f", "bytes": 30096, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/70f020d930634b4443dc665897d75284d3f9e38c9354e8def95ca30c795e59fa.mp3", "duration_ms": 4960}, "s1-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/11922905e270562b54b40d243a461e89d82a6eb7ea1152f4b7db57dce810fb52.mp3", "hash": "55ff3960a2c1eb7eab793f2296be870a9d5d5918c341fab8c474b1b053d10b6a", "bytes": 88128, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/11922905e270562b54b40d243a461e89d82a6eb7ea1152f4b7db57dce810fb52.mp3", "duration_ms": 14640}, "s1-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/3fb7c26bba912901ad8b6e4a6fc90f17a318c114115a5fcaef990e9e0686103a.mp3", "hash": "ae53b402ba0498625d209f9610f3c572b7ca25373ed9a3654f790a109c04d851", "bytes": 67968, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3fb7c26bba912901ad8b6e4a6fc90f17a318c114115a5fcaef990e9e0686103a.mp3", "duration_ms": 11280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dialogo-doble-choice", "title": "Um dia real da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ouvir uma conversa entre clientes sobre a barraca de limonada", "Identificar se uma afirmação sobre a conversa é verdadeira ou falsa", "Escolher a imagem correta que corresponde à conversa"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo-clientes", "xp": 0, "type": "story_dialogue", "hints": [], "title": "Vizinhos opinam sobre a barraca", "payload": {"lines": [{"action": "idle", "emotion": "neutral", "text_md": "Olha, a barraca de limonada do Liruf. O copo custa 5 pesos, né?", "character": "rho"}, {"action": "idle", "emotion": "happy", "text_md": "Sim, e está bem gelada. Ontem comprei um e adorei.", "character": "zara"}, {"action": "idle", "emotion": "surprised", "text_md": "Só 5 pesos? Que pechincha! Com 10 pesos compro dois.", "character": "rho"}, {"action": "idle", "emotion": "encouraging", "text_md": "Exato. E se pagar com 20, recebe 15 de troco.", "character": "zara"}, {"action": "idle", "emotion": "proud", "text_md": "(Ouve sorrindo) Que bom que gostam da minha limonada!", "character": "liruf"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Ontem você decidiu que o preço seria 5 pesos. Hoje, ouça o que os vizinhos dizem sobre sua barraca.", "difficulty": 1, "explanation_md": "Liruf escuta atentamente o que os vizinhos dizem sobre sua barraca de limonada.", "audio_segment_id": "s1-dialogo-clientes.prompt"}, {"id": "s2-verdadero-falso", "xp": 10, "type": "true_false", "hints": ["Cada copo custa 5 pesos. Quanto custam dois copos?"], "title": "Certo ou falso?", "payload": {"statement_md": "Com 10 pesos você pode comprar dois copos de limonada.", "justifications": [{"id": "j1", "text_md": "É verdade, porque cada copo custa 5 pesos e 5+5=10."}, {"id": "j2", "text_md": "É falso, porque cada copo custa 5 pesos e 5+5=10, mas não dá."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Segundo a conversa, Rho diz: ''Com 10 pesos compro dois copos''. É verdade que com 10 pesos dá para dois copos?", "difficulty": 1, "explanation_md": "Dois copos custam 5 + 5 = 10 pesos. Sim, dá! A afirmação é verdadeira.", "audio_segment_id": "s2-verdadero-falso.prompt"}, {"id": "s3-eleccion-imagen", "xp": 10, "type": "picture_choice", "hints": ["O copo custa 5 pesos. Se pagar com 20, quanto sobra?"], "title": "Escolha a imagem correta", "payload": {"options": [{"id": "opt1", "icon": "monetization_on", "label": "15 pesos", "image_url": "http://localhost:4006/files/lesson-images/39cba6776663f9980ee6f2193dcb061e955be6fad1009f8164bc9bcb8b403ccf.png"}, {"id": "opt2", "icon": "monetization_on", "label": "10 pesos", "image_url": "http://localhost:4006/files/lesson-images/5c0865eee4b9d624201a489a58d597b5c72ebb0d520f2b7e491bc5254d18c924.png", "rationale_md": "Você pode ter subtraído 20 menos 10, mas o preço é 5, não 10. O troco correto é 15."}, {"id": "opt3", "icon": "monetization_on", "label": "5 pesos", "image_url": "http://localhost:4006/files/lesson-images/c980ecfc0eb971bd7fbcb29004a4c0a1bba2db2f4a268b11d80ae7ed0090be46.png", "rationale_md": "5 pesos é o preço do copo, não o troco. O troco é 20 menos 5 = 15."}]}, "narrator": {"emotion": "happy", "character": "liruf"}, "prompt_md": "Rho dá 20 pesos por um copo. Quanto troco ele deve receber? Escolha a imagem que mostra a quantidade correta.", "difficulty": 1, "explanation_md": "O copo custa 5 pesos. Se pagar com 20, o troco é 20 menos 5 = 15 pesos.", "audio_segment_id": "s3-eleccion-imagen.prompt"}], "schema_version": 1}', '{"s2-verdadero-falso": {"is_true": true, "correct_justification_id": "j1"}, "s3-eleccion-imagen": {"correct_option_id": "opt1"}}', '{"units": {"s2-verdadero-falso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4060afed20982caafc71ab2455ecade9a7a8b5c55752c31e26f137b6844bccfc.mp3", "hash": "4e4df072b6b60ebdeb96ef83c4dfa75a79130a6be922a514bef54c3f49b8885b", "bytes": 28224, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/4060afed20982caafc71ab2455ecade9a7a8b5c55752c31e26f137b6844bccfc.mp3", "duration_ms": 4640}, "s2-verdadero-falso.prompt": {"url": "http://localhost:4006/files/lesson-audio/14a2772d5dd2985341b91dac46d1b40b8983c49c2247cf0e5efd50344f5ebf44.mp3", "hash": "9cab353df8f983f8e4c81cb4311ab4ca12e5eec189c2eaab24d5115dd2c5b283", "bytes": 48816, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/14a2772d5dd2985341b91dac46d1b40b8983c49c2247cf0e5efd50344f5ebf44.mp3", "duration_ms": 8080}, "s3-eleccion-imagen.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e0c84add2943ae8b2d568cb9af2989376c00e0e0959019129ab4cbd6f589802a.mp3", "hash": "1c849508bc30b158bc99f10452b58f1c657916a8819a287fbf99e9578ed4f915", "bytes": 31536, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/e0c84add2943ae8b2d568cb9af2989376c00e0e0959019129ab4cbd6f589802a.mp3", "duration_ms": 5200}, "s3-eleccion-imagen.prompt": {"url": "http://localhost:4006/files/lesson-audio/1e47827fcb303780af3aa1586638affab407d0958c0c046961a063c34c91feae.mp3", "hash": "426428e75f39f2a15815e43283713a7b6dbd5b1e2d4894a7528d9a582654ff3f", "bytes": 49824, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/1e47827fcb303780af3aa1586638affab407d0958c0c046961a063c34c91feae.mp3", "duration_ms": 8240}, "s1-dialogo-clientes.line.0": {"url": "http://localhost:4006/files/lesson-audio/02b94b05242e793afd595a60a1985b489d82a6e52a47079956953820bb5f8c60.mp3", "hash": "a5aaf0b5da8e55b0f1a959cde46473e22947363df026732f399c4fcc2118f700", "bytes": 36288, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/02b94b05242e793afd595a60a1985b489d82a6e52a47079956953820bb5f8c60.mp3", "duration_ms": 6000}, "s1-dialogo-clientes.line.1": {"url": "http://localhost:4006/files/lesson-audio/d041d3dfb686003971dbf186ef11316f40e3e61f1d52133756644d6a906de919.mp3", "hash": "70b10c05d059c74f154b5bf87b1cb655a66774f47c40e08ac0807b0bbc5a4443", "bytes": 26784, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/d041d3dfb686003971dbf186ef11316f40e3e61f1d52133756644d6a906de919.mp3", "duration_ms": 4400}, "s1-dialogo-clientes.line.2": {"url": "http://localhost:4006/files/lesson-audio/185482d7ee2134f4b12e2f879e7eb3a0ec69699c2c2187e7a9ecbdeec929ff11.mp3", "hash": "41fc45ae749127ecbdb1d9400b3ab89a4593e4d6d407eda13392f7e98e17cc8b", "bytes": 30096, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/185482d7ee2134f4b12e2f879e7eb3a0ec69699c2c2187e7a9ecbdeec929ff11.mp3", "duration_ms": 4960}, "s1-dialogo-clientes.line.3": {"url": "http://localhost:4006/files/lesson-audio/73586ba7000e47fd1575ebedf9c21a38991979303ab302d2ee7bcaf7a01b3616.mp3", "hash": "91d498b5e8368616371bf924a321bd480ac6d2b7d7810dc2de522d4bd1c9a7b5", "bytes": 25344, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/73586ba7000e47fd1575ebedf9c21a38991979303ab302d2ee7bcaf7a01b3616.mp3", "duration_ms": 4160}, "s1-dialogo-clientes.line.4": {"url": "http://localhost:4006/files/lesson-audio/0b58fa2ae6d19ce98e9c3aa37c7923d46f3b2013a3ad1e1160a3fce6305b7042.mp3", "hash": "b29e736c38871d94019f63f73f46007af4402636a09ad566103c874c1b9a566c", "bytes": 22464, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/0b58fa2ae6d19ce98e9c3aa37c7923d46f3b2013a3ad1e1160a3fce6305b7042.mp3", "duration_ms": 3680}, "s1-dialogo-clientes.prompt": {"url": "http://localhost:4006/files/lesson-audio/853fc4d967232970bbe2371fa11d1dc577e831f46e4b10392b990c33186b5a82.mp3", "hash": "c5b5738938dffa94d6b0134b2b4409847f4b584dbf400f56bd63e7c8b7a4fe74", "bytes": 43488, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/853fc4d967232970bbe2371fa11d1dc577e831f46e4b10392b990c33186b5a82.mp3", "duration_ms": 7200}, "s3-eleccion-imagen.choices": {"url": "http://localhost:4006/files/lesson-audio/a323846a2583d9194934751ac4816ae6d7d5afdb5e4079fdec8d71bbb7e701d1.mp3", "hash": "2a83f37f66f5a67c8d6f4fe0223e3c31e7b36df9250bc0e2299fdfcf5746a5d4", "bytes": 21024, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/a323846a2583d9194934751ac4816ae6d7d5afdb5e4079fdec8d71bbb7e701d1.mp3", "duration_ms": 3440}, "s2-verdadero-falso.explanation": {"url": "http://localhost:4006/files/lesson-audio/f933d24b17ed1424eb4594d1189d6b4b6fe88d9d02b221ad5f45ac2d44417625.mp3", "hash": "d316cec327e65333a627e5738283fc839d9c9f92b250f22f189d707ca6612799", "bytes": 44928, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/f933d24b17ed1424eb4594d1189d6b4b6fe88d9d02b221ad5f45ac2d44417625.mp3", "duration_ms": 7440}, "s3-eleccion-imagen.explanation": {"url": "http://localhost:4006/files/lesson-audio/5b562db5f0acd7f92ff49330edec256856237c8f2757371cd4ad5847bad9e5a6.mp3", "hash": "2cd810f6a9952c58a3741aed52ecf46d5fb509b200bbd3bcfec822718913c9e2", "bytes": 40176, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/5b562db5f0acd7f92ff49330edec256856237c8f2757371cd4ad5847bad9e5a6.mp3", "duration_ms": 6640}, "s1-dialogo-clientes.explanation": {"url": "http://localhost:4006/files/lesson-audio/2114fede797c61b0f03093a4e0eaf8983322d4d3059cd0baa9c7ae353e9b4b61.mp3", "hash": "d357596b40c5e32b4c248311c6359caae2444445a3c678444c13ed59aee688d9", "bytes": 33984, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/2114fede797c61b0f03093a4e0eaf8983322d4d3059cd0baa9c7ae353e9b4b61.mp3", "duration_ms": 5600}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "make-change", "title": "Dar troco exato", "locale": "pt-BR", "subject": "money", "objectives": ["Calcular o troco de uma compra de 8 pesos pagando com nota de 20 usando moedas de 1, 2, 5 e 10."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-make-change", "xp": 10, "type": "make_change", "hints": ["Primeiro some quanto custa tudo que seu Beto comprou.", "O troco é o que sobra da nota depois de pagar."], "title": "O troco do seu Beto", "payload": {"price": 8, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf acabou de contar moedas para pagar 5 pesos pela sua limonada. Agora seu Beto compra um copo de limonada de 5 pesos e um biscoito de 3 pesos. Paga com uma nota de 20. Mas seu Beto precisa de troco exato para o ônibus. Se você der menos do que ele deve, ele ficará sem passagem! Quanto troco você precisa dar? Monte o troco com as moedas que você tem.", "difficulty": 1, "explanation_md": "O total é 5 + 3 = 8 pesos. Pagou com 20, então o troco é 20 - 8 = 12 pesos. Você deu 12 pesos em moedas. Assim seu Beto pode pegar o ônibus!", "audio_segment_id": "s1-make-change.prompt"}], "schema_version": 1}', '{"s1-make-change": {}}', '{"units": {"s1-make-change.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6651e7c77a0e23000d4de0df4203c478ba965e49079b775f65f6a34abfb114b6.mp3", "hash": "a0471d8d1190de2dd5149d6f855cb2cdc7f1e9320753d8e514debd0bbbb1f5d1", "bytes": 20448, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/6651e7c77a0e23000d4de0df4203c478ba965e49079b775f65f6a34abfb114b6.mp3", "duration_ms": 3360}, "s1-make-change.hint.1": {"url": "http://localhost:4006/files/lesson-audio/14d82e2dd2e0bd499f10eb4f0bb8be62deaba3f44e0dfc090329b3d0aabf118c.mp3", "hash": "56601c5dfb72d0932186942b366b51f79d4ed293e98cbae2e959360d4903887f", "bytes": 19584, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/14d82e2dd2e0bd499f10eb4f0bb8be62deaba3f44e0dfc090329b3d0aabf118c.mp3", "duration_ms": 3200}, "s1-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/a654c9e9ce2b4372907fb8c0cc777abb856ba08782620038ff964822b081346d.mp3", "hash": "6f6ef60cd582272e97abb9e4fa77f2c7fc50ce2ab33621692f8e682a5a3722d5", "bytes": 147744, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/a654c9e9ce2b4372907fb8c0cc777abb856ba08782620038ff964822b081346d.mp3", "duration_ms": 24560}, "s1-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/36bf7016dde9a842a9207bab58a657efaa4d41efa21c8ba73fb7b754fb57bde9.mp3", "hash": "b6afb53a52b44a3212f86c1b258cd9d115ef4472cae0bb60ff1f0e652ee47cb9", "bytes": 81504, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/36bf7016dde9a842a9207bab58a657efaa4d41efa21c8ba73fb7b754fb57bde9.mp3", "duration_ms": 13520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'es-MX', '1', '{"meta": {"cast": ["rho", "liruf"], "slug": "savings-goal", "title": "¿Cuántas semanas para la guitarra?", "locale": "es-MX", "subject": "money", "objectives": ["Calcular cuántas semanas se necesita ahorrar para alcanzar una meta de 80 pesos con diferentes ahorros semanales.", "Comparar los tiempos con un plazo de 4 semanas para decidir qué plan funciona."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-savings-goal", "xp": 15, "type": "savings_goal", "hints": ["Piensa en cuántas veces cabe lo que aparta cada semana en 80 pesos. Por ejemplo, si aparta 10 pesos, necesita 8 semanas porque 10+10+10+10+10+10+10+10 = 80."], "title": "Planes de ahorro", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Liruf ya ganó **20 pesos** este fin de semana con su puesto de limonada. Guarda todo en su alcancía para la guitarra de **80 pesos**. Pero el concurso de bandas es en **4 semanas**. Puede apartar **10**, **20** o **40 pesos** cada semana. Ayuda a Liruf a decidir: toca cada opción para ver cuántas semanas necesita. ¿Algún plan llega a tiempo para el concurso?", "difficulty": 2, "explanation_md": "Si aparta 10 pesos cada semana, necesita 8 semanas (10+10+10+10+10+10+10+10 = 80). Con 20 pesos, necesita 4 semanas (20+20+20+20 = 80). Con 40 pesos, necesita 2 semanas (40+40 = 80). Solo los planes de 20 y 40 pesos llegan antes o justo en 4 semanas. ¡Liruf puede tocar en el concurso si elige uno de esos!", "audio_segment_id": "s1-savings-goal.prompt"}], "schema_version": 1}', '{"s1-savings-goal": {"correct": {"10": 8, "20": 4, "40": 2}}}', '{"units": {"s1-savings-goal.hint.0": {"url": "http://localhost:4006/files/lesson-audio/616e7ab7429b6f07bcf2ddac7f9fd072a633a4d3637b93095feeb099b6f00416.mp3", "hash": "c4d1e4203ccc0be29ffce1f53e428cbc3f308378b72e86372cfd8eec0db6831f", "bytes": 82368, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/616e7ab7429b6f07bcf2ddac7f9fd072a633a4d3637b93095feeb099b6f00416.mp3", "duration_ms": 13680}, "s1-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/c11e99167d77377abb60aca63d15e5aa3dca9cd6f354ff01028a7250ca64ec00.mp3", "hash": "5c47a674b39b37ec0ee96348ceb74c38bc44a223851b96b80012356584ff1345", "bytes": 151056, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/c11e99167d77377abb60aca63d15e5aa3dca9cd6f354ff01028a7250ca64ec00.mp3", "duration_ms": 25120}, "s1-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/4223f853c2bb9a991b7de1813ab16fbbc7e69b28a025e69d8db0ffb4b67d1908.mp3", "hash": "2b0a58bd4c2541c9daf7748ccb08baecd63fdaaea87a5ba82cf9fd1897bb0390", "bytes": 186624, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/4223f853c2bb9a991b7de1813ab16fbbc7e69b28a025e69d8db0ffb4b67d1908.mp3", "duration_ms": 31040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "combo-narrativa-choice", "title": "Um sábado na barraca", "locale": "pt-BR", "subject": "money", "objectives": ["Decidir o preço da limonada em uma situação realista com clientes e troco"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-apertura", "xp": 0, "type": "story_scene", "hints": [], "title": "Chegam os clientes!", "payload": {"art": {"icon": "storefront", "tint": "primary"}, "action": "idle", "body_md": "O sol brilha. Liruf tem os limões prontos, o açúcar e os copos. Mas… ele não colocou a placa com o preço! Os clientes perguntam: ''Quanto custa um copo?'' Liruf precisa decidir rápido. Assim como a máquina de gorjetas dobrava as moedas, aqui Liruf pode dobrar seu dinheiro se colocar o preço certo.", "emotion": "thinking", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "É sábado de manhã. Liruf abre sua barraca de limonada. Já tem uma fila de clientes esperando. O copo custa 5 pesos, mas Liruf ainda não colocou o preço do dia. Qual preço ele deve colocar?", "difficulty": 1, "explanation_md": "Liruf lembra que cada copo custa 5 pesos para preparar. Assim como a máquina de gorjetas dobrava as moedas, aqui Liruf pode dobrar seu dinheiro se colocar um preço maior que 5 pesos.", "audio_segment_id": "s1-apertura.prompt"}, {"id": "s2-decision-precio", "xp": 10, "type": "quiz_mcq", "hints": ["Pense: se o copo custa 5 pesos, o preço deve ser maior para ganhar algo.", "Se você colocar 5 pesos, só recupera o que gastou, não ganha nada."], "title": "Escolha o preço", "payload": {"options": [{"id": "a", "text_md": "3 pesos", "rationale_md": "3 pesos é menos do que custa fazer o copo. Liruf perderia dinheiro!"}, {"id": "b", "text_md": "5 pesos", "rationale_md": "5 pesos é exatamente o custo, mas ele não ganha nada. Não é um bom negócio."}, {"id": "c", "text_md": "7 pesos", "rationale_md": "7 pesos é mais que 5, então Liruf ganha 2 pesos por copo. Bom lucro!"}, {"id": "d", "text_md": "10 pesos", "rationale_md": "10 pesos é muito mais caro. Talvez os clientes não queiram pagar tanto e vão embora."}], "shuffle": true}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf sabe que cada copo custa 5 pesos para fazer. Qual preço ele deveria colocar na placa para ganhar dinheiro? Veja este exemplo: se Liruf vender um copo a 7 pesos, gasta 5 pesos, então ganha 2 pesos. Isso é lucro!", "difficulty": 1, "explanation_md": "Liruf precisa ganhar dinheiro, então o preço deve ser maior que 5 pesos. 7 pesos é uma boa opção: ele ganha 2 pesos por copo. Se você tivesse escolhido 3 pesos, perderia dinheiro. Se 5 pesos, não ganha nada. Se 10 pesos, talvez os clientes não comprem.", "audio_segment_id": "s2-decision-precio.prompt"}], "schema_version": 1}', '{"s2-decision-precio": {"correct_option_id": "c"}}', '{"units": {"s1-apertura.body": {"url": "http://localhost:4006/files/lesson-audio/9c8cf7c2fa12d680ac81d62b7860245903ef353a0726ef94555fb2652e8cbb94.mp3", "hash": "e442a1693f9ed41837af3a02a720d58fe638b121a2ed1e4ef4068ba00222f397", "bytes": 139968, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/9c8cf7c2fa12d680ac81d62b7860245903ef353a0726ef94555fb2652e8cbb94.mp3", "duration_ms": 23280}, "s1-apertura.prompt": {"url": "http://localhost:4006/files/lesson-audio/6c3e7a5dbd569310546f7017b5d4075d513a137dab6dadbc227631ab281e94e3.mp3", "hash": "949469bd2b65bc0eb5f756be3b9b5c8d731bd44f8b2675bade3e905bf16e00e0", "bytes": 91584, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6c3e7a5dbd569310546f7017b5d4075d513a137dab6dadbc227631ab281e94e3.mp3", "duration_ms": 15200}, "s1-apertura.explanation": {"url": "http://localhost:4006/files/lesson-audio/18425124cb86af47b0415f460efa67fbd50d21dee059d89074236848f4deeafe.mp3", "hash": "707ce35f2ad7f4855d63ef1ddf1c92ca82b30d6ef24a2dbfbf66be190c5e733f", "bytes": 77184, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/18425124cb86af47b0415f460efa67fbd50d21dee059d89074236848f4deeafe.mp3", "duration_ms": 12800}, "s2-decision-precio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0810d193481466a8c80db767abdc49e25d1459204633d8a2405651ae56f205f5.mp3", "hash": "c388e8fff3b9a07b11398b3b37872560623349b99a94e5b2c65335441f5c498c", "bytes": 35424, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0810d193481466a8c80db767abdc49e25d1459204633d8a2405651ae56f205f5.mp3", "duration_ms": 5840}, "s2-decision-precio.hint.1": {"url": "http://localhost:4006/files/lesson-audio/515eae1542cbb90a6d441799de1dc7d8a246b62e8f0e4e3af0126322e7c55852.mp3", "hash": "5d5ef3d19e988dd150e8f32f09fb4e6ddeb413d40bd55d6499883759022d1022", "bytes": 29664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/515eae1542cbb90a6d441799de1dc7d8a246b62e8f0e4e3af0126322e7c55852.mp3", "duration_ms": 4880}, "s2-decision-precio.prompt": {"url": "http://localhost:4006/files/lesson-audio/1d826d5a83bbbf3fbf4c0ad68725e0c5303ba73d6d76a5c6bbddb4d4f0ef5ca7.mp3", "hash": "d4bc57612717c10a2975abb4d6be164935a8489fc09021d2250ce39bed45120a", "bytes": 103536, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1d826d5a83bbbf3fbf4c0ad68725e0c5303ba73d6d76a5c6bbddb4d4f0ef5ca7.mp3", "duration_ms": 17200}, "s2-decision-precio.choices": {"url": "http://localhost:4006/files/lesson-audio/99f2c93b6090d47de47d9660b16a0849b57e2f6d4211fce585d5a45dd3b4e557.mp3", "hash": "ea6850ec77221fae9951e5144e5d89f9a7b331fc670453e85d365635c77e1c06", "bytes": 29664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/99f2c93b6090d47de47d9660b16a0849b57e2f6d4211fce585d5a45dd3b4e557.mp3", "duration_ms": 4880}, "s2-decision-precio.explanation": {"url": "http://localhost:4006/files/lesson-audio/5332126f600eddb9317502b5bcbd2eb49d0540f8f8bb4358675a6a04ce2209d2.mp3", "hash": "edb4f423999fde8f40c27cdbf827b5a09e215a885624381b840cae7f43126094", "bytes": 119808, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5332126f600eddb9317502b5bcbd2eb49d0540f8f8bb4358675a6a04ce2209d2.mp3", "duration_ms": 19920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "balance-scale", "title": "Equilibra la balanza del trueque", "locale": "es-MX", "subject": "mixed", "objectives": ["Equilibrar la balanza del trueque para lograr un trato justo", "Comprender que cantidades iguales en ambos platos logran el equilibrio"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance", "xp": 15, "type": "balance_scale", "hints": ["Cada vaso vale 5 pesos. ¿Cuánto suman los 3 vasos?", "Las galletas valen 3 pesos cada una. ¿Cuántas necesitas para igualar el total de los vasos?"], "title": "Trueque justo", "payload": {"weights": [{"id": "galleta1", "label": "Galleta", "value": 3}, {"id": "galleta2", "label": "Galleta", "value": 3}, {"id": "galleta3", "label": "Galleta", "value": 3}, {"id": "galleta4", "label": "Galleta", "value": 3}, {"id": "galleta5", "label": "Galleta", "value": 3}, {"id": "galleta6", "label": "Galleta", "value": 3}], "left_fixed": [{"label": "Vasos de limonada", "value": 15}], "unknown_label": "Galletas"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf vendió 3 vasos de limonada a 5 pesos cada uno. El galletero le pagará con galletas de 3 pesos cada una. Si Liruf da menos galletas de las justas, perderá dinero. Coloca galletas una por una en el otro plato hasta que la balanza se equilibre. ¿Cuántas galletas debe dar el galletero para que el trato sea justo?", "difficulty": 2, "explanation_md": "3 vasos de 5 pesos suman 15 pesos. 5 galletas de 3 pesos también suman 15 pesos. ¡La balanza se equilibra y Liruf recibe el pago justo!", "audio_segment_id": "s1-balance.prompt"}], "schema_version": 1}', '{"s1-balance": {}}', '{"units": {"s1-balance.hint.0": {"url": "http://localhost:4006/files/lesson-audio/34052a4cf8978830364e77917893d3fcee58dbface3c3668b55022f60b166249.mp3", "hash": "eb17a4efc2885507e91ce0cf5a86fee6798ee685deb08cd8cd09ffae32e243f6", "bytes": 26784, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/34052a4cf8978830364e77917893d3fcee58dbface3c3668b55022f60b166249.mp3", "duration_ms": 4400}, "s1-balance.hint.1": {"url": "http://localhost:4006/files/lesson-audio/17c3b2a99fdb62484092e63b60a3b7cb19ea1bcd02816f3ea85a713c48461ae1.mp3", "hash": "12a9e7428adbc92255fcffc8fe3e798c9f44759ef6eaf37dfd4f30e80734c940", "bytes": 40608, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/17c3b2a99fdb62484092e63b60a3b7cb19ea1bcd02816f3ea85a713c48461ae1.mp3", "duration_ms": 6720}, "s1-balance.prompt": {"url": "http://localhost:4006/files/lesson-audio/4d8b913fbf32cb8d6b452375f81294f4d1e62764f25c9a1a6220ce9edb463f9b.mp3", "hash": "749f7622aaf14765cb842138f3a61383decf094b4c7ed839c0ef1445779c48c5", "bytes": 126144, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/4d8b913fbf32cb8d6b452375f81294f4d1e62764f25c9a1a6220ce9edb463f9b.mp3", "duration_ms": 20960}, "s1-balance.explanation": {"url": "http://localhost:4006/files/lesson-audio/66464472c86af434e235e299e8c50aa1865d5e0c6d0d7b2da54bb46bdc4f389c.mp3", "hash": "35bc6b73c88aa52232c66f969ecc0f04e5fa1e6bec092941451f3f8f666f9618", "bytes": 70416, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/66464472c86af434e235e299e8c50aa1865d5e0c6d0d7b2da54bb46bdc4f389c.mp3", "duration_ms": 11680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "spot-error", "title": "Find the error in the account", "locale": "en-US", "subject": "mixed", "objectives": ["Detect an error in a sales sum", "Read a simple graph of cups sold per day", "Recognize signs of a bad deal"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-spot-error", "xp": 10, "type": "spot_error", "hints": ["Add the numbers again: 5 + 5 + 5 is 15, not 20."], "title": "The account that doesn''t add up", "payload": {"steps": [{"id": "step1", "text_md": "Step 1: I sold 3 glasses."}, {"id": "step2", "text_md": "Step 2: Each glass costs 5 pesos."}, {"id": "step3", "text_md": "Step 3: 5 + 5 + 5 = 20."}, {"id": "step4", "text_md": "Step 4: I wrote the total in the notebook."}], "context_md": "Liruf sold 3 glasses of lemonade at 5 pesos each. He wants to save everything to buy a skateboard that costs 20 pesos. He wrote: 5 + 5 + 5 = 20."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Tap the step that is wrong in Liruf''s account.", "difficulty": 1, "explanation_md": "The error is in step 3: 5 + 5 + 5 = 15, not 20. Liruf added wrong. If he had saved the 20 he thought, he would have 5 more pesos for his piggy bank. But he only has 15, so his money will grow less when he saves it.", "audio_segment_id": "s1-spot-error.prompt"}], "schema_version": 1}', '{"s1-spot-error": {"error_ids": ["step3"], "correction_md": "5 + 5 + 5 = 15, no 20."}}', '{"units": {"s1-spot-error.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8c8a4b17e6b936f9032745639f1c80a96eacad674f0386b62dbd3b1382b4c4ba.mp3", "hash": "f0e281f2769ca60c96438aec0fe139d2cf1d99a421036c1dac90eb0406da3978", "bytes": 27648, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8c8a4b17e6b936f9032745639f1c80a96eacad674f0386b62dbd3b1382b4c4ba.mp3", "duration_ms": 4560}, "s1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/fc31d305a356f9c1902728bed44d1415cdc2888349e71b81142ccc7950bc94f3.mp3", "hash": "80af7f978d4b1c34e2cdeba19809eed586d167b9f6c2bff8b945fcb4c69b5210", "bytes": 14688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/fc31d305a356f9c1902728bed44d1415cdc2888349e71b81142ccc7950bc94f3.mp3", "duration_ms": 2400}, "s1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/53f68538f9b7376493f016720a9bd5eecde5213b6608e0851641e10de7e0e0dc.mp3", "hash": "05b0a1eed887b87ec00776a81fbf83e41798fdaae36fa3cf12b70e326abd1c38", "bytes": 87696, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/53f68538f9b7376493f016720a9bd5eecde5213b6608e0851641e10de7e0e0dc.mp3", "duration_ms": 14560}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "pattern-complete", "title": "La escalera de vasos", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar pasos, emparejar productos con precios y clasificar compras entre necesidades del puesto y gustos que pueden esperar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-escalera", "xp": 15, "type": "pattern_complete", "hints": ["Observa el patrón: chico, mediano, grande, chico… ¿qué tamaño sigue después de grande?", "La escalera sube de precio: más grande cuesta más. ¿Cuál es el más caro de los tres?"], "title": "¿Qué vaso va aquí?", "payload": {"options": [{"id": "chico", "icon": "water_drop", "tint": "primary"}, {"id": "mediano", "icon": "water_drop", "tint": "accent"}, {"id": "grande", "icon": "water_drop", "tint": "success"}], "sequence": [{"icon": "water_drop", "tint": "primary"}, {"icon": "water_drop", "tint": "accent"}, {"icon": "water_drop", "tint": "success"}, {"icon": "water_drop", "tint": "primary"}, {"icon": "water_drop", "tint": "accent"}, {"icon": "water_drop", "tint": "success"}], "missing_slots": 1}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Ayer Zara compró limones, preparó la limonada, la vendió y guardó las ganancias. Hoy prepara los vasos para mañana. Los ordena así: chico ($5), mediano ($10), grande ($15), y luego otra vez chico, mediano, grande… para que los clientes vean que más grande cuesta más. Pero dejó un hueco. ¿Qué vaso va en el lugar vacío para que la escalera siga subiendo?", "difficulty": 2, "explanation_md": "Después del vaso grande ($15) viene el chico ($5) otra vez, porque la escalera vuelve a empezar. Así los clientes ven que más grande cuesta más y pueden escoger el que les alcanza. Si elegiste ''grande'', pensaste que seguía subiendo, pero la escalera se repite. Si elegiste ''mediano'', confundiste el orden del ciclo.", "audio_segment_id": "s1-escalera.prompt"}], "schema_version": 1}', '{"s1-escalera": {"correct": {"0": "chico"}}}', '{"units": {"s1-escalera.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5a142cd22f94ae2c81f1c1c061e378a660d141b69fd77f1fbbab4c6e29f54971.mp3", "hash": "3fb6d5e94b4c54f024c1a353855108202e9730093df7dd2085fcea3c00b67610", "bytes": 36288, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/5a142cd22f94ae2c81f1c1c061e378a660d141b69fd77f1fbbab4c6e29f54971.mp3", "duration_ms": 6000}, "s1-escalera.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f01de493ae8221b87291209cada62af7eff82d664885574f3f151c48bbe84ef4.mp3", "hash": "8000d7e16f9af2b98a624e282ce6b4dbb1609222291feb616f640d45d9994304", "bytes": 31536, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/f01de493ae8221b87291209cada62af7eff82d664885574f3f151c48bbe84ef4.mp3", "duration_ms": 5200}, "s1-escalera.prompt": {"url": "http://localhost:4006/files/lesson-audio/41696033be7bbac8896c767c09388e01a159b6673bd1be863b384cfe70e9cdf2.mp3", "hash": "f8976244d7324d7da0bfd94c6dad012786524a3a5747f8bc69a89a880a94ab86", "bytes": 146304, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/41696033be7bbac8896c767c09388e01a159b6673bd1be863b384cfe70e9cdf2.mp3", "duration_ms": 24320}, "s1-escalera.explanation": {"url": "http://localhost:4006/files/lesson-audio/e76e221c10c24b59934f25bdeffe40642df7d7782de7db9cb81f3238f75ca676.mp3", "hash": "e0a9df34c74546b77b1787ad7129fccb5aba606e96f4d381238038615f8e577d", "bytes": 121248, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/e76e221c10c24b59934f25bdeffe40642df7d7782de7db9cb81f3238f75ca676.mp3", "duration_ms": 20160}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "lightning-round", "title": "Lightning round at peak hour", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate the correct change for customers ordering 1-3 glasses of 5 pesos and paying with 10 or 20 pesos", "Apply the strategy: first add the glasses, then subtract from the payment"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lightning", "xp": 15, "type": "lightning_round", "hints": ["First add up how much all the glasses cost (each glass costs 5 pesos).", "Then subtract that total from the bill the customer pays with."], "title": "Change on the fly!", "payload": {"questions": [{"id": "q1", "options": [{"id": "q1a", "text_md": "10 pesos"}, {"id": "q1b", "text_md": "5 pesos"}, {"id": "q1c", "text_md": "15 pesos"}, {"id": "q1d", "text_md": "20 pesos"}], "prompt_md": "Doña Rosa: 2 glasses, pays with 20 pesos. How much change do you give her?"}, {"id": "q2", "options": [{"id": "q2a", "text_md": "5 pesos"}, {"id": "q2b", "text_md": "10 pesos"}, {"id": "q2c", "text_md": "0 pesos"}, {"id": "q2d", "text_md": "1 peso"}], "prompt_md": "Don Toño: 1 glass, pays with 10 pesos. How much change do you give him?"}, {"id": "q3", "options": [{"id": "q3a", "text_md": "5 pesos"}, {"id": "q3b", "text_md": "10 pesos"}, {"id": "q3c", "text_md": "15 pesos"}, {"id": "q3d", "text_md": "20 pesos"}], "prompt_md": "Mari: 3 glasses, pays with 20 pesos. How much change do you give her?"}, {"id": "q4", "options": [{"id": "q4a", "text_md": "15 pesos"}, {"id": "q4b", "text_md": "10 pesos"}, {"id": "q4c", "text_md": "5 pesos"}, {"id": "q4d", "text_md": "20 pesos"}], "prompt_md": "Don Luis: 1 glass, pays with 20 pesos. How much change do you give him?"}, {"id": "q5", "options": [{"id": "q5a", "text_md": "0 pesos"}, {"id": "q5b", "text_md": "5 pesos"}, {"id": "q5c", "text_md": "10 pesos"}, {"id": "q5d", "text_md": "2 pesos"}], "prompt_md": "Abuela Chole: 2 glasses, pays with 10 pesos. How much change do you give her?"}], "seconds_per_q": 15}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "The line reaches the corner! Zara sings the orders and you are Liruf: you must give the change before the clock rings. Each correct answer puts a coin in the 80-peso guitar jar. Ready? Remember: saving is keeping money, like the piggy bank you saw before. Here, every correct change is like a coin you save for the guitar!", "difficulty": 2, "explanation_md": "The trick is: add the glasses (2 glasses × 5 pesos = 10 pesos) and subtract from the payment (20 - 10 = 10 pesos change).", "audio_segment_id": "s1-lightning.prompt"}], "schema_version": 1}', '{"s1-lightning": {"correct": {"q1": "q1a", "q2": "q2a", "q3": "q3a", "q4": "q4a", "q5": "q5a"}}}', '{"units": {"s1-lightning.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5690a42588f8c739a1db1f04866e7b7c3475571646cbf56868a9e9a8c1c13d99.mp3", "hash": "9f75e02bc5da0519b8d6f9c3b9900e93e4c4d3d392f6cbedd3f80aac5567b6d4", "bytes": 26208, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5690a42588f8c739a1db1f04866e7b7c3475571646cbf56868a9e9a8c1c13d99.mp3", "duration_ms": 4320}, "s1-lightning.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2307c73c2588d760d5d9bae5fc6312fcc13ba28ebeb108867eb4d509ab3c70dc.mp3", "hash": "472e856b393540c715a9faa11709f96ed0a8ecc8d0a5d7b846f1364c52e915d0", "bytes": 16704, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/2307c73c2588d760d5d9bae5fc6312fcc13ba28ebeb108867eb4d509ab3c70dc.mp3", "duration_ms": 2720}, "s1-lightning.prompt": {"url": "http://localhost:4006/files/lesson-audio/4a1677d53ec439def75824e7329fe15315b32e49a45ce1a932b537774ec9762b.mp3", "hash": "a8c72f31301c5f5126d4e8141c066df19aa474e49e4084f6957890b91fa5fd82", "bytes": 105408, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4a1677d53ec439def75824e7329fe15315b32e49a45ce1a932b537774ec9762b.mp3", "duration_ms": 17520}, "s1-lightning.explanation": {"url": "http://localhost:4006/files/lesson-audio/4ed4455be74bb6bb8b973d4df55ddb46bf2eb6a55c27df31869ea7bcad3af687.mp3", "hash": "12f46ace96229c10c7f8e2aa11a19ad4374270b91272f599dc27ddedcc7e0727", "bytes": 51264, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4ed4455be74bb6bb8b973d4df55ddb46bf2eb6a55c27df31869ea7bcad3af687.mp3", "duration_ms": 8480}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "repaso-true-false", "title": "Revisão: Verdadeiro ou Falso?", "locale": "pt-BR", "subject": "money", "objectives": ["Distinguir entre receita total e lucro em uma barraca de limonada.", "Lembrar que cada copo custa 2 pesos de insumos, então o lucro por copo é de 3 pesos."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-verdadero-falso", "xp": 10, "type": "true_false", "hints": ["Lembre-se: cada copo custa 2 pesos de limão e açúcar. Quanto sobra de verdade para cada copo?", "Se para cada copo você ganha 3 pesos, multiplique 3 × 10 para saber o lucro real."], "title": "A última armadilha de Rho", "payload": {"statement_md": "Liruf vendeu 10 copos a 5 pesos, então ganhou 50 pesos.", "justifications": [{"id": "j-ingreso", "text_md": "50 pesos é o que entrou no caixa, mas cada copo custou 2 pesos de ingredientes, então o lucro é de 3 pesos por copo, 30 no total."}, {"id": "j-ganancia", "text_md": "50 pesos é o lucro porque 10 × 5 = 50, e não há outras despesas."}]}, "narrator": {"emotion": "surprised", "character": "rho"}, "prompt_md": "Rho levanta a placa: ''Hoje você vendeu 10 copos a 5 pesos cada. Então você ganhou 50 pesos!'' É verdade ou é falso?", "difficulty": 1, "explanation_md": "É falso. 50 pesos é o que entrou, mas cada copo custou 2 pesos para fazer, então o lucro real é de 3 pesos por copo, 30 pesos no total.", "audio_segment_id": "s1-verdadero-falso.prompt"}], "schema_version": 1}', '{"s1-verdadero-falso": {"is_true": false, "correct_justification_id": "j-ingreso"}}', '{"units": {"s1-verdadero-falso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ae781d57a5a193f6500421f33cae7291e52313efffa601e26efa0fdce6d26a39.mp3", "hash": "31bafb5e60fcd72da97184ed94c7632ecce01a181300abe16d48e9f089ad3980", "bytes": 46368, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/ae781d57a5a193f6500421f33cae7291e52313efffa601e26efa0fdce6d26a39.mp3", "duration_ms": 7680}, "s1-verdadero-falso.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b13088484bbaf494b56f3dee0e97f93b0cebe172b25c1e957844a5e9e33ac9a4.mp3", "hash": "b27f981a87368c578fb6d8955e89d7057cd2875faaa8dd07a67543971befe272", "bytes": 45936, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/b13088484bbaf494b56f3dee0e97f93b0cebe172b25c1e957844a5e9e33ac9a4.mp3", "duration_ms": 7600}, "s1-verdadero-falso.prompt": {"url": "http://localhost:4006/files/lesson-audio/7409bd03cc5d84191668a45f5de9976f2b9e8d2581fa5f6f293398535e8c63b6.mp3", "hash": "6f14497a16c3b994b6bd0e26934a6c72e6b9fd06728d07e68ab06b1c1132b144", "bytes": 63216, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/7409bd03cc5d84191668a45f5de9976f2b9e8d2581fa5f6f293398535e8c63b6.mp3", "duration_ms": 10480}, "s1-verdadero-falso.explanation": {"url": "http://localhost:4006/files/lesson-audio/3e64f519929c35cb2d6fe4947e398e6a37e49903e892daa7089e2f155414c83c.mp3", "hash": "fa21793d84197cf903ac306d1201531ceaf6059444468b5f6dec25666acdbee8", "bytes": 71424, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/3e64f519929c35cb2d6fe4947e398e6a37e49903e892daa7089e2f155414c83c.mp3", "duration_ms": 11840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Compara proveedores de limones", "locale": "es-MX", "subject": "mixed", "objectives": ["Leer una tabla de dos proveedores y elegir el que da más por menos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 10, "type": "compare_table", "hints": ["Si hace sol, Dina vende más limonadas, así que necesita más limones.", "Compara cuántos limones da cada proveedor por el mismo precio."], "title": "¿Cuál proveedor te conviene más?", "payload": {"cols": [{"id": "precio", "label": "Precio"}, {"id": "limones", "label": "Limones"}], "rows": [{"id": "proveedor-a", "label": "Proveedor A"}, {"id": "proveedor-b", "label": "Proveedor B"}], "tokens": [{"id": "t1", "text_md": "10 pesos"}, {"id": "t2", "text_md": "20 limones"}, {"id": "t3", "text_md": "10 pesos"}, {"id": "t4", "text_md": "30 limones"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Ayer, con el sol, Dina vendió 20 limonadas. Pero hoy está nublado y vendió solo 10. Dina recuerda: cuando hace sol, la gente compra más, aunque el precio suba un poco. Ahora tiene que elegir proveedor de limones para mañana. Si hace sol, quiere muchos limones; si está nublado, no necesita tantos. Mira la tabla de los dos proveedores. ¿Cuál le conviene más si mañana hace sol? Toca cada celda para ver los datos.", "difficulty": 1, "explanation_md": "Si hace sol, Dina venderá muchas limonadas. El proveedor B da 30 limones por 10 pesos, mientras que el A da solo 20. Con el B obtiene más limones por el mismo dinero, justo lo que necesita para un día soleado.", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"proveedor-a:precio": "t1", "proveedor-b:precio": "t3", "proveedor-a:limones": "t2", "proveedor-b:limones": "t4"}}}', '{"units": {"s1-compare-table.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d174be373ee5492d856ee8a2a5c4b6407fc7c9fb43403ed4ce781584e95c6e8e.mp3", "hash": "177f73cce4f884e47d79f9d5a3616047326d6ae96ac1ccada012aa5f326c10eb", "bytes": 35856, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d174be373ee5492d856ee8a2a5c4b6407fc7c9fb43403ed4ce781584e95c6e8e.mp3", "duration_ms": 5920}, "s1-compare-table.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c8d661fd95a5bdd288692b8fb8b6fe7d1336940dc2080b52a5b5fee7ed16758e.mp3", "hash": "2abe13cd986c1dc69c1451437fdfd99dc966f71bde2dfb5f996e0dc6307fc0bc", "bytes": 23904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c8d661fd95a5bdd288692b8fb8b6fe7d1336940dc2080b52a5b5fee7ed16758e.mp3", "duration_ms": 3920}, "s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/0e66593f02622d7cd52fc81079f1b83e3a27946c4791c2cb2385cc3fc7c9b1f3.mp3", "hash": "20af4c037d6a12f72079299af14eb82e3252769a37ef4adbaeb864e0bf872217", "bytes": 167904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0e66593f02622d7cd52fc81079f1b83e3a27946c4791c2cb2385cc3fc7c9b1f3.mp3", "duration_ms": 27920}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/e7ad41c75f9b567305dc2ba837cfb988b95c2ed89450a2b5e6a569f5e6ad12b5.mp3", "hash": "012ff35ee5403188e366b577d981cfc15f59e4ff1eec86f0311db6b0e1f27ba3", "bytes": 90576, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/e7ad41c75f9b567305dc2ba837cfb988b95c2ed89450a2b5e6a569f5e6ad12b5.mp3", "duration_ms": 15040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'pt-BR', '1', '{"meta": {"cast": ["rho"], "slug": "rank-choices", "title": "Organize suas compras", "locale": "pt-BR", "subject": "mixed", "objectives": ["Organizar do mais urgente ao menos urgente no que gastar o lucro de hoje: repor limões primeiro, depois copos, e por último enfeites."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-compras", "xp": 15, "type": "rank_choices", "hints": ["Pense: o que a barraca precisa para continuar vendendo limonada?", "Os enfeites são bonitos, mas não urgentes."], "title": "O que comprar primeiro?", "payload": {"items": [{"id": "limones", "text_md": "Repor limões (custam 8 reais)"}, {"id": "vasos", "text_md": "Comprar copos novos (custam 5 reais)"}, {"id": "adornos", "text_md": "Enfeites para a barraca (custam 3 reais)"}], "criterion_md": "Organize do mais urgente (em cima) ao menos urgente (embaixo)."}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho ganhou 20 reais em sua barraca de limonada. Ajude Rho a decidir o que comprar primeiro. Toque nos gastos para organizá-los do mais urgente ao menos urgente.", "difficulty": 2, "explanation_md": "Rho precisa de limões para fazer mais limonada, depois copos para servi-la. Os enfeites podem esperar.", "audio_segment_id": "s1-ordenar-compras.prompt"}], "schema_version": 1}', '{"s1-ordenar-compras": {"order": ["limones", "vasos", "adornos"]}}', '{"units": {"s1-ordenar-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0429e1e024f97845538b02c8677e7375c7e959f5267923e13b6d5d223088596a.mp3", "hash": "a58c51ac94ebe6dff2c2b747900cedc7c17ac854bcbbf4215c8faabda7a6f5d2", "bytes": 27648, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/0429e1e024f97845538b02c8677e7375c7e959f5267923e13b6d5d223088596a.mp3", "duration_ms": 4560}, "s1-ordenar-compras.hint.1": {"url": "http://localhost:4006/files/lesson-audio/28e4ed048f5a6363afc1fd114b65675d7e144ed162c41797774715e7f148f717.mp3", "hash": "044e364add1135c49c5851bbe277fd5768fbbb72d7da20b152ba9184f153fbc0", "bytes": 22464, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/28e4ed048f5a6363afc1fd114b65675d7e144ed162c41797774715e7f148f717.mp3", "duration_ms": 3680}, "s1-ordenar-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/16609b07e588709738e25299e5a0be3e9c2932d0f6a105f29eb0ba5fa3d16ef9.mp3", "hash": "46722401340a4df53296e9e90bb2e471439ca0a5fb392d11e8948db0576d6b3b", "bytes": 67104, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/16609b07e588709738e25299e5a0be3e9c2932d0f6a105f29eb0ba5fa3d16ef9.mp3", "duration_ms": 11120}, "s1-ordenar-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/3402d1bb88e4f817218423b252446c2efee6b38a6d1142450c809360b0a8f2a5.mp3", "hash": "4d4f185ec785174ad9fe05e046693ca47affa04db060412f7ac9261721bbe679", "bytes": 44928, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/3402d1bb88e4f817218423b252446c2efee6b38a6d1142450c809360b0a8f2a5.mp3", "duration_ms": 7440}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fair-trade", "title": "Troca justa", "locale": "pt-BR", "subject": "mixed", "objectives": ["Decidir se uma troca é justa comparando valores", "Contar moedas de 1, 2, 5 e 10", "Calcular troco de uma nota de 20", "Planejar semanas para economizar 80 reais"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 10, "type": "fair_trade", "hints": ["Quanto Liruf pagou por 2 copos na semana passada?", "Se a troca é justa, Liruf não perde dinheiro. Quanto vale o saco de limões?"], "title": "Troca justa", "payload": {"offer_a": {"qty": 2, "icon": "local_cafe", "label": "2 copos de limonada"}, "offer_b": {"qty": 1, "icon": "storefront", "label": "Saco de limões"}, "rate_md": "Na semana passada, Liruf pagou 10 reais por 2 copos de limonada. O saco de limões custa 10 reais."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf está economizando 20 reais por semana para comprar um violão de 80 reais. Já se passaram 3 semanas e ele tem 60 reais. O feirante oferece trocar um saco de limões por 2 copos de limonada. Liruf lembra que na semana passada pagou 10 reais por 2 copos de limonada. O saco de limões custa 10 reais na loja. A troca é justa?", "difficulty": 1, "explanation_md": "Na semana passada, Liruf pagou 10 reais por 2 copos de limonada, e o saco de limões também custa 10 reais. Ambos valem a mesma coisa, então a troca é justa. Liruf não perde dinheiro e continua com seus 60 reais mais os 20 que economizará esta semana, terá 80 reais exatos para o violão!", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "fair"}}', '{"units": {"s1-fair-trade.hint.0": {"url": "http://localhost:4006/files/lesson-audio/44a8bb141d4315b06671687664251b05f5b81253e75276680c8ea8044aaf375e.mp3", "hash": "321995bb1c799c40ac40acd545a3985582129694e573dced0db0f14873abb2a9", "bytes": 21888, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/44a8bb141d4315b06671687664251b05f5b81253e75276680c8ea8044aaf375e.mp3", "duration_ms": 3600}, "s1-fair-trade.hint.1": {"url": "http://localhost:4006/files/lesson-audio/1cbdeaa34acd02cfd828f0164c13ac186cf8c238434fb584ebf8fa9dd7af4188.mp3", "hash": "fb1b969333fee1d36cfa4978695ff2ad411cdeaae79060fd71bfdb16e76ce104", "bytes": 32976, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/1cbdeaa34acd02cfd828f0164c13ac186cf8c238434fb584ebf8fa9dd7af4188.mp3", "duration_ms": 5440}, "s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/bd26b63406370fda80e17bfcf7a3d92d5dbe691f7185ed962bf1387dff76decc.mp3", "hash": "6067f6692700362c02c9d8f1a4f1d55efb2348dd9fe28283f9e3095d5428a569", "bytes": 143424, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/bd26b63406370fda80e17bfcf7a3d92d5dbe691f7185ed962bf1387dff76decc.mp3", "duration_ms": 23840}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/ac2fdd3a00b07c0253555d7a49e5706c7121007f5b65fe82f5ced33d568039d3.mp3", "hash": "d8fbfced9d0eeeb86773455be595036b99917caba54663d2dca48a0fc3c44ff1", "bytes": 129024, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/ac2fdd3a00b07c0253555d7a49e5706c7121007f5b65fe82f5ced33d568039d3.mp3", "duration_ms": 21440}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "spot-error", "title": "Encontre o erro na conta", "locale": "pt-BR", "subject": "mixed", "objectives": ["Detectar um erro em uma soma de vendas", "Ler um gráfico simples de copos vendidos por dia", "Reconhecer sinais de um mau negócio"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-spot-error", "xp": 10, "type": "spot_error", "hints": ["Some os números novamente: 5 + 5 + 5 são 15, não 20."], "title": "A conta que não fecha", "payload": {"steps": [{"id": "step1", "text_md": "Passo 1: Vendi 3 copos."}, {"id": "step2", "text_md": "Passo 2: Cada copo custa 5 reais."}, {"id": "step3", "text_md": "Passo 3: 5 + 5 + 5 = 20."}, {"id": "step4", "text_md": "Passo 4: Anotei o total no caderno."}], "context_md": "Liruf vendeu 3 copos de limonada a 5 reais cada. Quer economizar tudo para comprar um skate de 20 reais. Anotou: 5 + 5 + 5 = 20."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Toque no passo que está errado na conta de Liruf.", "difficulty": 1, "explanation_md": "O erro está no passo 3: 5 + 5 + 5 = 15, não 20. Liruf somou errado. Se tivesse economizado os 20 que pensava, teria 5 reais a mais para seu cofrinho. Mas só tem 15, então seu dinheiro crescerá menos quando guardar.", "audio_segment_id": "s1-spot-error.prompt"}], "schema_version": 1}', '{"s1-spot-error": {"error_ids": ["step3"], "correction_md": "5 + 5 + 5 = 15, no 20."}}', '{"units": {"s1-spot-error.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c9c0ccf9143925fe19c586894fbf7f653294493d6969a0f8ad33ef210080f7e8.mp3", "hash": "d4cc9863166936a8b7fe20931f411d39b04f7b9db9f2a81ea47bef38e0d4182f", "bytes": 31968, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c9c0ccf9143925fe19c586894fbf7f653294493d6969a0f8ad33ef210080f7e8.mp3", "duration_ms": 5280}, "s1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/5ee9d1e8e75845501cb0947e6ae87dde5a94361b8626c9246774797396f9c1de.mp3", "hash": "eb1296237c31de72d1d348d91bfc1ed24b7b10f7e8b30e2db593b3e1956948f2", "bytes": 18576, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5ee9d1e8e75845501cb0947e6ae87dde5a94361b8626c9246774797396f9c1de.mp3", "duration_ms": 3040}, "s1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/6776a220602ad4a8ff461fac685c382ddc3b023a9891d056116a96c8f891ae18.mp3", "hash": "58054b15dbaf070aa1993fe0ace0dd4b229a714b8e5f35eb5f255508864ace80", "bytes": 112176, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6776a220602ad4a8ff461fac685c382ddc3b023a9891d056116a96c8f891ae18.mp3", "duration_ms": 18640}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "match-pairs", "title": "Empareja los precios", "locale": "es-MX", "subject": "money", "objectives": ["Emparejar cada producto del puesto con su precio correcto (vaso chico–5, jarra–20, galleta–3)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-prices", "xp": 10, "type": "match_pairs", "hints": ["Si 3 vasos cuestan 15 pesos, cada vaso cuesta 5 pesos. La jarra cuesta 20 y la galleta 3."], "title": "Las etiquetas de Dina", "payload": {"left": [{"id": "vaso", "text_md": "Vaso chico"}, {"id": "jarra", "text_md": "Jarra"}, {"id": "galleta", "text_md": "Galleta"}], "right": [{"id": "p5", "text_md": "5 pesos"}, {"id": "p20", "text_md": "20 pesos"}, {"id": "p3", "text_md": "3 pesos"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Ayer Dina vendió 3 vasos chicos y ganó 15 pesos. ¿Cuánto cuesta UN vaso chico? Usa eso para emparejar cada producto con su precio: toca el producto y luego su precio.", "difficulty": 1, "explanation_md": "3 vasos por 15 pesos significa que cada vaso cuesta 5 pesos (porque 5+5+5=15). La jarra cuesta 20 y la galleta 3. ¡Bien hecho!", "audio_segment_id": "s1-match-prices.prompt"}], "schema_version": 1}', '{"s1-match-prices": {"pairs": [["vaso", "p5"], ["jarra", "p20"], ["galleta", "p3"]]}}', '{"units": {"s1-match-prices.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6be26adfaf6ee5588164a6e4b93ff53771fc0ce111cb7461d05a7d5c4cc4abf1.mp3", "hash": "eec46ded5d9f03478d880c4eb4541ac939f115627ac18e0356ee0478978770ec", "bytes": 45936, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6be26adfaf6ee5588164a6e4b93ff53771fc0ce111cb7461d05a7d5c4cc4abf1.mp3", "duration_ms": 7600}, "s1-match-prices.prompt": {"url": "http://localhost:4006/files/lesson-audio/d6bd6de6cac973cccfb1329bb8aede1ca60453800d920418dc20fbc017274157.mp3", "hash": "97053e0e55a2aa1205ec3af141c6d2185707b02bcb558701217c8d6bcd403ea5", "bytes": 78048, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d6bd6de6cac973cccfb1329bb8aede1ca60453800d920418dc20fbc017274157.mp3", "duration_ms": 12960}, "s1-match-prices.explanation": {"url": "http://localhost:4006/files/lesson-audio/a8894c16f5d4940a584d9c270ff76a4310978399a06aea331d4be06ef94c54d5.mp3", "hash": "f35e0e0bf56c697bb860b2a76e8b146ddab089e8293016634aa5fccaaca31415", "bytes": 74304, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a8894c16f5d4940a584d9c270ff76a4310978399a06aea331d4be06ef94c54d5.mp3", "duration_ms": 12320}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-arrange-largo", "title": "Fechar o posto: tudo misturado", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular o troco correto para cada pagamento em uma venda real.", "Ordenar os passos para calcular o lucro: separar o custo primeiro.", "Separar necessidades do posto de despesas que podem esperar.", "Ordenar eventos do dia para que o caixa nunca fique sem troco."], "estimated_minutes": 12}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-cambio", "xp": 15, "type": "match_pairs", "hints": ["Lembre-se: troco = pagamento - preço. Se pagaram 10 por um copo de 5, quanto sobra?", "Calcule quanto custam 2 copos se alguém comprou 2."], "title": "Emparelhe cada pagamento com seu troco", "payload": {"left": [{"id": "pago10", "text_md": "Paga com 10 pesos por 1 copo"}, {"id": "pago20", "text_md": "Paga com 20 pesos por 2 copos"}, {"id": "pago6", "text_md": "Paga com 6 pesos por 1 copo"}], "right": [{"id": "cambio5", "text_md": "Troco: 5 pesos"}, {"id": "cambio10", "text_md": "Troco: 10 pesos"}, {"id": "cambio1", "text_md": "Troco: 1 peso"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Ontem você fechou o posto e contou as moedas para o violão de 80 pesos. Hoje Liruf vende 3 copos de limonada. Cada copo custa 5 pesos. Emparelhe cada pagamento com o troco que deve dar ao cliente.", "difficulty": 2, "explanation_md": "Se pagaram 10 por um copo de 5, o troco é 5. Se pagaram 20 por dois copos (10), o troco é 10. Se pagaram 6 por um copo de 5, o troco é 1.", "audio_segment_id": "s1-match-cambio.prompt"}, {"id": "s2-order-ganancia", "xp": 15, "type": "order_steps", "hints": ["Primeiro, é preciso separar o que custou fazer a limonada.", "Depois de subtrair o custo, o que sobra é o lucro."], "title": "Ordene como calcular o lucro", "payload": {"items": [{"id": "restar-costo", "text_md": "Subtrair o custo dos ingredientes (12 pesos)"}, {"id": "contar-venta", "text_md": "Contar todo o dinheiro das vendas (25 pesos)"}, {"id": "resultado-ganancia", "text_md": "O resultado é o lucro (13 pesos)"}], "slots": 3}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina vendeu limonada hoje. Gastou 12 pesos em limões e copos, e juntou 25 pesos das vendas. Ajude Dina a ordenar os passos para saber quanto ela realmente ganhou. Se não fizer direito, ela não saberá se dá para o violão de 80 pesos.", "difficulty": 2, "explanation_md": "Primeiro, conta-se todo o dinheiro das vendas (25 pesos). Depois, subtrai-se o custo dos ingredientes (12 pesos). O resultado (13 pesos) é o lucro. Assim Dina sabe quanto está juntando para o violão!", "audio_segment_id": "s2-order-ganancia.prompt"}, {"id": "s3-sort-necesidades", "xp": 15, "type": "sort_buckets", "hints": ["Pense: sem isso, o posto não pode vender limonada?", "O que é urgente para abrir vai em ''Precisa'', o resto em ''Pode esperar''."], "title": "Separe o que o posto precisa", "payload": {"items": [{"id": "limones", "text_md": "Limões (8 pesos)"}, {"id": "vasos", "text_md": "Copos (6 pesos)"}, {"id": "hielo", "text_md": "Gelo (4 pesos)"}, {"id": "calcomania", "text_md": "Adesivo para o posto (2 pesos)"}], "buckets": [{"id": "necesita", "label": "Precisa para abrir"}, {"id": "esperar", "label": "Pode esperar"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Você tem 20 pesos para gastar amanhã. Separe cada gasto no que o posto PRECISA para abrir e no que PODE ESPERAR.", "difficulty": 2, "explanation_md": "Os limões e os copos são necessários para vender. O gelo e o adesivo podem esperar outro dia.", "audio_segment_id": "s3-sort-necesidades.prompt"}, {"id": "s4-timeline-cambio", "xp": 25, "type": "timeline_order", "hints": ["Antes de gastar dinheiro, certifique-se de que entre uma venda com nota grande.", "Se gastar troco antes de recebê-lo, você fica sem moedas."], "title": "Organize o dia para não ficar sem troco", "payload": {"events": [{"id": "venta50", "icon": "payments", "text_md": "Cliente paga com nota de 50 por 2 copos"}, {"id": "compra-vasos", "icon": "shopping_cart", "text_md": "Comprar mais copos (gastar 10 pesos)"}, {"id": "venta20", "icon": "payments", "text_md": "Cliente paga com nota de 20 por 1 copo"}, {"id": "compra-hielo", "icon": "local_cafe", "text_md": "Comprar gelo (gastar 8 pesos)"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina precisa que o caixa sempre tenha moedas para dar troco. Ordene estes eventos na ordem correta para que nunca falte troco.", "difficulty": 3, "explanation_md": "Primeiro chega uma venda com nota de 50, isso dá troco. Depois, compram-se mais copos. Em seguida, outra venda com nota de 20 dá mais troco. Por fim, compra-se gelo.", "audio_segment_id": "s4-timeline-cambio.prompt"}], "schema_version": 1}', '{"s1-match-cambio": {"pairs": [["pago10", "cambio5"], ["pago20", "cambio10"], ["pago6", "cambio1"]]}, "s2-order-ganancia": {"order": ["contar-venta", "restar-costo", "resultado-ganancia"]}, "s4-timeline-cambio": {"order": ["venta50", "compra-vasos", "venta20", "compra-hielo"]}, "s3-sort-necesidades": {"assignments": {"hielo": "esperar", "vasos": "necesita", "limones": "necesita", "calcomania": "esperar"}}}', '{"units": {"s1-match-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/09c0a2046219caf2edd5e67a84e461e41ee95b2ef9f8f15531490efa6ce722ad.mp3", "hash": "ccf07d7c611db363486071060c8eed036b14f76022a4cb6f930e5643b0a5344c", "bytes": 40608, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/09c0a2046219caf2edd5e67a84e461e41ee95b2ef9f8f15531490efa6ce722ad.mp3", "duration_ms": 6720}, "s1-match-cambio.hint.1": {"url": "http://localhost:4006/files/lesson-audio/68614635e972fc44209f60