tion_ms": 18560}, "s4-timeline-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1d869ed63ec6c16bcdb53e1dbc54fdb18ba2dee5bbce5d3d0d8974ced209c0e0.mp3", "hash": "cf436577d2e65db7259bff2bd7133603053dce21f82180a52c4e7815371f7ca4", "bytes": 31536, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1d869ed63ec6c16bcdb53e1dbc54fdb18ba2dee5bbce5d3d0d8974ced209c0e0.mp3", "duration_ms": 5200}, "s4-timeline-cambio.hint.1": {"url": "http://localhost:4006/files/lesson-audio/1f95ae96437e84fe8b67efab913364c8c633abd54a1f1d76a184042de793a370.mp3", "hash": "21d2a12562e07f84a865e57ee58d39d835c6cc37fb625a70bf69f2f356c9f23e", "bytes": 26784, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1f95ae96437e84fe8b67efab913364c8c633abd54a1f1d76a184042de793a370.mp3", "duration_ms": 4400}, "s4-timeline-cambio.prompt": {"url": "http://localhost:4006/files/lesson-audio/f0b14cd2c6e86bc8db75ec5263153be07db14a62954f885840454588b5cd24e9.mp3", "hash": "e66d168088372a506c6ce8f8979c5073b3e7b7358a39bca7bbd487e850d94fe9", "bytes": 55584, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f0b14cd2c6e86bc8db75ec5263153be07db14a62954f885840454588b5cd24e9.mp3", "duration_ms": 9200}, "s3-sort-necesidades.hint.0": {"url": "http://localhost:4006/files/lesson-audio/53e130cc4fa1c5761a731ef637e50fd43436359cb3eeb1ad164210307c801982.mp3", "hash": "43e24c7913c3456bc2effec8e94c2a5c7cabd2ba5f35b308d35da91553d9f792", "bytes": 22896, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/53e130cc4fa1c5761a731ef637e50fd43436359cb3eeb1ad164210307c801982.mp3", "duration_ms": 3760}, "s3-sort-necesidades.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2754efa427005e3241c87470c02df8c167d8db626be5c1577ad09962189da390.mp3", "hash": "0775cf8630c062b55bdacfee44549cabf3f9093da286b0bd691c74cd814a2269", "bytes": 30528, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/2754efa427005e3241c87470c02df8c167d8db626be5c1577ad09962189da390.mp3", "duration_ms": 5040}, "s3-sort-necesidades.prompt": {"url": "http://localhost:4006/files/lesson-audio/a2c6ebd17dd8cc29dcbe4e84c7d2f11e9e7a1f2ed90b93696beee92f9a032e04.mp3", "hash": "43a6121128b508d314e0b1cb2ba9abec34595fa7ac0c000a1727ef884fedeebd", "bytes": 48816, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/a2c6ebd17dd8cc29dcbe4e84c7d2f11e9e7a1f2ed90b93696beee92f9a032e04.mp3", "duration_ms": 8080}, "s1-match-cambio.explanation": {"url": "http://localhost:4006/files/lesson-audio/ecc6d44d329f03340fb89d4c087fe01ea8fb1ebfbfd9d6132aa801013a324898.mp3", "hash": "f740b0d9d76217a0aba26f4a59ba7f68f32e55cea80198d597a988515d853f3d", "bytes": 75744, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/ecc6d44d329f03340fb89d4c087fe01ea8fb1ebfbfd9d6132aa801013a324898.mp3", "duration_ms": 12560}, "s2-order-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/f2e59005f8ce44e4bc318fd4033fe5fb59ac2fad09d0bd9c1b64b53c522af627.mp3", "hash": "bc8e502679cb6cb922bb2e01e361cb00e681ed7c8ad90123fd5ff2d81d71737d", "bytes": 95904, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f2e59005f8ce44e4bc318fd4033fe5fb59ac2fad09d0bd9c1b64b53c522af627.mp3", "duration_ms": 15920}, "s4-timeline-cambio.explanation": {"url": "http://localhost:4006/files/lesson-audio/92a1785b31b9dcf4d2c7fe219a95818b1acd18f3e06d82544c3e458efad571c6.mp3", "hash": "a19231ea3312ad2323d062e8748f8d76e29616327d900265708176df285711d2", "bytes": 79488, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/92a1785b31b9dcf4d2c7fe219a95818b1acd18f3e06d82544c3e458efad571c6.mp3", "duration_ms": 13200}, "s3-sort-necesidades.explanation": {"url": "http://localhost:4006/files/lesson-audio/950f2dc0f1c0e7467ce5fd2da345c66d76e14f769c3a72161d97b59baf167114.mp3", "hash": "ca9f88d1b9cc92115e2dc26e7dc8ff10b483016ba7d34cfa7429eb64427f272d", "bytes": 45936, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/950f2dc0f1c0e7467ce5fd2da345c66d76e14f769c3a72161d97b59baf167114.mp3", "duration_ms": 7600}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "repaso-true-false", "title": "Review: True or False?", "locale": "en-US", "subject": "money", "objectives": ["Distinguish between total revenue and profit at a lemonade stand.", "Remember that each cup costs 2 pesos in supplies, so the profit per cup is 3 pesos."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-verdadero-falso", "xp": 10, "type": "true_false", "hints": ["Remember: each cup costs 2 pesos for lemon and sugar. How much do you actually keep per cup?", "If you earn 3 pesos per cup, multiply 3 × 10 to find the actual profit."], "title": "Rho''s Last Trap", "payload": {"statement_md": "Liruf sold 10 cups at 5 pesos, so he earned 50 pesos.", "justifications": [{"id": "j-ingreso", "text_md": "50 pesos is what went into the cash box, but each cup cost 2 pesos for ingredients, so the profit is 3 pesos per cup, 30 total."}, {"id": "j-ganancia", "text_md": "50 pesos is the profit because 10 × 5 = 50, and there are no other expenses."}]}, "narrator": {"emotion": "surprised", "character": "rho"}, "prompt_md": "Rho holds up a sign: ''Today you sold 10 cups at 5 pesos each. So you earned 50 pesos!'' Is it true or false?", "difficulty": 1, "explanation_md": "It''s false. 50 pesos is what came in, but each cup cost 2 pesos to make, so the actual profit is 3 pesos per cup, 30 pesos total.", "audio_segment_id": "s1-verdadero-falso.prompt"}], "schema_version": 1}', '{"s1-verdadero-falso": {"is_true": false, "correct_justification_id": "j-ingreso"}}', '{"units": {"s1-verdadero-falso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9f7b6333c1649285037824a41bcd39182b9b1527394adb990c0e8dca7931ff34.mp3", "hash": "b85e7c004f734f500689482ed3997956cdecfcc8b2b36d959c133a85ddd30ad9", "bytes": 41616, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/9f7b6333c1649285037824a41bcd39182b9b1527394adb990c0e8dca7931ff34.mp3", "duration_ms": 6880}, "s1-verdadero-falso.hint.1": {"url": "http://localhost:4006/files/lesson-audio/41dc3151052004f7cd6579b5a0d4d3b65d3d4f2c493b46d7038b3e7c5a5ca37f.mp3", "hash": "676a2a6e2c11c8f20809087f2de786516bd750ac593ca20c29f1b68734e23560", "bytes": 40608, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/41dc3151052004f7cd6579b5a0d4d3b65d3d4f2c493b46d7038b3e7c5a5ca37f.mp3", "duration_ms": 6720}, "s1-verdadero-falso.prompt": {"url": "http://localhost:4006/files/lesson-audio/a2c0613755eea38289efa12051e29e260ebd8261195fd01e0aa71b6050bfbc06.mp3", "hash": "a4da3acc276d29e9e97924670f008b98362359199cbe3771009fe0ee9f4d3ef5", "bytes": 57888, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/a2c0613755eea38289efa12051e29e260ebd8261195fd01e0aa71b6050bfbc06.mp3", "duration_ms": 9600}, "s1-verdadero-falso.explanation": {"url": "http://localhost:4006/files/lesson-audio/6bcb1829853bed0e6747ff9f4d16c20a364d42135269409848f594d56f0c7c5e.mp3", "hash": "c2443b1622215325facd9a0ef34248d626252805532bcb54b5fa3ea401601839", "bytes": 69984, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/6bcb1829853bed0e6747ff9f4d16c20a364d42135269409848f594d56f0c7c5e.mp3", "duration_ms": 11600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "interest-peek", "title": "The piggy bank that rewards patience", "locale": "en-US", "subject": "money", "objectives": ["Deciding whether leaving money in a piggy bank that gives extra coins each week is better than spending it now.", "Predicting the total after waiting, understanding that it grows a little but doesn''t double."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 10, "type": "interest_peek", "hints": ["Each week the piggy bank gives 2 coins of 1 peso. How many extra coins does it give in 2 weeks?", "Start with 20. Add the extra coins."], "title": "Leave the 20 or take them out now?", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 20, "prediction": {"kind": "choice", "options": [{"id": "opt1", "text_md": "Stays at 20"}, {"id": "opt2", "text_md": "24 pesos"}, {"id": "opt3", "text_md": "Almost 40 pesos"}]}}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf has 20 pesos saved for a guitar that costs 80. Rho tells him: ''If you keep your money in this special piggy bank, it gives you 2 extra 1-peso coins each week for leaving it there.'' Liruf puts in his 20 pesos. He thinks: ''If I wait 2 weeks, will I have more or less than if I spend everything now?'' How much will Liruf have after 2 weeks?", "difficulty": 1, "explanation_md": "The piggy bank gives 2 coins of 1 peso each week, so in 2 weeks it gives 4 extra pesos. 20 + 4 = 24. The money grows little by little toward the guitar! If he had spent everything now, he wouldn''t have those 4 extra pesos.", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 24, "tolerance": 1, "correct_option_id": "opt2"}}', '{"units": {"s1-interest-peek.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4a5700d8d7b93dd2db63d59f3749fcbcf6a67b294b3e1c8b6b4b676ba6e8c866.mp3", "hash": "e3ea14dc8606d826d144eb6363d4368856117ed4d8f67dadc689bfe55e4c73ae", "bytes": 35424, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4a5700d8d7b93dd2db63d59f3749fcbcf6a67b294b3e1c8b6b4b676ba6e8c866.mp3", "duration_ms": 5840}, "s1-interest-peek.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a82f3ebf19baf7e9138309a130b71f757267c05925caf540b44c44cfbea0dfb0.mp3", "hash": "f8bc08ef72f497b9b77b2307f928554ffa4b3b6cc12fc571460ffce20f85865a", "bytes": 14688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a82f3ebf19baf7e9138309a130b71f757267c05925caf540b44c44cfbea0dfb0.mp3", "duration_ms": 2400}, "s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/b49a04c24d33234aaeaaf63490164a18df1ed618b6c733bd37179b830457b80d.mp3", "hash": "06bcab7bd0bd3055f199a09c2880c35f064564fca791d36fd206176edd6790db", "bytes": 111744, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b49a04c24d33234aaeaaf63490164a18df1ed618b6c733bd37179b830457b80d.mp3", "duration_ms": 18560}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/179506ab0a47a00b58d140453e8731475a2c2f74df181290002d2c3b1fd26cd9.mp3", "hash": "a23efb9b593ec86ce6a5983bd0d2b921db12b5e029c2f53aeed641521e81bdb1", "bytes": 83376, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/179506ab0a47a00b58d140453e8731475a2c2f74df181290002d2c3b1fd26cd9.mp3", "duration_ms": 13840}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "spot-error", "title": "Encuentra el error en la cuenta", "locale": "es-MX", "subject": "mixed", "objectives": ["Detectar un error en una suma de ventas", "Leer una gráfica simple de vasos vendidos por día", "Reconocer señales de un mal trato"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-spot-error", "xp": 10, "type": "spot_error", "hints": ["Suma los números otra vez: 5 + 5 + 5 son 15, no 20."], "title": "La cuenta que no cuadra", "payload": {"steps": [{"id": "step1", "text_md": "Paso 1: Vendí 3 vasos."}, {"id": "step2", "text_md": "Paso 2: Cada vaso cuesta 5 pesos."}, {"id": "step3", "text_md": "Paso 3: 5 + 5 + 5 = 20."}, {"id": "step4", "text_md": "Paso 4: Anoté el total en el cuaderno."}], "context_md": "Liruf vendió 3 vasos de limonada a 5 pesos cada uno. Quiere ahorrar todo para comprar una patineta de 20 pesos. Anotó: 5 + 5 + 5 = 20."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Toca el paso que está mal en la cuenta de Liruf.", "difficulty": 1, "explanation_md": "El error está en el paso 3: 5 + 5 + 5 = 15, no 20. Liruf sumó mal. Si hubiera ahorrado los 20 que pensaba, tendría 5 pesos más para su alcancía. Pero solo tiene 15, así que su dinero crecerá menos cuando lo guarde.", "audio_segment_id": "s1-spot-error.prompt"}], "schema_version": 1}', '{"s1-spot-error": {"error_ids": ["step3"], "correction_md": "5 + 5 + 5 = 15, no 20."}}', '{"units": {"s1-spot-error.hint.0": {"url": "http://localhost:4006/files/lesson-audio/175213242fa47561358b3e6e66d1c5ef57d362ee43575e31df6016c4122fce56.mp3", "hash": "e1da768a3e5a46b41949842e9a78d4f11d56210214e41024c4a043ae425a29a8", "bytes": 35424, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/175213242fa47561358b3e6e66d1c5ef57d362ee43575e31df6016c4122fce56.mp3", "duration_ms": 5840}, "s1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/5c36fedc037897fb5b7dd440de06c586f8f82a00ddd66cb46a15737e702b088b.mp3", "hash": "36cf8c7097f5a2482a1e0621c75a03ede29730da9f515f0376fc7b826f813795", "bytes": 18576, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5c36fedc037897fb5b7dd440de06c586f8f82a00ddd66cb46a15737e702b088b.mp3", "duration_ms": 3040}, "s1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/3f61da7bf2a66a907dc2ad4d1c469036d2db0d426bd00d5773fa4b8efc0d9d43.mp3", "hash": "b22a38c576fee3e24b575571fbedf21364adbe19091b1f2ef1f7730a8257eae4", "bytes": 102096, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3f61da7bf2a66a907dc2ad4d1c469036d2db0d426bd00d5773fa4b8efc0d9d43.mp3", "duration_ms": 16960}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "quiz-mcq", "title": "Preço justo para a limonada", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher o preço justo para um copo de limonada (5 pesos) entre opções exageradas"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-justo", "xp": 10, "type": "quiz_mcq", "hints": ["Pense: se o copo custa 5 pesos, um preço justo deve ser um pouquinho mais, mas não demais."], "title": "Quanto custa o copo?", "payload": {"options": [{"id": "a", "text_md": "5 pesos", "rationale_md": "5 pesos não dá lucro, você só recupera o custo. Não economizaria nada!"}, {"id": "b", "text_md": "8 pesos", "rationale_md": "8 pesos é justo: você ganha 3 pesos por copo e os clientes pagam um preço razoável."}, {"id": "c", "text_md": "20 pesos", "rationale_md": "20 pesos é caro demais. Os clientes não vão pagar tanto e você não venderá nada."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Respirar e revisar: você já tem meta (80 pesos), produto (limonada a 5 pesos) e sabe o que é custo e lucro. Como você se sente para abrir a barraca? Liruf está pronto. Mas é preciso decidir o preço. Se você colocar o copo a 5 pesos, não ganha nada. Se colocar a 20 pesos, ninguém vai comprar. Qual é um preço justo que te dê lucro sem espantar os clientes?", "difficulty": 1, "explanation_md": "Exato! 8 pesos é justo: você ganha 3 pesos por copo (8 - 5 = 3) e os clientes pagam um preço razoável. Assim você pode economizar para o seu skate!", "audio_segment_id": "s1-precio-justo.prompt"}], "schema_version": 1}', '{"s1-precio-justo": {"correct_option_id": "b"}}', '{"units": {"s1-precio-justo.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f66cb0edba4c8c7ea2429089236ef4f1b8b22eb5b4a4d60c35a3ce5880a1293b.mp3", "hash": "477529acbdaf9868577ffe7648cebf357dc1e527db7840008adee7c64654235b", "bytes": 43488, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f66cb0edba4c8c7ea2429089236ef4f1b8b22eb5b4a4d60c35a3ce5880a1293b.mp3", "duration_ms": 7200}, "s1-precio-justo.prompt": {"url": "http://localhost:4006/files/lesson-audio/a359b4eb40376cbfc7b46d3edcec276d5fbdca7b09969106beda3df749f73f8f.mp3", "hash": "afc5a223c4477268854c0d895c5a9d99569cc4dec137be1217bdd15d7adb79a3", "bytes": 159696, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a359b4eb40376cbfc7b46d3edcec276d5fbdca7b09969106beda3df749f73f8f.mp3", "duration_ms": 26560}, "s1-precio-justo.choices": {"url": "http://localhost:4006/files/lesson-audio/d5405aa664d6846b5661098ca8277e3609a5e4230ce51ea4b1978e3947f93496.mp3", "hash": "9721c709c14676894bed67515c058f00381a162a72129d866fd2c117d65d9155", "bytes": 23904, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d5405aa664d6846b5661098ca8277e3609a5e4230ce51ea4b1978e3947f93496.mp3", "duration_ms": 3920}, "s1-precio-justo.explanation": {"url": "http://localhost:4006/files/lesson-audio/1a4ba51d576d44f8f53621d2599223cd1ab1d26084b772382b45f8b9cf25bf33.mp3", "hash": "cb92a4c62887cb65afd710cc8a5465308bb56f4d071286e36d0a193706c1f7c3", "bytes": 85824, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1a4ba51d576d44f8f53621d2599223cd1ab1d26084b772382b45f8b9cf25bf33.mp3", "duration_ms": 14240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "repaso-true-false", "title": "Repaso: ¿Verdadero o Falso?", "locale": "es-MX", "subject": "money", "objectives": ["Distinguir entre ingreso total y ganancia en un puesto de limonada.", "Recordar que cada vaso cuesta 2 pesos de insumos, por lo que la ganancia por vaso es de 3 pesos."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-verdadero-falso", "xp": 10, "type": "true_false", "hints": ["Recuerda: cada vaso cuesta 2 pesos de limón y azúcar. ¿Cuánto te queda de verdad por cada vaso?", "Si por cada vaso ganas 3 pesos, multiplica 3 × 10 para saber la ganancia real."], "title": "La última trampa de Rho", "payload": {"statement_md": "Liruf vendió 10 vasos a 5 pesos, entonces ganó 50 pesos.", "justifications": [{"id": "j-ingreso", "text_md": "50 pesos es lo que entró a la caja, pero cada vaso costó 2 pesos de ingredientes, así que la ganancia es de 3 pesos por vaso, 30 en total."}, {"id": "j-ganancia", "text_md": "50 pesos es la ganancia porque 10 × 5 = 50, y no hay otros gastos."}]}, "narrator": {"emotion": "surprised", "character": "rho"}, "prompt_md": "Rho levanta el letrero: ''Hoy vendiste 10 vasos a 5 pesos cada uno. ¡Entonces ganaste 50 pesos!'' ¿Es verdad o es falso?", "difficulty": 1, "explanation_md": "Es falso. 50 pesos es lo que entró, pero cada vaso costó 2 pesos hacerlo, así que la ganancia real es de 3 pesos por vaso, 30 pesos en total.", "audio_segment_id": "s1-verdadero-falso.prompt"}], "schema_version": 1}', '{"s1-verdadero-falso": {"is_true": false, "correct_justification_id": "j-ingreso"}}', '{"units": {"s1-verdadero-falso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2dc009d3fb12dbd1fee3d9dc36d63cee50351914a0af909d247ef711df752fb1.mp3", "hash": "22d17e295d210d95ae538a2d1ad7344351c1be05dadefddc7dc924032504839e", "bytes": 44496, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/2dc009d3fb12dbd1fee3d9dc36d63cee50351914a0af909d247ef711df752fb1.mp3", "duration_ms": 7360}, "s1-verdadero-falso.hint.1": {"url": "http://localhost:4006/files/lesson-audio/267f7531fad18318a0ed5125d453551237c101ebd68c03620c4dafd22fb2c28d.mp3", "hash": "26b79f7734cd624661a89fe10a3b6e2936b83d30a853bd09a8b07c1b718debb1", "bytes": 37296, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/267f7531fad18318a0ed5125d453551237c101ebd68c03620c4dafd22fb2c28d.mp3", "duration_ms": 6160}, "s1-verdadero-falso.prompt": {"url": "http://localhost:4006/files/lesson-audio/9fd338ca995b375490969a2bebbd7ea74114f5b4e940b628d2ebf9051db692f4.mp3", "hash": "90fb0513cb60de9f61c936b2a6682242813e94e08d4ca663c3a64b8ee716aee5", "bytes": 61344, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/9fd338ca995b375490969a2bebbd7ea74114f5b4e940b628d2ebf9051db692f4.mp3", "duration_ms": 10160}, "s1-verdadero-falso.explanation": {"url": "http://localhost:4006/files/lesson-audio/4395a6b911574dcc0cc3810f76b16290f645fee545b8fdea0bb205fd1cab8776.mp3", "hash": "6f969815227936077b65a690f50c9e3240169e55c72bf3950addd9e7fbb4d2ed", "bytes": 71856, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/4395a6b911574dcc0cc3810f76b16290f645fee545b8fdea0bb205fd1cab8776.mp3", "duration_ms": 11920}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'en-US', '1', E'{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "cause-effect", "title": "Cause and effect at the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Connect causes and effects at the stand: sunny day → more thirst → more cups sold; doubling the price → fewer customers."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cause-effect", "xp": 10, "type": "cause_effect", "hints": ["Think: when it''s hot, people are thirstier and buy more lemonade.", "If the price goes up a lot, some customers no longer buy."], "title": "What happened at the stand?", "payload": {"slots": 4, "events": [{"id": "e1", "text_md": "Monday: sunny and hot day"}, {"id": "e2", "text_md": "Tuesday: Liruf raises the price from 5 to 10 pesos"}, {"id": "e3", "text_md": "Monday: 8 cups sold"}, {"id": "e4", "text_md": "Tuesday: only 3 cups sold"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "On Monday it was very hot and Liruf sold 8 cups of lemonade at 5 pesos each. On Tuesday, Liruf thought: \\"If I double the price, I''ll earn twice as much.\\" He raised the price to 10 pesos, but only sold 3 cups. What happened? Help Rho connect each cause with its effect. Remember: Liruf already made a mistake before when adding 5+5+5 and thinking it was 20. Now he made a mistake again by thinking that raising the price always gives more money!", "difficulty": 1, "explanation_md": "On Monday, with heat, he sold 8 cups. On Tuesday, after doubling the price, he only sold 3. Liruf thought he would earn twice as much, but he forgot that with a high price he sells less. Just like when he added 5+5+5 wrong!", "audio_segment_id": "s1-cause-effect.prompt"}], "schema_version": 1}', '{"s1-cause-effect": {"chain": ["e1", "e3", "e2", "e4"]}}', '{"units": {"s1-cause-effect.hint.0": {"url": "http://localhost:4006/files/lesson-audio/31bb5f2c01976702dd0d277a59d68d5583a440ba8985051c3a0fddf8ab27e1aa.mp3", "hash": "19377a54b7ac4a55ba54f041a0ac399ce8fa3323309ae56d77cedc7d74231dba", "bytes": 22464, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/31bb5f2c01976702dd0d277a59d68d5583a440ba8985051c3a0fddf8ab27e1aa.mp3", "duration_ms": 3680}, "s1-cause-effect.hint.1": {"url": "http://localhost:4006/files/lesson-audio/03998211d3263a48b33c7659afb5c64b48bbd69488783fd9a11992d88d4d08f7.mp3", "hash": "d6d724bc2ab04732e990e4668ff01ff54610933fd2c85273fb27ed81a1d71f15", "bytes": 21456, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/03998211d3263a48b33c7659afb5c64b48bbd69488783fd9a11992d88d4d08f7.mp3", "duration_ms": 3520}, "s1-cause-effect.prompt": {"url": "http://localhost:4006/files/lesson-audio/88872526c9026619e0eb086e0d02e04d2bcff45eb24659ba3cc9422883febb99.mp3", "hash": "79179d1f0a07bf833f75a7c09554bf88b0d9566d3acb9ac06cd46b9310b418ac", "bytes": 158688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/88872526c9026619e0eb086e0d02e04d2bcff45eb24659ba3cc9422883febb99.mp3", "duration_ms": 26400}, "s1-cause-effect.explanation": {"url": "http://localhost:4006/files/lesson-audio/c61fff68bd01e3a02b4bd6c529b3ca9f5ceb73ac23f14d2a2b666639983d4ad2.mp3", "hash": "94d22ff2377c3b68c046555fdd7bba6e60db66a667a9b67d11f05ec569767e57", "bytes": 85824, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c61fff68bd01e3a02b4bd6c529b3ca9f5ceb73ac23f14d2a2b666639983d4ad2.mp3", "duration_ms": 14240}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "interest-peek", "title": "O cofrinho que agradece a paciência", "locale": "pt-BR", "subject": "money", "objectives": ["Decidir se deixar dinheiro em um cofrinho que dá moedinhas extras toda semana vale mais do que gastá-lo agora.", "Prever o total depois de esperar, entendendo que cresce um pouco, mas não dobra."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 10, "type": "interest_peek", "hints": ["Cada semana o cofrinho dá 2 moedas de 1 real. Quantas moedas extras ele dá em 2 semanas?", "Começa com 20. Soma as moedinhas extras."], "title": "Deixar os 20 ou tirá-los agora?", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 20, "prediction": {"kind": "choice", "options": [{"id": "opt1", "text_md": "Fica em 20"}, {"id": "opt2", "text_md": "24 reais"}, {"id": "opt3", "text_md": "Quase 40 reais"}]}}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf tem 20 reais guardados para um violão que custa 80. Rho diz: ''Se você guardar seu dinheiro neste cofrinho especial, toda semana ele te dá 2 moedas de 1 real extra por deixá-lo lá.'' Liruf coloca seus 20 reais. Ele pensa: ''Se eu esperar 2 semanas, terei mais ou menos do que se gastar tudo agora?'' Quanto Liruf terá depois de 2 semanas?", "difficulty": 1, "explanation_md": "O cofrinho dá 2 moedas de 1 real por semana, então em 2 semanas dá 4 reais extras. 20 + 4 = 24. O dinheiro cresce pouquinho a pouquinho em direção ao violão! Se tivesse gasto tudo agora, não teria esses 4 reais extras.", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 24, "tolerance": 1, "correct_option_id": "opt2"}}', '{"units": {"s1-interest-peek.hint.0": {"url": "http://localhost:4006/files/lesson-audio/15c8d42a81e76e915fe3887eff8a429983acd363dc96705d1e4ec0e628271e2c.mp3", "hash": "196538f34b2819eb47de5903748f77e7b49d10d4e2c8ca5d7ae70a964f276120", "bytes": 41184, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/15c8d42a81e76e915fe3887eff8a429983acd363dc96705d1e4ec0e628271e2c.mp3", "duration_ms": 6800}, "s1-interest-peek.hint.1": {"url": "http://localhost:4006/files/lesson-audio/94246887ec011f654238fff79533392c4fa267c9a6a7176754cf81c2c0fba8f2.mp3", "hash": "68205f29a78766e858fb87c5bed3698e0edd3e76f3e3815689d9c9fdf3bf0983", "bytes": 21024, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/94246887ec011f654238fff79533392c4fa267c9a6a7176754cf81c2c0fba8f2.mp3", "duration_ms": 3440}, "s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/8d2446827b5dfe079ef7c4af2f81ab70d70f224adcc231c88e5428650ba17a0e.mp3", "hash": "a49d13c1d700898ab76f3de6d66edef95a7a3fc75e1a1d6b73c925bba2331ffd", "bytes": 152064, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8d2446827b5dfe079ef7c4af2f81ab70d70f224adcc231c88e5428650ba17a0e.mp3", "duration_ms": 25280}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/502978ab8beb65b2716a40ddd32d3108471507f848c1584c75807ed5a8039f28.mp3", "hash": "10d7c733f96ddee36b970195711bac0efc7e1d2b84b73366148a2065d5f44a1a", "bytes": 110736, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/502978ab8beb65b2716a40ddd32d3108471507f848c1584c75807ed5a8039f28.mp3", "duration_ms": 18400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "speed-tap", "title": "Grab what helps!", "locale": "en-US", "subject": "money", "objectives": ["Distinguish expenses that help the lemonade stand from treats that don''t."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 10, "type": "speed_tap", "hints": ["Think: does this help make or sell lemonade?", "Lemons, cups, sugar, ice, and a sign help. Stickers, candy, and toys do not."], "title": "Grab what helps!", "payload": {"items": [{"id": "limones", "text_md": "More lemons"}, {"id": "vasos", "text_md": "Bag of cups"}, {"id": "azucar", "text_md": "Sugar"}, {"id": "hielo", "text_md": "Ice"}, {"id": "cartel", "text_md": "Eye-catching sign"}, {"id": "calcomania", "text_md": "Dinosaur sticker"}, {"id": "dulce", "text_md": "Candy"}, {"id": "juguete", "text_md": "Toy"}], "seconds": 15, "instruction_md": "Tap the cards that help the lemonade stand. Quick!"}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho flies past shopping cards. Tap only those that help sell MORE lemonade. Let the treats pass!", "difficulty": 1, "explanation_md": "Lemons, cups, sugar, ice, and a sign let you sell more lemonade. The sticker, candy, and toy are treats that don''t help the stand.", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["limones", "vasos", "azucar", "hielo", "cartel"]}}', '{"units": {"s1-speed-tap.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c927042b881e642a45e44538f5a18138e288514221e7e007382b82e752e62839.mp3", "hash": "7b5cd823d44c18768fd6c6eee908f50ddc0ac55be238d6b0df47cab8eab4d2a7", "bytes": 23328, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/c927042b881e642a45e44538f5a18138e288514221e7e007382b82e752e62839.mp3", "duration_ms": 3840}, "s1-speed-tap.hint.1": {"url": "http://localhost:4006/files/lesson-audio/9a74994a47b1c8d2289a929a291955def2dd9baaf8c4d1cc606d333e5314aacb.mp3", "hash": "f0908f128b68a285cc8866125ee982df59908c78f1d9c6342f74436541a4b107", "bytes": 41184, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/9a74994a47b1c8d2289a929a291955def2dd9baaf8c4d1cc606d333e5314aacb.mp3", "duration_ms": 6800}, "s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/d8b77b8fb7b6d6b4454d5cdcd20571dd5cf09e5f4a17394d8ad2ebeeb5eccbc3.mp3", "hash": "c1894a25972c56c4e59abb53ba3508b74aceff11fcc4e0d520e9f2d36a39373d", "bytes": 44928, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/d8b77b8fb7b6d6b4454d5cdcd20571dd5cf09e5f4a17394d8ad2ebeeb5eccbc3.mp3", "duration_ms": 7440}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/273e4cabc26cef9196532a14908c31c1940a17d8aa09c90cf38f7f3689f28050.mp3", "hash": "9352f2473c87def8341228fb42662a7711d78fd5a1718b010dffc738deb9e6ab", "bytes": 59328, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/273e4cabc26cef9196532a14908c31c1940a17d8aa09c90cf38f7f3689f28050.mp3", "duration_ms": 9840}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'es-MX', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "code-order", "title": "Construye la registradora de cartón", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar las instrucciones de la registradora casera: recibir pago, verificar monto, dar cambio, anotar la venta."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-registradora", "xp": 10, "type": "code_order", "hints": ["¿Qué haces primero cuando alguien te paga?", "Después de recibir el dinero, ¿qué debes revisar para no dar cambio de más?"], "title": "La registradora de cartón", "payload": {"blocks": [{"id": "recibir", "text_md": "Recibir pago"}, {"id": "verificar", "text_md": "Verificar monto"}, {"id": "dar_cambio", "text_md": "Dar cambio"}, {"id": "anotar", "text_md": "Anotar la venta"}], "language_hint": "Ordena los pasos de la registradora."}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "La semana pasada elegiste entre ganar 10 pesos hoy o 20 después. Hoy, Rho ya tiene una venta: Dina compra un cuaderno de 12 pesos y paga con un billete de 20. Rho sabe que debe dar 8 de cambio. Pero si se salta un paso, ¡puede dar 10 en vez de 8 y perder dinero! Ayuda a Rho a ordenar los pasos para no equivocarse. Toca los bloques en el orden correcto.", "difficulty": 1, "explanation_md": "El orden correcto es: recibir pago, verificar monto, dar cambio, anotar la venta. Si Rho verifica primero el monto, sabe cuánto cambio dar. Si anota antes de dar cambio, puede confundirse y dar mal el cambio. Si pusiste ''anotar'' antes de ''dar cambio'', Rho podría dar 10 en vez de 8 y perder 2 pesos. ¡Así Rho no pierde dinero!", "audio_segment_id": "s1-ordenar-registradora.prompt"}], "schema_version": 1}', '{"s1-ordenar-registradora": {"order": ["recibir", "verificar", "dar_cambio", "anotar"]}}', '{"units": {"s1-ordenar-registradora.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2828bc557a57584bdd34016f627919f335fd8511498704a1e6d8792a7972368c.mp3", "hash": "3b7bcc805ff3de42938c7203c1bae550840e629d8e0556f983b5285a060c713e", "bytes": 14256, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/2828bc557a57584bdd34016f627919f335fd8511498704a1e6d8792a7972368c.mp3", "duration_ms": 2320}, "s1-ordenar-registradora.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c46b7a19f6c9071ab25b50e35209e7eea00eea55011c9fffd105fefeb7004c4b.mp3", "hash": "3e190b0d251cb07b7dfa48902cf3396af7e9be7851453010633a0ab7381dd306", "bytes": 29088, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/c46b7a19f6c9071ab25b50e35209e7eea00eea55011c9fffd105fefeb7004c4b.mp3", "duration_ms": 4800}, "s1-ordenar-registradora.prompt": {"url": "http://localhost:4006/files/lesson-audio/9eab10cd22ee9bfba9d42f3c5948fb04d7c9d2ee9449779569a48070b4a089f3.mp3", "hash": "9621cebef18ad20af1284dac9fda0802c2e945b27bb6aba6c8da9015bb19a15b", "bytes": 160704, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/9eab10cd22ee9bfba9d42f3c5948fb04d7c9d2ee9449779569a48070b4a089f3.mp3", "duration_ms": 26720}, "s1-ordenar-registradora.explanation": {"url": "http://localhost:4006/files/lesson-audio/42cfd3e0d208eab6ccc431575949e18da473b854382cfbc0c5d7abc6277da089.mp3", "hash": "35119f4139540ce29c25f6c1c4179c12f31007784829d687e0bbcb71e2fb8172", "bytes": 152928, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/42cfd3e0d208eab6ccc431575949e18da473b854382cfbc0c5d7abc6277da089.mp3", "duration_ms": 25440}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'es-MX', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "read-chart", "title": "Lee la gráfica de ventas", "locale": "es-MX", "subject": "mixed", "objectives": ["Leer la gráfica de barras de vasos vendidos por día y responder cuál fue el mejor día de la semana."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 10, "type": "read_chart", "hints": ["Busca la barra más alta en la gráfica.", "Cada barra muestra cuántos vasos se vendieron ese día."], "title": "El mejor día de Zara", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Vasos vendidos", "points": [{"x": "Lunes", "y": 3}, {"x": "Martes", "y": 5}, {"x": "Miércoles", "y": 4}, {"x": "Jueves", "y": 6}, {"x": "Viernes", "y": 8}]}]}, "questions": [{"id": "q-best-day", "options": [{"id": "lunes", "text_md": "Lunes"}, {"id": "martes", "text_md": "Martes"}, {"id": "miercoles", "text_md": "Miércoles"}, {"id": "jueves", "text_md": "Jueves"}, {"id": "viernes", "text_md": "Viernes"}], "prompt_md": "¿Cuál día vendió más vasos de limonada?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Zara quiere saber qué día venderá más limonada la próxima semana para pedir suficientes limones. Como elegiste al mejor proveedor de limones, ahora ayúdala a encontrar el mejor día usando su gráfica de ventas de esta semana. ¿Cuál día vendió más vasos?", "difficulty": 1, "explanation_md": "El viernes la barra llega hasta 8, que es más alto que los otros días. ¡Ese fue el mejor día! Zara pedirá más limones para el viernes.", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q-best-day": "viernes"}}}', '{"units": {"s1-read-chart.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c3ac25d500f6d0311a1abc5cdd523183fe68c5aab7f54cf801ac99d73508647b.mp3", "hash": "bfdb9c0120c6a82572ee8e159298a98a33b84fb24917140fbed5417fd8494614", "bytes": 15264, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c3ac25d500f6d0311a1abc5cdd523183fe68c5aab7f54cf801ac99d73508647b.mp3", "duration_ms": 2480}, "s1-read-chart.hint.1": {"url": "http://localhost:4006/files/lesson-audio/bf2929109082bfce23c20d8d395084b91327fe681908e768b58bb4076a3851cb.mp3", "hash": "e7f491464ef776dd9a8a28b6fc710d6590f405a5043a603ade9b7c99d44532a8", "bytes": 22464, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/bf2929109082bfce23c20d8d395084b91327fe681908e768b58bb4076a3851cb.mp3", "duration_ms": 3680}, "s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/c984da99bffd095fb947039a2e3c32a58808e6709329b8ff223a6c801358eb18.mp3", "hash": "cd029c97db095055aeabe84c4eae67a9db65c1550555d00ab8bf2c69aa6c54f3", "bytes": 95904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c984da99bffd095fb947039a2e3c32a58808e6709329b8ff223a6c801358eb18.mp3", "duration_ms": 15920}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/a84ece7aba09288941257da463d3846a779ae15931f0f3dbe699ee9abcf0fc4c.mp3", "hash": "cdc6737014506c24bc96c19409fe2ac717bff9cc2c7f8f5b0f37ba4ef4c97ba3", "bytes": 56016, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a84ece7aba09288941257da463d3846a779ae15931f0f3dbe699ee9abcf0fc4c.mp3", "duration_ms": 9280}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "concept-reveal", "title": "Cost and profit", "locale": "en-US", "subject": "mixed", "objectives": ["Identify that cost is what you spend to make the product", "Identify that profit is what you have left after paying the cost"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": [], "title": "Cost and profit", "payload": {"cards": [{"icon": "receipt_long", "back_md": "What you spend to make the product: lemons, sugar, cups.", "front_md": "Cost"}, {"icon": "savings", "back_md": "What you have left after subtracting the cost from what you sold.", "front_md": "Profit"}]}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Liruf wants to save for an 80-peso skateboard. He sold 10 glasses of lemonade at 5 pesos each. He spent 2 pesos on lemons and sugar per glass. Can he buy the skateboard with what he has left?", "difficulty": 1, "explanation_md": "Liruf earned 50 pesos from selling 10 glasses. But he spent 20 pesos on lemons and sugar (cost). What he has left is the profit: 50 - 20 = 30 pesos. He still needs 50 more pesos for the skateboard!", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/417e1eca5ce8215528c13c8cb75d88ef73a02e0b1b8a06cc37c926eba5e187ae.mp3", "hash": "94543b3a152bc01c55b641bccab1d4a3021c57e2b5a7396d55f2fb6e447e7a27", "bytes": 85248, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/417e1eca5ce8215528c13c8cb75d88ef73a02e0b1b8a06cc37c926eba5e187ae.mp3", "duration_ms": 14160}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/d3eb0a26857a389a27976c68a2963c8477b1b55a4ec2149501091a20c1a43935.mp3", "hash": "bf163850ed5ba172cb238280ea7dfdcb2279837b6c2e32187b7e029b0cbfe8d9", "bytes": 27216, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/d3eb0a26857a389a27976c68a2963c8477b1b55a4ec2149501091a20c1a43935.mp3", "duration_ms": 4480}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/16b96c5e0fae7fab19b4cf6c1823e54153a78a5ae71df9df49af0ac346bfa58a.mp3", "hash": "a62387fa72d4d6e8ffea332593a2bd6cdf27ffc117e0b697e11fa8ef3a933b92", "bytes": 27216, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/16b96c5e0fae7fab19b4cf6c1823e54153a78a5ae71df9df49af0ac346bfa58a.mp3", "duration_ms": 4480}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/514d91b77c0ee44a0442e556e6f0bc7a14204bcbd14dbc81adba8985924c5d7b.mp3", "hash": "b75cc537be18847bc6686bab0a57b67b0d49dc6a7b0965f56f3178194df7b4c4", "bytes": 86256, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/514d91b77c0ee44a0442e556e6f0bc7a14204bcbd14dbc81adba8985924c5d7b.mp3", "duration_ms": 14320}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "concept-reveal", "title": "Custo e lucro", "locale": "pt-BR", "subject": "mixed", "objectives": ["Identificar que o custo é o que você gasta para fazer o produto", "Identificar que o lucro é o que sobra depois de pagar o custo"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": [], "title": "Custo e lucro", "payload": {"cards": [{"icon": "receipt_long", "back_md": "O que você gasta para fazer o produto: limões, açúcar, copos.", "front_md": "Custo"}, {"icon": "savings", "back_md": "O que sobra depois de subtrair o custo do que você vendeu.", "front_md": "Lucro"}]}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Liruf quer economizar para um skate de 80 pesos. Vendeu 10 copos de limonada a 5 pesos cada. Gastou 2 pesos em limões e açúcar por copo. Ele consegue comprar o skate com o que sobra?", "difficulty": 1, "explanation_md": "Liruf ganhou 50 pesos vendendo 10 copos. Mas gastou 20 pesos em limões e açúcar (custo). O que sobra é o lucro: 50 - 20 = 30 pesos. Ainda faltam 50 pesos para o skate!", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/b9211035021813bd648f45b8073679f5a4c85be8e662e7ca0753301915103d00.mp3", "hash": "07db82c1441bfd72bc4ebcadfb6326d507098067a8e4670e238fe8be17a85626", "bytes": 85248, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/b9211035021813bd648f45b8073679f5a4c85be8e662e7ca0753301915103d00.mp3", "duration_ms": 14160}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/4bc1a483a468b76e61ebe85a58a4ef0e34d9e284ebeaffbcd9629a1d93e12e7f.mp3", "hash": "17b13b7d6b88c99ec271e6c89aaf884b2d3c4231a454ac6136e2f43cf7d64071", "bytes": 32544, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/4bc1a483a468b76e61ebe85a58a4ef0e34d9e284ebeaffbcd9629a1d93e12e7f.mp3", "duration_ms": 5360}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/6f1f2c3540091e28baf5bea0c3fea1061701e78ad05f8b66e5df93e907c42b0b.mp3", "hash": "1bc0cb692ff8883110434bc9135bb2162f3ea964ca13355c8eb05a593a3bcc68", "bytes": 23328, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/6f1f2c3540091e28baf5bea0c3fea1061701e78ad05f8b66e5df93e907c42b0b.mp3", "duration_ms": 3840}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/ff605562b3be5aeefc06b84af866d07689af5dda91ac9ae8d25e419bc8b70a7b.mp3", "hash": "22eeff41e380aa6b92d5e1b2ab7f6f0fcf29090a910c34aff4db7968f6878d5b", "bytes": 83808, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/ff605562b3be5aeefc06b84af866d07689af5dda91ac9ae8d25e419bc8b70a7b.mp3", "duration_ms": 13920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "speed-tap", "title": "Pegue o que ajuda!", "locale": "pt-BR", "subject": "money", "objectives": ["Distinguir gastos que ajudam a barraca de limonada de caprichos que não."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 10, "type": "speed_tap", "hints": ["Pense: isso ajuda a fazer ou vender limonada?", "Limões, copos, açúcar, gelo e placa ajudam. Adesivos, doces e brinquedos não."], "title": "Pegue o que ajuda!", "payload": {"items": [{"id": "limones", "text_md": "Mais limões"}, {"id": "vasos", "text_md": "Saco de copos"}, {"id": "azucar", "text_md": "Açúcar"}, {"id": "hielo", "text_md": "Gelo"}, {"id": "cartel", "text_md": "Placa chamativa"}, {"id": "calcomania", "text_md": "Adesivo de dinossauro"}, {"id": "dulce", "text_md": "Doce"}, {"id": "juguete", "text_md": "Brinquedo"}], "seconds": 15, "instruction_md": "Toque nos cartões que ajudam a barraca de limonada. Rápido!"}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho passa voando cartões de compras. Toque apenas nos que ajudam a vender MAIS limonada. Deixe passar os caprichos!", "difficulty": 1, "explanation_md": "Limões, copos, açúcar, gelo e placa fazem com que você possa vender mais limonada. O adesivo, o doce e o brinquedo são caprichos que não ajudam a barraca.", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["limones", "vasos", "azucar", "hielo", "cartel"]}}', '{"units": {"s1-speed-tap.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f2b6bf3fa1dde0f1b6e56b57846db1b9edadf46a6941dd883fab1e9648e002c5.mp3", "hash": "645def84edd1185cdbd851d0dca18b00d2b3c23ee3f4456994719952c73a0791", "bytes": 23328, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/f2b6bf3fa1dde0f1b6e56b57846db1b9edadf46a6941dd883fab1e9648e002c5.mp3", "duration_ms": 3840}, "s1-speed-tap.hint.1": {"url": "http://localhost:4006/files/lesson-audio/526d6faa6a5ef29a6660671c8da1707d11e0f0fee92745c53e2522f8ab4ef796.mp3", "hash": "6a6c8406759f3048de8e66143ce008583349ec18bdd98eae63e3af8aa0f9ea35", "bytes": 46368, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/526d6faa6a5ef29a6660671c8da1707d11e0f0fee92745c53e2522f8ab4ef796.mp3", "duration_ms": 7680}, "s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/1f129ca611c6f80774623c6d51a2d5817118473007c7dcc95dec700bc85815d3.mp3", "hash": "28ab59cde6ca6b3c629dac3d529cebbcac364516d1c7dd99063cad3b45dfaabb", "bytes": 54144, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/1f129ca611c6f80774623c6d51a2d5817118473007c7dcc95dec700bc85815d3.mp3", "duration_ms": 8960}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/a7920c840811ae689d8c8c3e6cbd07c4a710934ee2029c0e5927680f39773987.mp3", "hash": "38d75271172839f8f00433229bcecc0fb5a7616bdba3d5ee9133e035cda6eea1", "bytes": 74736, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/a7920c840811ae689d8c8c3e6cbd07c4a710934ee2029c0e5927680f39773987.mp3", "duration_ms": 12400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "pattern-complete", "title": "The Cup Ladder", "locale": "en-US", "subject": "mixed", "objectives": ["Order steps, match products with prices, and sort purchases between stall needs and treats that can wait."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-escalera", "xp": 15, "type": "pattern_complete", "hints": ["Look at the pattern: small, medium, large, small… what size comes after large?", "The ladder goes up in price: bigger costs more. Which is the most expensive of the three?"], "title": "Which cup goes here?", "payload": {"options": [{"id": "chico", "icon": "water_drop", "tint": "primary"}, {"id": "mediano", "icon": "water_drop", "tint": "accent"}, {"id": "grande", "icon": "water_drop", "tint": "success"}], "sequence": [{"icon": "water_drop", "tint": "primary"}, {"icon": "water_drop", "tint": "accent"}, {"icon": "water_drop", "tint": "success"}, {"icon": "water_drop", "tint": "primary"}, {"icon": "water_drop", "tint": "accent"}, {"icon": "water_drop", "tint": "success"}], "missing_slots": 1}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Yesterday Zara bought lemons, made lemonade, sold it, and saved the earnings. Today she prepares the cups for tomorrow. She arranges them like this: small ($5), medium ($10), large ($15), and then again small, medium, large… so customers can see that bigger costs more. But she left a gap. Which cup goes in the empty spot so the ladder keeps going up?", "difficulty": 2, "explanation_md": "After the large cup ($15) comes the small cup ($5) again, because the ladder starts over. That way customers see that bigger costs more and can choose what they can afford. If you chose ''large'', you thought it kept going up, but the ladder repeats. If you chose ''medium'', you confused the order of the cycle.", "audio_segment_id": "s1-escalera.prompt"}], "schema_version": 1}', '{"s1-escalera": {"correct": {"0": "chico"}}}', '{"units": {"s1-escalera.hint.0": {"url": "http://localhost:4006/files/lesson-audio/06a1731dbd66cf030aa9151684d72a3798d00c1f0b6abae1740d1c57e9663882.mp3", "hash": "e800f201cdd40eaa8ca126c8e84dcb992210fc499a15cb2eca2b04683ee3fdcb", "bytes": 38736, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/06a1731dbd66cf030aa9151684d72a3798d00c1f0b6abae1740d1c57e9663882.mp3", "duration_ms": 6400}, "s1-escalera.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7ca862ea7784542e746f0f9eed4042a39139424cfabc3495f34fc3d06ac04396.mp3", "hash": "e75ee155f6677d00799863edfa60a5631c2ba1113f4e50f25454beab47895915", "bytes": 35424, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/7ca862ea7784542e746f0f9eed4042a39139424cfabc3495f34fc3d06ac04396.mp3", "duration_ms": 5840}, "s1-escalera.prompt": {"url": "http://localhost:4006/files/lesson-audio/663d80fb5e9d561e5785faa00d3f04ec050e18928358c310933a089832da93dd.mp3", "hash": "549ec5d36cb72742d122349f04c15be63cad937d01998f64b0caa0c142a3fc5f", "bytes": 150048, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/663d80fb5e9d561e5785faa00d3f04ec050e18928358c310933a089832da93dd.mp3", "duration_ms": 24960}, "s1-escalera.explanation": {"url": "http://localhost:4006/files/lesson-audio/ac92486c26b9744935f87c30ef6c8622ceb957e491ad75b7d384cd4e1fe5ea97.mp3", "hash": "695af6e408a1f655aa85375e3817db2e3e35dc7a21d059203ffe82589b9fdfba", "bytes": 125136, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/ac92486c26b9744935f87c30ef6c8622ceb957e491ad75b7d384cd4e1fe5ea97.mp3", "duration_ms": 20800}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-arrange-largo", "title": "Close the stand: all mixed up", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate the correct change for each payment in a real sale.", "Order the steps to calculate profit: set aside the cost first.", "Separate stand needs from expenses that can wait.", "Order the day''s events so the cash box never runs out of change."], "estimated_minutes": 12}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-cambio", "xp": 15, "type": "match_pairs", "hints": ["Remember: change = payment - price. If they paid 10 for a 5-peso glass, how much is left?", "Calculate how much 2 glasses cost if someone bought 2."], "title": "Match each payment with its change", "payload": {"left": [{"id": "pago10", "text_md": "Pays with 10 pesos for 1 glass"}, {"id": "pago20", "text_md": "Pays with 20 pesos for 2 glasses"}, {"id": "pago6", "text_md": "Pays with 6 pesos for 1 glass"}], "right": [{"id": "cambio5", "text_md": "Change: 5 pesos"}, {"id": "cambio10", "text_md": "Change: 10 pesos"}, {"id": "cambio1", "text_md": "Change: 1 peso"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Yesterday you closed the stand and counted the coins for the 80-peso guitar. Today Liruf sells 3 glasses of lemonade. Each glass costs 5 pesos. Match each payment with the change you need to give the customer.", "difficulty": 2, "explanation_md": "If they paid 10 for a 5-peso glass, the change is 5. If they paid 20 for two glasses (10), the change is 10. If they paid 6 for a 5-peso glass, the change is 1.", "audio_segment_id": "s1-match-cambio.prompt"}, {"id": "s2-order-ganancia", "xp": 15, "type": "order_steps", "hints": ["First, you need to set aside what it cost to make the lemonade.", "After subtracting the cost, what''s left is the profit."], "title": "Order how to find the profit", "payload": {"items": [{"id": "restar-costo", "text_md": "Subtract the cost of ingredients (12 pesos)"}, {"id": "contar-venta", "text_md": "Count all the money from sales (25 pesos)"}, {"id": "resultado-ganancia", "text_md": "The result is the profit (13 pesos)"}], "slots": 3}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina sold lemonade today. She spent 12 pesos on lemons and cups, and collected 25 pesos from sales. Help Dina order the steps to find out how much she really earned. If she doesn''t do it right, she won''t know if she can afford the 80-peso guitar.", "difficulty": 2, "explanation_md": "First, count all the money from sales (25 pesos). Then subtract the cost of ingredients (12 pesos). The result (13 pesos) is the profit. That''s how Dina knows how much she adds to the guitar fund!", "audio_segment_id": "s2-order-ganancia.prompt"}, {"id": "s3-sort-necesidades", "xp": 15, "type": "sort_buckets", "hints": ["Think: without this, can the stand not sell lemonade?", "What is urgent to open goes in ''Needs'', the rest in ''Can wait''."], "title": "Separate what the stand needs", "payload": {"items": [{"id": "limones", "text_md": "Lemons (8 pesos)"}, {"id": "vasos", "text_md": "Cups (6 pesos)"}, {"id": "hielo", "text_md": "Ice (4 pesos)"}, {"id": "calcomania", "text_md": "Sticker for the stand (2 pesos)"}], "buckets": [{"id": "necesita", "label": "Needs to open"}, {"id": "esperar", "label": "Can wait"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "You have 20 pesos to spend tomorrow. Separate each expense into what the stand NEEDS to open and what CAN WAIT.", "difficulty": 2, "explanation_md": "Lemons and cups are necessary to sell. Ice and a sticker can wait another day.", "audio_segment_id": "s3-sort-necesidades.prompt"}, {"id": "s4-timeline-cambio", "xp": 25, "type": "timeline_order", "hints": ["Before spending money, make sure a sale with a large bill comes in.", "If you spend change before receiving it, you''ll run out of coins."], "title": "Arrange the day so you don''t run out of change", "payload": {"events": [{"id": "venta50", "icon": "payments", "text_md": "Customer pays with a 50-peso bill for 2 glasses"}, {"id": "compra-vasos", "icon": "shopping_cart", "text_md": "Buy more cups (spend 10 pesos)"}, {"id": "venta20", "icon": "payments", "text_md": "Customer pays with a 20-peso bill for 1 glass"}, {"id": "compra-hielo", "icon": "local_cafe", "text_md": "Buy ice (spend 8 pesos)"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina needs the cash box to always have coins for change. Order these events in the correct order so that change never runs out.", "difficulty": 3, "explanation_md": "First, a sale with a 50-peso bill comes in, that gives change. Then buy more cups. Then another sale with a 20-peso bill gives more change. Finally, buy ice.", "audio_segment_id": "s4-timeline-cambio.prompt"}], "schema_version": 1}', '{"s1-match-cambio": {"pairs": [["pago10", "cambio5"], ["pago20", "cambio10"], ["pago6", "cambio1"]]}, "s2-order-ganancia": {"order": ["contar-venta", "restar-costo", "resultado-ganancia"]}, "s4-timeline-cambio": {"order": ["venta50", "compra-vasos", "venta20", "compra-hielo"]}, "s3-sort-necesidades": {"assignments": {"hielo": "esperar", "vasos": "necesita", "limones": "necesita", "calcomania": "esperar"}}}', '{"units": {"s1-match-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3add7dc2ca24ac9fc9d9b22ab5847d33636268c2c5d79b5e37226484a04fd43c.mp3", "hash": "c57194d6e4959f85a611c5d0a4197585f2d62a5acc64a6ca364cf8c3d691f636", "bytes": 38736, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/3add7dc2ca24ac9fc9d9b22ab5847d33636268c2c5d79b5e37226484a04fd43c.mp3", "duration_ms": 6400}, "s1-match-cambio.hint.1": {"url": "http://localhost:4006/files/lesson-audio/06eea2d57cb78c7a389864a39b788802a1a4e6fe60f30f31b34e788c9c538ff4.mp3", "hash": "2f84365c097e12454c9f771852d432b6b04253b8723eb4a41ada292e0a7432bf", "bytes": 21888, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/06eea2d57cb78c7a389864a39b788802a1a4e6fe60f30f31b34e788c9c538ff4.mp3", "duration_ms": 3600}, "s1-match-cambio.prompt": {"url": "http://localhost:4006/files/lesson-audio/89499325e3e8e232127c4ee427cfb71477a9721d32f3d06bd1f2f9bb2f351862.mp3", "hash": "2f7db153723b4b427b7fd4a20e69b5c73261675f1e99e21903015e0a62b59db8", "bytes": 80064, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/89499325e3e8e232127c4ee427cfb71477a9721d32f3d06bd1f2f9bb2f351862.mp3", "duration_ms": 13280}, "s2-order-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/badc312343e7d5ee8727ef4df844c215d85634221520e3c3a9f3a7a005898acc.mp3", "hash": "3ccb83ed558c8383feb37fadf088991be3082a0465e8b34cf123e31d337e8bdb", "bytes": 20016, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/badc312343e7d5ee8727ef4df844c215d85634221520e3c3a9f3a7a005898acc.mp3", "duration_ms": 3280}, "s2-order-ganancia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f691d01161e0dde57a50b6b524a138a6131b2ac2e2aada0e3da154a28451376f.mp3", "hash": "058ef4968210b4d63ac2a357c5d220cb55e5c6b76b12613465480a2ad128b5bc", "bytes": 17568, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f691d01161e0dde57a50b6b524a138a6131b2ac2e2aada0e3da154a28451376f.mp3", "duration_ms": 2880}, "s2-order-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/7b72a8e152752f0dc071c363730f92e2fa66e05232c9dd3b67e7f0d5e14445ee.mp3", "hash": "b37bd998c5c24fd2980c390154a523b555356a72cac1cc37909f6d8166309761", "bytes": 81936, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/7b72a8e152752f0dc071c363730f92e2fa66e05232c9dd