wen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/028bd1cfd3158865233359e1a9cdd2fb6b6dd23347924a400aa6c9e1b0093661.mp3", "duration_ms": 4000}, "s3-sort-necesidades.prompt": {"url": "http://localhost:4006/files/lesson-audio/555be86ac5aa2fa632e86290a440ab91fd11e69a4e71852e451abe0eebe9a4d5.mp3", "hash": "49d7cdc96ccbb791f2018b685632243e14728b5c3b7a8f15258d4c80b6e0c96d", "bytes": 41616, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/555be86ac5aa2fa632e86290a440ab91fd11e69a4e71852e451abe0eebe9a4d5.mp3", "duration_ms": 6880}, "s1-match-cambio.explanation": {"url": "http://localhost:4006/files/lesson-audio/69175b41a0d9f3d1a2876b6ba6982df78534691703eea702755486bb9c563f0d.mp3", "hash": "ce84b2620e7a27f198b44e7bd4a1777452bfe55129f5281bb3de8f49aee49563", "bytes": 67968, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/69175b41a0d9f3d1a2876b6ba6982df78534691703eea702755486bb9c563f0d.mp3", "duration_ms": 11280}, "s2-order-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/f1034c001d0f5ae64e6148d7180d60d38746ef4572d0596298f1d74ca6e4b76e.mp3", "hash": "9abba338af53b1e82b0fc0a38696486a6f39b2a621734cdc967e397a02829494", "bytes": 75744, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f1034c001d0f5ae64e6148d7180d60d38746ef4572d0596298f1d74ca6e4b76e.mp3", "duration_ms": 12560}, "s4-timeline-cambio.explanation": {"url": "http://localhost:4006/files/lesson-audio/24171a7999e45026b64aea43f64581d106dd289c7231bbca9014e654444648c0.mp3", "hash": "16b40931dd69906bcfa41cdfb2ef7585c4d0396e2c0cae2ddefbc21973a78547", "bytes": 57456, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/24171a7999e45026b64aea43f64581d106dd289c7231bbca9014e654444648c0.mp3", "duration_ms": 9520}, "s3-sort-necesidades.explanation": {"url": "http://localhost:4006/files/lesson-audio/a087d9da9631b690a82c02fea92e8955b846d011a57bcc179279814e19b577e8.mp3", "hash": "28126d4f6b06c24ac82cc90578c087aed76b1f4f9bd7bed44c70b1bc2f52a60f", "bytes": 29088, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/a087d9da9631b690a82c02fea92e8955b846d011a57bcc179279814e19b577e8.mp3", "duration_ms": 4800}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "lightning-round", "title": "Rodada relâmpago na hora do rush", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular o troco correto para clientes que pedem 1-3 copos de 5 pesos e pagam com 10 ou 20 pesos", "Aplicar a estratégia: primeiro soma os copos, depois subtrai do pagamento"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lightning", "xp": 15, "type": "lightning_round", "hints": ["Primeiro soma quanto custam todos os copos (cada copo custa 5 pesos).", "Depois subtrai esse total da nota com que o cliente paga."], "title": "Troco na hora!", "payload": {"questions": [{"id": "q1", "options": [{"id": "q1a", "text_md": "10 pesos"}, {"id": "q1b", "text_md": "5 pesos"}, {"id": "q1c", "text_md": "15 pesos"}, {"id": "q1d", "text_md": "20 pesos"}], "prompt_md": "Dona Rosa: 2 copos, paga com 20 pesos. Quanto troco você dá?"}, {"id": "q2", "options": [{"id": "q2a", "text_md": "5 pesos"}, {"id": "q2b", "text_md": "10 pesos"}, {"id": "q2c", "text_md": "0 pesos"}, {"id": "q2d", "text_md": "1 peso"}], "prompt_md": "Seu Toño: 1 copo, paga com 10 pesos. Quanto troco você dá?"}, {"id": "q3", "options": [{"id": "q3a", "text_md": "5 pesos"}, {"id": "q3b", "text_md": "10 pesos"}, {"id": "q3c", "text_md": "15 pesos"}, {"id": "q3d", "text_md": "20 pesos"}], "prompt_md": "Mari: 3 copos, paga com 20 pesos. Quanto troco você dá?"}, {"id": "q4", "options": [{"id": "q4a", "text_md": "15 pesos"}, {"id": "q4b", "text_md": "10 pesos"}, {"id": "q4c", "text_md": "5 pesos"}, {"id": "q4d", "text_md": "20 pesos"}], "prompt_md": "Seu Luís: 1 copo, paga com 20 pesos. Quanto troco você dá?"}, {"id": "q5", "options": [{"id": "q5a", "text_md": "0 pesos"}, {"id": "q5b", "text_md": "5 pesos"}, {"id": "q5c", "text_md": "10 pesos"}, {"id": "q5d", "text_md": "2 pesos"}], "prompt_md": "Vovó Chole: 2 copos, paga com 10 pesos. Quanto troco você dá?"}], "seconds_per_q": 15}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "A fila vai até a esquina! Zara canta os pedidos e você é Liruf: deve dar o troco antes que o relógio toque. Cada acerto coloca uma moeda no pote da guitarra de 80 pesos. Pronto? Lembre-se: poupar é guardar dinheiro, como no cofrinho que você viu antes. Aqui cada troco que você der certo é como uma moeda que você poupa para a guitarra!", "difficulty": 2, "explanation_md": "O truque é: soma os copos (2 copos × 5 pesos = 10 pesos) e subtrai do pagamento (20 - 10 = 10 pesos de troco).", "audio_segment_id": "s1-lightning.prompt"}], "schema_version": 1}', '{"s1-lightning": {"correct": {"q1": "q1a", "q2": "q2a", "q3": "q3a", "q4": "q4a", "q5": "q5a"}}}', '{"units": {"s1-lightning.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7d8dcbdaed0c4c216239d2a8b4bcdcb50b4ae5a23998ba4208db77104bb5addd.mp3", "hash": "baffb6f41c9626e940bb8ad21d17a34ce01410e986a74e27646a5d7e719952c3", "bytes": 33984, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7d8dcbdaed0c4c216239d2a8b4bcdcb50b4ae5a23998ba4208db77104bb5addd.mp3", "duration_ms": 5600}, "s1-lightning.hint.1": {"url": "http://localhost:4006/files/lesson-audio/642ee75962a8d7a49af130234f394b5ff34a0415782f48c3f96e2b838c3e9d14.mp3", "hash": "421d6537b235a36e44dac6fb6678c0b71f6a83e59e5a70901c5a5d59c2ebef3c", "bytes": 26784, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/642ee75962a8d7a49af130234f394b5ff34a0415782f48c3f96e2b838c3e9d14.mp3", "duration_ms": 4400}, "s1-lightning.prompt": {"url": "http://localhost:4006/files/lesson-audio/b9cdf050dc434f0e512a3df2829d10332cc18cd26d10c6078a4a9478d58722f0.mp3", "hash": "0dda86f4ee25f3e983b2ad78ae65b76e791a0253c5fdbc62dd2d86b8c337bd6c", "bytes": 142848, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b9cdf050dc434f0e512a3df2829d10332cc18cd26d10c6078a4a9478d58722f0.mp3", "duration_ms": 23760}, "s1-lightning.explanation": {"url": "http://localhost:4006/files/lesson-audio/279154c0ddb6024af9a4b96bfb83a708b9b5b0a4f669bfbd7fc19d5792f88482.mp3", "hash": "7a4766d86f7c6ab1fdd8266fbdcc0dcf001ce6e1f336fc87eccd9658c077146d", "bytes": 63648, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/279154c0ddb6024af9a4b96bfb83a708b9b5b0a4f669bfbd7fc19d5792f88482.mp3", "duration_ms": 10560}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'pt-BR', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "true-false", "title": "Verdadeiro ou falso? A poupança que cresce", "locale": "pt-BR", "subject": "mixed", "objectives": ["Decida se é verdadeiro ou falso: ''Se eu guardar 5 reais de cada venda, minha poupança CRESCE a cada dia''."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Pense: se você guarda 5 reais a cada dia, a quantia total aumenta ou fica igual?", "Imagine que hoje você guarda 5, amanhã mais 5... você tem mais ou menos do que ontem?"], "title": "Pegue a frase", "payload": {"statement_md": "Se eu guardar 5 reais de cada venda, minha poupança CRESCE a cada dia.", "justifications": [{"id": "crece", "text_md": "É verdadeiro, porque a cada dia você adiciona mais 5 reais ao total."}, {"id": "no-crece", "text_md": "É falso, porque a poupança fica sempre igual."}]}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Zara diz: ''Se eu guardar 5 reais de cada venda, minha poupança CRESCE a cada dia''. Liruf precisa decidir se é verdadeiro ou falso. O que você acha?", "difficulty": 1, "explanation_md": "É verdadeiro. Se você guarda 5 reais a cada dia, o total da sua poupança aumenta. Por exemplo, na segunda você tem 5, na terça 10, na quarta 15... cresce a cada dia!", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "crece"}}', '{"units": {"s1-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a49b47bb53ca1891ccd050eaf52bdbd51f053ca2ba5b362a5750ac09062423c4.mp3", "hash": "68e85437071edad1c865320bcf6a873071d44e75cb9013863b63ba5419cffd8d", "bytes": 39744, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/a49b47bb53ca1891ccd050eaf52bdbd51f053ca2ba5b362a5750ac09062423c4.mp3", "duration_ms": 6560}, "s1-true-false.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0f992f2119ba72e9957d3071c5703b01d01b2fa50aabb733598e1c7f0ff7a493.mp3", "hash": "0348f2061fac0f0d78c5e436d31d8a1e6209562045925b54d443988ace48350e", "bytes": 37728, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/0f992f2119ba72e9957d3071c5703b01d01b2fa50aabb733598e1c7f0ff7a493.mp3", "duration_ms": 6240}, "s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/9986faa8c2c26b61b9a1291aad8e208140a5b36f249bfffb104800e210ad263f.mp3", "hash": "35ae8931fff193d525d87757f396342c1aa1bae77d69dc76411f1ed43c4490e6", "bytes": 67104, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/9986faa8c2c26b61b9a1291aad8e208140a5b36f249bfffb104800e210ad263f.mp3", "duration_ms": 11120}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/a4de12f2683cb8c3a6fabb182bc783ffb06eeb11d1d60a8e4e7713ebb61ec468.mp3", "hash": "b7a745eecf01e12aa882b842cc35d2f7faf9c3ad0c91019e86fa1f3306801e06", "bytes": 78048, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/a4de12f2683cb8c3a6fabb182bc783ffb06eeb11d1d60a8e4e7713ebb61ec468.mp3", "duration_ms": 12960}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "needs-wants", "title": "Needs and wants at the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Separate needs for the lemon and ice stand from personal wants like a lollipop or comic."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 10, "type": "needs_wants", "hints": ["Think: without this, can the stand make lemonade?", "What Liruf wants for fun is a want, not a need for the stand."], "title": "The stand eats first", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Lemons"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Ice"}, {"id": "paleta", "icon": "icecream", "text_md": "Strawberry lollipop"}, {"id": "comic", "icon": "menu_book", "text_md": "Superhero comic"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf earned 10 pesos and already set aside 5 for his guitar. The other 5 are to restock ingredients. Help Dina decide: which purchases are for the stand (need) and which are for Liruf (want)? Tap each item and place it in the correct category.", "difficulty": 1, "explanation_md": "Lemons and ice are needs for the stand because without them there is no lemonade. The lollipop and comic are Liruf''s wants, not urgent for the business.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["limones", "hielo"]}}', '{"units": {"s1-needs-wants.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a13e08c3e21a346ffea0474877db28200fd7cc1445fc7e9f3d9cab0c6e13dbc9.mp3", "hash": "0a9a9d76469ce7bd6d2b86e7fbd967eb737ea1c6d0dfa57fbfd57d78b2097778", "bytes": 16704, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a13e08c3e21a346ffea0474877db28200fd7cc1445fc7e9f3d9cab0c6e13dbc9.mp3", "duration_ms": 2720}, "s1-needs-wants.hint.1": {"url": "http://localhost:4006/files/lesson-audio/14e0fe2a4b699174c4cbcfb9b8b97bb17cda0459325b62df62dc0f6d58112f1a.mp3", "hash": "0b1f8cf69d8f7e347d8e8716480211561c21b5f7c7597decf482fd3a7a540155", "bytes": 21456, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/14e0fe2a4b699174c4cbcfb9b8b97bb17cda0459325b62df62dc0f6d58112f1a.mp3", "duration_ms": 3520}, "s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/ee53a2cc83d2e58ed1bb419fab9a8f0319de301a7b76883ca3912f467a0840a7.mp3", "hash": "b683eb02c652956e724870bede0158e7688bedc389fdf4e23089b90cebeb47e3", "bytes": 82368, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ee53a2cc83d2e58ed1bb419fab9a8f0319de301a7b76883ca3912f467a0840a7.mp3", "duration_ms": 13680}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/61f33c2ea297063e1287d63de6142fb75e6bbd774e95cb5cfa4dfa0c7b01911b.mp3", "hash": "f9e56005ee5cc0a7e39c7ba521eeecbdee9ef295a3c8edff2ab90a536cb93322", "bytes": 48816, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/61f33c2ea297063e1287d63de6142fb75e6bbd774e95cb5cfa4dfa0c7b01911b.mp3", "duration_ms": 8080}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "checkpoint", "title": "A noite antes de abrir", "locale": "pt-BR", "subject": "mixed", "objectives": ["Revisar a meta do violão de 80 pesos, o preço da limonada a 5 reais o copo, e que o lucro é o que sobra depois de pagar o custo.", "Fechar com um gancho emocional: quão perto você sente o violão?"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "hints": [], "title": "A noite antes de abrir", "payload": {"recap_md": "A meta está colada na parede: violão, 80 pesos. O cartaz da limonada diz 5 reais o copo. E o segredo que aprenderam: de cada copo, o que sobra depois do custo é o lucro que empurra o pote para os 80.", "mood_prompt_md": "Liruf olha o pote vazio e sorri. Dina pergunta: ''quão perto você já sente esse violão?''"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina senta ao lado de Liruf e seu pote vazio do violão. Em vez de uma prova, apontam as três coisas que já estão prontas.", "difficulty": 1, "explanation_md": "Liruf respira: a ideia já não é só um sonho, amanhã é testada de verdade.", "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/43e349e2fbc7baa3a590a629fc17280a8feef1bb3ecc81eb8e754550926c6268.mp3", "hash": "751612d1caa1773a2052660394600a5817276f7ff571bbe8a33210788828ee62", "bytes": 92448, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/43e349e2fbc7baa3a590a629fc17280a8feef1bb3ecc81eb8e754550926c6268.mp3", "duration_ms": 15360}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/4f8fb3ad53a09a2881a8cc12c2993012a0779fe6b59cf4921a0b3ce56609b461.mp3", "hash": "ba7ae769f1d85155cfda2341984719deb28a2bae0e0f840c8d21d7d842a80204", "bytes": 55008, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4f8fb3ad53a09a2881a8cc12c2993012a0779fe6b59cf4921a0b3ce56609b461.mp3", "duration_ms": 9120}, "s1-checkpoint.explanation": {"url": "http://localhost:4006/files/lesson-audio/cb70651e13c4156e177f632520a3d325e6acc7f26fca899a9e1e9d67b2930dc4.mp3", "hash": "d8b8364f7291b422d4ab212157d562a5ab37cc1abb9a0937ce5838cb33d7943e", "bytes": 38304, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/cb70651e13c4156e177f632520a3d325e6acc7f26fca899a9e1e9d67b2930dc4.mp3", "duration_ms": 6320}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-arrange-largo", "title": "Cerrar el puesto: todo revuelto", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular el cambio correcto para cada pago en una venta real.", "Ordenar los pasos para calcular la ganancia: apartar el costo primero.", "Separar necesidades del puesto de gastos que pueden esperar.", "Ordenar eventos del día para que la caja nunca se quede sin cambio."], "estimated_minutes": 12}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-cambio", "xp": 15, "type": "match_pairs", "hints": ["Recuerda: cambio = pago - precio. Si pagaron 10 por un vaso de 5, ¿cuánto sobra?", "Calcula cuánto cuestan 2 vasos si alguien compró 2."], "title": "Empareja cada pago con su cambio", "payload": {"left": [{"id": "pago10", "text_md": "Paga con 10 pesos por 1 vaso"}, {"id": "pago20", "text_md": "Paga con 20 pesos por 2 vasos"}, {"id": "pago6", "text_md": "Paga con 6 pesos por 1 vaso"}], "right": [{"id": "cambio5", "text_md": "Cambio: 5 pesos"}, {"id": "cambio10", "text_md": "Cambio: 10 pesos"}, {"id": "cambio1", "text_md": "Cambio: 1 peso"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Ayer cerraste el puesto y contaste las monedas para la guitarra de 80 pesos. Hoy Liruf vende 3 vasos de limonada. Cada vaso cuesta 5 pesos. Empareja cada pago con el cambio que hay que darle al cliente.", "difficulty": 2, "explanation_md": "Si pagaron 10 por un vaso de 5, el cambio es 5. Si pagaron 20 por dos vasos (10), el cambio es 10. Si pagaron 6 por un vaso de 5, el cambio es 1.", "audio_segment_id": "s1-match-cambio.prompt"}, {"id": "s2-order-ganancia", "xp": 15, "type": "order_steps", "hints": ["Primero hay que apartar lo que costó hacer la limonada.", "Después de restar el costo, lo que sobra es la ganancia."], "title": "Ordena cómo sacar la ganancia", "payload": {"items": [{"id": "restar-costo", "text_md": "Restar el costo de los ingredientes (12 pesos)"}, {"id": "contar-venta", "text_md": "Contar todo el dinero de las ventas (25 pesos)"}, {"id": "resultado-ganancia", "text_md": "El resultado es la ganancia (13 pesos)"}], "slots": 3}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina vendió limonada hoy. Gastó 12 pesos en limones y vasos, y juntó 25 pesos de las ventas. Ayuda a Dina a ordenar los pasos para saber cuánto ganó realmente. Si no lo hace bien, no sabrá si alcanza para la guitarra de 80 pesos.", "difficulty": 2, "explanation_md": "Primero se cuenta todo el dinero de las ventas (25 pesos). Luego se resta el costo de los ingredientes (12 pesos). El resultado (13 pesos) es la ganancia. ¡Así Dina sabe cuánto suma para la guitarra!", "audio_segment_id": "s2-order-ganancia.prompt"}, {"id": "s3-sort-necesidades", "xp": 15, "type": "sort_buckets", "hints": ["Piensa: ¿sin esto el puesto no puede vender limonada?", "Lo que es urgente para abrir va en ''Necesita'', lo demás en ''Puede esperar''."], "title": "Separa lo que el puesto necesita", "payload": {"items": [{"id": "limones", "text_md": "Limones (8 pesos)"}, {"id": "vasos", "text_md": "Vasos (6 pesos)"}, {"id": "hielo", "text_md": "Hielo (4 pesos)"}, {"id": "calcomania", "text_md": "Calcomanía para el puesto (2 pesos)"}], "buckets": [{"id": "necesita", "label": "Necesita para abrir"}, {"id": "esperar", "label": "Puede esperar"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Tienes 20 pesos para gastar mañana. Separa cada gasto en lo que el puesto NECESITA para abrir y lo que PUEDE ESPERAR.", "difficulty": 2, "explanation_md": "Los limones y los vasos son necesarios para vender. El hielo y la calcomanía pueden esperar otro día.", "audio_segment_id": "s3-sort-necesidades.prompt"}, {"id": "s4-timeline-cambio", "xp": 25, "type": "timeline_order", "hints": ["Antes de gastar dinero, asegúrate de que entre una venta con billete grande.", "Si gastas cambio antes de recibirlo, te quedas sin monedas."], "title": "Acomoda el día para no quedarte sin cambio", "payload": {"events": [{"id": "venta50", "icon": "payments", "text_md": "Cliente paga con billete de 50 por 2 vasos"}, {"id": "compra-vasos", "icon": "shopping_cart", "text_md": "Comprar más vasos (gastar 10 pesos)"}, {"id": "venta20", "icon": "payments", "text_md": "Cliente paga con billete de 20 por 1 vaso"}, {"id": "compra-hielo", "icon": "local_cafe", "text_md": "Comprar hielo (gastar 8 pesos)"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina necesita que la caja siempre tenga monedas para dar cambio. Ordena estos eventos en el orden correcto para que nunca falte cambio.", "difficulty": 3, "explanation_md": "Primero llega una venta con billete de 50, eso da cambio. Luego se compran más vasos. Después otra venta con billete de 20 da más cambio. Al final se compra hielo.", "audio_segment_id": "s4-timeline-cambio.prompt"}], "schema_version": 1}', '{"s1-match-cambio": {"pairs": [["pago10", "cambio5"], ["pago20", "cambio10"], ["pago6", "cambio1"]]}, "s2-order-ganancia": {"order": ["contar-venta", "restar-costo", "resultado-ganancia"]}, "s4-timeline-cambio": {"order": ["venta50", "compra-vasos", "venta20", "compra-hielo"]}, "s3-sort-necesidades": {"assignments": {"hielo": "esperar", "vasos": "necesita", "limones": "necesita", "calcomania": "esperar"}}}', '{"units": {"s1-match-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/05a867774ece91b609d3153ed4f1000e6c7a3b62e57edd8499e50010e2bacd61.mp3", "hash": "591c86da1004f1c463b198b73a202c22ad9ef4c8a96523862030fd60e8d65fd6", "bytes": 49824, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/05a867774ece91b609d3153ed4f1000e6c7a3b62e57edd8499e50010e2bacd61.mp3", "duration_ms": 8240}, "s1-match-cambio.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6da6c225df1bc1f5cec55a1f0af06241a5557358d463f80fdac733a08bcd7190.mp3", "hash": "46344789e1b7545021fd885bf9b43c5202b7ce50c917bffa564fa7b47326f4f8", "bytes": 25344, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/6da6c225df1bc1f5cec55a1f0af06241a5557358d463f80fdac733a08bcd7190.mp3", "duration_ms": 4160}, "s1-match-cambio.prompt": {"url": "http://localhost:4006/files/lesson-audio/b1f55f11a2643a9cee50b4ac7c7499bb6572d444008f975624383b8e2de5205a.mp3", "hash": "a9b5d095b3d601a791d722686e534ea1922c000cd99a9fd460fb59eda54ca7c6", "bytes": 88128, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/b1f55f11a2643a9cee50b4ac7c7499bb6572d444008f975624383b8e2de5205a.mp3", "duration_ms": 14640}, "s2-order-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3553edbe3c018602374df9df1353d693cf6cb68c6cea772ba3fc32c6bbcaa5fc.mp3", "hash": "327979549544768fdb85756d917fd365e4976962333316ab684973d6d8daef0d", "bytes": 23328, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3553edbe3c018602374df9df1353d693cf6cb68c6cea772ba3fc32c6bbcaa5fc.mp3", "duration_ms": 3840}, "s2-order-ganancia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/8b7b346c89d31c5bfea6b73bd72104eb50c4511f721a31680fd6ba0fb6eab968.mp3", "hash": "fe7fd618cf5ee45bd724f027dc6ea725807bb2c61b8fd7c386d4a4f729d4719b", "bytes": 22896, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8b7b346c89d31c5bfea6b73bd72104eb50c4511f721a31680fd6ba0fb6eab968.mp3", "duration_ms": 3760}, "s2-order-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/aecf144a81676a57fca85ccd9303ddf2b03f46ee932a80f76ad1f19ace13457a.mp3", "hash": "7c0a632d7703420fd559c6431640fb322e3d5e31f89e61f35538b523958bccba", "bytes": 102528, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/