es/lesson-audio/0c29532384db0d99901692ea26faf8196b2fbbb66095c4d238cee21daee49782.mp3", "hash": "209798f305b73ceb51f29c3dda7a836700f4cb1e3017113f14644339d13242b3", "bytes": 47376, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/0c29532384db0d99901692ea26faf8196b2fbbb66095c4d238cee21daee49782.mp3", "duration_ms": 7840}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "quiz-mcq", "title": "Fair price for lemonade", "locale": "en-US", "subject": "mixed", "objectives": ["Choosing the fair price for a glass of lemonade (5 pesos) among exaggerated options"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-justo", "xp": 10, "type": "quiz_mcq", "hints": ["Think: if the glass costs 5 pesos, a fair price should be a little more, but not too much."], "title": "How much per glass?", "payload": {"options": [{"id": "a", "text_md": "5 pesos", "rationale_md": "5 pesos gives no profit, you only recover the cost. You wouldn''t save anything!"}, {"id": "b", "text_md": "8 pesos", "rationale_md": "8 pesos is fair: you earn 3 pesos per glass and customers pay a reasonable price."}, {"id": "c", "text_md": "20 pesos", "rationale_md": "20 pesos is too expensive. Customers won''t pay that much and you won''t sell anything."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Breathe and review: you already have a goal (80 pesos), a product (lemonade at 5 pesos), and you know what cost and profit are. How do you feel about opening the stand? Liruf is ready. But you have to decide the price. If you set the glass at 5 pesos, you earn nothing. If you set it at 20 pesos, no one will buy from you. What is a fair price that gives you profit without scaring away customers?", "difficulty": 1, "explanation_md": "Exactly! 8 pesos is fair: you earn 3 pesos per glass (8 - 5 = 3) and customers pay a reasonable price. That way you can save for your skateboard!", "audio_segment_id": "s1-precio-justo.prompt"}], "schema_version": 1}', '{"s1-precio-justo": {"correct_option_id": "b"}}', '{"units": {"s1-precio-justo.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3a8e30860c124abe8a41ac600fabbc2c6ffcbbf456acd9e33003390e84f82da4.mp3", "hash": "f06f28b6a3f2e3b46b25f47de22bfc6fb4ce0f8083515c72daa45d891c32e61c", "bytes": 33408, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3a8e30860c124abe8a41ac600fabbc2c6ffcbbf456acd9e33003390e84f82da4.mp3", "duration_ms": 5520}, "s1-precio-justo.prompt": {"url": "http://localhost:4006/files/lesson-audio/08387aba3d0f81b763857fd333a7060a0da0a4859f2c2d750671c28905086f14.mp3", "hash": "32c9341775aceb85e65d7ebf482727311495884dac9ac8252d0d3bbd4af2b8bb", "bytes": 126144, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/08387aba3d0f81b763857fd333a7060a0da0a4859f2c2d750671c28905086f14.mp3", "duration_ms": 20960}, "s1-precio-justo.choices": {"url": "http://localhost:4006/files/lesson-audio/235c6c6848c0009e81283d2ee8e4c322850dfd06fb4477a9275d165da74470e5.mp3", "hash": "7974e8111116b7dc35031a0ebf552ce1ded41113f3e16a3dc172140c8089b22c", "bytes": 16704, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/235c6c6848c0009e81283d2ee8e4c322850dfd06fb4477a9275d165da74470e5.mp3", "duration_ms": 2720}, "s1-precio-justo.explanation": {"url": "http://localhost:4006/files/lesson-audio/ae5612216cd24dd96fde07c81af93352e41cd642163a6887fd45089b23eddd27.mp3", "hash": "2839d747f194ae379ca97ae3cfb14e434e6224f059b0c5d0e54c798a284082e8", "bytes": 62784, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ae5612216cd24dd96fde07c81af93352e41cd642163a6887fd45089b23eddd27.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "memory-flip", "title": "Memória de preços", "locale": "pt-BR", "subject": "mixed", "objectives": ["Combine cada produto com as moedas que o pagam, usando os preços da barraca: biscoito = 3 (1+2), copo pequeno = 5, jarra grande = 20 (10+10)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 15, "type": "memory_flip", "hints": ["Lembre-se: o biscoito custa 3 reais (1+2), o copo pequeno 5, e a jarra grande 20 (10+10).", "Comece pelo produto que você mais gravar, como a jarra grande."], "title": "Combine produto com pagamento", "payload": {"pairs": [{"a_md": "Biscoito", "b_md": "1 real + 2 reais", "a_icon": "cookie", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/f5a1a4c517a764ec6ad5f59cae029f3222fd4b9c04e44d7073736b16b7ee365a.png", "b_image_url": "http://localhost:4006/files/lesson-images/8c3c67a376252975b4c478669bab607afea5c567924decdcea06b59bf76b53ca.png"}, {"a_md": "Copo pequeno", "b_md": "5 reais", "a_icon": "water_drop", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/9c2554b55b4f8c6172080092ad2678065e4ac126528ebccede5e31e28c73cd02.png", "b_image_url": "http://localhost:4006/files/lesson-images/3d638591fe3f5eadcbc1422e300c240bd68c5efdd68781c7083fc2656a030430.png"}, {"a_md": "Jarra grande", "b_md": "10 reais + 10 reais", "a_icon": "local_bar", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/1505f1edb40c0e20b38e5475fb8b3e8da17d002a2110551094cdf7ababadf90b.png", "b_image_url": "http://localhost:4006/files/lesson-images/a65bbe49b6aaf3c524ba61399a47c55a25ba5e23b4e2b8d27f2f54d529399f65.png"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Toque nas cartas para encontrar cada produto com as moedas que o pagam. Ganha quem lembrar os preços mais rápido!", "difficulty": 2, "explanation_md": "Cada produto tem um preço exato: biscoito 3 reais (1+2), copo pequeno 5 reais, jarra grande 20 reais (10+10). Combiná-los ajuda a cobrar sem erros.", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c251c35e9afc4fe1f9845e0a61ad98d4aba536fbb19d2047353463b08d5315bb.mp3", "hash": "1bef3135150d2e46894f819237d2e91f1522e54ec60cb2a0b697f9dedc95ca31", "bytes": 53136, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/c251c35e9afc4fe1f9845e0a61ad98d4aba536fbb19d2047353463b08d5315bb.mp3", "duration_ms": 8800}, "s1-memory-flip.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6ebcee32fd5badc6bb064b8d5bfdc6919f642d149f09edeb8dd3ce13b3f95cab.mp3", "hash": "634d2098bbf26cedf97c9d3895e321f1e66c5c1706899ccec80dcc788790be36", "bytes": 26784, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/6ebcee32fd5badc6bb064b8d5bfdc6919f642d149f09edeb8dd3ce13b3f95cab.mp3", "duration_ms": 4400}, "s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/4aa469dcfb54bb4cb20eed883fe6f779ac978b27008acdd9ebf4fadd8b239bdc.mp3", "hash": "521bb7f8debb0063e7db177f07ffd223e8eb222937c48da37c2403c1291323eb", "bytes": 42048, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/4aa469dcfb54bb4cb20eed883fe6f779ac978b27008acdd9ebf4fadd8b239bdc.mp3", "duration_ms": 6960}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/f3b258d8aa23df7a1117468f2181c45d6c27c1953c7f8f303615efdff9dabad1.mp3", "hash": "56f6e61d80e9acae99bdf67f9d3223ed25be85faf2cc07c1a402e9b4b916cc89", "bytes": 76608, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/f3b258d8aa23df7a1117468f2181c45d6c27c1953c7f8f303615efdff9dabad1.mp3", "duration_ms": 12720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "lightning-round", "title": "Ronda relámpago en la hora pico", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular el cambio correcto para clientes que piden 1-3 vasos de 5 pesos y pagan con 10 o 20 pesos", "Aplicar la estrategia: primero suma los vasos, luego resta del pago"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lightning", "xp": 15, "type": "lightning_round", "hints": ["Primero suma cuánto cuestan todos los vasos (cada vaso cuesta 5 pesos).", "Luego resta ese total del billete con que paga el cliente."], "title": "¡Cambio al vuelo!", "payload": {"questions": [{"id": "q1", "options": [{"id": "q1a", "text_md": "10 pesos"}, {"id": "q1b", "text_md": "5 pesos"}, {"id": "q1c", "text_md": "15 pesos"}, {"id": "q1d", "text_md": "20 pesos"}], "prompt_md": "Doña Rosa: 2 vasos, paga con 20 pesos. ¿Cuánto cambio le das?"}, {"id": "q2", "options": [{"id": "q2a", "text_md": "5 pesos"}, {"id": "q2b", "text_md": "10 pesos"}, {"id": "q2c", "text_md": "0 pesos"}, {"id": "q2d", "text_md": "1 peso"}], "prompt_md": "Don Toño: 1 vaso, paga con 10 pesos. ¿Cuánto cambio le das?"}, {"id": "q3", "options": [{"id": "q3a", "text_md": "5 pesos"}, {"id": "q3b", "text_md": "10 pesos"}, {"id": "q3c", "text_md": "15 pesos"}, {"id": "q3d", "text_md": "20 pesos"}], "prompt_md": "Mari: 3 vasos, paga con 20 pesos. ¿Cuánto cambio le das?"}, {"id": "q4", "options": [{"id": "q4a", "text_md": "15 pesos"}, {"id": "q4b", "text_md": "10 pesos"}, {"id": "q4c", "text_md": "5 pesos"}, {"id": "q4d", "text_md": "20 pesos"}], "prompt_md": "Don Luis: 1 vaso, paga con 20 pesos. ¿Cuánto cambio le das?"}, {"id": "q5", "options": [{"id": "q5a", "text_md": "0 pesos"}, {"id": "q5b", "text_md": "5 pesos"}, {"id": "q5c", "text_md": "10 pesos"}, {"id": "q5d", "text_md": "2 pesos"}], "prompt_md": "Abuela Chole: 2 vasos, paga con 10 pesos. ¿Cuánto cambio le das?"}], "seconds_per_q": 15}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "¡La fila llega hasta la esquina! Zara canta los pedidos y tú eres Liruf: debes dar el cambio antes de que suene el reloj. Cada acierto pone una moneda en el frasco de la guitarra de 80 pesos. ¿Listo? Recuerda: ahorrar es guardar dinero, como en la alcancía que viste antes. ¡Aquí cada cambio que des bien es como una moneda que ahorras para la guitarra!", "difficulty": 2, "explanation_md": "El truco es: suma los vasos (2 vasos × 5 pesos = 10 pesos) y resta del pago (20 - 10 = 10 pesos de cambio).", "audio_segment_id": "s1-lightning.prompt"}], "schema_version": 1}', '{"s1-lightning": {"correct": {"q1": "q1a", "q2": "q2a", "q3": "q3a", "q4": "q4a", "q5": "q5a"}}}', '{"units": {"s1-lightning.hint.0": {"url": "http://localhost:4006/files/lesson-audio/880cacdf8b036681fac77489f46fd96b3e8e13f0c4bb7ac8d7eca03e3603b45f.mp3", "hash": "c420407434ea88761fbac24af96f9d27de54bb9aff2f330ba9ebb937bcf92cd5", "bytes": 33408, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/880cacdf8b036681fac77489f46fd96b3e8e13f0c4bb7ac8d7eca03e3603b45f.mp3", "duration_ms": 5520}, "s1-lightning.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2ff3bf0da038f7cc039ec598cd5593141c9fc1ee87bf42534316c9a65adb59dc.mp3", "hash": "f230e9598807f6fa68f40eab0577adacdc26cee05ac72b3734960df8ac7c5270", "bytes": 23904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2ff3bf0da038f7cc039ec598cd5593141c9fc1ee87bf42534316c9a65adb59dc.mp3", "duration_ms": 3920}, "s1-lightning.prompt": {"url": "http://localhost:4006/files/lesson-audio/4db972c06d808048e25a7ce8b395308ac028fb7826a54958b89c61c6f5f105ea.mp3", "hash": "05ffc7353c46d6868fcb560ceb8123b501cc8f3b0d7f51b0f327f2dc59cf16aa", "bytes": 137088, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4db972c06d808048e25a7ce8b395308ac028fb7826a54958b89c61c6f5f105ea.mp3", "duration_ms": 22800}, "s1-lightning.explanation": {"url": "http://localhost:4006/files/lesson-audio/b89ab02013441d947e2aa0128dd5dc1ea5f53107c61af814a5a2bc5b14221de6.mp3", "hash": "0469fa7176b6c0ac37f6728e734e638f91bba39163ce588ede257a4d3cade309", "bytes": 61344, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b89ab02013441d947e2aa0128dd5dc1ea5f53107c61af814a5a2bc5b14221de6.mp3", "duration_ms": 10160}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "checkpoint", "title": "The Night Before Opening", "locale": "en-US", "subject": "mixed", "objectives": ["Review the goal of the 80-peso guitar, the lemonade price of 5 pesos per cup, and that profit is what''s left after paying the cost.", "Close with an emotional hook: how close does the guitar feel?"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "hints": [], "title": "The Night Before Opening", "payload": {"recap_md": "The goal is taped to the wall: guitar, 80 pesos. The lemonade sign says 5 pesos per cup. And the secret they learned: from each cup, what''s left after the cost is the profit that pushes the jar toward 80.", "mood_prompt_md": "Liruf looks at the empty jar and smiles. Dina asks him: ''How close do you already feel that guitar?''"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina sits next to Liruf and his empty guitar jar. Instead of a test, they point to the three things already ready.", "difficulty": 1, "explanation_md": "Liruf breathes: the idea is no longer just a dream, tomorrow it gets tested for real.", "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/5ea0c0796fb302fd82146d2b49525c5a86333fc9ea0ef5a3007350eee6b8a1c5.mp3", "hash": "47c6f9cd46e5b195216a8e2f02beacfc8c04d7028b047782c051f02c44aaf616", "bytes": 70848, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5ea0c0796fb302fd82146d2b49525c5a86333fc9ea0ef5a3007350eee6b8a1c5.mp3", "duration_ms": 11760}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/99d488d846cf631eb9449bc23edd70f44bbb469a9378cb4d6a0d16bdd9f281da.mp3", "hash": "f51d571ffde0f05e733e3b82bd5547fa8d2a3a65e28e67556c470617f3542b5a", "bytes": 38304, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/99d488d846cf631eb9449bc23edd70f44bbb469a9378cb4d6a0d16bdd9f281da.mp3", "duration_ms": 6320}, "s1-checkpoint.explanation": {"url": "http://localhost:4006/files/lesson-audio/10609b2641956da244a3710c14b839a69c7f7c887ab4252696731e13d7713d7c.mp3", "hash": "f696d9964dc7ef5632ac9bb113938e5491219acc719cec41a363d9ada782939b", "bytes": 32544, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/10609b2641956da244a3710c14b839a69c7f7c887ab4252696731e13d7713d7c.mp3", "duration_ms": 5360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "zara"], "slug": "build-sentence", "title": "O letreiro do combo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular o preço de 2 copos de limonada (2 × 5 = 10) para completar um letreiro de combo."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-combo-sign", "xp": 10, "type": "build_sentence", "hints": ["Pense: um copo custa 5, dois copos custam o dobro.", "Quanto é 5 mais 5?"], "title": "O letreiro do combo", "payload": {"slots": 5, "tokens": [{"id": "t1", "text_md": "2"}, {"id": "t2", "text_md": "copos"}, {"id": "t3", "text_md": "por"}, {"id": "t4", "text_md": "10"}, {"id": "t5", "text_md": "reais"}, {"id": "t6", "text_md": "5"}, {"id": "t7", "text_md": "15"}, {"id": "t8", "text_md": "20"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf já organizou seus gastos: primeiro os limões, depois os copos, depois os enfeites. Agora ele quer vender mais rápido e coloca um letreiro: **2 copos por ___ reais**. Cada copo custa 5 reais. Toque nas fichas em ordem para montar o letreiro correto. Se acertar, os clientes saberão o preço justo e Liruf venderá mais.", "difficulty": 1, "explanation_md": "Dois copos custam 10 reais porque cada copo vale 5: 5 + 5 = 10. Se você colocar 5, estaria dando um copo de graça. Se colocar 15 ou 20, os clientes acharão muito caro e não comprarão.", "audio_segment_id": "s1-combo-sign.prompt"}], "schema_version": 1}', '{"s1-combo-sign": {"order": ["t1", "t2", "t3", "t4", "t5"]}}', '{"units": {"s1-combo-sign.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b226fa75d63fb136b47bf79e885273023258e1a57747f6b483c6e3993a401323.mp3", "hash": "e00cfe54102f0d1d94898174c7db090503a022e4e83c1ec6c2878fd5a2e83ace", "bytes": 26784, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/b226fa75d63fb136b47bf79e885273023258e1a57747f6b483c6e3993a401323.mp3", "duration_ms": 4400}, "s1-combo-sign.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0f88832710d0b6f5bd27477965bf6105cb7f2215863aca418e2b26663313a4cc.mp3", "hash": "69e6d2124c663ad03f55e3f013e4687d81ad23944bbef2c701347f835aaf17e2", "bytes": 13248, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/0f88832710d0b6f5bd27477965bf6105cb7f2215863aca418e2b26663313a4cc.mp3", "duration_ms": 2160}, "s1-combo-sign.prompt": {"url": "http://localhost:4006/files/lesson-audio/3d67e341a16a3bc19f3afd5119bf0b6a3d73fed2c9d1d90a25c621a488553337.mp3", "hash": "6cd9e5f802c61a5c89bff035a313657712967d75a1e62d362cf0f317d805cd5f", "bytes": 143424, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/3d67e341a16a3bc19f3afd5119bf0b6a3d73fed2c9d1d90a25c621a488553337.mp3", "duration_ms": 23840}, "s1-combo-sign.explanation": {"url": "http://localhost:4006/files/lesson-audio/ef9fea7e55202844a4d81c14b8ab85d3927578231ce6d5123a7f43ba82180d8a.mp3", "hash": "90ae3587653a95eb47f7009b8688ffaf4dcd840cc687f0a4901ec49a65173eca", "bytes": 93456, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/ef9fea7e55202844a4d81c14b8ab85d3927578231ce6d5123a7f43ba82180d8a.mp3", "duration_ms": 15520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "budget-fit", "title": "Liruf''s Market", "locale": "en-US", "subject": "money", "objectives": ["Calculate the total needed items and remaining money", "Decide which extras fit in a 20-peso budget"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 15, "type": "budget_fit", "hints": ["First add the essentials: 8 + 6 = 14. You have 6 pesos left.", "Check the prices: ice 5, straws 3, pitcher 8. Which ones cost 6 or less?"], "title": "Fill the cart", "payload": {"items": [{"id": "limones", "icon": "nutrition", "need": true, "label": "Lemons", "price": 8}, {"id": "azucar", "icon": "bakery_dining", "need": true, "label": "Sugar", "price": 6}, {"id": "hielo", "icon": "ac_unit", "need": false, "label": "Ice", "price": 5}, {"id": "popotes", "icon": "local_drink", "need": false, "label": "Straws", "price": 3}, {"id": "jarra", "icon": "table_restaurant", "need": false, "label": "Pretty pitcher", "price": 8}], "budget": 20, "currency": "MXN", "must_buy_needs": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf has a **20-peso** bill. He must buy **lemons (8)** and **sugar (6)**. Without these, there''s no lemonade tomorrow. What else can he get without going over 20? Tap the ones that fit.", "difficulty": 2, "explanation_md": "Liruf spends 8+6=14 on essentials. He has 6 pesos left. Ice costs 5 and straws cost 3, together they add up to 8 (they don''t fit). Only ice (5) fits, or only straws (3). The pitcher costs 8, more than what''s left.", "audio_segment_id": "s1-budget-fit.prompt"}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{"units": {"s1-budget-fit.hint.0": {"url": "http://localhost:4006/files/lesson-audio/44cef9fe8c11bcda4c927b5e2bad9ef2ecc3387f95c56574cdfeb07e5ac86e17.mp3", "hash": "819851e9951804a9c23b238282187947f1380072662b2ecbb8e5c677ec82bd42", "bytes": 31536, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/44cef9fe8c11bcda4c927b5e2bad9ef2ecc3387f95c56574cdfeb07e5ac86e17.mp3", "duration_ms": 5200}, "s1-budget-fit.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c9f32873de523a67242d98b18ee56ef5b1a4c7a4411427ba8cad86d225c81b26.mp3", "hash": "69f3e9045c7383de117d7cb81529af8ba022a5077bf85bbd83d5ec5fa7626562", "bytes": 33408, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c9f32873de523a67242d98b18ee56ef5b1a4c7a4411427ba8cad86d225c81b26.mp3", "duration_ms": 5520}, "s1-budget-fit.prompt": {"url": "http://localhost:4006/files/lesson-audio/b6ecebba78d095eb6df14c81e5170dd454d3736d107d2010b4054835544c06ed.mp3", "hash": "f0c431c07ba832a1aa33317a977fc9b442e01200b0694d150bd13decc4c789e7", "bytes": 66096, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b6ecebba78d095eb6df14c81e5170dd454d3736d107d2010b4054835544c06ed.mp3", "duration_ms": 10960}, "s1-budget-fit.explanation": {"url": "http://localhost:4006/files/lesson-audio/3a0cd4e02d68f3b742754e2856c84a59be2db3a5f982eb3ae02681389ab7c3ff.mp3", "hash": "83dd8abf1c25996644b25110aaa25e8d8aa12da24c506cd71873a1bc43286072", "bytes": 95328, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3a0cd4e02d68f3b742754e2856c84a59be2db3a5f982eb3ae02681389ab7c3ff.mp3", "duration_ms": 15840}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'en-US', '1', E'{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "price-compare", "title": "Compare lemon prices", "locale": "en-US", "subject": "mixed", "objectives": ["Compare lemon prices at two market stalls and choose the cheapest to spend less (lower cost = more profit)."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 10, "type": "price_compare", "hints": ["Since both stalls sell the same number of lemons, just compare the total price. The cheaper one leaves you more money for the guitar."], "title": "Which stall is better?", "payload": {"offers": [{"id": "dina", "qty": 10, "unit": "limones", "label": "Dina''s Stall", "price": 12}, {"id": "rho", "qty": 10, "unit": "limones", "label": "Rho''s Stall", "price": 15}], "currency": "MXN"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf needs to buy lemons for his lemonade stand. Remember: first we buy what the stand needs, and we look for the best deal to spend less.\\n\\nAt the market, there are two stalls selling lemons:\\n- **Dina''s Stall**: 10 lemons for 12 pesos.\\n- **Rho''s Stall**: 10 lemons for 15 pesos.\\n\\nBoth sell the same number of lemons. Which stall has the lowest total price? Tap the one that saves you more money.", "difficulty": 1, "explanation_md": "Both stalls sell 10 lemons, but Dina''s stall costs 12 pesos and Rho''s costs 15 pesos. Buying from Dina''s stall saves you 3 pesos for the guitar goal. Choosing the cheapest deal is a way to spend less!", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "dina"}}', '{"units": {"s1-price-compare.hint.0": {"url": "http://localhost:4006/files/lesson-audio/75df1c3e32d37fe8e45115e23a957d69c6bdc3f0d5fdaf894725c5252ba6d7de.mp3", "hash": "36ff7833ad501caa4e6ee26a469cdf0fc3ef1c1e63365d81c59a999bd57d3334", "bytes": 38736, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/75df1c3e32d37fe8e45115e23a957d69c6bdc3f0d5fdaf894725c5252ba6d7de.mp3", "duration_ms": 6400}, "s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/00e838084212a49a855529c6e8898f683d9724178f03d577aa7ff22b1e68b027.mp3", "hash": "64478b83fb28e2676571d8489e4eb74874110e0c6383a4b37781ac3cc153ed3c", "bytes": 121824, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/00e838084212a49a855529c6e8898f683d9724178f03d577aa7ff22b1e68b027.mp3", "duration_ms": 20240}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/b93a25105921dd7e91023b4d69b4df1283d0d77299f3233090e0b8d2f14bcc9b.mp3", "hash": "3a5a89582afe1867b5e1c588f91c0f61aeca295eee1cbc6358c5675c143d7694", "bytes": 72288, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b93a25105921dd7e91023b4d69b4df1283d0d77299f3233090e0b8d2f14bcc9b.mp3", "duration_ms": 12000}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "Earning Money with an Idea", "locale": "en-US", "subject": "money", "objectives": ["Discovering that money can be earned by offering something others want", "Identifying that a clear goal helps to get started"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogue", "xp": 0, "type": "story_dialogue", "hints": [], "title": "Liruf''s Guitar", "payload": {"lines": [{"action": "idle", "emotion": "thinking", "text_md": "Oh, Dina... I want that 80-peso guitar, but I don''t have any money.", "character": "liruf"}, {"action": "idle", "emotion": "excited", "text_md": "What if you earn it yourself? You could sell lemonade in the neighborhood.", "character": "dina"}, {"action": "idle", "emotion": "surprised", "text_md": "Sell lemonade? And people would pay me?", "character": "liruf"}, {"action": "idle", "emotion": "encouraging", "text_md": "Of course! If you offer something others want, you can earn money. Each glass for 5 pesos.", "character": "dina"}, {"action": "idle", "emotion": "happy", "text_md": "Then I can save up the 80 pesos! I''m going to make lemonade!", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf wants a guitar that costs 80 pesos. How can she get it?", "difficulty": 1, "explanation_md": "Liruf discovered that she can earn money by selling lemonade for 5 pesos a glass, instead of just waiting for a gift.", "audio_segment_id": "s1-dialogue.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-dialogue.line.0": {"url": "http://localhost:4006/files/lesson-audio/26ecb9b08137f14eb4dfab3383747af4fa6124bfaa88f9fcfe2d6cd10114808a.mp3", "hash": "88c68e3c0190a5a8d737ecb7e1aa39f57728451c54b0846431f1090c332b21a1", "bytes": 29664, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/26ecb9b08137f14eb4dfab3383747af4fa6124bfaa88f9fcfe2d6cd10114808a.mp3", "duration_ms": 4880}, "s1-dialogue.line.1": {"url": "http://localhost:4006/files/lesson-audio/c6755c783ba22069f38164d9dd8525306b2268037031cfbe02f735a56c4af177.mp3", "hash": "c689bc0a291081fde52aefc33ff9df8ab35a1f9791168667276dbfa60fd11795", "bytes": 21024, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c6755c783ba22069f38164d9dd8525306b2268037031cfbe02f735a56c4af177.mp3", "duration_ms": 3440}, "s1-dialogue.line.2": {"url": "http://localhost:4006/files/lesson-audio/9b5bda4102ec47aca2e026f243c10f80d6bdb21773202ef30de92735735a5c07.mp3", "hash": "fc49f4753e4e49e09a7850b7c7e59138a24dbf0df933d5de54ecf21878e4960a", "bytes": 15696, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/9b5bda4102ec47aca2e026f243c10f80d6bdb21773202ef30de92735735a5c07.mp3", "duration_ms": 2560}, "s1-dialogue.line.3": {"url": "http://localhost:4006/files/lesson-audio/22fb6f272858c7bb62ddb8161f878e9d82834ba8f23b21df6d57e7aaeca1fd29.mp3", "hash": "bd28ea1ea89e8931d6c3afb0bf40c42613a378cee4c39f198b62812df7f76744", "bytes": 33408, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/22fb6f272858c7bb62ddb8161f878e9d82834ba8f23b21df6d57e7aaeca1fd29.mp3", "duration_ms": 5520}, "s1-dialogue.line.4": {"url": "http://localhost:4006/files/lesson-audio/1feefcd98dad758c6d3aed87be2b8a21eef92524cf5f90da47315c4e549f9f78.mp3", "hash": "93e70951781135d6c3b1bf8598bec894bfd510d1ad8527edb4259e8cf9232c46", "bytes": 26208, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/1feefcd98dad758c6d3aed87be2b8a21eef92524cf5f90da47315c4e549f9f78.mp3", "duration_ms": 4320}, "s1-dialogue.prompt": {"url": "http://localhost:4006/files/lesson-audio/632f374a648fd0dd9e4494260a5926d4357d985cd90cd82c16cb7ecbe45c8557.mp3", "hash": "134e1a62d69be80569d015c4f452471feaeef915da6aff0f6ba9d8cd3e029481", "bytes": 23328, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/632f374a648fd0dd9e4494260a5926d4357d985cd90cd82c16cb7ecbe45c8557.mp3", "duration_ms": 3840}, "s1-dialogue.explanation": {"url": "http://localhost:4006/files/lesson-audio/c8890627b2d07b6e760e867b655d41a1ae59406664961b7ce0a7a0a9d8969895.mp3", "hash": "0f595081e1c3dbd59a743368bb242630b6eecd304b0bcca6cccf4143c1327d58", "bytes": 35856, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c8890627b2d07b6e760e867b655d41a1ae59406664961b7ce0a7a0a9d8969895.mp3", "duration_ms": 5920}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'es-MX', '1', '{"meta": {"cast": ["rho"], "slug": "odd-one-out", "title": "El ingrediente extraño", "locale": "es-MX", "subject": "mixed", "objectives": ["Identificar qué elementos no son ingredientes de la limonada para distinguir gastos reales de producción."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-ingredient", "xp": 10, "type": "odd_one_out", "hints": ["Piensa en lo que necesitas para hacer limonada: limones, agua, azúcar... ¿algo más?", "Si no se come ni se bebe, probablemente no es un ingrediente."], "title": "¿Qué no va en la limonada?", "payload": {"items": [{"id": "item-limones", "text_md": "Limones ($3)"}, {"id": "item-azucar", "text_md": "Azúcar ($2)"}, {"id": "item-agua", "text_md": "Agua ($1)"}, {"id": "item-pelota", "text_md": "Pelota ($5)"}], "reasons": [{"id": "reason-ingrediente", "text_md": "Sí es un ingrediente de la limonada."}, {"id": "reason-no-ingrediente", "text_md": "No es un ingrediente de la limonada."}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho tiene $10 ahorrados en su alcancía para comprar ingredientes. En su lista escribió: limones ($3), azúcar ($2), agua ($1) y una pelota ($5). Pero la pelota no es un ingrediente. ¿Cuál de estos NO debe comprar con su dinero de limonada?", "difficulty": 1, "explanation_md": "La pelota no es un ingrediente de la limonada. Los ingredientes son cosas que se mezclan para hacer la bebida: limones, azúcar y agua. La pelota es un juguete, no cuesta dinero producir la limonada. Rho debe guardar sus $5 para la pelota si quiere, pero no para la receta.", "audio_segment_id": "s1-odd-ingredient.prompt"}], "schema_version": 1}', '{"s1-odd-ingredient": {"odd_item_id": "item-pelota", "correct_reason_id": "reason-no-ingrediente"}}', '{"units": {"s1-odd-ingredient.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9314de6866fa7401760f536b4b825226c4264393388bf4f694d4a96e9719777c.mp3", "hash": "dfcee75938af646fff0b49d9bf580056bcf751f56feb648a373ec5c30772721b", "bytes": 36288, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/9314de6866fa7401760f536b4b825226c4264393388bf4f694d4a96e9719777c.mp3", "duration_ms": 6000}, "s1-odd-ingredient.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5cc3603c7e4874090d0f7fd7fea83e6e3d0fc9b6542f641a8ef0e32a44e8ac7b.mp3", "hash": "7fba1fe3799d9cc2d6a8a95114b7a36f0defc4eb6f4e5a7783fc983cdcde8594", "bytes": 25344, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/5cc3603c7e4874090d0f7fd7fea83e6e3d0fc9b6542f641a8ef0e32a44e8ac7b.mp3", "duration_ms": 4160}, "s1-odd-ingredient.prompt": {"url": "http://localhost:4006/files/lesson-audio/90a54f9926229512b051c6d827f8586243f6e238c2704c4f87313b316907c25e.mp3", "hash": "2c0715cb7ce66941637e63141569974761268fbcb5441921ad9291c998edb257", "bytes": 124128, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/90a54f9926229512b051c6d827f8586243f6e238c2704c4f87313b316907c25e.mp3", "duration_ms": 20640}, "s1-odd-ingredient.choices": {"url": "http://localhost:4006/files/lesson-audio/3a0e208f4e717ceb030aebc104842216096e9ee07baddfc30d50d24311c7cd32.mp3", "hash": "3ea2eb26fbd39c57c2cc26b3af8a3f360b87bf155091d85fed9d63c975cb4c0a", "bytes": 52704, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/3a0e208f4e717ceb030aebc104842216096e9ee07baddfc30d50d24311c7cd32.mp3", "duration_ms": 8720}, "s1-odd-ingredient.explanation": {"url": "http://localhost:4006/files/lesson-audio/7eca987850f29391dff3f03aeb3191650265e7f2f39104927bb47021e100d4c1.mp3", "hash": "4aaffa219f5d7f335aa7504f1dd668c7fe5e56fd4eccb74b574cda7630e8bbcb", "bytes": 119808, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/7eca987850f29391dff3f03aeb3191650265e7f2f39104927bb47021e100d4c1.mp3", "duration_ms": 19920}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fair-trade", "title": "Fair trade", "locale": "en-US", "subject": "mixed", "objectives": ["Decide if a trade is fair by comparing values", "Count coins of 1, 2, 5, and 10", "Calculate change from a 20 bill", "Plan weeks to save 80 pesos"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 10, "type": "fair_trade", "hints": ["How much did Liruf pay for 2 glasses last week?", "If the trade is fair, Liruf doesn''t lose money. How much is the bag of lemons worth?"], "title": "Fair trade", "payload": {"offer_a": {"qty": 2, "icon": "local_cafe", "label": "2 glasses of lemonade"}, "offer_b": {"qty": 1, "icon": "storefront", "label": "Bag of lemons"}, "rate_md": "Last week, Liruf paid 10 pesos for 2 glasses of lemonade. The bag of lemons costs 10 pesos."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf is saving 20 pesos each week to buy an 80-peso guitar. He has been saving for 3 weeks and has 60 pesos. The fruit seller offers to trade a bag of lemons for 2 glasses of lemonade. Liruf remembers that last week he paid 10 pesos for 2 glasses of lemonade. The bag of lemons costs 10 pesos at the store. Is the trade fair?", "difficulty": 1, "explanation_md": "Last week, Liruf paid 10 pesos for 2 glasses of lemonade, and the bag of lemons also costs 10 pesos. They are worth the same, so the trade is fair. Liruf doesn''t lose money and still has his 60 pesos plus the 20 he will save this week, so he''ll have exactly 80 for the guitar!", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "fair"}}', '{"units": {"s1-fair-trade.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d17744d2232bb3219b802e807913763201d82cf856957fff916accecb2db165b.mp3", "hash": "9bfdb488b5b052e51f65dd053fee48c9817228cdce6b6fe19897d7e51ffc5618", "bytes": 19584, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/d17744d2232bb3219b802e807913763201d82cf856957fff916accecb2db165b.mp3", "duration_ms": 3200}, "s1-fair-trade.hint.1": {"url": "http://localhost:4006/files/lesson-audio/48ee289e5ddd39968fd52fd91b7b8191cee577016d7dba009a3cab9375f3b345.mp3", "hash": "a638f6dd8223db1234f588c05d0f6c282f9322e08f5ce509dd38fc316d3b9d28", "bytes": 30528, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/48ee289e5ddd39968fd52fd91b7b8191cee577016d7dba009a3cab9375f3b345.mp3", "duration_ms": 5040}, "s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/bc6181d1c577baf48eb6cf5272e01f0baf9de8924b9f8139ab66847ad45bc8dd.mp3", "hash": "89fec53d16b1fbdf6faf7c2ac73f2c800e0ab9da40b9d8306d76ac404b5b602e", "bytes": 116496, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/bc6181d1c577baf48eb6cf5272e01f0baf9de8924b9f8139ab66847ad45bc8dd.mp3", "duration_ms": 19360}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/7ed9e54af905dfdd2f35bfdc88250f39afa3125884b535e71435e48a8eb13706.mp3", "hash": "853b8290ced620f72216d32f03427bfcfb7ba9a56e52d64c1c10a586beda38f1", "bytes": 99648, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/7ed9e54af905dfdd2f35bfdc88250f39afa3125884b535e71435e48a8eb13706.mp3", "duration_ms": 16560}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "measure-read", "title": "O copo medidor: copos iguais", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ler a linha do líquido em um copo medidor para servir copos iguais de 5 reais."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-measure-read", "xp": 10, "type": "measure_read", "hints": ["Observe as marcas: 200, 250, 300. Até qual a água chegou?"], "title": "Leia o copo", "payload": {"max": 300, "min": 200, "unit": "ml", "ticks": 3, "instrument": "beaker", "pointer_value": 250}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Ontem Liruf vendeu 3 copos de limonada a 5 reais cada e ganhou 15 reais. Hoje ele quer servir copos iguais para que ninguém se sinta enganado. Use o copo medidor: cada copo deve ter 250 ml. A água subiu até uma linha. Quantos ml há no copo? Se colocar menos, os clientes reclamarão.", "difficulty": 1, "explanation_md": "A água chegou até a linha de 250 ml. Assim cada copo de 5 reais terá a mesma quantidade, e Liruf pode servir 3 copos para ganhar 15 reais, como ontem.", "audio_segment_id": "s1-measure-read.prompt"}], "schema_version": 1}', '{"s1-measure-read": {"value": 250, "tolerance": 0}}', '{"units": {"s1-measure-read.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e603569dbdde5276334528b64d83932179721c4989cbebbc5e52807353ed9942.mp3", "hash": "a7e261e12b75568dae3e8a8d2af6bd266b15f0ee5167f363fd85bb4a10ad9d86", "bytes": 44928, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/e603569dbdde5276334528b64d83932179721c4989cbebbc5e52807353ed9942.mp3", "duration_ms": 7440}, "s1-measure-read.prompt": {"url": "http://localhost:4006/files/lesson-audio/3ef6ac3630d51f1be9b81d089342b6542d8180bacf67316e732fbca92ba93526.mp3", "hash": "ced548b84f8bfb46e6f19a4a7a437b1d6065eb2e5ed259849a6629fd17a989d2", "bytes": 147168, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/3ef6ac3630d51f1be9b81d089342b6542d8180bacf67316e732fbca92ba93526.mp3", "duration_ms": 24480}, "s1-measure-read.explanation": {"url": "http://localhost:4006/files/lesson-audio/99accec3f36ff2beb2466251b3ee4119cfb8f3ec16757b499cdb32db4c669242.mp3", "hash": "1bcc5536b230da1b3f0b7ef03143b9e93ed6a21c19f7b81cdfc111a632f5446b", "bytes": 82368, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/99accec3f36ff2beb2466251b3ee4119cfb8f3ec16757b499cdb32db4c669242.mp3", "duration_ms": 13680}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "picture-choice", "title": "Escolha o lugar mais seguro", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher com imagens o lugar mais seguro para guardar os lucros do dia: o cofrinho com chave (não o bolso furado nem a mesa da barraca)."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lugar-seguro", "xp": 10, "type": "picture_choice", "hints": ["Pense: em que lugar o dinheiro está mais protegido?", "Imagine que você deixa suas moedas em um lugar onde só você pode abrir."], "title": "Onde você guarda seu dinheiro?", "payload": {"options": [{"id": "alcancia", "icon": "lock", "label": "Cofrinho com chave", "image_url": "http://localhost:4006/files/lesson-images/969d02b3305f1757763e426012eea915a7a4fe9df2d4f274cfaaf148668b4c16.png"}, {"id": "bolsillo", "icon": "checkroom", "label": "Bolso furado", "image_url": "http://localhost:4006/files/lesson-images/23673b2b3632d2c627a9b86858a270c26d33d1636250426026522118088720b4.png", "rationale_md": "O bolso tem um furo, as moedas cairiam e se perderiam. Sua poupança escaparia."}, {"id": "mesa", "icon": "table_restaurant", "label": "Mesa da barraca", "image_url": "http://localhost:4006/files/lesson-images/bad1b24fb80f59a268da01824b267df647f7b286bcf4a213f73a35e77aac869d.png", "rationale_md": "A mesa está à vista de todos, qualquer um poderia pegar o dinheiro. Sua poupança não estaria protegida."}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Ontem Liruf guardou 5 reais em seu cofrinho. Hoje ele vendeu limonada e tem mais 20 reais. Sua poupança está crescendo. Onde ele deve colocar essas moedas para que sua poupança fique segura?", "difficulty": 1, "explanation_md": "O cofrinho com chave é o lugar mais seguro porque só Liruf pode abri-lo. Assim, sua poupança de 25 reais não se perde nem é roubada. O bolso tem um furo e a mesa está ao alcance de todos.", "audio_segment_id": "s1-lugar-seguro.prompt"}], "schema_version": 1}', '{"s1-lugar-seguro": {"correct_option_id": "alcancia"}}', '{"units": {"s1-lugar-seguro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/69c5962748c844c1ee3905ec9b45980f40b5b758b61f45e325dff84aa5f744a9.mp3", "hash": "ba7441b5438f2daf3012978fd2b4e4dfa1148c63fb02795457611fcc903d3702", "bytes": 21024, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/69c5962748c844c1ee3905ec9b45980f40b5b758b61f45e325dff84aa5f744a9.mp3", "duration_ms": 3440}, "s1-lugar-seguro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5bdcbda1b1aaaf0f2b2db6530f926a41e34ac83f87667648ee987811bbac5a4f.mp3", "hash": "e2667d8b95f960f460955cbce675d2bedfe44fec50e88dcce4fec267d2f0a278", "bytes": 28656, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5bdcbda1b1aaaf0f2b2db6530f926a41e34ac83f87667648ee987811bbac5a4f.mp3", "duration_ms": 4720}, "s1-lugar-seguro.prompt": {"url": "http://localhost:4006/files/lesson-audio/906e10d92fd1db2ca6728da2e2d0857adbe223d89bc8654c9ae051d26034c2a1.mp3", "hash": "e5c2cef04ff91e64502df7a9b9ca5c87e36e78735b0629d61b7d7814fb7c062b", "bytes": 85824, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/906e10d92fd1db2ca6728da2e2d0857adbe223d89bc8654c9ae051d26034c2a1.mp3", "duration_ms": 14240}, "s1-lugar-seguro.choices": {"url": "http://localhost:4006/files/lesson-audio/6f384fd606df7aa6e968a523effdb1decdc2337593f65eb0bc0b4f37bae556e2.mp3", "hash": "67c36aee41f4705f141b8ed664664d2ed99bc9e8b05058412416103fdecf5379", "bytes": 27216, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6f384fd606df7aa6e968a523effdb1decdc2337593f65eb0bc0b4f37bae556e2.mp3", "duration_ms": 4480}, "s1-lugar-seguro.explanation": {"url": "http://localhost:4006/files/lesson-audio/e983df857542f02ced7476e62cdbc5ae5631e282ae02aaaf7ca24d31b5c42e5f.mp3", "hash": "96c76d1a6c24f549dd4d2e16c45049a5d0b563ed32dd483deb5234bb44d7a2f5", "bytes": 85824, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e983df857542f02ced7476e62cdbc5ae5631e282ae02aaaf7ca24d31b5c42e5f.mp3", "duration_ms": 14240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'en-US', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "read-chart", "title": "Read the sales chart", "locale": "en-US", "subject": "mixed", "objectives": ["Read the bar chart of cups sold per day and answer which was the best day of the week."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 10, "type": "read_chart", "hints": ["Look for the tallest bar in the chart.", "Each bar shows how many cups were sold that day."], "title": "Zara''s best day", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Cups sold", "points": [{"x": "Monday", "y": 3}, {"x": "Tuesday", "y": 5}, {"x": "Wednesday", "y": 4}, {"x": "Thursday", "y": 6}, {"x": "Friday", "y": 8}]}]}, "questions": [{"id": "q-best-day", "options": [{"id": "lunes", "text_md": "Monday"}, {"id": "martes", "text_md": "Tuesday"}, {"id": "miercoles", "text_md": "Wednesday"}, {"id": "jueves", "text_md": "Thursday"}, {"id": "viernes", "text_md": "Friday"}], "prompt_md": "Which day sold the most cups of lemonade?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Zara wants to know which day she will sell the most lemonade next week so she can order enough lemons. Since you chose the best lemon supplier, now help her find the best day using her sales chart from this week. Which day sold the most cups?", "difficulty": 1, "explanation_md": "On Friday the bar reaches 8, which is higher than the other days. That was the best day! Zara will order more lemons for Friday.", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q-best-day": "viernes"}}}', '{"units": {"s1-read-chart.hint.0": {"url": "http://localhost:4006/files/lesson-audio/42df1ce09fc9aa24d3226ccc1f002ccd935ae3ba59f5f5d75500a935a1741073.mp3", "hash": "947c334e32c6e2f0f7f4ae62eae83d0b86118b73ee2f22a524415ef4d481df6d", "bytes": 12384, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/42df1ce09fc9aa24d3226ccc1f002ccd935ae3ba59f5f5d75500a935a1741073.mp3", "duration_ms": 2000}, "s1-read-chart.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6794e99d5e8cb8485e110e28ed37cecdd07b3d9c7dc73e205a1b9cb60da1d578.mp3", "hash": "43a3a7a639c75cb0e6d77895d6a092848d71924736623a3ba3f61d9e9bb33f80", "bytes": 16128, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6794e99d5e8cb8485e110e28ed37cecdd07b3d9c7dc73e205a1b9cb60da1d578.mp3", "duration_ms": 2640}, "s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/35460f60ad2fbaba1119dadd7e7d7ebba58107207d680e0f5ef58375bb0c8955.mp3", "hash": "c290cf4f65145ec123d4a787e99bc94dafce5a9543da9c957d8a5e27a620177d", "bytes": 74736, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/35460f60ad2fbaba1119dadd7e7d7ebba58107207d680e0f5ef58375bb0c8955.mp3", "duration_ms": 12400}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/cfb96a9d09e5c539c723cc7f1f4014bfaff396d47d68904f84f025bca454e719.mp3", "hash": "5c33bf33158773dd068a8ce73088550d3aaa99e5f2c7a5e9301f05c382b65631", "bytes": 46368, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/cfb96a9d09e5c539c723cc7f1f4014bfaff396d47d68904f84f025bca454e719.mp3", "duration_ms": 7680}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'es-MX', '1', '{"meta": {"cast": ["liruf", "zara"], "slug": "build-sentence", "title": "El letrero del combo", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular el precio de 2 vasos de limonada (2 × 5 = 10) para completar un letrero de combo."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-combo-sign", "xp": 10, "type": "build_sentence", "hints": ["Piensa: un vaso cuesta 5, dos vasos cuestan el doble.", "¿Cuánto es 5 más 5?"], "title": "El letrero del combo", "payload": {"slots": 5, "tokens": [{"id": "t1", "text_md": "2"}, {"id": "t2", "text_md": "vasos"}, {"id": "t3", "text_md": "por"}, {"id": "t4", "text_md": "10"}, {"id": "t5", "text_md": "pesos"}, {"id": "t6", "text_md": "5"}, {"id": "t7", "text_md": "15"}, {"id": "t8", "text_md": "20"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf ya ordenó sus gastos: primero los limones, luego los vasos, después los adornos. Ahora quiere vender más rápido y pone un letrero: **2 vasos por ___ pesos**. Cada vaso cuesta 5 pesos. Toca las fichas en orden para armar el letrero correcto. Si aciertas, los clientes sabrán el precio justo y Liruf venderá más.", "difficulty": 1, "explanation_md": "Dos vasos cuestan 10 pesos porque cada vaso vale 5: 5 + 5 = 10. Si pones 5, regalarías un vaso. Si pones 15 o 20, los clientes pensarían que es muy caro y no comprarían.", "audio_segment_id": "s1-combo-sign.prompt"}], "schema_version": 1}', '{"s1-combo-sign": {"order": ["t1", "t2", "t3", "t4", "t5"]}}', '{"units": {"s1-combo-sign.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6d46eec2a58448787b16cdc268285b215578e27741fb3b2f362daa2c1558b2f1.mp3", "hash": "6212e34020f9fdba07a2f73b497a3c026db71fe4ae3776d68ca7a4978f697684", "bytes": 28656, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/6d46eec2a58448787b16cdc268285b215578e27741fb3b2f362daa2c1558b2f1.mp3", "duration_ms": 4720}, "s1-combo-sign.hint.1": {"url": "http://localhost:4006/files/lesson-audio/4f69c412b64303fed71d966980aac6e98b20e68bd363482b39e1b578dc0d1c12.mp3", "hash": "6270549ce7f6942cf380272ed2108bf51e0a4af2f12c4746506745191ecfa020", "bytes": 12816, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/4f69c412b64303fed71d966980aac6e98b20e68bd363482b39e1b578dc0d1c12.mp3", "duration_ms": 2080}, "s1-combo-sign.prompt": {"url": "http://localhost:4006/files/lesson-audio/fdc6afd8a67d38d9167e6654886c16d18b92284bccd9b447168f272182514ffa.mp3", "hash": "fcdb56f277c221c5ee4d7b0828d35d7439c8fede4803bad33053233f6631c938", "bytes": 135648, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/fdc6afd8a67d38d9167e6654886c16d18b92284bccd9b447168f272182514ffa.mp3", "duration_ms": 22560}, "s1-combo-sign.explanation": {"url": "http://localhost:4006/files/lesson-audio/85d7efc5abf15388e6e6afcf07fc6ebd5e4100fc3cf76ade517ddf35b331a17e.mp3", "hash": "396a45f9e76e546c39a39794f73b1711b1e5906862631b1ccb5e23d22c4a5ba8", "bytes": 93024, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/85d7efc5abf15388e6e6afcf07fc6ebd5e4100fc3cf76ade517ddf35b331a17e.mp3", "duration_ms": 15440}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "Ganhar dinheiro com uma ideia", "locale": "pt-BR", "subject": "money", "objectives": ["Descobrir que o dinheiro pode ser ganho oferecendo algo que os outros querem", "Identificar que uma meta clara ajuda a começar"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogue", "xp": 0, "type": "story_dialogue", "hints": [], "title": "O violão de Liruf", "payload": {"lines": [{"action": "idle", "emotion": "thinking", "text_md": "Ah, Dina… quero aquele violão de 80 pesos, mas não tenho dinheiro.", "character": "liruf"}, {"action": "idle", "emotion": "excited", "text_md": "E se você ganhar ele sozinho? Poderia vender limonada na vizinhança.", "character": "dina"}, {"action": "idle", "emotion": "surprised", "text_md": "Vender limonada? E as pessoas me pagariam?", "character": "liruf"}, {"action": "idle", "emotion": "encouraging", "text_md": "Claro! Se você oferecer algo que os outros queiram, pode ganhar dinheiro. Cada copo a 5 pesos.", "character": "dina"}, {"action": "idle", "emotion": "happy", "text_md": "Então eu posso juntar os 80 pesos! Vou fazer limonada!", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf quer um violão que custa 80 pesos. Como ele pode conseguir?", "difficulty": 1, "explanation_md": "Liruf descobriu que pode ganhar dinheiro vendendo limonada a 5 pesos o copo, em vez de apenas esperar um presente.", "audio_segment_id": "s1-dialogue.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-dialogue.line.0": {"url": "http://localhost:4006/files/lesson-audio/4b121adb0df9ec92e63f30fd8302538bfac549470c7c335335a7d9dbc165eca8.mp3", "hash": "b7a083edd69647fb33e2eaff2770e538a728bb48ed65fef7e05594ae2bae7ce3", "bytes": 28656, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/4b121adb0df9ec92e63f30fd8302538bfac549470c7c335335a7d9dbc165eca8.mp3", "duration_ms": 4720}, "s1-dialogue.line.1": {"url": "http://localhost:4006/files/lesson-audio/a5846d051b51255775ce8f8dcaecbb886ad9d29a6452cd4227f81c1fe4f4d687.mp3", "hash": "1639d620871094bf36dc601ad07e1b01be565fd6d31ce5a5ac37d48672923054", "bytes": 29664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a5846d051b51255775ce8f8dcaecbb886ad9d29a6452cd4227f81c1fe4f4d687.mp3", "duration_ms": 4880}, "s1-dialogue.line.2": {"url": "http://localhost:4006/files/lesson-audio/117ea6ea6b806ed55812880040ca49379fa19e11d60f0fd6542c5a11dc140b21.mp3", "hash": "a34ee9c987388481279a374004b77eb86c81b3fd6404c125f332114f81069275", "bytes": 20016, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/117ea6ea6b806ed55812880040ca49379fa19e11d60f0fd6542c5a11dc140b21.mp3", "duration_ms": 3280}, "s1-dialogue.line.3": {"url": "http://localhost:4006/files/lesson-audio/4014ac5518b8d8ccfe1fac9481ef790113bbb5bb78582ce1ca16419e46ce4729.mp3", "hash": "b28d4f3810c553d5751ade4ec3d31cb9ed956ed884ce33814d10cc40d15c49f3", "bytes": 39744, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4014ac5518b8d8ccfe1fac9481ef790113bbb5bb78582ce1ca16419e46ce4729.mp3", "duration_ms": 6560}, "s1-dialogue.line.4": {"url": "http://localhost:4006/files/lesson-audio/df40aac1174f2e8b1fc2885be7fa52b9398987cb848e4f00ce7325715160f49b.mp3", "hash": "ad03ffffe3f28a3d2a35611d1e897576c37accc1487b89884e4bebafe813feaa", "bytes": 25776, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/df40aac1174f2e8b1fc2885be7fa52b9398987cb848e4f00ce7325715160f49b.mp3", "duration_ms": 4240}, "s1-dialogue.prompt": {"url": "http://localhost:4006/files/lesson-audio/9717faae33ffc337ddf3f92714bcbacee5bd51f16c808bad0dc5dd7bb66460ac.mp3", "hash": "237a6b0efc54b312c09ceafca171ec9e5d44eaf517e5309f389e7af2385ee5f3", "bytes": 32976, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9717faae33ffc337ddf3f92714bcbacee5bd51f16c808bad0dc5dd7bb66460ac.mp3", "duration_ms": 5440}, "s1-dialogue.explanation": {"url": "http://localhost:4006/files/lesson-audio/4c3735323fce9dc55fe1f28db3076edcb8fc91c8bca6778f6c9ce8f804867d19.mp3", "hash": "05d03598df1c174f9fb6d1082500d564c381359a9bb52674863bcf32cf280186", "bytes": 50256, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4c3735323fce9dc55fe1f28db3076edcb8fc91c8bca6778f6c9ce8f804867d19.mp3", "duration_ms": 8320}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'pt-BR', '1', E'{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "price-compare", "title": "Comparar preços de limões", "locale": "pt-BR", "subject": "mixed", "objectives": ["Comparar preços de limões em duas barracas do mercado e escolher a mais barata para gastar menos (custo mais baixo = mais lucro)."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 10, "type": "price_compare", "hints": ["Como as duas barracas vendem a mesma quantidade de limões, basta comparar o preço total. A que custar menos deixa mais dinheiro para o violão."], "title": "Qual barraca compensa?", "payload": {"offers": [{"id": "dina", "qty": 10, "unit": "limones", "label": "Barraca da Dina", "price": 12}, {"id": "rho", "qty": 10, "unit": "limones", "label": "Barraca do Rho", "price": 15}], "currency": "MXN"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf precisa comprar limões para sua barraca de limonada. Lembre-se: primeiro compramos o que a barraca precisa e procuramos a melhor oferta para gastar menos.\\n\\nNo mercado há duas barracas que vendem limões:\\n- **Barraca da Dina**: 10 limões por 12 reais.\\n- **Barraca do Rho**: 10 limões por 15 reais.\\n\\nAmbas vendem a mesma quantidade de limões. Qual barraca tem o preço total mais baixo? Toque na que compensa para economizar mais dinheiro.", "difficulty": 1, "explanation_md": "Ambas as barracas vendem 10 limões, mas a barraca da Dina custa 12 reais e a do Rho custa 15 reais. Comprar na barraca da Dina economiza 3 reais para a meta do violão. Escolher a oferta mais barata é uma forma de gastar menos!", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "dina"}}', '{"units": {"s1-price-compare.hint.0": {"url": "http://localhost:4006/files/lesson-audio/fc48ae5d034013384ce11bf4060857a4c6b6bed2b76845208ba93822d35de7c1.mp3", "hash": "28b74e42c0483fc73467971cdba6ab92f6ced6567fd799dac048ceb44a234a59", "bytes": 55584, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/fc48ae5d034013384ce11bf4060857a4c6b6bed2b76845208ba93822d35de7c1.mp3", "duration_ms": 9200}, "s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/446aa2bafb61fe1ff19752ee253c08125b21cdd305c8bb35dba4f580a3bf16a1.mp3", "hash": "f59dd5f225419097cda62db55a2929577142af72667ae7d39ecf4c712c939102", "bytes": 190368, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/446aa2bafb61fe1ff19752ee253c08125b21cdd305c8bb35dba4f580a3bf16a1.mp3", "duration_ms": 31680}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/d72eb5c3dcc01b66ace94d9e9ca0856be6b40399696c5efec594e2f93f6e9c54.mp3", "hash": "b0e85e7738132629a26476a0dc7fb455074ea659d3a440f64f1905e30857dd98", "bytes": 114048, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d72eb5c3dcc01b66ace94d9e9ca0856be6b40399696c5efec594e2f93f6e9c54.mp3", "duration_ms": 18960}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "Decir sí o no, caso por caso", "locale": "es-MX", "subject": "mixed", "objectives": ["Decidir si un gasto ayuda al puesto de limonada o no, basado en si es una necesidad o una tentación."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 10, "type": "yes_no_cases", "hints": ["Piensa: ¿esto ayuda a vender más limonada o a hacerla mejor?", "Si es para el puesto hoy, tal vez sí. Si es un gusto personal, mejor esperar."], "title": "¿Gasto que ayuda o tentación?", "payload": {"cases": [{"id": "case-limones", "text_md": "Comprar más limones para hacer más limonada."}, {"id": "case-juguete", "text_md": "Comprar un juguete nuevo hoy en la tienda."}, {"id": "case-vasos", "text_md": "Comprar vasos desechables para servir la limonada."}, {"id": "case-dulces", "text_md": "Comprar dulces para comértelos mientras trabajas."}], "rule_md": "Pregúntate: **¿esto ayuda a que el puesto funcione mejor o venda más?** Si la respuesta es sí, es un gasto que vale la pena. Si es solo un antojo, mejor guarda el dinero."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Ahora que Liruf sabe dar el cambio correcto de un billete de $20 por una limonada de $5, Dina le pregunta: ''¿Deberíamos gastar en esto para el puesto o es una tentación?'' Ayuda a Liruf a decidir para cada caso.", "difficulty": 1, "explanation_md": "Comprar más limones ayuda a hacer más limonada y ganar más dinero. Un juguete nuevo no ayuda al puesto hoy.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["case-limones", "case-vasos"]}}', '{"units": {"s1-yes-no-cases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f440d290e314cc5505fb9d17af04c2543cf530a7dd4175551ccc6a0032188641.mp3", "hash": "1ff2eeb1e1a35bdb19ca375daeab6dcba6ca5df3a4bb7ef0b0f85f0a6f88feb6", "bytes": 28224, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f440d290e314cc5505fb9d17af04c2543cf530a7dd4175551ccc6a0032188641.mp3", "duration_ms": 4640}, "s1-yes-no-cases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/062679785f728b7b47fcdcacfa7d19d24280a2884a59992d5839caf2f83630d7.mp3", "hash": "2a1ad84fb2778895ff945239ca9bfc20b2c04b156a757d905f5477b6eb11de63", "bytes": 32976, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/062679785f728b7b47fcdcacfa7d19d24280a2884a59992d5839caf2f83630d7.mp3", "duration_ms": 5440}, "s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/5d36cd40cde88fd5fd7527cb80b150371110d13ebfe6b83a349db3a16c6f4766.mp3", "hash": "018a0931e0ec40a2591122d22110f7ee4c20d8ccdfc768787f5b7269ad04b1ae", "bytes": 90576, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5d36cd40cde88fd5fd7527cb80b150371110d13ebfe6b83a349db3a16c6f4766.mp3", "duration_ms": 15040}, "s1-yes-no-cases.choices": {"url": "http://localhost:4006/files/lesson-audio/74a61fe152d38e772df438bc35430ae1c13c98043b8f0a4f74b37c5cda84e559.mp3", "hash": "77f2c8102e4725db378e24e135acb08d1d98aa15bda0d3e52e4721cb5eb591d9", "bytes": 75168, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/74a61fe152d38e772df438bc35430ae1c13c98043b8f0a4f74b37c5cda84e559.mp3", "duration_ms": 12480}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/7854fc9930e0195d607a038dcfdbd6a5a7cebd8fec9ae20b75ce18779cf743a6.mp3", "hash": "658931d46496ee0eaefc721be100b36bb834c74f86846a62545eb818f9823bd6", "bytes": 48384, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7854fc9930e0195d607a038dcfdbd6a5a7cebd8fec9ae20b75ce18779cf743a6.mp3", "duration_ms": 8000}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "Ganar dinero con una idea", "locale": "es-MX", "subject": "money", "objectives": ["Descubrir que el dinero se puede ganar ofreciendo algo que otros quieren", "Identificar que una meta clara ayuda a empezar"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogue", "xp": 0, "type": "story_dialogue", "hints": [], "title": "La guitarra de Liruf", "payload": {"lines": [{"action": "idle", "emotion": "thinking", "text_md": "Ay, Dina… quiero esa guitarra de 80 pesos, pero no tengo dinero.", "character": "liruf"}, {"action": "idle", "emotion": "excited", "text_md": "¿Y si la ganas tú mismo? Podrías vender limonada en el vecindario.", "character": "dina"}, {"action": "idle", "emotion": "surprised", "text_md": "¿Vender limonada? ¿Y la gente me pagaría?", "character": "liruf"}, {"action": "idle", "emotion": "encouraging", "text_md": "¡Claro! Si ofreces algo que otros quieran, puedes ganar dinero. Cada vaso a 5 pesos.", "character": "dina"}, {"action": "idle", "emotion": "happy", "text_md": "¡Entonces sí puedo juntar los 80 pesos! ¡Voy a hacer limonada!", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf quiere una guitarra que cuesta 80 pesos. ¿Cómo puede conseguirla?", "difficulty": 1, "explanation_md": "Liruf descubrió que puede ganar dinero vendiendo limonada a 5 pesos el vaso, en lugar de solo esperar un regalo.", "audio_segment_id": "s1-dialogue.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-dialogue.line.0": {"url": "http://localhost:4006/files/lesson-audio/3ad19cde58a146560e687f046c6a6b66a2bb212a67a3ba1615136bec4ce9baf9.mp3", "hash": "ccc98f7cad26a259603f1a8667e403e8974150cd07af99e8921ec097b6adc9f5", "bytes": 32544, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/3ad19cde58a146560e687f046c6a6b66a2bb212a67a3ba1615136bec4ce9baf9.mp3", "duration_ms": 5360}, "s1-dialogue.line.1": {"url": "http://localhost:4006/files/lesson-audio/79b2f3a67a5d9c5b693cf2ead466a2ea0f3f918c9514d1c1d34d1432ae8a4878.mp3", "hash": "210f513010e86f3babb6218ea2952370d5cc6caa49c0b12a47951495f6951d93", "bytes": 27648, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/79b2f3a67a5d9c5b693cf2ead466a2ea0f3f918c9514d1c1d34d1432ae8a4878.mp3", "duration_ms": 4560}, "s1-dialogue.line.2": {"url": "http://localhost:4006/files/lesson-audio/e8be34d9b6b6e69f88f6063c717fa6637176dbc423792c726e31d1b2da765ec7.mp3", "hash": "3b16291ecb011800c80ae0e4f2d009a4f7302dc654a3b27008d91dd6cef672d8", "bytes": 19584, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/e8be34d9b6b6e69f88f6063c717fa6637176dbc423792c726e31d1b2da765ec7.mp3", "duration_ms": 3200}, "s1-dialogue.line.3": {"url": "http://localhost:4006/files/lesson-audio/dfbf4cd43a8d1a40644e101f1aa5307dfe54440c9de43c6a6658506dbccd712e.mp3", "hash": "e78881c593e4369b608f8a2f23439c9fe3adf9531e02dcbe725518c26cc8453b", "bytes": 41616, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/dfbf4cd43a8d1a40644e101f1aa5307dfe54440c9de43c6a6658506dbccd712e.mp3", "duration_ms": 6880}, "s1-dialogue.line.4": {"url": "http://localhost:4006/files/lesson-audio/70890aa1832c1052473897e334e69b6b19ea9bc25129473eadc45f4935f861fc.mp3", "hash": "904da7b3227f74e85ecf258015f06714ebb257ae7c79b16970443adc3adeb201", "bytes": 30096, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/70890aa1832c1052473897e334e69b6b19ea9bc25129473eadc45f4935f861fc.mp3", "duration_ms": 4960}, "s1-dialogue.prompt": {"url": "http://localhost:4006/files/lesson-audio/94d08ea2273b082f6b12746a7586ff91c7c58ad733f7ff8fd233c1a08731234a.mp3", "hash": "f4d6d266b945271221c546a3f9631b06ea58916cb6ebcd4125c4a146a038eeec", "bytes": 33408, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/94d08ea2273b082f6b12746a7586ff91c7c58ad733f7ff8fd233c1a08731234a.mp3", "duration_ms": 5520}, "s1-dialogue.explanation": {"url": "http://localhost:4006/files/lesson-audio/f081c22182cd5f41e3097297cb187bec52bad65fcf47a194a2aa32a1889806d2.mp3", "hash": "d29858d5349e536005434d7456cd31286e4cfc7ec86bc6e0ada872f9932981ca", "bytes": 45936, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f081c22182cd5f41e3097297cb187bec52bad65fcf47a194a2aa32a1889806d2.mp3", "duration_ms": 7600}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'es-MX', '1', E'{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "El plan de Liruf", "locale": "es-MX", "subject": "money", "objectives": ["Ver el plan completo: vender vasos de limonada a 5 pesos hasta juntar 80 para la guitarra"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan", "xp": 0, "type": "story_scene", "hints": ["Cada vaso da 5 pesos. ¿Cuánto ha juntado ya con 10 vasos?", "Si ya tiene 50 pesos, ¿cuánto le falta para 80?"], "title": "El plan de Liruf", "payload": {"art": {"icon": "emoji_events", "tint": "primary"}, "action": "idle", "body_md": "Liruf dibujó su plan en una cartulina. Escribió: **1 vaso = 5 pesos**. Luego dibujó muchos vasos y al final una guitarra de 80 pesos. \\"¡Voy a vender limonada hasta tener mi guitarra!\\" Como descubrieron ayer con Dina, ¡no hay que esperar un regalo!", "emotion": "excited", "backdrop": "band", "character": "dina"}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Liruf ya vendió 10 vasos de limonada a 5 pesos cada uno. ¿Cuántos vasos más necesita vender para juntar los 80 pesos de la guitarra?", "difficulty": 1, "explanation_md": "¡Muy bien! Con 10 vasos juntó 50 pesos. Le faltan 30 pesos para la guitarra. Como cada vaso da 5 pesos, necesita 6 vasos más (porque 6 × 5 = 30). ¡Así su plan se vuelve real!", "audio_segment_id": "s1-plan.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-plan.body": {"url": "http://localhost:4006/files/lesson-audio/b5e2b05e4a51dfbfb33ab74b882684fb5224b748e60598378359dca773a1f5cb.mp3", "hash": "2d22b6d03747bbfbc27adbabecc58f95a58de5d549cc4acee8b545f99ce2cf18", "bytes": 107424, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b5e2b05e4a51dfbfb33ab74b882684fb5224b748e60598378359dca773a1f5cb.mp3", "duration_ms": 17840}, "s1-plan.hint.0": {"url": "http://localhost:4006/files/lesson-audio/168b9d16c7f93e56c005b07fc99d2b8bc43355fa8b132aadd53c3e04a6cff477.mp3", "hash": "00ba607001d3210c1079f34abbc0e685991bc3088ead7678b1d3d5a8402535fa", "bytes": 27648, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/168b9d16c7f93e56c005b07fc99d2b8bc43355fa8b132aadd53c3e04a6cff477.mp3", "duration_ms": 4560}, "s1-plan.hint.1": {"url": "http://localhost:4006/files/lesson-audio/1a8113714c223340a290401a7c4504bb035fe5f148d24c4ede42cf30646b3115.mp3", "hash": "02e00d270b0fe3897783cfc7818ac8a99e49734236b65620b1880dea061b4a5f", "bytes": 24336, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1a8113714c223340a290401a7c4504bb035fe5f148d24c4ede42cf30646b3115.mp3", "duration_ms": 4000}, "s1-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/87edf9dcd170bca7a61fcca237f8b398c915068f14b319c018615a5cc5a01ff2.mp3", "hash": "366b5e9844c8614c62b100786978066d647ec354ee0b375df5a34efc7f78a725", "bytes": 55008, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/87edf9dcd170bca7a61fcca237f8b398c915068f14b319c018615a5cc5a01ff2.mp3", "duration_ms": 9120}, "s1-plan.explanation": {"url": "http://localhost:4006/files/lesson-audio/4f1356dc0c740b83355920ce8b5d15d2efe1c8150a9bf62936ddd80faa95262b.mp3", "hash": "6ee21651d7aa759d388866b4caaa74332c95a8d7ff209b69f61347fa9d01f869", "bytes": 90576, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4f1356dc0c740b83355920ce8b5d15d2efe1c8150a9bf62936ddd80faa95262b.mp3", "duration_ms": 15040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "best-decision", "title": "The best decision when receiving change", "locale": "en-US", "subject": "mixed", "objectives": ["Choosing the best decision when a customer pays with a 20-peso bill for a 5-peso glass: counting the change calmly"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-best-decision", "xp": 10, "type": "best_decision", "hints": ["Think: if you paid with 20 and it costs 5, how much change should you get back?", "Is it better to count calmly or guess the change?"], "title": "Liruf''s change", "payload": {"options": [{"id": "contar", "text_md": "Count the change calmly: give her 15 pesos", "rationale_md": "It''s the best decision because Liruf gives the exact change and doesn''t make a mistake."}, {"id": "adivinar", "text_md": "Guess the change and give her 10 pesos", "rationale_md": "Guessing might make you give less change and upset the customer, or give more and lose money."}, {"id": "quedarse", "text_md": "Give change quickly without counting, just 5 pesos", "rationale_md": "Giving change quickly without counting might make you give less than you should, and the customer would leave upset."}], "scenario_md": "Liruf is at his lemonade stand. A customer gives him a 20-peso bill for a 5-peso glass. Liruf feels nervous because it''s the first time he''s been paid with a large bill. He remembers that the ingredients cost money, so he must take care of his profits."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Now that you know which ingredients cost money, Liruf has sold his first glass. A customer pays with a 20-peso bill for a 5-peso glass. What should Liruf do to avoid losing money or upsetting the customer?", "difficulty": 1, "explanation_md": "Liruf should count the change calmly: 20 minus 5 is 15 pesos. That way he makes sure to give the correct amount and not lose money. If he guesses, he might give less and upset the customer, or give more and lose profits.", "audio_segment_id": "s1-best-decision.prompt"}], "schema_version": 1}', '{"s1-best-decision": {"qualities": {"contar": 100, "adivinar": 30, "quedarse": 0}}}', '{"units": {"s1-best-decision.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ccb8755aa5bb0fb5bb4db6834ee31a291c51c0f4cba7b3ef7ef7e49ff85a1905.mp3", "hash": "b36b19c304b0ddacc02adae33fd7d362be2010dfacff223e1610b2b7715a9156", "bytes": 25776, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ccb8755aa5bb0fb5bb4db6834ee31a291c51c0f4cba7b3ef7ef7e49ff85a1905.mp3", "duration_ms": 4240}, "s1-best-decision.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a346724ead8c0a9ec8e925d9ac46fca4bf042915b81aa1fa33b73da07f075962.mp3", "hash": "58a022dd7f977e742820296cc77b31586aa8753bc139b22bfb868c031617e352", "bytes": 16128, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a346724ead8c0a9ec8e925d9ac46fca4bf042915b81aa1fa33b73da07f075962.mp3", "duration_ms": 2640}, "s1-best-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/e944a127ea23fc8ebcd413b9c48d0db118f9edd7e02b73525ff1238e1a540609.mp3", "hash": "e90cbb5aa3e2b08fd59c754ea28eb1bee40d0efedfa1277d074da67c881d7da6", "bytes": 68544, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e944a127ea23fc8ebcd413b9c48d0db118f9edd7e02b73525ff1238e1a540609.mp3", "duration_ms": 11360}, "s1-best-decision.choices": {"url": "http://localhost:4006/files/lesson-audio/4045c01ff2d4901e8ce37fe88466b3c6826254aba2ee3b2418750116cd28306b.mp3", "hash": "c947f072aaa1f738b6d5aafb3c85f1027a24797da0764d651ecb461a6fc8452c", "bytes": 56016, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4045c01ff2d4901e8ce37fe88466b3c6826254aba2ee3b2418750116cd28306b.mp3", "duration_ms": 9280}, "s1-best-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/cf8c7eb3f0889e043ccef6efeb2e8a5315498b1bfae15c065dbb498a16592905.mp3", "hash": "31e9f330936fc14f16ec7f3a29c8769066d05e9960283851d0af176b1aba2fac", "bytes": 73296, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/cf8c7eb3f0889e043ccef6efeb2e8a5315498b1bfae15c065dbb498a16592905.mp3", "duration_ms": 12160}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "key-ideas", "title": "Las tres reglas de oro del pequeño vendedor", "locale": "es-MX", "subject": "mixed", "objectives": ["Identificar las tres ideas clave del plan de Liruf: tener una meta de 80 pesos, ofrecer limonada fría que la gente quiera, y guardar lo ganado."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": [], "title": "Las tres reglas de oro", "payload": {"ideas": [{"icon": "emoji_events", "title": "Tener una meta", "body_md": "Liruf quiere la guitarra de **80 pesos**. Saber cuánto necesita le da dirección."}, {"icon": "local_cafe", "title": "Ofrecer algo que la gente quiera", "body_md": "Limonada fría a **5 pesos** el vaso. ¡A todos les gusta en un día caluroso!"}, {"icon": "savings", "title": "Guardar lo ganado", "body_md": "Cada peso que Liruf gane lo guarda para su meta. Así no se gasta en otras cosas."}]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf ya vendió 10 vasos de limonada y tiene 50 pesos. Pero recuerda que su meta es la guitarra de 80 pesos. **Ayuda a Liruf a decidir: ¿qué debe hacer con sus 50 pesos para llegar a la meta?**", "difficulty": 1, "explanation_md": "¡Exacto! Liruf debe **guardar** los 50 pesos y seguir vendiendo. Si los gasta en otra cosa, no alcanzará los 80. Guardar lo ganado es una de las tres reglas de oro.", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/b3bd189fc0750d2656491fb90f0c0dfd0c608596a3d3a5001d6b19668a7dfe89.mp3", "hash": "08f41bb095604ac891d8cf2878dd9e473ae617508c27c1e064d0c5130b3689ab", "bytes": 33408, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/b3bd189fc0750d2656491fb90f0c0dfd0c608596a3d3a5001d6b19668a7dfe89.mp3", "duration_ms": 5520}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/3372223fbe222f940a5afcb57870050e45303d48f2bbf04b1bfac6df5d0a5171.mp3", "hash": "5e555a7c72b5d21db5223950d3fae232f5f21504eb890dac278666ffd7308bc1", "bytes": 36288, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/3372223fbe222f940a5afcb57870050e45303d48f2bbf04b1bfac6df5d0a5171.mp3", "duration_ms": 6000}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/68eabfe105f003efba5b21db72d38e4e7caf72d65d9af1ecaef453c415886e21.mp3", "hash": "0a15f57863a1b6553ba0b9332cfc8d71e5e3e9d473aff29fe35eb1c5de817f7b", "bytes": 35424, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/68eabfe105f003efba5b21db72d38e4e7caf72d65d9af1ecaef453c415886e21.mp3", "duration_ms": 5840}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/69dc434e87160866a36d69647648ff0c2505ceb2f7e41fd3b33acbb5c8c87181.mp3", "hash": "e97243e39c09c615d04f1d0638f347f5e1d1857181e5bab2c752605c3f3ca9fa", "bytes": 84816, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/69dc434e87160866a36d69647648ff0c2505ceb2f7e41fd3b33acbb5c8c87181.mp3", "duration_ms": 14080}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/e780522941503e3a2fc3ccf9330d865928c391b63f719e77119d3643b5f75c94.mp3", "hash": "2015132050b135c0f469a2bb213c2ee6b00a4f409d323273cd183c98c5b131b5", "bytes": 78624, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/e780522941503e3a2fc3ccf9330d865928c391b63f719e77119d3643b5f75c94.mp3", "duration_ms": 13040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "red-flags", "title": "Señales de alerta en el puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Detectar las señales de alerta en la oferta de un desconocido: promesas demasiado buenas no son de fiar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-red-flags", "xp": 10, "type": "red_flags", "hints": ["Piensa: ¿es normal ganar 80 pesos de la noche a la mañana sin trabajar?", "¿Conoces a ese vendedor? ¿Por qué estaría tan apurado?"], "title": "El negocio mágico", "payload": {"flags": [{"id": "f1", "text_md": "Promete mucho dinero en muy poco tiempo"}, {"id": "f2", "text_md": "El vendedor es un desconocido"}, {"id": "f3", "text_md": "El vendedor está muy apurado"}, {"id": "f4", "text_md": "No explica cómo va a ganar ese dinero"}], "artifact_md": "**Oferta relámpago:** Dame 20 pesos hoy y mañana te doy 100. ¡Solo hoy!", "artifact_kind": "ad"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Al igual que revisaste el recibo para ver cuánto costaron los limones, ahora revisa esta oferta para ver si algo no cuadra. Un vendedor apurado le dice a Liruf: ''Dame tus 20 pesos hoy y mañana te doy 100. ¡Es un negocio mágico!'' Liruf está emocionado, pero tú sabes que hay que revisar con cuidado. ¿Qué señales de alerta ves en esta oferta?", "difficulty": 1, "explanation_md": "Las promesas de ganar mucho dinero muy rápido sin esfuerzo casi siempre son falsas. El vendedor desconocido y apurado es una señal de alerta.", "audio_segment_id": "s1-red-flags.prompt"}], "schema_version": 1}', '{"s1-red-flags": {"redflag_ids": ["f1", "f2", "f3", "f4"]}}', '{"units": {"s1-red-flags.hint.0": {"url": "http://localhost:4006/files/lesson-audio/fd7d7a28ea4f0c773c29ee74e3a952aaf884f851e736cf1e13a15c03021c06d9.mp3", "hash": "b2e4333156f464060e41daf7764aeb961f491b9528be64d69237f2fa13fbb4e6", "bytes": 28656, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/fd7d7a28ea4f0c773c29ee74e3a952aaf884f851e736cf1e13a15c03021c06d9.mp3", "duration_ms": 4720}, "s1-red-flags.hint.1": {"url": "http://localhost:4006/files/lesson-audio/1d920ef7eca16f6cc9c741b2cc21c573efb54148749a0cabda27552ed5d04d59.mp3", "hash": "2d2f894723fed13f6d00e3ea348b6b6c7a023675e0d35ec4ba1e6ebac27b7223", "bytes": 23904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1d920ef7eca16f6cc9c741b2cc21c573efb54148749a0cabda27552ed5d04d59.mp3", "duration_ms": 3920}, "s1-red-flags.prompt": {"url": "http://localhost:4006/files/lesson-audio/8694accce6a641e3243dc2b700a1a7937942850baaeb28a7c38b1ce3fe36247c.mp3", "hash": "425441324940d7fe85d5e0ff6e3c694d21355a1f276d9ec43a7286cfc508444a", "bytes": 132336, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8694accce6a641e3243dc2b700a1a7937942850baaeb28a7c38b1ce3fe36247c.mp3", "duration_ms": 22000}, "s1-red-flags.explanation": {"url": "http://localhost:4006/files/lesson-audio/11da365d97db368f3dadcddfd505bbc333f1e10a70806348c1771e5fc457a7ab.mp3", "hash": "75a6a675cd821941af8b30fab7d15d88ceab9b022ef4e12e3e2a71ab592d2c79", "bytes": 57888, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/11da365d97db368f3dadcddfd505bbc333f1e10a70806348c1771e5fc457a7ab.mp3", "duration_ms": 9600}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "key-ideas", "title": "As três regras de ouro do pequeno vendedor", "locale": "pt-BR", "subject": "mixed", "objectives": ["Identificar as três ideias principais do plano de Liruf: ter uma meta de 80 reais, oferecer limonada gelada que as pessoas queiram, e guardar o que ganhou."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": [], "title": "As três regras de ouro", "payload": {"ideas": [{"icon": "emoji_events", "title": "Ter uma meta", "body_md": "Liruf quer o violão de **80 reais**. Saber quanto precisa lhe dá direção."}, {"icon": "local_cafe", "title": "Oferecer algo que as pessoas queiram", "body_md": "Limonada gelada a **5 reais** o copo. Todo mundo gosta num dia quente!"}, {"icon": "savings", "title": "Guardar o que ganhou", "body_md": "Cada real que Liruf ganha ele guarda para sua meta. Assim não gasta em outras coisas."}]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf já vendeu 10 copos de limonada e tem 50 reais. Mas lembre-se que a meta dele é o violão de 80 reais. **Ajude Liruf a decidir: o que ele deve fazer com seus 50 reais para alcançar a meta?**", "difficulty": 1, "explanation_md": "Exato! Liruf deve **guardar** os 50 reais e continuar vendendo. Se gastar em outra coisa, não alcançará os 80. Guardar o que ganhou é uma das três regras de ouro.", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/b2c0e8368b708e77892175dbad70d1fe2a9b7931f29e74328830593e65bdca7b.mp3", "hash": "f0a05d8d6a1751574acd8e85cf80004434f0572b37e7a319be340a9e62e2aaad", "bytes": 35856, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/b2c0e8368b708e77892175dbad70d1fe2a9b7931f29e74328830593e65bdca7b.mp3", "duration_ms": 5920}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/48d19ba58ffc9445475893df0d04c65230141b5df445c058de6b4a1d7daff70e.mp3", "hash": "3c185b48c26cd69aa72219d2a9f6b30bf03b0ab778503359de6fb1b24af37340", "bytes": 36864, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/48d19ba58ffc9445475893df0d04c65230141b5df445c058de6b4a1d7daff70e.mp3", "duration_ms": 6080}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/d1bdd85c08821c5f2218eb8db68ad11628f8e9c7a3df9456551199cdc651c1ac.mp3", "hash": "77a41fdbfd4c193c51b1cc216b28b6ad12dde8a7f3769261b1c621cf95a18b3c", "bytes": 40608, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/d1bdd85c08821c5f2218eb8db68ad11628f8e9c7a3df9456551199cdc651c1ac.mp3", "duration_ms": 6720}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/f8758f758a58c6fbb294c77ab49a71474a90c27abbe5c832501cf8e89cdddce6.mp3", "hash": "1638957ddb62fd213b4065540e80aab14112646f790fe1957a03ae98b5c6f926", "bytes": 96336, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/f8758f758a58c6fbb294c77ab49a71474a90c27abbe5c832501cf8e89cdddce6.mp3", "duration_ms": 16000}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/2463d89a1175e4eb906ae050c98bb080ad2a878a04bce5417e6584dd0ef058b9.mp3", "hash": "12086a9db72725cc438187f88f90784591f31abe67a0e362cf86ad84a5e0bd75", "bytes": 81504, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/2463d89a1175e4eb906ae050c98bb080ad2a878a04bce5417e6584dd0ef058b9.mp3", "duration_ms": 13520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'en-US', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "fact-opinion", "title": "Facts vs. Opinions at the Stand", "locale": "en-US", "subject": "mixed", "objectives": ["Separating facts from opinions in lemonade stand phrases"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 10, "type": "fact_opinion", "hints": ["A fact can be measured or counted, like the price of a cup.", "An opinion is what someone thinks or feels, it cannot be proven."], "title": "Fact or Opinion", "payload": {"statements": [{"id": "f1", "text_md": "The cup of lemonade costs 5 pesos."}, {"id": "f2", "text_md": "My lemonade is the tastiest in the world."}, {"id": "f3", "text_md": "Today I sold 12 cups of lemonade."}, {"id": "f4", "text_md": "This lemonade tastes better than Dina''s."}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho and Dina are at Liruf''s stand. Liruf says: ''My lemonade is the best! It costs 5 pesos and today I sold 12 cups!'' But Rho remembers that a stranger also said ''this deal is amazing'' and it turned out to be a scam. Help Rho separate what can be proven (facts) from what is just an opinion. Tap the phrases that are facts.", "difficulty": 1, "explanation_md": "The cup costs 5 pesos is a fact because you can see the price. ''The tastiest'' is an opinion, it cannot be measured. Just like the stranger exaggerated, Liruf might also be exaggerating.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["f1", "f3"]}}', '{"units": {"s1-fact-opinion.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9324b7fa28a166058fc5d8f559488e14498549f821f2ab5caf6ae46f1b9a6f1a.mp3", "hash": "0fb33f794223731d87e381f7a65d8086136411493ccdc6283fa77e86fbc6e132", "bytes": 25776, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/9324b7fa28a166058fc5d8f559488e14498549f821f2ab5caf6ae46f1b9a6f1a.mp3", "duration_ms": 4240}, "s1-fact-opinion.hint.1": {"url": "http://localhost:4006/files/lesson-audio/df5362be8f0217dec84c29f44b8a66bf5707d277604a9968f6818f89ca0deec3.mp3", "hash": "16bd75091acbc89244d9b9924113b0703e77f544381394fcf205df4a8894da92", "bytes": 28224, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/df5362be8f0217dec84c29f44b8a66bf5707d277604a9968f6818f89ca0deec3.mp3", "duration_ms": 4640}, "s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/b9ccd0e3c1ebc58cbfc08d4529679ad0b8061aa1f0e89721d9416a71f8cddfeb.mp3", "hash": "961f97496f647c19e5447a3ff7aa8d80d6a8d6e8bde1a028803054bdf5d5bcba", "bytes": 136224, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/b9ccd0e3c1ebc58cbfc08d4529679ad0b8061aa1f0e89721d9416a71f8cddfeb.mp3", "duration_ms": 22640}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/83f8476a8afea6f7b5d50f859310fb354958665f936e7e6bfe81d91a8fa2ea0a.mp3", "hash": "0dc33b6c67b7a614be467919db6fe8cee106d346762048e443e058096119462e", "bytes": 82368, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/83f8476a8afea6f7b5d50f859310fb354958665f936e7e6bfe81d91a8fa2ea0a.mp3", "duration_ms": 13680}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'pt-BR', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "fact-opinion", "title": "Fatos vs. Opiniões na Barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Separar fatos de opiniões em frases da barraca de limonada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 10, "type": "fact_opinion", "hints": ["Um fato pode ser medido ou contado, como o preço de um copo.", "Uma opinião é o que alguém pensa ou sente, não pode ser comprovada."], "title": "Fato ou Opinião", "payload": {"statements": [{"id": "f1", "text_md": "O copo de limonada custa 5 pesos."}, {"id": "f2", "text_md": "Minha limonada é a mais gostosa do mundo."}, {"id": "f3", "text_md": "Hoje vendi 12 copos de limonada."}, {"id": "f4", "text_md": "Esta limonada tem um gosto melhor que a de Dina."}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho e Dina estão na barraca de Liruf. Liruf diz: ''Minha limonada é a melhor! Custa 5 pesos e hoje vendi 12 copos!'' Mas Rho lembra que um estranho também disse ''esta oferta é incrível'' e acabou sendo um engano. Ajude Rho a separar o que pode ser comprovado (fatos) do que é apenas uma opinião. Toque nas frases que são fatos.", "difficulty": 1, "explanation_md": "O copo custa 5 pesos é um fato porque você pode ver o preço. ''A mais gostosa'' é uma opinião, não pode ser medida. Assim como o estranho exagerava, Liruf também pode estar exagerando.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["f1", "f3"]}}', '{"units": {"s1-fact-opinion.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3e9e5fb1e82e21d2764519d279a11199e5dcf2c6d3ddf1a31cf597fa084e75d0.mp3", "hash": "dc56bbf786afcb79ac4d0de4a31c927bbeab41cd1f27b1303eaa35f4e63fe719", "bytes": 28656, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/3e9e5fb1e82e21d2764519d279a11199e5dcf2c6d3ddf1a31cf597fa084e75d0.mp3", "duration_ms": 4720}, "s1-fact-opinion.hint.1": {"url": "http://localhost:4006/files/lesson-audio/ace729ab1e8064b94d4d4a580cdf8519483c219ac13fdc19eaee67d0e2d19928.mp3", "hash": "886f1e4e499c5d881c87651a9f624a049f4750d55d0d49a8f59e9ac2de25a6b4", "bytes": 31104, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/ace729ab1e8064b94d4d4a580cdf8519483c219ac13fdc19eaee67d0e2d19928.mp3", "duration_ms": 5120}, "s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/b0880efd3d2bfe4567a76b601d5613a4d514dbe94a44bb9325952cdb761e7ec2.mp3", "hash": "a103282050b3d1c2168e88677010231828af7beef1f6be546b7f749bb7631f26", "bytes": 143856, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/b0880efd3d2bfe4567a76b601d5613a4d514dbe94a44bb9325952cdb761e7ec2.mp3", "duration_ms": 23920}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/a65a7e46d3c2486080b18b98bd5ffd5400467ae8e5e0cd048f64a192204c282b.mp3", "hash": "cb471a8653c18aaeec7bf0191431bbb77cfcc7aae97a8b087015465c5b5210a9", "bytes": 81936, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/a65a7e46d3c2486080b18b98bd5ffd5400467ae8e5e0cd048f64a192204c282b.mp3", "duration_ms": 13600}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "quiz-mcq", "title": "Precio justo para la limonada", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir el precio justo para un vaso de limonada (5 pesos) entre opciones exageradas"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-justo", "xp": 10, "type": "quiz_mcq", "hints": ["Piensa: si el vaso cuesta 5 pesos, un precio justo debe ser un poquito más, pero no demasiado."], "title": "¿A cuánto el vaso?", "payload": {"options": [{"id": "a", "text_md": "5 pesos", "rationale_md": "5 pesos no da ganancia, solo recuperas el costo. ¡No ahorrarías nada!"}, {"id": "b", "text_md": "8 pesos", "rationale_md": "8 pesos es justo: ganas 3 pesos por vaso y los clientes pagan un precio razonable."}, {"id": "c", "text_md": "20 pesos", "rationale_md": "20 pesos es demasiado caro. Los clientes no pagarán tanto y no venderás nada."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Respirar y repasar: ya tienes meta (80 pesos), producto (limonada a 5 pesos) y sabes qué es costo y ganancia. ¿Cómo te sientes para abrir el puesto? Liruf está listo. Pero hay que decidir el precio. Si pones el vaso a 5 pesos, no ganas nada. Si lo pones a 20 pesos, nadie te comprará. ¿Cuál es un precio justo que te dé ganancia sin espantar a los clientes?", "difficulty": 1, "explanation_md": "¡Exacto! 8 pesos es justo: ganas 3 pesos por vaso (8 - 5 = 3) y los clientes pagan un precio razonable. ¡Así puedes ahorrar para tu patineta!", "audio_segment_id": "s1-precio-justo.prompt"}], "schema_version": 1}', '{"s1-precio-justo": {"correct_option_id": "b"}}', '{"units": {"s1-precio-justo.hint.0": {"url": "http://localhost:4006/files/lesson-audio/837114eaa54e8069f42f6eb3b852d4b023bd6516e8f77cd1c62f96d636657b04.mp3", "hash": "0348877248fa70df40071bab56b392f9893153d6f9b299aca569972dfa58ff64", "bytes": 43488, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/837114eaa54e8069f42f6eb3b852d4b023bd6516e8f77cd1c62f96d636657b04.mp3", "duration_ms": 7200}, "s1-precio-justo.prompt": {"url": "http://localhost:4006/files/lesson-audio/f547af731bf903de64b3b93cbc2192f7c91589aaed517ddc6372a40a680b12ba.mp3", "hash": "9198081bdf068c3dc97ada5a36a457994799d8585782ba3fb26eb45b15de4bf3", "bytes": 158688, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f547af731bf903de64b3b93cbc2192f7c91589aaed517ddc6372a40a680b12ba.mp3", "duration_ms": 26400}, "s1-precio-justo.choices": {"url": "http://localhost:4006/files/lesson-audio/2a0a8a33770d81e8b67f6b9850d1cb15bd8aa03a30348631d388da405c2aab39.mp3", "hash": "1ddea2453d60253f1079c7d46fcb2f4f8dc8fe3241f7f232010ce0d57c588fb7", "bytes": 22896, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2a0a8a33770d81e8b67f6b9850d1cb15bd8aa03a30348631d388da405c2aab39.mp3", "duration_ms": 3760}, "s1-precio-justo.explanation": {"url": "http://localhost:4006/files/lesson-audio/4c033e8af0e56ec391fba1499a5f02bc4155cc0cf9ff72b53f364bca34dc1400.mp3", "hash": "410d70940988791c541fb3a410a0009538f9528fc986b9ac46dd2ae2d3dc56f6", "bytes": 72288, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4c033e8af0e56ec391fba1499a5f02bc4155cc0cf9ff72b53f364bca34dc1400.mp3", "duration_ms": 12000}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "dialogue-choice", "title": "Can you give it to me for 3?", "locale": "en-US", "subject": "mixed", "objectives": ["Choosing a kind but firm response to a customer asking for a discount, without giving away the profit."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-negocia-cliente", "xp": 15, "type": "dialogue_choice", "hints": ["Think: if you lower the price too much, how much do you earn per glass?", "The customer leaves happy if you offer something fair, but without losing money."], "title": "The customer asks for a discount", "payload": {"turns": [{"id": "t1", "npc_md": "—Hi, Liruf. Will you sell me a glass of lemonade? But… can you give it to me for 3 pesos?", "replies": [{"id": "r1", "text_md": "—Sure, take it for 3 pesos."}, {"id": "r2", "text_md": "—I''m sorry, the price is 5 pesos. But I can offer you a smaller glass for 4 pesos."}, {"id": "r3", "text_md": "—No, the price is 5 pesos, not a peso less."}]}, {"id": "t2", "npc_md": "The customer thinks for a moment and replies:", "replies": [{"id": "r4", "text_md": "—Okay, I''ll take the 4-peso glass. Thanks!"}, {"id": "r5", "text_md": "—No, thanks, it''s too expensive. I''m leaving."}, {"id": "r6", "text_md": "—Okay, I''ll take the 4-peso glass. Thanks!"}]}], "persona": {"name": "Liruf", "role_md": "lemonade stand owner", "character": "liruf"}, "opening_md": "You are at your stand. A customer smiles and says:"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf is tending his lemonade stand. A customer approaches and says:", "difficulty": 2, "explanation_md": "Liruf offered a glass for 5 pesos. If he lowers it to 3, he earns only 3 pesos, but if he offers 4, the customer saves 1 peso and Liruf still earns 4. Everyone wins!", "audio_segment_id": "s1-negocia-cliente.prompt"}], "schema_version": 1}', '{"s1-negocia-cliente": {"turns": [{"turn_id": "t1", "qualities": {"r1": 20, "r2": 90, "r3": 30}, "reactions": {"r1": "El cliente se va feliz, pero Liruf ganó solo 3 pesos. Perdió 2 pesos de ganancia.", "r2": "El cliente duda, pero acepta la oferta. ¡Buen trato!", "r3": "El cliente se ofende y se va sin comprar. Liruf no vende nada."}}, {"turn_id": "t2", "qualities": {"r4": 100, "r5": 0, "r6": 100}, "reactions": {"r4": "¡Vendiste un vaso! Ganaste 4 pesos y el cliente se fue contento.", "r5": "El cliente se fue. No hubo venta. Tal vez otra oferta funcione mejor.", "r6": "¡Vendiste un vaso! Ganaste 4 pesos y el cliente se fue contento."}}]}}', '{"units": {"s1-negocia-cliente.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b96a6f8987938d5031688fcd950860bf44f2e3279eb53ce9262ca33a8f989fcb.mp3", "hash": "446f55c132e42777acfa3b97ac083ba934cdd17980c618a28ed489e4117ec6a4", "bytes": 25776, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b96a6f8987938d5031688fcd950860bf44f2e3279eb53ce9262ca33a8f989fcb.mp3", "duration_ms": 4240}, "s1-negocia-cliente.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5cfe8a485cb1aac46babe7c437fb41e012810d7967c521a6dd85e7a65d05aed7.mp3", "hash": "3e1d6d5b6d71b7fcf8d080346c37797b6b3025f34cc1acbc37586d14e835a96d", "bytes": 23328, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5cfe8a485cb1aac46babe7c437fb41e012810d7967c521a6dd85e7a65d05aed7.mp3", "duration_ms": 3840}, "s1-negocia-cliente.prompt": {"url": "http://localhost:4006/files/lesson-audio/51f1aef9dbf53605ff1fe99ef121af29afee49a357acf31f0d338567b2629208.mp3", "hash": "988a12d056a97fade6a6b3e3d128b0ad8cf790a887ecdf6bc92ab7994ad4b3c6", "bytes": 26208, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/51f1aef9dbf53605ff1fe99ef121af29afee49a357acf31f0d338567b2629208.mp3", "duration_ms": 4320}, "s1-negocia-cliente.explanation": {"url": "http://localhost:4006/files/lesson-audio/186d265a61db313b4506814d81ec32075a7e74981d43ea9b0e21a2a9493b1609.mp3", "hash": "4c420d9efe9708030b417bc6c388d201b21ab55fb2a4b98c39b5121008c7c336", "bytes": 67104, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/186d265a61db313b4506814d81ec32075a7e74981d43ea9b0e21a2a9493b1609.mp3", "duration_ms": 11120}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "number-input", "title": "¿Cuánto ganó Liruf?", "locale": "es-MX", "subject": "money", "objectives": ["Calcular y escribir cuánto ganó Liruf en total si vendió 4 vasos a 5 pesos cada uno (20 pesos)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-liruf", "xp": 10, "type": "number_input", "hints": ["Primero, ¿cuánto recibió en total por los 4 vasos?", "Luego, resta los 8 pesos que gastó."], "title": "Ganancia de Liruf", "payload": {"unit": "pesos", "decimals_hint": 0}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Recuerda que la vez pasada calculaste la ganancia de un solo vaso. ¡Ahora Liruf vendió más! Liruf gastó 8 pesos en limones y azúcar para hacer limonada. Vendió 4 vasos a 5 pesos cada uno. ¿Cuánto dinero ganó de verdad? (Ganancia = lo que recibió menos lo que gastó). Escribe el número.", "difficulty": 1, "explanation_md": "Liruf recibió 20 pesos por los vasos, pero gastó 8 en los ingredientes. Así que su ganancia real es 20 - 8 = 12 pesos. ¡Eso es lo que se queda!", "audio_segment_id": "s1-ganancia-liruf.prompt"}], "schema_version": 1}', '{"s1-ganancia-liruf": {"value": 12, "tolerance": 0}}', '{"units": {"s1-ganancia-liruf.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1b0f94829e18f72a6e421b8c8fab7d9a400e2b0191e4780052716a0072f4c005.mp3", "hash": "a6f5b0f15e4c5543294ddcf44ed89b360fb089e2bf000ad8c683bab713ace9d1", "bytes": 22464, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1b0f94829e18f72a6e421b8c8fab7d9a400e2b0191e4780052716a0072f4c005.mp3", "duration_ms": 3680}, "s1-ganancia-liruf.hint.1": {"url": "http://localhost:4006/files/lesson-audio/1a8611375744c11281bd1a9ab3c3855c82e599e04e3de239b09e3b8b95f77d20.mp3", "hash": "d881e2934509470336087ee67b83df8414ba2e49f8f2cf25886856bfb2544a70", "bytes": 17568, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1a8611375744c11281bd1a9ab3c3855c82e599e04e3de239b09e3b8b95f77d20.mp3", "duration_ms": 2880}, "s1-ganancia-liruf.prompt": {"url": "http://localhost:4006/files/lesson-audio/afb2f153df8b345ec8b66d6ebccd695292ee6c4f9e353cc6b935bb08599e574e.mp3", "hash": "7d91c8266fd5022fc62b07069394b0aa6e9534551eb9cde9046a3639c3383ab5", "bytes": 120816, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/afb2f153df8b345ec8b66d6ebccd695292ee6c4f9e353cc6b935bb08599e574e.mp3", "duration_ms": 20080}, "s1-ganancia-liruf.explanation": {"url": "http://localhost:4006/files/lesson-audio/2674669c36bb12b0ce971318a182f90938604ad76b2f6fe63f1e89919b323be6.mp3", "hash": "fb7de434954b45f7d77d56db80360490089cb72aecf1a315eb8c094bdf05e721", "bytes": 70848, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2674669c36bb12b0ce971318a182f90938604ad76b2f6fe63f1e89919b323be6.mp3", "duration_ms": 11760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'en-US', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "true-false", "title": "True or false? Savings that grow", "locale": "en-US", "subject": "mixed", "objectives": ["Decide if it''s true or false: ''If I save 5 pesos from each sale, my savings GROW every day.''"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Think: if you save 5 pesos each day, does the total amount increase or stay the same?", "Imagine you save 5 today, another 5 tomorrow... do you have more or less than yesterday?"], "title": "Catch the phrase", "payload": {"statement_md": "If I save 5 pesos from each sale, my savings GROW every day.", "justifications": [{"id": "crece", "text_md": "It''s true, because each day you add 5 more pesos to the total."}, {"id": "no-crece", "text_md": "It''s false, because the savings always stay the same."}]}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Zara says: ''If I save 5 pesos from each sale, my savings GROW every day.'' Liruf must decide if it''s true or false. What do you say?", "difficulty": 1, "explanation_md": "It''s true. If you save 5 pesos each day, your total savings increases. For example, on Monday you have 5, on Tuesday 10, on Wednesday 15... it grows every day!", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "crece"}}', '{"units": {"s1-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0f324f2d190b848f7d99a9df5b527d1c91b81fd700cc686fdbb339d74b01788d.mp3", "hash": "170e3d5d8cf29889c613ae06b627e51058275865f91baac8bcb15110e97ffd78", "bytes": 38736, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/0f324f2d190b848f7d99a9df5b527d1c91b81fd700cc686fdbb339d74b01788d.mp3", "duration_ms": 6400}, "s1-true-false.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b50534cec0cf5ecb187077aa71942c962c9ba3aff3347d87d2f4c67a77ad600b.mp3", "hash": "f67b1a6639a80917c02642540fb9662f5ced1b36330888853018eb00d2840245", "bytes": 43056, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/b50534cec0cf5ecb187077aa71942c962c9ba3aff3347d87d2f4c67a77ad600b.mp3", "duration_ms": 7120}, "s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/a326b87658a16bf251002523c6bf43a79b9528bd43fd65dd2ddd62030c224439.mp3", "hash": "28deaca84422ee257cad45f73c98b47da070d1f30a7febcd626bc3cb3025c098", "bytes": 61344, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/a326b87658a16bf251002523c6bf43a79b9528bd43fd65dd2ddd62030c224439.mp3", "duration_ms": 10160}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/fb6aa48be4a3336a03ad51eba7607574aad1812ee17342c7b20c88fcd74d99e0.mp3", "hash": "eeb3076e8e25661860cf908afefd8994bd94e9185a4ae1428fc67da50c2eaaf3", "bytes": 80496, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/fb6aa48be4a3336a03ad51eba7607574aad1812ee17342c7b20c88fcd74d99e0.mp3", "duration_ms": 13360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'en-US', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "flash-match", "title": "Stand Concept Race", "locale": "en-US", "subject": "mixed", "objectives": ["Match stand keywords with their concrete examples", "Recognize saving, cost, and profit in lemonade stand situations"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 0, "type": "flash_match", "hints": ["Think about what each word means in the lemonade stand.", "Saving is what you keep, cost is what you pay, profit is what''s left over."], "title": "Connect the Concepts", "payload": {"left": [{"id": "ahorro", "text_md": "Saving"}, {"id": "costo", "text_md": "Cost"}, {"id": "ganancia", "text_md": "Profit"}], "right": [{"id": "alcancia", "text_md": "Zara''s piggy bank with 5 pesos"}, {"id": "limones", "text_md": "8 lemons Dina bought yesterday"}, {"id": "sobra", "text_md": "2 pesos Zara earned for helping"}], "seconds": 30}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Yesterday Zara negotiated with Dina: ''If I help you sell, will you give me 2 pesos in profit?'' Dina agreed. Now Zara has 5 pesos saved in her piggy bank. What does each stand word mean? Tap the word on the left and then its example on the right. Quick!", "difficulty": 1, "explanation_md": "Each stand word has a concrete example: saving is Zara''s piggy bank where she keeps 5 pesos, cost is the 8 lemons Dina bought yesterday, and profit is the 2 pesos Zara earned for helping.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["ahorro", "alcancia"], ["costo", "limones"], ["ganancia", "sobra"]]}}', '{"units": {"s1-flash-match.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c5e94f0748b3e7ec0c5b200b250cc96d4d7fb688e002340c14203e3c1bcf24a5.mp3", "hash": "af07baf81a788983121df8e3ba1681f3b5b3b3a1025987a914c94961cf66d6d2", "bytes": 21024, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/c5e94f0748b3e7ec0c5b200b250cc96d4d7fb688e002340c14203e3c1bcf24a5.mp3", "duration_ms": 3440}, "s1-flash-match.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2276644fc0b7f0a394f09509208e794c9b1c374bf34a83f81be92e1594f11bd2.mp3", "hash": "5b8685c8769af809a7dea21c09a0a4ba0d92d08721c43c3f2417b943b5035242", "bytes": 30528, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/2276644fc0b7f0a394f09509208e794c9b1c374bf34a83f81be92e1594f11bd2.mp3", "duration_ms": 5040}, "s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/41455d151eb5261d6ea7a05f4f41d44808335495d760b2e52ea01101621ad49e.mp3", "hash": "4f35a583a786f19a5f139b2752fbe611826f503dc39baf31ca783f5c4a5928fd", "bytes": 112608, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/41455d151eb5261d6ea7a05f4f41d44808335495d760b2e52ea01101621ad49e.mp3", "duration_ms": 18720}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/b8a311b1234ead885ff001e749df146cc36d6f5663a40e5962a78022967f0299.mp3", "hash": "ffca7e7f3822364d93de7d39ca2fe51e5e7aa9b1e6eb25fc88605b121daf32ba", "bytes": 80064, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/b8a311b1234ead885ff001e749df146cc36d6f5663a40e5962a78022967f0299.mp3", "duration_ms": 13280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "best-decision", "title": "La mejor decisión al recibir cambio", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir la mejor decisión cuando un cliente paga con billete de 20 por un vaso de 5: contar el cambio con calma"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-best-decision", "xp": 10, "type": "best_decision", "hints": ["Piensa: si pagaste con 20 y cuesta 5, ¿cuánto te deben regresar?", "¿Conviene más contar con calma o adivinar el cambio?"], "title": "El cambio de Liruf", "payload": {"options": [{"id": "contar", "text_md": "Contar el cambio con calma: darle 15 pesos", "rationale_md": "Es la mejor decisión porque así Liruf da el cambio exacto y no se equivoca."}, {"id": "adivinar", "text_md": "Adivinar el cambio y darle 10 pesos", "rationale_md": "Adivinar puede hacer que des menos cambio y la clienta se enoje, o que des más y pierdas dinero."}, {"id": "quedarse", "text_md": "Dar cambio rápido sin contar, solo 5 pesos", "rationale_md": "Dar cambio rápido sin contar puede hacer que des menos de lo debido, y la clienta se iría enojada."}], "scenario_md": "Liruf está en su puesto de limonada. Una clienta le da un billete de 20 pesos por un vaso de 5 pesos. Liruf siente nervios porque es la primera vez que le pagan con un billete grande. Recuerda que los ingredientes costaron dinero, así que debe cuidar sus ganancias."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ahora que sabes qué ingredientes cuestan dinero, Liruf ya vendió su primer vaso. Una clienta paga con un billete de 20 pesos por un vaso de 5 pesos. ¿Qué debería hacer Liruf para no perder dinero ni enojar a la clienta?", "difficulty": 1, "explanation_md": "Liruf debe contar el cambio con calma: 20 menos 5 son 15 pesos. Así se asegura de dar lo correcto y no perder dinero. Si adivina, podría dar menos y la clienta se enojaría, o dar más y perder ganancias.", "audio_segment_id": "s1-best-decision.prompt"}], "schema_version": 1}', '{"s1-best-decision": {"qualities": {"contar": 100, "adivinar": 30, "quedarse": 0}}}', '{"units": {"s1-best-decision.hint.0": {"url": "http://localhost:4006/files/lesson-audio/448055e46fb171827b415a8d9ee1ebb425d9cba38e18fd80fbb282b24ee74af6.mp3", "hash": "cf397845427b6c927bca12b51fed73c91be1c76c3d5cef6739ae29bbe8d23d8a", "bytes": 29664, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/448055e46fb171827b415a8d9ee1ebb425d9cba38e18fd80fbb282b24ee74af6.mp3", "duration_ms": 4880}, "s1-best-decision.hint.1": {"url": "http://localhost:4006/files/lesson-audio/af42a0fcf837207ee621a0f81a13212fa43e69295d2133e2dd7e1dcbfea3d15b.mp3", "hash": "1ccdf51fcededd4925b0438f6cf183a0bb60342d1d2ee9f0f431d3410cac26eb", "bytes": 20448, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/af42a0fcf837207ee621a0f81a13212fa43e69295d2133e2dd7e1dcbfea3d15b.mp3", "duration_ms": 3360}, "s1-best-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/2db3e56d9654e2d2f483a088de11dcf81767880c967dae9a1e16f248b3465b9c.mp3", "hash": "33fe87f38d8ca7da11c6e4947bfe20f0f9494a7e4a4c3898c6f44f859172166a", "bytes": 85824, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2db3e56d9654e2d2f483a088de11dcf81767880c967dae9a1e16f248b3465b9c.mp3", "duration_ms": 14240}, "s1-best-decision.choices": {"url": "http://localhost:4006/files/lesson-audio/0373c2b25a48a8ce865536d6cf18378eb7911a72a2b8de45aff81248acc2229a.mp3", "hash": "9eb658f8ef66ef8626e70a08c2099ec86fa0a190b5a003d714aa78067a607007", "bytes": 61344, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0373c2b25a48a8ce865536d6cf18378eb7911a72a2b8de45aff81248acc2229a.mp3", "duration_ms": 10160}, "s1-best-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/a22bd8111edf864017213e5eed1117a11505e16e2a48e86c63f9f5992947e1a0.mp3", "hash": "ed9e68222b55a8eb889a2d5e2044e1c5d8a8d476d4c16f1d0cefa876e84ccd7f", "bytes": 91584, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a22bd8111edf864017213e5eed1117a11505e16e2a48e86c63f9f5992947e1a0.mp3", "duration_ms": 15200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'pt-BR', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "flash-match", "title": "Corrida de conceitos do posto", "locale": "pt-BR", "subject": "mixed", "objectives": ["Relacionar palavras-chave do posto com seus exemplos concretos", "Reconhecer poupança, custo e lucro em situações do posto de limonada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 0, "type": "flash_match", "hints": ["Pense no que cada palavra significa no posto de limonada.", "A poupança é o que você guarda, o custo é o que você paga, o lucro é o que sobra."], "title": "Conecte os conceitos", "payload": {"left": [{"id": "ahorro", "text_md": "Poupança"}, {"id": "costo", "text_md": "Custo"}, {"id": "ganancia", "text_md": "Lucro"}], "right": [{"id": "alcancia", "text_md": "Cofrinho de Zara com 5 reais"}, {"id": "limones", "text_md": "8 limões que Dina comprou ontem"}, {"id": "sobra", "text_md": "2 reais que Zara ganhou por ajudar"}], "seconds": 30}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Ontem Zara negociou com Dina: ''Se eu te ajudar a vender, você me dá 2 reais de lucro?'' Dina aceitou. Agora Zara tem 5 reais guardados no seu cofrinho. O que significa cada palavra do posto? Toque na palavra da esquerda e depois no seu exemplo da direita. Rápido!", "difficulty": 1, "explanation_md": "Cada palavra do posto tem um exemplo concreto: poupança é o cofrinho de Zara onde ela guarda 5 reais, custo são os 8 limões que Dina comprou ontem, e lucro são os 2 reais que Zara ganhou por ajudar.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["ahorro", "alcancia"], ["costo", "limones"], ["ganancia", "sobra"]]}}', '{"units": {"s1-flash-match.hint.0": {"url": "http://localhost:4006/files/lesson-audio/eef68ce6de037c53c89e952dc2198e779c89acc0ef85dc5191cdd18116bd026a.mp3", "hash": "05c6cd6d157c9d262256c234137fd22ee223195b582bba3c3454604a34e51901", "bytes": 21456, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/eef68ce6de037c53c89e952dc2198e779c89acc0ef85dc5191cdd18116bd026a.mp3", "duration_ms": 3520}, "s1-flash-match.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c749fa6d714a1a184c741813b03974c545aae4f197025b39c56e5663c729283a.mp3", "hash": "4b809f913a5fd627c162db37e610ee71dc5b290fd5eddc7d8fcf3080f052b467", "bytes": 35424, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/c749fa6d714a1a184c741813b03974c545aae4f197025b39c56e5663c729283a.mp3", "duration_ms": 5840}, "s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/f9e5a51bb4e6f70f4e3906271dd063c1ed04f349db960463c1af72de9caa46ff.mp3", "hash": "d7d7b005aa02aa506192c966c5d40d73b04fd13dd65d9da7698dce0b83331af4", "bytes": 108864, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/f9e5a51bb4e6f70f4e3906271dd063c1ed04f349db960463c1af72de9caa46ff.mp3", "duration_ms": 18080}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/9b3a2d3b3296b2685e9035f6f75619f233a97b9f10f797ee2cd64aaa1b90676c.mp3", "hash": "af71d45a7ca70859d193b4b0fdfc0024c2f7ee5b5bdc0340c607ecf803977ec1", "bytes": 80928, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/9b3a2d3b3296b2685e9035f6f75619f233a97b9f10f797ee2cd64aaa1b90676c.mp3", "duration_ms": 13440}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "picture-choice", "title": "Choose the safest place", "locale": "en-US", "subject": "mixed", "objectives": ["Choose with images the safest place to keep the day''s earnings: the lockable piggy bank (not the torn pocket or the stall table)."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lugar-seguro", "xp": 10, "type": "picture_choice", "hints": ["Think: in which place is the money most protected?", "Imagine leaving your coins in a place where only you can open it."], "title": "Where do you keep your money?", "payload": {"options": [{"id": "alcancia", "icon": "lock", "label": "Lockable piggy bank", "image_url": "http://localhost:4006/files/lesson-images/969d02b3305f1757763e426012eea915a7a4fe9df2d4f274cfaaf148668b4c16.png"}, {"id": "bolsillo", "icon": "checkroom", "label": "Torn pocket", "image_url": "http://localhost:4006/files/lesson-images/23673b2b3632d2c627a9b86858a270c26d33d1636250426026522118088720b4.png", "rationale_md": "The pocket has a hole, the coins would fall out and get lost. Your savings would escape."}, {"id": "mesa", "icon": "table_restaurant", "label": "Stall table", "image_url": "http://localhost:4006/files/lesson-images/bad1b24fb80f59a268da01824b267df647f7b286bcf4a213f73a35e77aac869d.png", "rationale_md": "The table is in plain sight of everyone, anyone could take the money. Your savings would not be protected."}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Yesterday Liruf saved 5 pesos in his piggy bank. Today he sold lemonade and has 20 more pesos. His savings are growing. Where should he put these coins so his savings are safe?", "difficulty": 1, "explanation_md": "The lockable piggy bank is the safest place because only Liruf can open it. That way his savings of 25 pesos won''t get lost or stolen. The pocket has a hole and the table is within everyone''s reach.", "audio_segment_id": "s1-lugar-seguro.prompt"}], "schema_version": 1}', '{"s1-lugar-seguro": {"correct_option_id": "alcancia"}}', '{"units": {"s1-lugar-seguro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/663dd8f5e91ba65c897be0014f18a0909202656d8e213425d5d0056d0d3fd555.mp3", "hash": "431b393ed31feeab116c44474ed6852186784b9db55e5eccb5eb701ca30c451c", "bytes": 16704, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/663dd8f5e91ba65c897be0014f18a0909202656d8e213425d5d0056d0d3fd555.mp3", "duration_ms": 2720}, "s1-lugar-seguro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6787c6f4a4278ddc66f3e6786f51b3f5d8902ace0df17ffc011e8c4b2d34a203.mp3", "hash": "859447c4b1b09b0359b5d8cc55df704ebb3bc71ee741117efcd95af87a4b0219", "bytes": 19584, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6787c6f4a4278ddc66f3e6786f51b3f5d8902ace0df17ffc011e8c4b2d34a203.mp3", "duration_ms": 3200}, "s1-lugar-seguro.prompt": {"url": "http://localhost:4006/files/lesson-audio/5e71b238d793ef2c69cb8873f235889aeac4206ad3548a110da71957557dfdbc.mp3", "hash": "6e7b8f0ed117272442c7b434026f55303e91e722d458dacb776c1db204057b67", "bytes": 58896, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5e71b238d793ef2c69cb8873f235889aeac4206ad3548a110da71957557dfdbc.mp3", "duration_ms": 9760}, "s1-lugar-seguro.choices": {"url": "http://localhost:4006/files/lesson-audio/ded1a5efb691dc1cb54affbe7c34d7c4d292a88528b43d9c0181df5462885764.mp3", "hash": "e9e00b2cae04edbd88033d7161ec08101753cc0e18968b413793aa65749160c8", "bytes": 18576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ded1a5efb691dc1cb54affbe7c34d7c4d292a88528b43d9c0181df5462885764.mp3", "duration_ms": 3040}, "s1-lugar-seguro.explanation": {"url": "http://localhost:4006/files/lesson-audio/b368cc71d8fef752a8d96236e63de9003870e3b97742d688ef7cae5e2020dd4b.mp3", "hash": "baadee7a9170655027466818ef3f8032ecb4df47fc38347dcc1a8ebb4ee484e9", "bytes": 66528, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b368cc71d8fef752a8d96236e63de9003870e3b97742d688ef7cae5e2020dd4b.mp3", "duration_ms": 11040}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "speed-tap", "title": "¡Agarra lo que ayuda!", "locale": "es-MX", "subject": "money", "objectives": ["Distinguir gastos que ayudan al puesto de limonada de caprichos que no."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 10, "type": "speed_tap", "hints": ["Piensa: ¿esto ayuda a hacer o vender limonada?", "Los limones, vasos, azúcar, hielo y cartel ayudan. Las calcomanías, dulces y juguetes no."], "title": "¡Agarra lo que ayuda!", "payload": {"items": [{"id": "limones", "text_md": "Más limones"}, {"id": "vasos", "text_md": "Bolsa de vasos"}, {"id": "azucar", "text_md": "Azúcar"}, {"id": "hielo", "text_md": "Hielo"}, {"id": "cartel", "text_md": "Cartel llamativo"}, {"id": "calcomania", "text_md": "Calcomanía de dinosaurio"}, {"id": "dulce", "text_md": "Dulce"}, {"id": "juguete", "text_md": "Juguete"}], "seconds": 15, "instruction_md": "Toca las tarjetas que ayudan al puesto de limonada. ¡Rápido!"}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho pasa volando tarjetas de compras. Toca solo las que ayudan a vender MÁS limonada. ¡Deja pasar los caprichos!", "difficulty": 1, "explanation_md": "Los limones, vasos, azúcar, hielo y cartel hacen que puedas vender más limonada. La calcomanía, el dulce y el juguete son caprichos que no ayudan al puesto.", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["limones", "vasos", "azucar", "hielo", "cartel"]}}', '{"units": {"s1-speed-tap.hint.0": {"url": "http://localhost:4006/files/lesson-audio/420df2ec06ffdf8980611cf7a1545980edb80c82b4f5dab33d659280ffad46c7.mp3", "hash": "b74c6a35b9c21ba38793887f8364602e372009ad7af6ed37f22293a99f7ea736", "bytes": 23328, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/420df2ec06ffdf8980611cf7a1545980edb80c82b4f5dab33d659280ffad46c7.mp3", "duration_ms": 3840}, "s1-speed-tap.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f76316a8a365109e06a95b1db65b2d362902fea1dad99e97831a1b1464360955.mp3", "hash": "92668726bd2694df4e18e1f83d848213c5fd7b9d9d499ed208cc42d66d500f1e", "bytes": 51264, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/f76316a8a365109e06a95b1db65b2d362902fea1dad99e97831a1b1464360955.mp3", "duration_ms": 8480}, "s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/30651d01b498e20321ab10ada0be5690d907989479518c481a8c132f00252553.mp3", "hash": "67c3e2c4b242ae55eae7583d6da109a56096a9203e14831b1e9bab11f1a0e15c", "bytes": 50688, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/30651d01b498e20321ab10ada0be5690d907989479518c481a8c132f00252553.mp3", "duration_ms": 8400}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/a9584fd4473b397e27ca60cff87589f16a0953426cbb36981d439fa370a1087a.mp3", "hash": "c438fac6f4c6b25e6e4c58725eefc7ecdaa666509e89595ff87987fd7bcca14b", "bytes": 78624, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/a9584fd4473b397e27ca60cff87589f16a0953426cbb36981d439fa370a1087a.mp3", "duration_ms": 13040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'es-MX', '1', E'{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "price-compare", "title": "Comparar precios de limones", "locale": "es-MX", "subject": "mixed", "objectives": ["Comparar precios de limones en dos puestos del mercado y elegir el más barato para gastar menos (costo más bajo = más ganancia)."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 10, "type": "price_compare", "hints": ["Como los dos puestos venden la misma cantidad de limones, solo compara el precio total. El que cueste menos te deja más dinero para la guitarra."], "title": "¿Cuál puesto conviene?", "payload": {"offers": [{"id": "dina", "qty": 10, "unit": "limones", "label": "Puesto de Dina", "price": 12}, {"id": "rho", "qty": 10, "unit": "limones", "label": "Puesto de Rho", "price": 15}], "currency": "MXN"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf necesita comprar limones para su puesto de limonada. Recuerda: primero compramos lo que necesita el puesto, y buscamos la mejor oferta para gastar menos.\\n\\nEn el mercado hay dos puestos que venden limones:\\n- **Puesto de Dina**: 10 limones por 12 pesos.\\n- **Puesto de Rho**: 10 limones por 15 pesos.\\n\\nAmbos venden la misma cantidad de limones. ¿Cuál puesto tiene el precio total más bajo? Toca el que conviene para ahorrar más dinero.", "difficulty": 1, "explanation_md": "Ambos puestos venden 10 limones, pero el puesto de Dina cuesta 12 pesos y el de Rho cuesta 15 pesos. Comprar en el puesto de Dina te ahorra 3 pesos para la meta de la guitarra. ¡Elegir la oferta más barata es una forma de gastar menos!", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "dina"}}', '{"units": {"s1-price-compare.hint.0": {"url": "http://localhost:4006/files/lesson-audio/11479c2edaa461e3b54c31afcdb3c1fe0cc5cd100a0720fb598192de843eef64.mp3", "hash": "e7798992cde3de6820be56fcdfaa10de199ce1894ea45ec8675a898dd890ed3a", "bytes": 55008, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/11479c2edaa461e3b54c31afcdb3c1fe0cc5cd100a0720fb598192de843eef64.mp3", "duration_ms": 9120}, "s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/6a76bd1b49c9db896c704815f1930d492ba98ee7c8e8db766d1165ec0665c86d.mp3", "hash": "988a4d7ba9cbf69dc01e443d16926d0a9223a2293ec9984f30424b2f59eac4d6", "bytes": 169344, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6a76bd1b49c9db896c704815f1930d492ba98ee7c8e8db766d1165ec0665c86d.mp3", "duration_ms": 28160}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/88857498330ced4e6e95e7693aa857b51ae6ed8b6ab3605e7752a99b51f92c21.mp3", "hash": "22914a647b1150c1f73beb3e3fc692173afccf4155c8933b3cfa2a4555be0c39", "bytes": 94464, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/88857498330ced4e6e95e7693aa857b51ae6ed8b6ab3605e7752a99b51f92c21.mp3", "duration_ms": 15680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'pt-BR', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "code-order", "title": "Construa a registradora de papelão", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar as instruções da registradora caseira: receber pagamento, verificar valor, dar troco, anotar a venda."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-registradora", "xp": 10, "type": "code_order", "hints": ["O que você faz primeiro quando alguém te paga?", "Depois de receber o dinheiro, o que você deve verificar para não dar troco a mais?"], "title": "A registradora de papelão", "payload": {"blocks": [{"id": "recibir", "text_md": "Receber pagamento"}, {"id": "verificar", "text_md": "Verificar valor"}, {"id": "dar_cambio", "text_md": "Dar troco"}, {"id": "anotar", "text_md": "Anotar a venda"}], "language_hint": "Ordene os passos da registradora."}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Na semana passada você escolheu entre ganhar 10 reais hoje ou 20 depois. Hoje, Rho já tem uma venda: Dina compra um caderno de 12 reais e paga com uma nota de 20. Rho sabe que deve dar 8 de troco. Mas se pular uma etapa, pode dar 10 em vez de 8 e perder dinheiro! Ajude Rho a ordenar os passos para não errar. Toque nos blocos na ordem correta.", "difficulty": 1, "explanation_md": "A ordem correta é: receber pagamento, verificar valor, dar troco, anotar a venda. Se Rho verificar primeiro o valor, sabe quanto troco dar. Se anotar antes de dar o troco, pode se confundir e dar o troco errado. Se você colocou ''anotar'' antes de ''dar troco'', Rho poderia dar 10 em vez de 8 e perder 2 reais. Assim Rho não perde dinheiro!", "audio_segment_id": "s1-ordenar-registradora.prompt"}], "schema_version": 1}', '{"s1-ordenar-registradora": {"order": ["recibir", "verificar", "dar_cambio", "anotar"]}}', '{"units": {"s1-ordenar-registradora.hint.0": {"url": "http://localhost:4006/files/lesson-audio/56a2b1be7a54cc428a950197876158c5c41c846c5f57901678f3e7d3b9db5062.mp3", "hash": "317cbad2a7cd40376b360afaa59596572abb4e48c5ce8ac1437ca5a74bacd03f", "bytes": 18144, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/56a2b1be7a54cc428a950197876158c5c41c846c5f57901678f3e7d3b9db5062.mp3", "duration_ms": 2960}, "s1-ordenar-registradora.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a171ef119965ffde837fe490400c338a8c383fe1ddec3e6bd77e34a3b8f9d095.mp3", "hash": "4f0c9ea8b9113ec1a2b12336edc8831660889876b2f9a9d7a9851e3692471a5b", "bytes": 31968, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/a171ef119965ffde837fe490400c338a8c383fe1ddec3e6bd77e34a3b8f9d095.mp3", "duration_ms": 5280}, "s1-ordenar-registradora.prompt": {"url": "http://localhost:4006/files/lesson-audio/48599433965af2296744066664e74a27495af3d6f06a4444d35abde4da18ddbc.mp3", "hash": "594a3c7218bbecb256e18eb6eb33fffed68f1e7dc4b0a184eb108df537e5831d", "bytes": 153936, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/48599433965af2296744066664e74a27495af3d6f06a4444d35abde4da18ddbc.mp3", "duration_ms": 25600}, "s1-ordenar-registradora.explanation": {"url": "http://localhost:4006/files/lesson-audio/f256cf58a247d0393dafded6b8f4c76bce21cd98e34881349df87955d7a1930e.mp3", "hash": "d393ca63abd4d8865091c48f3897b44703fc042b4c20781ba79d974b1ae8a317", "bytes": 175104, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/f256cf58a247d0393dafded6b8f4c76bce21cd98e34881349df87955d7a1930e.mp3", "duration_ms": 29120}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "Dizer sim ou não, caso a caso", "locale": "pt-BR", "subject": "mixed", "objectives": ["Decidir se um gasto ajuda a barraca de limonada ou não, baseado em se é uma necessidade ou uma tentação."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 10, "type": "yes_no_cases", "hints": ["Pense: isso ajuda a vender mais limonada ou a melhorá-la?", "Se é para a barraca hoje, talvez sim. Se é um gosto pessoal, melhor esperar."], "title": "Gasto que ajuda ou tentação?", "payload": {"cases": [{"id": "case-limones", "text_md": "Comprar mais limões para fazer mais limonada."}, {"id": "case-juguete", "text_md": "Comprar um brinquedo novo hoje na loja."}, {"id": "case-vasos", "text_md": "Comprar copos descartáveis para servir a limonada."}, {"id": "case-dulces", "text_md": "Comprar doces para comer enquanto trabalha."}], "rule_md": "Pergunte-se: **isso ajuda a barraca a funcionar melhor ou vender mais?** Se a resposta for sim, é um gasto que vale a pena. Se é só um desejo, melhor guardar o dinheiro."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Agora que Liruf sabe dar o troco certo de uma nota de $20 por uma limonada de $5, Dina pergunta: ''Devemos gastar nisso para a barraca ou é uma tentação?'' Ajude Liruf a decidir para cada caso.", "difficulty": 1, "explanation_md": "Comprar mais limões ajuda a fazer mais limonada e ganhar mais dinheiro. Um brinquedo novo não ajuda a barraca hoje.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["case-limones", "case-vasos"]}}', '{"units": {"s1-yes-no-cases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5139de983f8fe3fa697c93f290bbc7e7ef16248eb2575e4a3fe4f15d0a273373.mp3", "hash": "55f947b59d16ab622ab8941dd16ace4c00a00b24825efd1948e0bfa92ceb4a3c", "bytes": 27216, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5139de983f8fe3fa697c93f290bbc7e7ef16248eb2575e4a3fe4f15d0a273373.mp3", "duration_ms": 4480}, "s1-yes-no-cases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/e4149be88cf40446991b3e87a339226db5a7d70c11e084121d15cc1877c32ca3.mp3", "hash": "32329901f4349c0f77c4b0d9447d92e1211a9c6e0ba69a45fab866ce636a5eab", "bytes": 34416, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e4149be88cf40446991b3e87a339226db5a7d70c11e084121d15cc1877c32ca3.mp3", "duration_ms": 5680}, "s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/75c71952244aab63b93a064bcbe71baa4ea40c1c4d88ec3c0d154ca44508871c.mp3", "hash": "7b199ed483de1b255e26b43f54c8868409df97e4f04596ff0258cd2e44310879", "bytes": 80496, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/75c71952244aab63b93a064bcbe71baa4ea40c1c4d88ec3c0d154ca44508871c.mp3", "duration_ms": 13360}, "s1-yes-no-cases.choices": {"url": "http://localhost:4006/files/lesson-audio/d5edcb6ca60c605f42c07301579a0c8850e841aceada7567a7ed98e7238299a1.mp3", "hash": "b32391bd2c54eacb2ca92cbe19cc40d85726edb1b97ac156079e9c4895c71837", "bytes": 77616, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d5edcb6ca60c605f42c07301579a0c8850e841aceada7567a7ed98e7238299a1.mp3", "duration_ms": 12880}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/43a2182a45fea8413682ec1e39d69335175223ae612c7da543441cf189473ac7.mp3", "hash": "18b6a68c265aa6e1e81ab34bd1bb37edd202caba84f6374323cfc94ac6502ad7", "bytes": 52128, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/43a2182a45fea8413682ec1e39d69335175223ae612c7da543441cf189473ac7.mp3", "duration_ms": 8640}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "debug-hunt", "title": "Bug Hunt", "locale": "en-US", "subject": "mixed", "objectives": ["Find the error in the promotion poster and fix it"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug", "xp": 15, "type": "debug_hunt", "hints": ["How much does a normal cup cost?", "Compare the price of 2 loose cups with the promotion."], "title": "The Wrong Poster", "payload": {"blocks": [{"id": "b1", "text_md": "2 cups for 8 pesos"}, {"id": "b2", "text_md": "it''s more expensive than buying them loose!"}, {"id": "b3", "text_md": "Normal price: 5 pesos per cup"}], "intro_md": "Liruf hung a poster with a promotion. But something doesn''t add up. Help him find the error."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "After helping the cart save steps, now help it save money. Liruf put up a poster that says: ''2 cups for 8 pesos''. But customers are laughing. What is the error?", "difficulty": 2, "explanation_md": "One cup costs 5 pesos. Two loose cups cost 5 + 5 = 10 pesos. The promotion of 8 pesos is cheaper, not more expensive. The error is saying ''it''s more expensive''.", "audio_segment_id": "s1-debug.prompt"}], "schema_version": 1}', '{"s1-debug": {"fix_md": "¡sale más barato que comprarlos sueltos!", "bug_ids": ["b2"]}}', '{"units": {"s1-debug.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ac605bb8c83c713de84df8680bf4a5ceed5a2c12d5425589517ba4d923927a2a.mp3", "hash": "bfbd52a12e9e6331c40badebd10d7f15d493938f24b0835d0414a340b0593869", "bytes": 11808, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ac605bb8c83c713de84df8680bf4a5ceed5a2c12d5425589517ba4d923927a2a.mp3", "duration_ms": 1920}, "s1-debug.hint.1": {"url": "http://localhost:4006/files/lesson-audio/1c68c7c3861d4d2ee5fba7ddbb39d2c183a3c41fa90a3767ce601d569dd04786.mp3", "hash": "98f2bd8191879a60d3abe45a71b990a56f60fd332573a6929e51673e59328ef6", "bytes": 17136, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1c68c7c3861d4d2ee5fba7ddbb39d2c183a3c41fa90a3767ce601d569dd04786.mp3", "duration_ms": 2800}, "s1-debug.prompt": {"url": "http://localhost:4006/files/lesson-audio/21bfd54ca3c4624064464f00a793ff85b747ebd97ac947573f1bcadc6cf2c2b4.mp3", "hash": "138e46f7a69ab01183b92c7a0199366b3ddec31ea7d7fc38c0d23654b134d2af", "bytes": 58896, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/21bfd54ca3c4624064464f00a793ff85b747ebd97ac947573f1bcadc6cf2c2b4.mp3", "duration_ms": 9760}, "s1-debug.explanation": {"url": "http://localhost:4006/files/lesson-audio/c13d14fe893417e8954c7232a69f77ebd80b0b39899eeb5b95d24cd69255909f.mp3", "hash": "b276e8cad4bcdb79c8029bc7e23028e65e9e519af09120f69822f40f65447fc0", "bytes": 69408, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c13d14fe893417e8954c7232a69f77ebd80b0b39899eeb5b95d24cd69255909f.mp3", "duration_ms": 11520}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "confidence-quiz", "title": "Confianza en tus cuentas", "locale": "es-MX", "subject": "mixed", "objectives": ["Sumar dos vasos de limonada (5+5) y evaluar tu nivel de confianza en el resultado."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confianza", "xp": 10, "type": "confidence_quiz", "hints": ["Recuerda: solo las monedas de verdad cuentan. La tapita no es dinero.", "Cuenta las monedas de 5 pesos: una son 5, dos son..."], "title": "¿Cuánto dinero ganaste?", "payload": {"options": [{"id": "opt-10", "text_md": "10 pesos", "rationale_md": "Sumaste las dos monedas de 5 pesos y supiste que la tapita no cuenta. ¡Correcto!"}, {"id": "opt-5", "text_md": "5 pesos", "rationale_md": "Tal vez solo contaste una moneda y olvidaste la otra. Liruf tiene dos monedas de 5, no una."}, {"id": "opt-15", "text_md": "15 pesos", "rationale_md": "Quizás contaste la tapita como si fuera una moneda de 5 pesos. Pero las tapitas no son dinero, solo las monedas de verdad cuentan."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf tiene dos monedas en la mano. Una es de 5 pesos, la otra es de 5 pesos. Pero entre sus juguetes hay una tapita de botella que parece moneda. ¿Cuánto dinero de verdad tiene Liruf en la mano? Después elige qué tan seguro estás de tu respuesta.", "difficulty": 1, "explanation_md": "Liruf tiene dos monedas de 5 pesos, así que tiene 10 pesos en total. La tapita de botella no vale dinero, aunque se parezca. ¡Bien por no dejarte engañar!", "audio_segment_id": "s1-confianza.prompt"}], "schema_version": 1}', '{"s1-confianza": {"correct_option_id": "opt-10"}}', '{"units": {"s1-confianza.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c1217009022c29c1907a3d590f81243c3064bc3dbfbbf2030dad416bd70ff11a.mp3", "hash": "35c9f577476e5842a1e304692331936a3a5c4c38fe4d5d2c121d64442314c0da", "bytes": 31104, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c1217009022c29c1907a3d590f81243c3064bc3dbfbbf2030dad416bd70ff11a.mp3", "duration_ms": 5120}, "s1-confianza.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c861549ca4dcbc1a21500077d5ef270d710e4c625e4399a3b81f0da4b55911a3.mp3", "hash": "58661e8ebb1dd6e73fcf25002467562949ff81c5028cdfe959b20bd082e431c1", "bytes": 26208, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c861549ca4dcbc1a21500077d5ef270d710e4c625e4399a3b81f0da4b55911a3.mp3", "duration_ms": 4320}, "s1-confianza.prompt": {"url": "http://localhost:4006/files/lesson-audio/55e5c2390348064fb4145ddff6e73866ac3808074029687f968bb226a35c5294.mp3", "hash": "d65899433dc048bd77b1b9e43a5102803423a3c1bc5ca07978be1deb6c31f734", "bytes": 94464, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/55e5c2390348064fb4145ddff6e73866ac3808074029687f968bb226a35c5294.mp3", "duration_ms": 15680}, "s1-confianza.choices": {"url": "http://localhost:4006/files/lesson-audio/40d1a7a89093d5c967b69127823a71e0face1653d99cd72e5f4f374e2e156256.mp3", "hash": "09a687c1188d8c459b90d8f4dcf00bda27979ca0ef2c46170b925538101755b4", "bytes": 21888, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/40d1a7a89093d5c967b69127823a71e0face1653d99cd72e5f4f374e2e156256.mp3", "duration_ms": 3600}, "s1-confianza.explanation": {"url": "http://localhost:4006/files/lesson-audio/ea7f5f0dfac6c696727990c10fa7a2740c501ce6a9331dd3a130337c5bfc1797.mp3", "hash": "9a5fcfc41050f4c491cf8ddba8a3c3091e5c462fa5b0a2af268488e173f7e9ba", "bytes": 63216, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/ea7f5f0dfac6c696727990c10fa7a2740c501ce6a9331dd3a130337c5bfc1797.mp3", "duration_ms": 10480}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "debug-hunt", "title": "Caça aos erros", "locale": "pt-BR", "subject": "mixed", "objectives": ["Encontrar o erro no cartaz de promoção e corrigi-lo"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug", "xp": 15, "type": "debug_hunt", "hints": ["Quanto custa um copo normal?", "Compare o preço de 2 copos avulsos com o da promoção."], "title": "O cartaz errado", "payload": {"blocks": [{"id": "b1", "text_md": "2 copos por 8 pesos"}, {"id": "b2", "text_md": "sai mais caro do que comprá-los avulsos!"}, {"id": "b3", "text_md": "Preço normal: 5 pesos cada copo"}], "intro_md": "Liruf pendurou um cartaz com uma promoção. Mas algo não está certo. Ajude-o a encontrar o erro."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Depois de ajudar o carrinho a economizar passos, agora ajude-o a economizar dinheiro. Liruf colocou um cartaz que diz: ''2 copos por 8 pesos''. Mas os clientes estão rindo. Qual é o erro?", "difficulty": 2, "explanation_md": "Um copo custa 5 pesos. Dois copos avulsos custam 5 + 5 = 10 pesos. A promoção de 8 pesos é mais barata, não mais cara. O erro está em dizer ''sai mais caro''.", "audio_segment_id": "s1-debug.prompt"}], "schema_version": 1}', '{"s1-debug": {"fix_md": "¡sale más barato que comprarlos sueltos!", "bug_ids": ["b2"]}}', '{"units": {"s1-debug.hint.0": {"url": "http://localhost:4006/files/lesson-audio/95e9a1b653199887ffece7369dd60a8620238470c620798f85534a65dddeadd8.mp3", "hash": "00f1fe036209530100b248351b8d0786fc751ff77d04bc890c0c57b6662159b9", "bytes": 13824, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/95e9a1b653199887ffece7369dd60a8620238470c620798f85534a65dddeadd8.mp3", "duration_ms": 2240}, "s1-debug.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b227c41d1ae60230046b5c62881c50afc3c1206f981a6e6ff99544af44a010e2.mp3", "hash": "6b46e7b32aa56713d262747d1007d56aa0a257ebb453431e1c83692f776a8948", "bytes": 24336, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b227c41d1ae60230046b5c62881c50afc3c1206f981a6e6ff99544af44a010e2.mp3", "duration_ms": 4000}, "s1-debug.prompt": {"url": "http://localhost:4006/files/lesson-audio/efc1db361109033921829f57a27521324f44d82fc2b437a386ab88fa6a0c1b15.mp3", "hash": "d2966a6124e62e5073a4164745ed8a7a6479817b746ca86f41a22656ec185553", "bytes": 80928, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/efc1db361109033921829f57a27521324f44d82fc2b437a386ab88fa6a0c1b15.mp3", "duration_ms": 13440}, "s1-debug.explanation": {"url": "http://localhost:4006/files/lesson-audio/1ac7b1e4131953cae2aa1bcc0817143e80df11fed1c026e46df1d64f67e6758b.mp3", "hash": "09cc30aa49f4dc4c33d87259cea1875f03413960ba5d52ebf4107473ccd8b694", "bytes": 82944, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1ac7b1e4131953cae2aa1bcc0817143e80df11fed1c026e46df1d64f67e6758b.mp3", "duration_ms": 13760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "number-input", "title": "Quanto Liruf ganhou?", "locale": "pt-BR", "subject": "money", "objectives": ["Calcular e escrever quanto Liruf ganhou no total se vendeu 4 copos a 5 pesos cada (20 pesos)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-liruf", "xp": 10, "type": "number_input", "hints": ["Primeiro, quanto ele recebeu no total pelos 4 copos?", "Depois, subtraia os 8 pesos que gastou."], "title": "Lucro de Liruf", "payload": {"unit": "pesos", "decimals_hint": 0}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Lembra que da outra vez você calculou o lucro de um único copo. Agora Liruf vendeu mais! Liruf gastou 8 pesos em limões e açúcar para fazer limonada. Vendeu 4 copos a 5 pesos cada. Quanto dinheiro ele realmente ganhou? (Lucro = o que recebeu menos o que gastou). Escreva o número.", "difficulty": 1, "explanation_md": "Liruf recebeu 20 pesos pelos copos, mas gastou 8 nos ingredientes. Então seu lucro real é 20 - 8 = 12 pesos. É isso que ele fica!", "audio_segment_id": "s1-ganancia-liruf.prompt"}], "schema_version": 1}', '{"s1-ganancia-liruf": {"value": 12, "tolerance": 0}}', '{"units": {"s1-ganancia-liruf.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b1deaf019b78ff23c6b41a6936e436561f55c16924af172b57ab5ba640912d9b.mp3", "hash": "83d8461bf7640d1834281d7b07eab4138b4877565c674ba8062dbf55f8c0ab30", "bytes": 22896, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b1deaf019b78ff23c6b41a6936e436561f55c16924af172b57ab5ba640912d9b.mp3", "duration_ms": 3760}, "s1-ganancia-liruf.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c1fac052b0a08facb35f0bb3e35f2e04da017fae72cf68f21a631643d30c531e.mp3", "hash": "ebd5c27522acd0484979add70af28c1c00bdcd08a50140225e9d0626632af223", "bytes": 21888, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c1fac052b0a08facb35f0bb3e35f2e04da017fae72cf68f21a631643d30c531e.mp3", "duration_ms": 3600}, "s1-ganancia-liruf.prompt": {"url": "http://localhost:4006/files/lesson-audio/c67225c1a374ca4d8733534fe664e3aa185d4b4640c3ca2c5cb7a37c74a08032.mp3", "hash": "67ab950f5309f40cfa38ae691105c60b293cbda8cbf6097469225ef4a8d2ef64", "bytes": 125136, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c67225c1a374ca4d8733534fe664e3aa185d4b4640c3ca2c5cb7a37c74a08032.mp3", "duration_ms": 20800}, "s1-ganancia-liruf.explanation": {"url": "http://localhost:4006/files/lesson-audio/b001ead0191322bdc52d7ea0c8b0401aa768b198f3ec993110e0992faaedf516.mp3", "hash": "b018721c8708c13ade875b1b3a3950bf91e7f6c10f7630ab5e611953848794e0", "bytes": 70416, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b001ead0191322bdc52d7ea0c8b0401aa768b198f3ec993110e0992faaedf516.mp3", "duration_ms": 11680}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'es-MX', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "estimate-slider", "title": "Estima cuántos vasos salen de la jarra", "locale": "es-MX", "subject": "mixed", "objectives": ["Estimar cantidades usando una barra deslizante", "Relacionar el tamaño de una jarra con la cantidad de vasos que puede llenar"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-jar", "xp": 8, "type": "estimate_slider", "hints": ["Piensa: la jarra de Liruf llenaba 4 vasos. La de Zara es el doble de grande, así que puede llenar más vasos.", "Si el doble de 4 es 8, entonces la jarra de Zara podría llenar alrededor de 8 vasos."], "title": "¿Cuántos vasos salen de la jarra?", "payload": {"max": 20, "min": 1, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Liruf vendió 4 vasos de limonada a 5 pesos cada uno y ganó 20 pesos. Ahora Zara quiere vender limonada como Liruf. Su jarra es mucho más grande que la de Liruf: la jarra de Liruf llenaba 4 vasos, pero la de Zara se ve como el doble de grande. Si cada vaso se vende a 5 pesos, ¿cuánto podría ganar Zara si vende todos los vasos? Primero, desliza la barra para estimar cuántos vasos salen de la jarra de Zara.", "difficulty": 1, "explanation_md": "¡Exacto! La jarra de Zara es el doble de grande que la de Liruf, así que llena unos 8 vasos. Si vende cada vaso a 5 pesos, ganaría 8 × 5 = 40 pesos. ¡Eso es el doble de lo que ganó Liruf!", "audio_segment_id": "s1-estimate-jar.prompt"}], "schema_version": 1}', '{"s1-estimate-jar": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 6}}', '{"units": {"s1-estimate-jar.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1c0bc9e7d074f0d46fbb37c4cb50a81d7140a67ff58d9d3d4cf3ea0ae7b30eb9.mp3", "hash": "2d361e6acef695deaeb9be9b2829a852482fef352191fb40a665a0a326fa636d", "bytes": 45504, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/1c0bc9e7d074f0d46fbb37c4cb50a81d7140a67ff58d9d3d4cf3ea0ae7b30eb9.mp3", "duration_ms": 7520}, "s1-estimate-jar.hint.1": {"url": "http://localhost:4006/files/lesson-audio/037b8e407e7061aa07b8929903fff06903a7d671f4bde8d83e9981c31eb9736d.mp3", "hash": "34f85da90ca1baa32f28103b2fae01aa11454d8f13cce286e05a24ba09c02f56", "bytes": 36864, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/037b8e407e7061aa07b8929903fff06903a7d671f4bde8d83e9981c31eb9736d.mp3", "duration_ms": 6080}, "s1-estimate-jar.prompt": {"url": "http://localhost:4006/files/lesson-audio/2dd75134f087fb33a405984c63f270bb67d4d1bc282b28fa613adc0688c08b37.mp3", "hash": "60646939e3983e5682d70a916f7dbf60ff2b0376db431d258ce760a477c997cb", "bytes": 154944, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/2dd75134f087fb33a405984c63f270bb67d4d1bc282b28fa613adc0688c08b37.mp3", "duration_ms": 25760}, "s1-estimate-jar.explanation": {"url": "http://localhost:4006/files/lesson-audio/f220dc2d7c95f87d200695c12c428256ae286c545eb35791ea775021c1f7fab3.mp3", "hash": "fe1a59a7bae38dba7a8b44b40a4c6caff120feb4d5ae6acc9ca0b6c6dad27ad4", "bytes": 80928, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/f220dc2d7c95f87d200695c12c428256ae286c545eb35791ea775021c1f7fab3.mp3", "duration_ms": 13440}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "memory-flip", "title": "Price Memory", "locale": "en-US", "subject": "mixed", "objectives": ["Memory match each product with the coins that pay for it, using the stall prices: cookie = 3 (1+2), small cup = 5, large pitcher = 20 (10+10)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 15, "type": "memory_flip", "hints": ["Remember: the cookie costs 3 pesos (1+2), the small cup 5, and the large pitcher 20 (10+10).", "Start with the product that sticks in your mind the most, like the large pitcher."], "title": "Match product with payment", "payload": {"pairs": [{"a_md": "Cookie", "b_md": "1 peso + 2 pesos", "a_icon": "cookie", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/f5a1a4c517a764ec6ad5f59cae029f3222fd4b9c04e44d7073736b16b7ee365a.png", "b_image_url": "http://localhost:4006/files/lesson-images/8c3c67a376252975b4c478669bab607afea5c567924decdcea06b59bf76b53ca.png"}, {"a_md": "Small cup", "b_md": "5 pesos", "a_icon": "water_drop", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/9c2554b55b4f8c6172080092ad2678065e4ac126528ebccede5e31e28c73cd02.png", "b_image_url": "http://localhost:4006/files/lesson-images/3d638591fe3f5eadcbc1422e300c240bd68c5efdd68781c7083fc2656a030430.png"}, {"a_md": "Large pitcher", "b_md": "10 pesos + 10 pesos", "a_icon": "local_bar", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/1505f1edb40c0e20b38e5475fb8b3e8da17d002a2110551094cdf7ababadf90b.png", "b_image_url": "http://localhost:4006/files/lesson-images/a65bbe49b6aaf3c524ba61399a47c55a25ba5e23b4e2b8d27f2f54d529399f65.png"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Tap the cards to find each product with the coins that pay for it. The one who remembers the prices fastest wins!", "difficulty": 2, "explanation_md": "Each product has an exact price: cookie 3 pesos (1+2), small cup 5 pesos, large pitcher 20 pesos (10+10). Matching them helps you charge without mistakes.", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b3bb508fa0fe696555da8aa8b853678363b8705b5b422b29a500856914403d97.mp3", "hash": "27b42d9974b8be10a21eef29d237c088218eaaef3feccadf0d9dfb5c35138db6", "bytes": 53568, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/b3bb508fa0fe696555da8aa8b853678363b8705b5b422b29a500856914403d97.mp3", "duration_ms": 8880}, "s1-memory-flip.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0854abdc5c44053d3b01dc154e62b29b697e89eaede8d4e93b3394bcdb3b1bed.mp3", "hash": "f37032ad751875ea71f088bbb5f51d808614af113e2cd30e1735da8d490f302c", "bytes": 28224, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/0854abdc5c44053d3b01dc154e62b29b697e89eaede8d4e93b3394bcdb3b1bed.mp3", "duration_ms": 4640}, "s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/8f29a3110808067f95f241ae7208a9504cd620d4172c8799950407fe6c7ded4b.mp3", "hash": "ca7cfa21463b082ab340abf6036fb988b4c036f43aaef6b17e333cc46040b4ce", "bytes": 44496, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/8f29a3110808067f95f241ae7208a9504cd620d4172c8799950407fe6c7ded4b.mp3", "duration_ms": 7360}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/00f901b0d778301e5e816f15c76615f724089faddbc131e9601ad9de03aec6b5.mp3", "hash": "0787406a8db49b8d031f2fcdc07c78755c7968928641e0387eb52c8b69de0da0", "bytes": 83376, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/00f901b0d778301e5e816f15c76615f724089faddbc131e9601ad9de03aec6b5.mp3", "duration_ms": 13840}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "machine-io", "title": "The Tip Machine", "locale": "en-US", "subject": "mixed", "objectives": ["Discovering that the machine doubles the input"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 10, "type": "machine_io", "hints": ["Observe: 1 → 2, 3 → 6. What operation repeats?"], "title": "The Tip Machine", "payload": {"options": [{"id": "opt1", "text_md": "7"}, {"id": "opt2", "text_md": "10"}, {"id": "opt3", "text_md": "8"}], "examples": [{"in": 1, "out": 2}, {"in": 3, "out": 6}], "probe_in": 5}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Just as Dina measured precisely in the jar, now watch how the machine transforms amounts. Dina''s grandmother has a mysterious little machine. If you put in 1 coin, 2 come out! If you put in 3, 6 come out. How many come out if you put in 5?", "difficulty": 1, "explanation_md": "The machine doubles what goes in: 5 × 2 = 10. That''s why 10 coins come out.", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 10, "correct_option_id": "opt2"}}', '{"units": {"s1-machine-io.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6df1b3cd7c32e484f93964d34d5ddb77bb578ef746cae426dc74890013e64a3d.mp3", "hash": "0726c66c6713b6f94eee8a6e03a2db18ab807bcaeb65ef2aa6515234f950cb3e", "bytes": 29088, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6df1b3cd7c32e484f93964d34d5ddb77bb578ef746cae426dc74890013e64a3d.mp3", "duration_ms": 4800}, "s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/7ad5d673e05a173703c0f9e3749921659522bc42d00a7f97b26067d4cca023fc.mp3", "hash": "49381475492132ef6137488e2bcf745143dca361627fd074eec82b48dfc4ef45", "bytes": 81936, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/7ad5d673e05a173703c0f9e3749921659522bc42d00a7f97b26067d4cca023fc.mp3", "duration_ms": 13600}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/3bf3421bad5316dade03c2edebf130966cb62929b084c1d46324a2676a18e6ea.mp3", "hash": "b5f7946b7991980b8183a61bc05afbd878b7555b5d80108f371c4b78fd5d2c5f", "bytes": 31536, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3bf3421bad5316dade03c2edebf130966cb62929b084c1d46324a2676a18e6ea.mp3", "duration_ms": 5200}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "evidence-hunt", "title": "Evidence Hunt: The Market Receipt", "locale": "en-US", "subject": "mixed", "objectives": ["Search the market receipt for the exact evidence of how much the lemons cost"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 10, "type": "evidence_hunt", "hints": ["Look on the receipt for the line that says ''lemons''.", "Pay close attention to the number next to ''lemons''."], "title": "The crumpled receipt", "payload": {"claim_md": "Liruf says: ''I spent 20 pesos on lemons.''", "sentences": [{"id": "s1", "text_md": "Lemons: 15 pesos"}, {"id": "s2", "text_md": "Sugar: 10 pesos"}, {"id": "s3", "text_md": "Total: 25 pesos"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Last week you saw in a chart which was the best lemonade sales day. Today, Liruf needs you: he bought lemons and sugar to make more lemonade, but he lost track. He only has this crumpled receipt. He says: ''I spent 20 pesos on lemons.'' But the receipt says something else. How much did the lemons actually cost? Help Liruf find the exact evidence on the receipt. Choose the line on the receipt that shows the real cost of the lemons.", "difficulty": 1, "explanation_md": "The receipt shows that the lemons cost 15 pesos, not 20. Liruf was mistaken when he remembered. The evidence is on the line ''Lemons: 15 pesos''.", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1"]}}', '{"units": {"s1-evidence-hunt.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5ab6caea3e50624061ec8be106a35cad931860b12fc0bde557a6d004b408e97e.mp3", "hash": "8a0f4ba0b82bff028536661fe75e26945fd8f5fa6c68662b51175b623050b06d", "bytes": 16128, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5ab6caea3e50624061ec8be106a35cad931860b12fc0bde557a6d004b408e97e.mp3", "duration_ms": 2640}, "s1-evidence-hunt.hint.1": {"url": "http://localhost:4006/files/lesson-audio/3f4bfe71e4d1dfbf2b55386284ace69fb90d8e7fd136b66ca0ebfb834251617d.mp3", "hash": "c82e434344ff66c0f5455be606c748ab7215102daa3de54dad917a3a0abfd8a0", "bytes": 16128, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3f4bfe71e4d1dfbf2b55386284ace69fb90d8e7fd136b66ca0ebfb834251617d.mp3", "duration_ms": 2640}, "s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/5f9accb3b557e60f2d89dd490921122e3a81d4c312839de45de9e80d9b613af6.mp3", "hash": "872d8c1f95120011201a320e8ff0fad2fea1c050dc89a8b0153ecc1e763460c4", "bytes": 135648, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5f9accb3b557e60f2d89dd490921122e3a81d4c312839de45de9e80d9b613af6.mp3", "duration_ms": 22560}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/1309ee7a3803c11f76fc298b82f7d953f37ffdca51c4e4a704d50d17d3fab036.mp3", "hash": "06a9bcbc06576cd0203c0b393aeeef096ad02b53443b6e178834c27b7e0f5f22", "bytes": 54576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1309ee7a3803c11f76fc298b82f7d953f37ffdca51c4e4a704d50d17d3fab036.mp3", "duration_ms": 9040}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fill-blank", "title": "Complete the stall accounts", "locale": "en-US", "subject": "mixed", "objectives": ["Complete number sentences about earnings using simple addition and subtraction."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia", "xp": 10, "type": "fill_blank", "hints": ["Subtract the cost of the ingredients from the price of the glass."], "title": "Liruf''s earnings", "payload": {"bank": [{"id": "b1", "text_md": "3"}, {"id": "b2", "text_md": "2"}, {"id": "b3", "text_md": "5"}, {"id": "b4", "text_md": "7"}], "mode": "typed", "text_md": "I sold a glass for 5 pesos, the ingredients cost 2, my earnings are {{1}} pesos."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf wants to save for a skateboard that costs 10 pesos. He has already saved 3 pesos. Today he sold a glass of lemonade for 5 pesos, but the ingredients cost him 2 pesos. How much money can he SAVE from this sale?", "difficulty": 1, "explanation_md": "Liruf earned 3 pesos (5 - 2 = 3). He can save that money for his skateboard. Now he has 3 + 3 = 6 pesos! If you chose 2, you confused cost with earnings. If you chose 5, you forgot to subtract the cost. If you chose 7, you added instead of subtracting.", "audio_segment_id": "s1-ganancia.prompt"}], "schema_version": 1}', '{"s1-ganancia": {"gaps": [{"gap": 1, "accept": ["3"], "bank_id": "b1"}]}}', '{"units": {"s1-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/134a6feead870bcebdfc68ef9291e11e0aa9fb55b703d23813eeec0265f15508.mp3", "hash": "6f4d4923aafd062f8b35431b3d6c482d17f8b080f87087e6c11ba0ba7ec5129f", "bytes": 18144, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/134a6feead870bcebdfc68ef9291e11e0aa9fb55b703d23813eeec0265f15508.mp3", "duration_ms": 2960}, "s1-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/c2bb95087b6a49a9fcbe20d4270a9b0d573d8f94b66a194abcc20a16c91d72ec.mp3", "hash": "b162b489f7caf681dff687199f037be98009f33fa0a211cadaecded0e43768b6", "bytes": 72288, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c2bb95087b6a49a9fcbe20d4270a9b0d573d8f94b66a194abcc20a16c91d72ec.mp3", "duration_ms": 12000}, "s1-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/b8515cddc3ae5f9664364527a32abc548038adb526522d1cebd5f3b386ec6ff5.mp3", "hash": "48c289bac6dc9dc8ce18b39e869eaca9b6544bd8156d96462b71bf1927c18ced", "bytes": 100224, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b8515cddc3ae5f9664364527a32abc548038adb526522d1cebd5f3b386ec6ff5.mp3", "duration_ms": 16640}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "picture-choice", "title": "Elige el lugar más seguro", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir con imágenes el lugar más seguro para guardar las ganancias del día: la alcancía con llave (no el bolsillo roto ni la mesa del puesto)."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lugar-seguro", "xp": 10, "type": "picture_choice", "hints": ["Piensa: ¿en qué lugar el dinero está más protegido?", "Imagina que dejas tus monedas en un lugar donde solo tú puedas abrirlo."], "title": "¿Dónde guardas tu dinero?", "payload": {"options": [{"id": "alcancia", "icon": "lock", "label": "Alcancía con llave", "image_url": "http://localhost:4006/files/lesson-images/969d02b3305f1757763e426012eea915a7a4fe9df2d4f274cfaaf148668b4c16.png"}, {"id": "bolsillo", "icon": "checkroom", "label": "Bolsillo roto", "image_url": "http://localhost:4006/files/lesson-images/23673b2b3632d2c627a9b86858a270c26d33d1636250426026522118088720b4.png", "rationale_md": "El bolsillo tiene un agujero, las monedas se caerían y se perderían. Tu ahorro se escaparía."}, {"id": "mesa", "icon": "table_restaurant", "label": "Mesa del puesto", "image_url": "http://localhost:4006/files/lesson-images/bad1b24fb80f59a268da01824b267df647f7b286bcf4a213f73a35e77aac869d.png", "rationale_md": "La mesa está a la vista de todos, cualquiera podría tomar el dinero. Tu ahorro no estaría protegido."}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Ayer Liruf guardó 5 pesos en su alcancía. Hoy vendió limonada y tiene 20 pesos más. Su ahorro está creciendo. ¿Dónde debe poner estas monedas para que su ahorro esté seguro?", "difficulty": 1, "explanation_md": "La alcancía con llave es el lugar más seguro porque solo Liruf puede abrirla. Así su ahorro de 25 pesos no se pierde ni lo roban. El bolsillo tiene un agujero y la mesa está al alcance de todos.", "audio_segment_id": "s1-lugar-seguro.prompt"}], "schema_version": 1}', '{"s1-lugar-seguro": {"correct_option_id": "alcancia"}}', '{"units": {"s1-lugar-seguro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/281745b5ac3d65739da98dc9176eec7c7fb8f61fab7fc02ef6b35567f6f445d7.mp3", "hash": "1bf41a995bd782a72b67dfe8696d97f5957f4db91769c2a99ec573d4e1bd1436", "bytes": 22464, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/281745b5ac3d65739da98dc9176eec7c7fb8f61fab7fc02ef6b35567f6f445d7.mp3", "duration_ms": 3680}, "s1-lugar-seguro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/cf1f52407885921706353998ebdcd60b8b08160275f476b79f2af2354c23a291.mp3", "hash": "27bbb41417fb766b6771e65aa074dd86d6190b196109f846d743a5ef6043c028", "bytes": 26784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/cf1f52407885921706353998ebdcd60b8b08160275f476b79f2af2354c23a291.mp3", "duration_ms": 4400}, "s1-lugar-seguro.prompt": {"url": "http://localhost:4006/files/lesson-audio/107f48b3bd2a4b673cd5cf84cfbe65b6efb17e14c6c6c3c4a824203894ac80bc.mp3", "hash": "1c3968c0f28124b2ddde49604a20d078786a7426327cfe93ecc9b8fe472086b5", "bytes": 72288, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/107f48b3bd2a4b673cd5cf84cfbe65b6efb17e14c6c6c3c4a824203894ac80bc.mp3", "duration_ms": 12000}, "s1-lugar-seguro.choices": {"url": "http://localhost:4006/files/lesson-audio/61be44ea59ea679d3f807c950578f1b3f5348b43990ff0e7e0fc4f2d904581cb.mp3", "hash": "71fa028d0ca9323d4bb86dd3af91abfa2b5cc0ecee47614b4a67c12f2a3cd272", "bytes": 25344, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/61be44ea59ea679d3f807c950578f1b3f5348b43990ff0e7e0fc4f2d904581cb.mp3", "duration_ms": 4160}, "s1-lugar-seguro.explanation": {"url": "http://localhost:4006/files/lesson-audio/8ffafcc097b85c65a60bd034886b32182c1b84a89946a2ea19e7f9b07f2b2ab3.mp3", "hash": "ee272e970513309aff5e96990f2ba2286b661e483ebbfb91eeb85535e7a92847", "bytes": 77184, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8ffafcc097b85c65a60bd034886b32182c1b84a89946a2ea19e7f9b07f2b2ab3.mp3", "duration_ms": 12800}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'pt-BR', '1', '{"meta": {"cast": ["rho"], "slug": "equation-builder", "title": "Monte a soma da tarde", "locale": "pt-BR", "subject": "mixed", "objectives": ["Montar com fichas a soma da tarde: 5 + 5 + 5 = 15 pesos (três copos vendidos)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-suma-tarde", "xp": 15, "type": "equation_builder", "hints": ["Cada copo vale 5 pesos. Você vendeu três copos. Coloque o 5 três vezes com sinais + entre eles.", "A conta começa com 5, depois +, depois 5, depois +, depois 5."], "title": "Monte a soma da tarde", "payload": {"slots": 5, "tokens": [{"id": "t1", "text": "5"}, {"id": "t2", "text": "+"}, {"id": "t3", "text": "5"}, {"id": "t4", "text": "+"}, {"id": "t5", "text": "5"}, {"id": "t6", "text": "15"}], "target_result": 15}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Ontem você contou 15 limões na cesta. Hoje Rho vendeu limonada. Por cada copo cobrou 5 pesos. Vendeu três copos. Dá para comprar amanhã 15 limões com o que ganhou? Monte a conta com as fichas para descobrir.", "difficulty": 2, "explanation_md": "Três copos a 5 pesos cada um somam 15 pesos. Exatamente o que custam os limões de amanhã! A conta é 5 + 5 + 5 = 15.", "audio_segment_id": "s1-suma-tarde.prompt"}], "schema_version": 1}', '{"s1-suma-tarde": {"accepted": ["t1 t2 t3 t4 t5"]}}', '{"units": {"s1-suma-tarde.hint.0": {"url": "http://localhost:4006/files/lesson-audio/fd725b9350082ee212abb695a0751df90ce3b2d3d9fa8464336ac6e1835397bf.mp3", "hash": "687e15bdc65f055ccc42ef7357286e44b6c13b5b6798089103445332712410e5", "bytes": 54144, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/fd725b9350082ee212abb695a0751df90ce3b2d3d9fa8464336ac6e1835397bf.mp3", "duration_ms": 8960}, "s1-suma-tarde.hint.1": {"url": "http://localhost:4006/files/lesson-audio/8542a7796bfcf461720e477b4767cf2dda9cd80403ecccef76eb75072a2202ea.mp3", "hash": "bc342b3de40e63913f9edaac5a9045e8457e9d6bd2bda1cb0409fe3a6d41315e", "bytes": 41184, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/8542a7796bfcf461720e477b4767cf2dda9cd80403ecccef76eb75072a2202ea.mp3", "duration_ms": 6800}, "s1-suma-tarde.prompt": {"url": "http://localhost:4006/files/lesson-audio/903c9c92e5e6db771c4f72dcb7cf0eedf768429e14c98e8002ae72af608e81dc.mp3", "hash": "598085e76f8df94ca9b7415c7edb644d53440426a52a176028cb62fc9391a0e0", "bytes": 115056, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/903c9c92e5e6db771c4f72dcb7cf0eedf768429e14c98e8002ae72af608e81dc.mp3", "duration_ms": 19120}, "s1-suma-tarde.explanation": {"url": "http://localhost:4006/files/lesson-audio/0420881fab28e3ba29acc86daad78fa7ff1a4bb446ab9d063f3347d7f173abbf.mp3", "hash": "6aa128afb24cd0dfca600d5be048ff6f359322fd6b4ec2ebf5809616ce73b673", "bytes": 70416, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/0420881fab28e3ba29acc86daad78fa7ff1a4bb446ab9d063f3347d7f173abbf.mp3", "duration_ms": 11680}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "budget-fit", "title": "El mercado de Liruf", "locale": "es-MX", "subject": "money", "objectives": ["Calcular el total de artículos necesarios y el dinero restante", "Decidir qué extras caben en un presupuesto de 20 pesos"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 15, "type": "budget_fit", "hints": ["Suma primero los necesarios: 8 + 6 = 14. Te quedan 6 pesos.", "Mira los precios: hielo 5, popotes 3, jarra 8. ¿Cuáles cuestan 6 o menos?"], "title": "Surte el carrito", "payload": {"items": [{"id": "limones", "icon": "nutrition", "need": true, "label": "Limones", "price": 8}, {"id": "azucar", "icon": "bakery_dining", "need": true, "label": "Azúcar", "price": 6}, {"id": "hielo", "icon": "ac_unit", "need": false, "label": "Hielo", "price": 5}, {"id": "popotes", "icon": "local_drink", "need": false, "label": "Popotes", "price": 3}, {"id": "jarra", "icon": "table_restaurant", "need": false, "label": "Jarra bonita", "price": 8}], "budget": 20, "currency": "MXN", "must_buy_needs": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf tiene un billete de **20 pesos**. Debe comprar **limones (8)** y **azúcar (6)**. Sin eso mañana no hay limonada. ¿Qué más puede llevar sin pasarse de 20? Toca los que quepan.", "difficulty": 2, "explanation_md": "Liruf gasta 8+6=14 en lo necesario. Le sobran 6 pesos. El hielo cuesta 5 y los popotes 3, juntos suman 8 (no caben). Solo el hielo (5) cabe, o solo los popotes (3). La jarra cuesta 8, más de lo que sobra.", "audio_segment_id": "s1-budget-fit.prompt"}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{"units": {"s1-budget-fit.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4b37093163c4dd530963cd52623429751701485a779c0d556fafb0c77c804612.mp3", "hash": "7197018c4cba886c957ec1480929af4d8657df7f58768381214275d3b073b0a8", "bytes": 36288, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4b37093163c4dd530963cd52623429751701485a779c0d556fafb0c77c804612.mp3", "duration_ms": 6000}, "s1-budget-fit.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a9b606cd6fc4e21286db92ba3e17c9e285e3dc0d3cc449292fa12997f13ecb90.mp3", "hash": "e5e621966643b0aa491102317adc7c1acf0d94fbb5d30d174af635a24c195c1b", "bytes": 41616, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a9b606cd6fc4e21286db92ba3e17c9e285e3dc0d3cc449292fa12997f13ecb90.mp3", "duration_ms": 6880}, "s1-budget-fit.prompt": {"url": "http://localhost:4006/files/lesson-audio/dbcd3db099662364a1c061bec761ed7918fbf58ba3e1d9bbd59e01763e37a19f.mp3", "hash": "cb3826102132532bfb181b06a55a33da5f4bd8215576bc96ac7ccc6c52bb12af", "bytes": 76176, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/dbcd3db099662364a1c061bec761ed7918fbf58ba3e1d9bbd59e01763e37a19f.mp3", "duration_ms": 12640}, "s1-budget-fit.explanation": {"url": "http://localhost:4006/files/lesson-audio/4bb70932be51dd7f26aea4b6c2e9e9dbcc93c151dfc5f7c5d83054e3e19ede15.mp3", "hash": "f665285edf4bc5e0aceb940ae96b818123961e7c4eea7c8592ad8c122df47c59", "bytes": 112176, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4bb70932be51dd7f26aea4b6c2e9e9dbcc93c151dfc5f7c5d83054e3e19ede15.mp3", "duration_ms": 18640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "repaso-quiz-mcq", "title": "Repaso: Precio justo y ganancia", "locale": "es-MX", "subject": "mixed", "objectives": ["Repasar con una pregunta directa el corazón del negocio: si el vaso cuesta 5 y los ingredientes 2, ¿cuál es la ganancia por vaso?"], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-por-vaso", "xp": 10, "type": "quiz_mcq", "hints": ["La ganancia es lo que sobra después de pagar los ingredientes.", "Resta el costo de los ingredientes al precio del vaso."], "title": "Ganancia por vaso", "payload": {"options": [{"id": "a", "text_md": "3 pesos", "rationale_md": "Correcto: 5 (precio) - 2 (costo) = 3 pesos de ganancia. ¡Bien hecho!"}, {"id": "b", "text_md": "2 pesos", "rationale_md": "Esa es la cantidad que gastaste en ingredientes, no lo que ganas. La ganancia es el precio menos el costo."}, {"id": "c", "text_md": "5 pesos", "rationale_md": "Ese es el precio del vaso, pero no consideraste que los ingredientes cuestan dinero. La ganancia es lo que queda después de pagarlos."}, {"id": "d", "text_md": "7 pesos", "rationale_md": "Sumaste el precio y el costo, pero la ganancia se calcula restando, no sumando."}], "shuffle": true}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Ayer preparaste el puesto con Dina: pusiste precio a cada vaso (5 pesos) y calculaste que los ingredientes cuestan 2 pesos por vaso. Hoy vendiste tu primer vaso. Dina te dice: «¡Felicidades! Vendiste un vaso. Ahora, ¿cuánto dinero GANASTE de verdad? Recuerda que los ingredientes no son gratis…» ¿Cuánto dinero te queda después de pagar los ingredientes de ese vaso?", "difficulty": 1, "explanation_md": "Ganaste 3 pesos: vendiste el vaso en 5 pesos, pero los ingredientes costaron 2 pesos, así que te quedan 3 pesos. ¡Esa es tu ganancia! Con esos 3 pesos podrás comprar más limones mañana.", "audio_segment_id": "s1-ganancia-por-vaso.prompt"}], "schema_version": 1}', '{"s1-ganancia-por-vaso": {"correct_option_id": "a"}}', '{"units": {"s1-ganancia-por-vaso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/43adbd4a0a30dd2284c870716d3eab7c1d991a94760ca0f333f1631495425353.mp3", "hash": "e74fe2bd3e024caba52c695471203a3db5bd4e5b818668694b310017ef4868ac", "bytes": 23904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/43adbd4a0a30dd2284c870716d3eab7c1d991a94760ca0f333f1631495425353.mp3", "duration_ms": 3920}, "s1-ganancia-por-vaso.hint.1": {"url": "http://localhost:4006/files/lesson-audio/70610d494b5d7f1fb40c3572e6fae7470378ddc56e8d3396e9df339e2de5125c.mp3", "hash": "035ef9f030850db0cc4d4eb16e78fcbba9d43e111604e8b969034a0c589b6e98", "bytes": 20016, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/70610d494b5d7f1fb40c3572e6fae7470378ddc56e8d3396e9df339e2de5125c.mp3", "duration_ms": 3280}, "s1-ganancia-por-vaso.prompt": {"url": "http://localhost:4006/files/lesson-audio/52185d4e169bc715cf0c9f10a119965caf0d664d85db7845936f302328b1f256.mp3", "hash": "5214a66043b0184c8641e383231192832f0bb3c76b446f393d95b9ffeca39917", "bytes": 139104, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/52185d4e169bc715cf0c9f10a119965caf0d664d85db7845936f302328b1f256.mp3", "duration_ms": 23120}, "s1-ganancia-por-vaso.choices": {"url": "http://localhost:4006/files/lesson-audio/53b90da533a62c477745687fc81fda39cdbdde83dd5d008f83d396a17bac0f4f.mp3", "hash": "db858d166784e99eadc25263c3b6d0fd5cc482d508361a83d1bff72f938d032c", "bytes": 32544, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/53b90da533a62c477745687fc81fda39cdbdde83dd5d008f83d396a17bac0f4f.mp3", "duration_ms": 5360}, "s1-ganancia-por-vaso.explanation": {"url": "http://localhost:4006/files/lesson-audio/fafb5508c6e078e4a1d8f5695998aa2434afa8b38ed2d9c73dd8b82543f06e8c.mp3", "hash": "d7eebb5b3aa72f04222fb4d1c3e1c5dbb7a89d53b10aa0c9539d2d1a0912b5e3", "bytes": 80928, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/fafb5508c6e078e4a1d8f5695998aa2434afa8b38ed2d9c73dd8b82543f06e8c.mp3", "duration_ms": 13440}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'en-US', '1', E'{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "Liruf''s plan", "locale": "en-US", "subject": "money", "objectives": ["See the full plan: sell lemonade cups for 5 pesos until you save 80 for the guitar"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan", "xp": 0, "type": "story_scene", "hints": ["Each cup gives 5 pesos. How much has he saved already with 10 cups?", "If he already has 50 pesos, how much more does he need to reach 80?"], "title": "Liruf''s plan", "payload": {"art": {"icon": "emoji_events", "tint": "primary"}, "action": "idle", "body_md": "Liruf drew his plan on a poster board. He wrote: **1 cup = 5 pesos**. Then he drew many cups and at the end a guitar worth 80 pesos. \\"I''m going to sell lemonade until I have my guitar!\\" As they discovered yesterday with Dina, you don''t have to wait for a gift!", "emotion": "excited", "backdrop": "band", "character": "dina"}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Liruf has already sold 10 cups of lemonade for 5 pesos each. How many more cups does he need to sell to save the 80 pesos for the guitar?", "difficulty": 1, "explanation_md": "Very good! With 10 cups he saved 50 pesos. He needs 30 more pesos for the guitar. Since each cup gives 5 pesos, he needs 6 more cups (because 6 × 5 = 30). So his plan becomes real!", "audio_segment_id": "s1-plan.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-plan.body": {"url": "http://localhost:4006/files/lesson-audio/3a4989c3d4ee30364168b359ce9aad1e8074240c377a0253ae6cae68d84df2bc.mp3", "hash": "27a9e6b8e73add1e768a1ed5a25b3f8e7c665f3502af998433ce536be94eb27f", "bytes": 90144, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3a4989c3d4ee30364168b359ce9aad1e8074240c377a0253ae6cae68d84df2bc.mp3", "duration_ms": 14960}, "s1-plan.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a913951596ab5ef662fa795f55b82a8b5fc06c5a0605cac9341ad3d8cdaba89e.mp3", "hash": "212cfd12d5ebaed26ecaaceab9e4e5ef225ccb4327f8c0ae1d8136f9c838c1d3", "bytes": 26784, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a913951596ab5ef662fa795f55b82a8b5fc06c5a0605cac9341ad3d8cdaba89e.mp3", "duration_ms": 4400}, "s1-plan.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0f4c7df0d276e15f5e5008da39ce6fd00b5cc2715bc29d3b70da9238fd82ca4c.mp3", "hash": "dd00b812fc6fad80934e46149ccbfc20eb55f92cf4f216456a42affd9434cb3e", "bytes": 26208, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0f4c7df0d276e15f5e5008da39ce6fd00b5cc2715bc29d3b70da9238fd82ca4c.mp3", "duration_ms": 4320}, "s1-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/c832d9b168c9c8b82067a51d65aa491c96213e1b49d0a7d67b075fc3d275427a.mp3", "hash": "6d3f3a0f0b13847549e43a1965d73f5c6008fd30912f038d706ac8e7e19e480a", "bytes": 44064, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c832d9b168c9c8b82067a51d65aa491c96213e1b49d0a7d67b075fc3d275427a.mp3", "duration_ms": 7280}, "s1-plan.explanation": {"url": "http://localhost:4006/files/lesson-audio/f09d0b14fff7f1f0d75a67c24d3ce4fb8ab716998fbcec62628b27e09389ec2d.mp3", "hash": "078b32e027cef51518fd40a6ecb88c15de1b0fddc8abc3dda6249854dc64a3d3", "bytes": 75744, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f09d0b14fff7f1f0d75a67c24d3ce4fb8ab716998fbcec62628b27e09389ec2d.mp3", "duration_ms": 12560}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Organize the stand''s purchases", "locale": "pt-BR", "subject": "mixed", "objectives": ["Sort the day''s purchases into two buckets: NEED of the stand (lemons, cups) or WANT that can wait (stickers, balloons)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort-buckets", "xp": 10, "type": "sort_buckets", "hints": ["Think: does the stand need this to sell lemonade, or is it just a want that can wait?"], "title": "Two buckets for the purchases", "payload": {"items": [{"id": "limones", "text_md": "Lemons 🍋"}, {"id": "vasos", "text_md": "Cups 🥤"}, {"id": "stickers", "text_md": "Stickers ⭐"}, {"id": "globos", "text_md": "Balloons 🎈"}, {"id": "panuelos", "text_md": "Tissues 🧻"}], "buckets": [{"id": "necesidad", "label": "NEED of the stand"}, {"id": "gusto", "label": "WANT that can wait"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "After helping Dina organize her coins, now they go to the market. Dina says: ''I need lemons and cups for the lemonade, but I also want stickers and balloons to decorate. Help me decide: what is a NEED for the stand and what is a WANT that can wait?'' Touch each item and put it in the correct bucket.", "difficulty": 1, "explanation_md": "Lemons and cups are needs for the stand because without them you can''t sell lemonade. Stickers and balloons are wants that can wait. And tissues can be a need if they are for cleaning the stand, or a want if they are just decoration!", "audio_segment_id": "s1-sort-buckets.prompt"}], "schema_version": 1}', '{"s1-sort-buckets": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "panuelos": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-sort-buckets.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f61c18f604b3409925c4226ec40f35af87f04bfd117247afa02ff490a238738f.mp3", "hash": "d6f3a8b6ac33eb6690470a2d2852372d3fc8fb3ff4c3db00979780f76f354708", "bytes": 38736, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f61c18f604b3409925c4226ec40f35af87f04bfd117247afa02ff490a238738f.mp3", "duration_ms": 6400}, "s1-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/17679f569acb60595366759fd3cd246f8edf728353a263b4a937a80b1895ed8a.mp3", "hash": "111bc85e7a09c146c1b9ae40a2672c68479699abad4473117243038cc03349a5", "bytes": 117936, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/17679f569acb60595366759fd3cd246f8edf728353a263b4a937a80b1895ed8a.mp3", "duration_ms": 19600}, "s1-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/0daf8ac73461ebd78dc6e139571aed30de8bc4146de4662e771e704bc8bf2b7d.mp3", "hash": "1f826321a970b0755db454cb2ca13ed1f8279e54f538c48e489a52d711e0540b", "bytes": 97344, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0daf8ac73461ebd78dc6e139571aed30de8bc4146de4662e771e704bc8bf2b7d.mp3", "duration_ms": 16160}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "memory-flip", "title": "Memoria de precios", "locale": "es-MX", "subject": "mixed", "objectives": ["Emparejar de memoria cada producto con las monedas que lo pagan, usando los precios del puesto: galleta = 3 (1+2), vaso chico = 5, jarra grande = 20 (10+10)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 15, "type": "memory_flip", "hints": ["Recuerda: la galleta cuesta 3 pesos (1+2), el vaso chico 5, y la jarra grande 20 (10+10).", "Empieza por el producto que más se te grabe, como la jarra grande."], "title": "Empareja producto con pago", "payload": {"pairs": [{"a_md": "Galleta", "b_md": "1 peso + 2 pesos", "a_icon": "cookie", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/f5a1a4c517a764ec6ad5f59cae029f3222fd4b9c04e44d7073736b16b7ee365a.png", "b_image_url": "http://localhost:4006/files/lesson-images/8c3c67a376252975b4c478669bab607afea5c567924decdcea06b59bf76b53ca.png"}, {"a_md": "Vaso chico", "b_md": "5 pesos", "a_icon": "water_drop", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/9c2554b55b4f8c6172080092ad2678065e4ac126528ebccede5e31e28c73cd02.png", "b_image_url": "http://localhost:4006/files/lesson-images/3d638591fe3f5eadcbc1422e300c240bd68c5efdd68781c7083fc2656a030430.png"}, {"a_md": "Jarra grande", "b_md": "10 pesos + 10 pesos", "a_icon": "local_bar", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/1505f1edb40c0e20b38e5475fb8b3e8da17d002a2110551094cdf7ababadf90b.png", "b_image_url": "http://localhost:4006/files/lesson-images/a65bbe49b6aaf3c524ba61399a47c55a25ba5e23b4e2b8d27f2f54d529399f65.png"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Toca las cartas para encontrar cada producto con las monedas que lo pagan. ¡Gana quien recuerde los precios más rápido!", "difficulty": 2, "explanation_md": "Cada producto tiene un precio exacto: galleta 3 pesos (1+2), vaso chico 5 pesos, jarra grande 20 pesos (10+10). Emparejarlos te ayuda a cobrar sin errores.", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.hint.0": {"url": "http://localhost:4006/files/lesson-audio/90a158472354ea277564e9b204c8d7fb01cd53da5547f4f3bf4bed0f79071a64.mp3", "hash": "0e25c2c90b29e8523c0ffd5260f35934fbc0a957c8ea0e201ff07dc38c9954cd", "bytes": 45504, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/90a158472354ea277564e9b204c8d7fb01cd53da5547f4f3bf4bed0f79071a64.mp3", "duration_ms": 7520}, "s1-memory-flip.hint.1": {"url": "http://localhost:4006/files/lesson-audio/778688b676c1d499f347cdb89962624ca971fb6a4861509ccb4d6e4caaabe87d.mp3", "hash": "5f2679e93b5f880239a7ff23a543f1e1c0848cec4ff5e633bbc3859735116412", "bytes": 23904, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/778688b676c1d499f347cdb89962624ca971fb6a4861509ccb4d6e4caaabe87d.mp3", "duration_ms": 3920}, "s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/06b7852561a58e3408c05d1e27d4dfbf8dc5a1b54b40fbc1e432f57b2fff1738.mp3", "hash": "791cfbe011aefa80905166e326b5a3090c72da742bc78ba4de2569f919d8d34e", "bytes": 43488, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/06b7852561a58e3408c05d1e27d4dfbf8dc5a1b54b40fbc1e432f57b2fff1738.mp3", "duration_ms": 7200}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/4d4ac892966a57904dcf67ef98092416b6c9e465057c2d1fb4cd00bbfdf15dba.mp3", "hash": "180e17e015daa096104d945055c38314a346c24288c1c899d738c3169feb09bb", "bytes": 73728, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/4d4ac892966a57904dcf67ef98092416b6c9e465057c2d1fb4cd00bbfdf15dba.mp3", "duration_ms": 12240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "key-ideas", "title": "The Little Seller''s Three Golden Rules", "locale": "en-US", "subject": "mixed", "objectives": ["Identify the three key ideas of Liruf''s plan: have a goal of 80 pesos, offer cold lemonade that people want, and save what you earn."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": [], "title": "The Three Golden Rules", "payload": {"ideas": [{"icon": "emoji_events", "title": "Have a goal", "body_md": "Liruf wants the **80-peso** guitar. Knowing how much he needs gives him direction."}, {"icon": "local_cafe", "title": "Offer something people want", "body_md": "Cold lemonade at **5 pesos** a glass. Everyone loves it on a hot day!"}, {"icon": "savings", "title": "Save what you earn", "body_md": "Every peso Liruf earns, he saves for his goal. That way he doesn''t spend it on other things."}]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf has already sold 10 glasses of lemonade and has 50 pesos. But remember, his goal is the 80-peso guitar. **Help Liruf decide: what should he do with his 50 pesos to reach his goal?**", "difficulty": 1, "explanation_md": "Exactly! Liruf must **save** the 50 pesos and keep selling. If he spends them on something else, he won''t reach 80. Saving what you earn is one of the three golden rules.", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/1117decefc2dff40a68912770e040268063802f5ddc201669c1acc1780431d07.mp3", "hash": "392e4324e6b85f6bd5de240827ae9914465e1fff024ecd634cdc498274b969d2", "bytes": 34416, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/1117decefc2dff40a68912770e040268063802f5ddc201669c1acc1780431d07.mp3", "duration_ms": 5680}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/03eb42f929c642427cff6f4b6830f9203eafe67ddde30f336676fb73e16e1d4a.mp3", "hash": "b9273cbc0f4e670d47831b338eca51905d2932d1c192479627480bec122ebc4e", "bytes": 35856, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/03eb42f929c642427cff6f4b6830f9203eafe67ddde30f336676fb73e16e1d4a.mp3", "duration_ms": 5920}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/359b8351cbe687a1743c5db9e8e1627632f9e40b9e81e6d531948168b865bff5.mp3", "hash": "06727cc1c61e4638b4d9cd4a4b3db08f27e0e5e3863f0f1c22e6442ea43ec758", "bytes": 44064, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/359b8351cbe687a1743c5db9e8e1627632f9e40b9e81e6d531948168b865bff5.mp3", "duration_ms": 7280}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/7f23463696b1968cf91d56e233d1281662c880c007e3cf542028d740871c38ab.mp3", "hash": "370edb629e35def828ad4e4bbb1159100d957fb1e0bee5770836d8292465398c", "bytes": 86256, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/7f23463696b1968cf91d56e233d1281662c880c007e3cf542028d740871c38ab.mp3", "duration_ms": 14320}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/9fb19cfdbe3a6a6e2061672b0267a45f28e9cb7d1a29a3d4395efec67a89ba7c.mp3", "hash": "345355b77249f71268e18ea174f053c8e6307c40f1ac95a3dba89f72a6fc142a", "bytes": 75168, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/9fb19cfdbe3a6a6e2061672b0267a45f28e9cb7d1a29a3d4395efec67a89ba7c.mp3", "duration_ms": 12480}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'es-MX', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "true-false", "title": "¿Cierto o falso? El ahorro que crece", "locale": "es-MX", "subject": "mixed", "objectives": ["Decidir si es cierto o falso: ''Si guardo 5 pesos de cada venta, mi ahorro CRECE cada día''."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Piensa: si cada día guardas 5 pesos, ¿la cantidad total aumenta o se queda igual?", "Imagina que hoy guardas 5, mañana otros 5... ¿tienes más o menos que ayer?"], "title": "Atrapa la frase", "payload": {"statement_md": "Si guardo 5 pesos de cada venta, mi ahorro CRECE cada día.", "justifications": [{"id": "crece", "text_md": "Es cierto, porque cada día sumas 5 pesos más al total."}, {"id": "no-crece", "text_md": "Es falso, porque el ahorro se queda igual siempre."}]}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Zara dice: ''Si guardo 5 pesos de cada venta, mi ahorro CRECE cada día''. Liruf debe decidir si es cierto o falso. ¿Tú qué dices?", "difficulty": 1, "explanation_md": "Es cierto. Si cada día guardas 5 pesos, el total de tu ahorro aumenta. Por ejemplo, el lunes tienes 5, el martes 10, el miércoles 15... ¡crece cada día!", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "crece"}}', '{"units": {"s1-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/578af70e872cdc0a64ac2e74a82ce6af3f8f32a210b57f27bf84a2b0225635d1.mp3", "hash": "aea18e9c9267b6918deb3bfc65de84bf508ac78dc86d578cc1b48702284985cc", "bytes": 33408, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/578af70e872cdc0a64ac2e74a82ce6af3f8f32a210b57f27bf84a2b0225635d1.mp3", "duration_ms": 5520}, "s1-true-false.hint.1": {"url": "http://localhost:4006/files/lesson-audio/d73d4cdc78ac3c35e2e20e0c4850fed17a712bfb33dd0a560a0aa6b9391352b5.mp3", "hash": "f08f71c4ffb750cfb12e315680262b8539b1c99436c9a8095a22d03741c10ff3", "bytes": 31536, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/d73d4cdc78ac3c35e2e20e0c4850fed17a712bfb33dd0a560a0aa6b9391352b5.mp3", "duration_ms": 5200}, "s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/95c155564957ed9e1c0f94813a79a6395cff2c5301ad61b9904cb0ac3315e1b4.mp3", "hash": "ddff943db8667f5dd0e4d012c49262e9033ac6820793433aa035bd28b168a464", "bytes": 51696, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/95c155564957ed9e1c0f94813a79a6395cff2c5301ad61b9904cb0ac3315e1b4.mp3", "duration_ms": 8560}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/29738e3a832085db5b26090410a2987798a46694deca5e5e3e4de9650ecc2ed2.mp3", "hash": "99489cb5a4a2fac7269c62166215bbd999d4a88422e44b4eb5215d0a1162c83e", "bytes": 62784, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/29738e3a832085db5b26090410a2987798a46694deca5e5e3e4de9650ecc2ed2.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fill-blank", "title": "Completar las cuentas del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Completar frases numéricas sobre ganancias usando suma y resta simples."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia", "xp": 10, "type": "fill_blank", "hints": ["Resta el costo de los ingredientes al precio del vaso."], "title": "La ganancia de Liruf", "payload": {"bank": [{"id": "b1", "text_md": "3"}, {"id": "b2", "text_md": "2"}, {"id": "b3", "text_md": "5"}, {"id": "b4", "text_md": "7"}], "mode": "typed", "text_md": "Vendí un vaso en 5 pesos, los ingredientes costaron 2, mi ganancia es {{1}} pesos."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf quiere ahorrar para una patineta que cuesta 10 pesos. Ya ahorró 3 pesos. Hoy vendió un vaso de limonada en 5 pesos, pero los ingredientes le costaron 2 pesos. ¿Cuánto dinero puede AHORRAR de esta venta?", "difficulty": 1, "explanation_md": "Liruf ganó 3 pesos (5 - 2 = 3). Ese dinero puede ahorrarlo para su patineta. ¡Ya tiene 3 + 3 = 6 pesos! Si elegiste 2, confundiste el costo con la ganancia. Si elegiste 5, olvidaste restar el costo. Si elegiste 7, sumaste en vez de restar.", "audio_segment_id": "s1-ganancia.prompt"}], "schema_version": 1}', '{"s1-ganancia": {"gaps": [{"gap": 1, "accept": ["3"], "bank_id": "b1"}]}}', '{"units": {"s1-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/996420b0b26e068ffed026ad384e1ed86dcaabef64cb39d3c1dab7edd4dd0d12.mp3", "hash": "035ef9f030850db0cc4d4eb16e78fcbba9d43e111604e8b969034a0c589b6e98", "bytes": 21024, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/996420b0b26e068ffed026ad384e1ed86dcaabef64cb39d3c1dab7edd4dd0d12.mp3", "duration_ms": 3440}, "s1-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/024855280db84e540730c036614a38761a69ef394b5a4f4ec4c4c8da671bf661.mp3", "hash": "2c80638f15257165694d6e91918ebc7f7ae18307d7b71ca36379b0fa594edca4", "bytes": 87264, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/024855280db84e540730c036614a38761a69ef394b5a4f4ec4c4c8da671bf661.mp3", "duration_ms": 14480}, "s1-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/3e990347dcd5413a15b31cbffce29657405a293f911a849d0cc24902cf554dcb.mp3", "hash": "7a3e65409c3a9cff7d3b3623c971fe3262d3d94a13df43be522e7a780340b4df", "bytes": 119808, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3e990347dcd5413a15b31cbffce29657405a293f911a849d0cc24902cf554dcb.mp3", "duration_ms": 19920}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'en-US', '1', '{"meta": {"cast": ["liruf", "zara"], "slug": "build-sentence", "title": "The combo sign", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate the price of 2 glasses of lemonade (2 × 5 = 10) to complete a combo sign."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-combo-sign", "xp": 10, "type": "build_sentence", "hints": ["Think: one glass costs 5, two glasses cost double.", "What is 5 plus 5?"], "title": "The combo sign", "payload": {"slots": 5, "tokens": [{"id": "t1", "text_md": "2"}, {"id": "t2", "text_md": "glasses"}, {"id": "t3", "text_md": "for"}, {"id": "t4", "text_md": "10"}, {"id": "t5", "text_md": "pesos"}, {"id": "t6", "text_md": "5"}, {"id": "t7", "text_md": "15"}, {"id": "t8", "text_md": "20"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf has already organized his expenses: first the lemons, then the cups, then the decorations. Now he wants to sell faster and puts up a sign: **2 glasses for ___ pesos**. Each glass costs 5 pesos. Tap the chips in order to put together the correct sign. If you get it right, customers will know the fair price and Liruf will sell more.", "difficulty": 1, "explanation_md": "Two glasses cost 10 pesos because each glass is worth 5: 5 + 5 = 10. If you put 5, you''d be giving away a glass. If you put 15 or 20, customers would think it''s too expensive and wouldn''t buy.", "audio_segment_id": "s1-combo-sign.prompt"}], "schema_version": 1}', '{"s1-combo-sign": {"order": ["t1", "t2", "t3", "t4", "t5"]}}', '{"units": {"s1-combo-sign.hint.0": {"url": "http://localhost:4006/files/lesson-audio/212cc2ad9e9f81077b881d4b7c75f2f2e6d6c6287d6ec1a2c64afd4faa4bc80e.mp3", "hash": "0995a787e0893f370a2c7244d55c3aebc9442bc6a95a86f5e9d1667095c7cbfe", "bytes": 23328, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/212cc2ad9e9f81077b881d4b7c75f2f2e6d6c6287d6ec1a2c64afd4faa4bc80e.mp3", "duration_ms": 3840}, "s1-combo-sign.hint.1": {"url": "http://localhost:4006/files/lesson-audio/24a8add06cb150dd458e898fc6e8ec3617aae58e530ff0499392f76a820a3bd1.mp3", "hash": "bbe06e6036394c78a83afe3a7ee1ea0dca3deaccce5b77fa604e9451b3055530", "bytes": 10944, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/24a8add06cb150dd458e898fc6e8ec3617aae58e530ff0499392f76a820a3bd1.mp3", "duration_ms": 1760}, "s1-combo-sign.prompt": {"url": "http://localhost:4006/files/lesson-audio/e007860cc923356a2adbad55336f17ac93fb800ca64c388b2956241bf8f9e4f9.mp3", "hash": "ae0d7b45e543bd2592e60ae10a0520ea4d46ca5a6cf7727ea715e20e18fa6fd1", "bytes": 116928, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/e007860cc923356a2adbad55336f17ac93fb800ca64c388b2956241bf8f9e4f9.mp3", "duration_ms": 19440}, "s1-combo-sign.explanation": {"url": "http://localhost:4006/files/lesson-audio/d2d6ec47e9a1c126409ae6054c109f0aa0959e41edf5a5e2431f0c44ac3b79a3.mp3", "hash": "89da51b7cafe70cdae4061ad258e40fd71efe76393f2aa5902cd01a46de91954", "bytes": 77184, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/d2d6ec47e9a1c126409ae6054c109f0aa0959e41edf5a5e2431f0c44ac3b79a3.mp3", "duration_ms": 12800}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'es-MX', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "robot-path", "title": "La ruta del carrito repartidor", "locale": "es-MX", "subject": "mixed", "objectives": ["Guiar al carrito repartidor por la cuadrícula del barrio hasta la casa del cliente gastando la menor cantidad de pasos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 10, "type": "robot_path", "hints": ["El carrito empieza mirando hacia arriba. ¿Hacia dónde está la casa de Leo?", "Prueba con un solo giro y luego avanza directo."], "title": "La ruta del carrito", "payload": {"goal": {"x": 2, "y": 0}, "grid": {"h": 4, "w": 4}, "start": {"x": 0, "y": 0, "dir": "up"}, "walls": [{"x": 1, "y": 1}, {"x": 2, "y": 1}], "commands": ["forward", "left", "right"], "max_commands": 3}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Al igual que ordenaste los pasos para la registradora, ahora ordena los pasos del carrito. Zara tiene un carrito repartidor que debe llevar un juguete a la casa de su amigo Leo. El carrito empieza en la esquina de la cuadrícula, mirando hacia arriba. La casa de Leo está a la derecha, a 2 cuadras. Toca los comandos para guiarlo: **forward** (avanza 1 cuadra), **left** (gira a la izquierda), **right** (gira a la derecha). ¡Usa la menor cantidad de pasos!", "difficulty": 1, "explanation_md": "El carrito giró a la derecha (1 comando) y avanzó 2 pasos (2 comandos) para llegar a la casa de Leo. ¡Usaste solo 3 comandos! Así como en la registradora, ordenar los pasos correctos ahorra tiempo.", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.hint.0": {"url": "http://localhost:4006/files/lesson-audio/fb2e995bb3358679728a9ff032e0f3c1275351d5918c7cb18594eadabac25379.mp3", "hash": "81f1a4884e0edb83fe514583f3445b1db5411c8c28681349cfb7cc6fcc6005a1", "bytes": 29088, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/fb2e995bb3358679728a9ff032e0f3c1275351d5918c7cb18594eadabac25379.mp3", "duration_ms": 4800}, "s1-robot-path.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f32b26ccc671f387814b32ff1d98db83b5d53d4439026267dc7ff936440eff2e.mp3", "hash": "4b8707b4475a2ae20275077c47bddba3ea1621b647e6e4377c6e4e2eb487e4ec", "bytes": 21024, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f32b26ccc671f387814b32ff1d98db83b5d53d4439026267dc7ff936440eff2e.mp3", "duration_ms": 3440}, "s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/3b4a4b65944137e841a68cfe71981ad2fb02b169b3a551921eafaaf8ddf9d213.mp3", "hash": "3a6abe4358922b09be4f448ec8473918a6def06e74038f43338a419addb0d65b", "bytes": 153936, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3b4a4b65944137e841a68cfe71981ad2fb02b169b3a551921eafaaf8ddf9d213.mp3", "duration_ms": 25600}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/2cc3d49bdd46e05a8bd42da5f24db3f409476312ec3f58bdb5f496ea75e9cf82.mp3", "hash": "69a0ddcdb840a1fe4ab91205bd293415573a79103ddc8162dff0af7e5c5dbafe", "bytes": 88704, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2cc3d49bdd46e05a8bd42da5f24db3f409476312ec3f58bdb5f496ea75e9cf82.mp3", "duration_ms": 14720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'en-US', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "robot-path", "title": "The delivery cart''s route", "locale": "en-US", "subject": "mixed", "objectives": ["Guide the delivery cart through the neighborhood grid to the customer''s house using the fewest steps."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 10, "type": "robot_path", "hints": ["The cart starts facing up. Which direction is Leo''s house?", "Try a single turn and then go straight ahead."], "title": "The cart''s route", "payload": {"goal": {"x": 2, "y": 0}, "grid": {"h": 4, "w": 4}, "start": {"x": 0, "y": 0, "dir": "up"}, "walls": [{"x": 1, "y": 1}, {"x": 2, "y": 1}], "commands": ["forward", "left", "right"], "max_commands": 3}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Just as you ordered the steps for the cash register, now order the cart''s steps. Zara has a delivery cart that must take a toy to her friend Leo''s house. The cart starts at the corner of the grid, facing up. Leo''s house is to the right, 2 blocks away. Tap the commands to guide it: **forward** (move 1 block), **left** (turn left), **right** (turn right). Use the fewest steps!", "difficulty": 1, "explanation_md": "The cart turned right (1 command) and moved forward 2 steps (2 commands) to reach Leo''s house. You used only 3 commands! Just like with the cash register, ordering the right steps saves time.", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9a894149bdaaea516d539a53a27047f0e217a389555d3f105e64abe1ca9e582c.mp3", "hash": "23fecf159c351a8bb0f26cfffd6de4cd7a8cc4703d0d8b1acc7b28503eb42d25", "bytes": 20448, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9a894149bdaaea516d539a53a27047f0e217a389555d3f105e64abe1ca9e582c.mp3", "duration_ms": 3360}, "s1-robot-path.hint.1": {"url": "http://localhost:4006/files/lesson-audio/76739c3cf05684f3515d26e1b7ff7c9d87ccad1db890ffec1b59042fffe3f968.mp3", "hash": "e5fb08045806a6786f272270d26112e69cada17ba80452f75f5643d18106763e", "bytes": 15264, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/76739c3cf05684f3515d26e1b7ff7c9d87ccad1db890ffec1b59042fffe3f968.mp3", "duration_ms": 2480}, "s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/5a696b2a6efa5b27f1ec26eb67d39531b93c9048d15831f3a3db0d7955d312fd.mp3", "hash": "38963c6926bc60fb519d204f7699ceee56c4466762dc43a515e26c4fa9cc1a7b", "bytes": 118368, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5a696b2a6efa5b27f1ec26eb67d39531b93c9048d15831f3a3db0d7955d312fd.mp3", "duration_ms": 19680}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/9727821d7385591112fc349745eac03f92d51667e97e7e81f731b2a450268217.mp3", "hash": "328fe5e19bed83e28782bcc682f52f0612747895648926d0d7a95b12a6b108e8", "bytes": 67104, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9727821d7385591112fc349745eac03f92d51667e97e7e81f731b2a450268217.mp3", "duration_ms": 11120}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "number-line", "title": "La recta del ahorro", "locale": "es-MX", "subject": "mixed", "objectives": ["Ubicar en la recta numérica del 0 al 100 dónde va el ahorro de Liruf (20 pesos) y dónde la meta (80): ver cuánto falta."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 10, "type": "number_line", "hints": ["El ahorro de Liruf está más cerca del 0 que de la meta.", "Cuenta de 10 en 10 desde 0: 10, 20, 30… hasta 80."], "title": "Marca el ahorro y la meta", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": false}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf juntó 20 pesos agrupando monedas como aprendiste. ¡Ya casi llega a su patineta de 80 pesos! Pero si marca mal en la recta, creerá que ya tiene suficiente. Ayúdala: primero marca dónde está su ahorro (20) y luego dónde está la meta (80). Así sabrá cuánto le falta.", "difficulty": 1, "explanation_md": "Liruf tiene 20 pesos ahorrados y su meta son 80 pesos. En la recta, 20 está más cerca del 0 y 80 más lejos. ¡Le faltan 60 pesos para llegar a su patineta!", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 20, "full_credit_delta": 5, "zero_credit_delta": 15}}', '{"units": {"s1-number-line.hint.0": {"url": "http://localhost:4006/files/lesson-audio/10035a1932c69998881e52b37d4cc6eb2617c8d943f88af6c3e64553285a5fec.mp3", "hash": "21f4b2d780b260310fe8440b61a64f61bdbec3d4a572a9315d8148f99344040b", "bytes": 24336, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/10035a1932c69998881e52b37d4cc6eb2617c8d943f88af6c3e64553285a5fec.mp3", "duration_ms": 4000}, "s1-number-line.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a0dd447a1fa4eafc85927cefe0fcaafc99bc737f7a17147eddff0f65dff4e767.mp3", "hash": "79ce38ed0ac9c332ace6c409a20cf80dc3817a0e41f93f0218fda7987c991095", "bytes": 34848, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/a0dd447a1fa4eafc85927cefe0fcaafc99bc737f7a17147eddff0f65dff4e767.mp3", "duration_ms": 5760}, "s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/b5fe4cbe8d8f660021cfbebf153a57dfcef63841b72bb14ec1b67fa28284285f.mp3", "hash": "3f72b8ebcf196de3b6a94c97127334e0bf0d4be1e75d721c374dcddea75b7b97", "bytes": 118944, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/b5fe4cbe8d8f660021cfbebf153a57dfcef63841b72bb14ec1b67fa28284285f.mp3", "duration_ms": 19760}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/1789a4bd6e08b2c3205b630dfa38ae6b049abbf6b51d3853b7d04e56ee22258a.mp3", "hash": "1d0df4fc5c1a3428b5e59fc58733b52455ebc85b7170028130a9bf71e2bca525", "bytes": 73728, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/1789a4bd6e08b2c3205b630dfa38ae6b049abbf6b51d3853b7d04e56ee22258a.mp3", "duration_ms": 12240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "number-input", "title": "How much did Liruf earn?", "locale": "en-US", "subject": "money", "objectives": ["Calculate and write how much Liruf earned in total if he sold 4 cups at 5 pesos each (20 pesos)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-liruf", "xp": 10, "type": "number_input", "hints": ["First, how much did he receive in total for the 4 cups?", "Then, subtract the 8 pesos he spent."], "title": "Liruf''s Profit", "payload": {"unit": "pesos", "decimals_hint": 0}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Remember, last time you calculated the profit from a single cup. Now Liruf sold more! Liruf spent 8 pesos on lemons and sugar to make lemonade. He sold 4 cups at 5 pesos each. How much money did he actually earn? (Profit = what he received minus what he spent). Write the number.", "difficulty": 1, "explanation_md": "Liruf received 20 pesos for the cups, but spent 8 on ingredients. So his actual profit is 20 - 8 = 12 pesos. That''s what he keeps!", "audio_segment_id": "s1-ganancia-liruf.prompt"}], "schema_version": 1}', '{"s1-ganancia-liruf": {"value": 12, "tolerance": 0}}', '{"units": {"s1-ganancia-liruf.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d73c301a2e7f12afc00461e015b3d3498a3dc4b90f17ff8453de0729b6b20edf.mp3", "hash": "50fa9b5ae4e201a921f7cb0856dc53e7b90f505dd277798f573fccb09ed25bea", "bytes": 19584, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d73c301a2e7f12afc00461e015b3d3498a3dc4b90f17ff8453de0729b6b20edf.mp3", "duration_ms": 3200}, "s1-ganancia-liruf.hint.1": {"url": "http://localhost:4006/files/lesson-audio/14e58a3115b9340860b1b3b5fbfdf4485b673f6fa72df6532edc38f09a3e8315.mp3", "hash": "fb28e52358ff097c28192d84e25ffac71f777c5a52ca7f77ba38febc262e47ca", "bytes": 15696, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/14e58a3115b9340860b1b3b5fbfdf4485b673f6fa72df6532edc38f09a3e8315.mp3", "duration_ms": 2560}, "s1-ganancia-liruf.prompt": {"url": "http://localhost:4006/files/lesson-audio/a279be0d3ef1feee5482cb0dd261308f037fe847a06ef8ef8fba70013ae397e6.mp3", "hash": "2dd412ea6159d4bb6d6ef70a77136991fd7cdc0419c8a9be35d4e4ecda339475", "bytes": 95328, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a279be0d3ef1feee5482cb0dd261308f037fe847a06ef8ef8fba70013ae397e6.mp3", "duration_ms": 15840}, "s1-ganancia-liruf.explanation": {"url": "http://localhost:4006/files/lesson-audio/dad30bcc506db31909c0f0ab284615fcb7d2bedc922492aebc8b76fab630511d.mp3", "hash": "2474d2c40fac100c978f8223cd51ed473392930b3a590864982bd98e1d3ae44c", "bytes": 57024, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/dad30bcc506db31909c0f0ab284615fcb7d2bedc922492aebc8b76fab630511d.mp3", "duration_ms": 9440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "piggy-split", "title": "Repartir la ganancia", "locale": "es-MX", "subject": "money", "objectives": ["Repartir una ganancia de 10 pesos entre dos alcancías: una para la meta de la guitarra y otra para reponer ingredientes."], "estimated_minutes": 4}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 15, "type": "piggy_split", "hints": ["Si pones 3 en ingredientes, ¿cuánto queda para la guitarra?", "Los dos números deben sumar 10."], "title": "Repartir la ganancia", "payload": {"jars": [{"id": "guitar", "icon": "savings", "label": "Alcancía de la guitarra", "hint_md": "Para la guitarra de 80 pesos"}, {"id": "ingredients", "icon": "local_cafe", "label": "Alcancía de ingredientes", "hint_md": "Para reponer limones y vasos"}], "step": 1, "unit": "MXN", "income": 10}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Ayer Liruf te dio 15 pesos de cambio. Hoy ganó 10 pesos más. Necesita guardar al menos 3 pesos para comprar limones mañana, y el resto para su guitarra de 80 pesos. ¿Cuánto pones en cada alcancía? ¡Tienes que repartir los 10 pesos completos!", "difficulty": 2, "explanation_md": "Repartiste 10 pesos: 3 para ingredientes y 7 para la guitarra. Así Liruf puede comprar limones mañana y sigue ahorrando para su guitarra.", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"guitar": {"max": 10, "min": 0}, "ingredients": {"max": 10, "min": 3}}, "rationale_md": "Los dos números deben sumar 10, y al menos 3 deben ir a ingredientes. Por ejemplo, 3 y 7 suman 10. Así Liruf asegura los limones y ahorra para la guitarra."}}', '{"units": {"s1-piggy-split.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0a959db119685842669a51ff7c173d2d8a775bec9b8e77dace230411da74f612.mp3", "hash": "918c45ae7d8762847686cc393c00ec6740464dab80d4a39100608ce57491e6d7", "bytes": 22896, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0a959db119685842669a51ff7c173d2d8a775bec9b8e77dace230411da74f612.mp3", "duration_ms": 3760}, "s1-piggy-split.hint.1": {"url": "http://localhost:4006/files/lesson-audio/92bfb5fc00eb09cc429214c47de5224faa42d98670d405e8299f8ebcb5f60d6f.mp3", "hash": "fa2b3ba3ede792fce99e756f41eba343a5ca6d5a79b5ac43a1789229c0cebf45", "bytes": 13824, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/92bfb5fc00eb09cc429214c47de5224faa42d98670d405e8299f8ebcb5f60d6f.mp3", "duration_ms": 2240}, "s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/53c26cc8efeb02abcc9b4d64b4299725321d76b6b1fe46fa1b0ce4680c2e0d70.mp3", "hash": "d55f9958fc5e4906763502cca6cd411dd60ff570d4ade6bd43ca66acd34d5563", "bytes": 99648, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/53c26cc8efeb02abcc9b4d64b4299725321d76b6b1fe46fa1b0ce4680c2e0d70.mp3", "duration_ms": 16560}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/e376816871b83c0f9f6578aaab9768e8d60417463a8aa1f0c9ae544f6aed61b3.mp3", "hash": "31e10221ff3b7f6c13c913562c079900aab55172376e8b93c8009c6f2c1dda6a", "bytes": 61776, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/e376816871b83c0f9f6578aaab9768e8d60417463a8aa1f0c9ae544f6aed61b3.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'pt-BR', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "estimate-slider", "title": "Estima quantos copos saem da jarra", "locale": "pt-BR", "subject": "mixed", "objectives": ["Estimar quantidades usando uma barra deslizante", "Relacionar o tamanho de uma jarra com a quantidade de copos que ela pode encher"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-jar", "xp": 8, "type": "estimate_slider", "hints": ["Pense: a jarra de Liruf enchia 4 copos. A de Zara é o dobro do tamanho, então pode encher mais copos.", "Se o dobro de 4 é 8, então a jarra de Zara poderia encher cerca de 8 copos."], "title": "Quantos copos saem da jarra?", "payload": {"max": 20, "min": 1, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Liruf vendeu 4 copos de limonada a 5 pesos cada e ganhou 20 pesos. Agora Zara quer vender limonada como Liruf. A jarra dela é muito maior que a de Liruf: a jarra de Liruf enchia 4 copos, mas a de Zara parece o dobro do tamanho. Se cada copo é vendido a 5 pesos, quanto Zara poderia ganhar se vender todos os copos? Primeiro, deslize a barra para estimar quantos copos saem da jarra de Zara.", "difficulty": 1, "explanation_md": "Exato! A jarra de Zara é o dobro do tamanho da de Liruf, então enche uns 8 copos. Se ela vender cada copo a 5 pesos, ganharia 8 × 5 = 40 pesos. Isso é o dobro do que Liruf ganhou!", "audio_segment_id": "s1-estimate-jar.prompt"}], "schema_version": 1}', '{"s1-estimate-jar": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 6}}', '{"units": {"s1-estimate-jar.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7359d0411bfb9a610371875a0e67fbe101ca73660c7713738d87a2b76b723c22.mp3", "hash": "e9b4555b801196abd8c249f974613de6b663b48a25cbffcab5ef73796e2fc083", "bytes": 46368, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/7359d0411bfb9a610371875a0e67fbe101ca73660c7713738d87a2b76b723c22.mp3", "duration_ms": 7680}, "s1-estimate-jar.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b941a94f3c29432c541722cb19755efa3756f0309244aa3e85f3d0f7790b13e0.mp3", "hash": "3c1ba087fdf841b44256238c00b3827de4648410bcfb1b2f67f13ce9220b9d90", "bytes": 37728, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/b941a94f3c29432c541722cb19755efa3756f0309244aa3e85f3d0f7790b13e0.mp3", "duration_ms": 6240}, "s1-estimate-jar.prompt": {"url": "http://localhost:4006/files/lesson-audio/264c90a7473222cb12c8da05fc4e3c144451f292d9bca32b37870081608ce257.mp3", "hash": "a04bf1e8ed575311d031f0c3fe6158ca5e3e1b14c43285377ccce660fdaeeb8b", "bytes": 165024, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/264c90a7473222cb12c8da05fc4e3c144451f292d9bca32b37870081608ce257.mp3", "duration_ms": 27440}, "s1-estimate-jar.explanation": {"url": "http://localhost:4006/files/lesson-audio/a21105fa33a27d5b5bdf14d6587a8db0ac78213ac8a98a56f5ab11b78282fb12.mp3", "hash": "9dab60b74a1c0cc74822f742110c4b52bf9a16013362db8e18b0527d40a6a890", "bytes": 87696, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/a21105fa33a27d5b5bdf14d6587a8db0ac78213ac8a98a56f5ab11b78282fb12.mp3", "duration_ms": 14560}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "make-change", "title": "Give exact change", "locale": "en-US", "subject": "money", "objectives": ["Calculate the change for a purchase of 8 pesos paying with a 20-peso bill using coins of 1, 2, 5, and 10."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-make-change", "xp": 10, "type": "make_change", "hints": ["First, add up how much everything Don Beto bought costs.", "The change is what is left from the bill after paying."], "title": "Don Beto''s change", "payload": {"price": 8, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf just counted coins to pay 5 pesos for his lemonade. Now Don Beto buys a glass of lemonade for 5 pesos and a cookie for 3 pesos. He pays with a 20-peso bill. But Don Beto needs exact change for the bus. If you give him less than what he is owed, he will be left without a ride! How much change do you need to give him? Make the change with the coins you have.", "difficulty": 1, "explanation_md": "The total is 5 + 3 = 8 pesos. He paid with 20, so the change is 20 - 8 = 12 pesos. You gave him 12 pesos in coins. That way Don Beto can take the bus!", "audio_segment_id": "s1-make-change.prompt"}], "schema_version": 1}', '{"s1-make-change": {}}', '{"units": {"s1-make-change.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ebfcd37c5862b23f1f5f852411e43e3880ca60c954727dcd7bebee8c101166c1.mp3", "hash": "54e1f9680cbe4456a63b50fc2a6413fd66cbe5ca0fa41b5920f1e557849cef82", "bytes": 22896, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/ebfcd37c5862b23f1f5f852411e43e3880ca60c954727dcd7bebee8c101166c1.mp3", "duration_ms": 3760}, "s1-make-change.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0f9f11a5e347ddc42c74f2dce3fbc889e5e45cb860d023d08ec61d229cc42489.mp3", "hash": "513b5cac0511a9ad86f679d6acbdc30c3bf0a39de40f824292e12a72d269fe3b", "bytes": 20016, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/0f9f11a5e347ddc42c74f2dce3fbc889e5e45cb860d023d08ec61d229cc42489.mp3", "duration_ms": 3280}, "s1-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/774c6011139dab8b83e818afe0888370881ab6ccff347edb4a8adaf67bc2de2a.mp3", "hash": "a5aa5870f0b73766fc65fc1833c48eee2cbb98d46d1c6296a628b8a2c4ec7463", "bytes": 133776, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/774c6011139dab8b83e818afe0888370881ab6ccff347edb4a8adaf67bc2de2a.mp3", "duration_ms": 22240}, "s1-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/9138c7e1d22390cf8ca26209de70ab7837ab2d1da62868838213a469e9616e90.mp3", "hash": "dfeccf8ef9b80e57cc0ea9c5d15f7a8fff289d5fe3e1f198d35ddb9d6b1e7805", "bytes": 74304, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/9138c7e1d22390cf8ca26209de70ab7837ab2d1da62868838213a469e9616e90.mp3", "duration_ms": 12320}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "coin-count", "title": "Counting coins from the sale", "locale": "en-US", "subject": "mixed", "objectives": ["Counting 1 and 2 peso coins to make exactly 5 pesos"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 10, "type": "coin_count", "hints": ["Count the 2-peso coins first, then the 1-peso coins.", "Add: 2 + 2 = 4, then 4 + 1 = 5."], "title": "Does she have enough for the sticker?", "payload": {"target": 5, "currency": "MXN", "denominations": [1, 2, 2]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina sold lemonade and was paid with these coins. She wants to buy a sticker that costs 5 pesos. Remember that Liruf saved until reaching 80 on the number line. Now Dina counts her coins to see if she has exactly 5 pesos. Does she have enough for the sticker?", "difficulty": 1, "explanation_md": "Yes, she has enough! Dina has exactly 5 pesos: 2 + 2 = 4, plus 1 = 5. With that, she can buy the sticker, just like Liruf reached his goal on the number line.", "audio_segment_id": "s1-coin-count.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}}', '{"units": {"s1-coin-count.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c3457a9e1a7ad9ab46d5b6fc6145d28c03dbb3a167e2fce548898e99047147eb.mp3", "hash": "e73fce264b4bb287cf2a1a4b0670d7ba1c8ac7f5118dc6879e072f70a52c7c2a", "bytes": 22464, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c3457a9e1a7ad9ab46d5b6fc6145d28c03dbb3a167e2fce548898e99047147eb.mp3", "duration_ms": 3680}, "s1-coin-count.hint.1": {"url": "http://localhost:4006/files/lesson-audio/762188a4743ab76f73c5bec9c73ab2f0bab598e2a327081f2719307387d85118.mp3", "hash": "500eb09045d76e92a6aeddc9dda8b5e9745b26b067bb4600e283ea0c1b4846d3", "bytes": 25344, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/762188a4743ab76f73c5bec9c73ab2f0bab598e2a327081f2719307387d85118.mp3", "duration_ms": 4160}, "s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/b4fa4d0d6e65b1d7c83b6c29b624976cf8c518523f1db2eb3775026ad7b86e5d.mp3", "hash": "ccbde22feb868539ff56865cea846be3988bb1f0856ef323768d291157b948fe", "bytes": 81504, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b4fa4d0d6e65b1d7c83b6c29b624976cf8c518523f1db2eb3775026ad7b86e5d.mp3", "duration_ms": 13520}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/970ef9c84f60eef3405467bf4e442744494c7aa62fcb0e15d93f819a6760753e.mp3", "hash": "0f36a76b57897a6e43e37889811aa4c18e6590f0890acaacb6178f192f929a32", "bytes": 64656, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/970ef9c84f60eef3405467bf4e442744494c7aa62fcb0e15d93f819a6760753e.mp3", "duration_ms": 10720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "group-sets", "title": "Ordena la caja del puesto", "locale": "es-MX", "subject": "money", "objectives": ["Agrupar monedas y billetes para contar el dinero más fácil"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-sets", "xp": 10, "type": "group_sets", "hints": ["Las monedas son redondas y de metal; los billetes son de papel y rectangulares.", "Busca el símbolo de moneda ($) para identificar los billetes."], "title": "Separa el dinero", "payload": {"items": [{"id": "moneda-1", "text_md": "🪙 Moneda de 5 pesos"}, {"id": "moneda-2", "text_md": "🪙 Moneda de 2 pesos"}, {"id": "moneda-3", "text_md": "🪙 Moneda de 10 pesos"}, {"id": "billete-1", "text_md": "💵 Billete de 20 pesos"}, {"id": "billete-2", "text_md": "💵 Billete de 50 pesos"}, {"id": "billete-3", "text_md": "💵 Billete de 100 pesos"}], "set_a": "Monedas", "set_b": "Billetes"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Al igual que ordenaste los vasos chico-grande, ahora ordena el dinero de Liruf. Después de vender limonada, la caja tiene monedas y billetes revueltos. Si agrupas bien, sabrás si alcanza para comprar más limones. Toca cada moneda y ponla en el grupo de monedas, y cada billete en el grupo de billetes. Luego suma cuánto hay en monedas y cuánto en billetes para saber si Liruf puede comprar más limones (cuestan 15 pesos).", "difficulty": 1, "explanation_md": "Separar monedas y billetes ayuda a contar el dinero más rápido. Liruf tiene 17 pesos en monedas y 170 pesos en billetes. ¡Sí alcanza para comprar más limones!", "audio_segment_id": "s1-group-sets.prompt"}], "schema_version": 1}', '{"s1-group-sets": {"zones": {"moneda-1": "a", "moneda-2": "a", "moneda-3": "a", "billete-1": "b", "billete-2": "b", "billete-3": "b"}}}', '{"units": {"s1-group-sets.hint.0": {"url": "http://localhost:4006/files/lesson-audio/48a5bcd9597de2d7358642947426dd4177b0b3c206f2b6a17a04bcde33b868b9.mp3", "hash": "e94be8deb93ad2021ecd8c71c9bbaca0aabdbfc97a27c2db06e251b3335e32e8", "bytes": 33408, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/48a5bcd9597de2d7358642947426dd4177b0b3c206f2b6a17a04bcde33b868b9.mp3", "duration_ms": 5520}, "s1-group-sets.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2f8221a5f9ebbdece04e1b8bb5c79bf9853d473a694ca104bb7c92b0837c4596.mp3", "hash": "18fb9cb16a792ac154163a9bc61fcab851ecb46121bc02a511504fa5fc34f612", "bytes": 21456, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2f8221a5f9ebbdece04e1b8bb5c79bf9853d473a694ca104bb7c92b0837c4596.mp3", "duration_ms": 3520}, "s1-group-sets.prompt": {"url": "http://localhost:4006/files/lesson-audio/a2b216136fca3849728fbc11291669860a8e61c699e93b4bf54a74d19cb005b9.mp3", "hash": "5fb29500cf87404a4a5258d3c6f57b5dd751497864480cde7b0dba4e6aa76cd5", "bytes": 157248, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a2b216136fca3849728fbc11291669860a8e61c699e93b4bf54a74d19cb005b9.mp3", "duration_ms": 26160}, "s1-group-sets.explanation": {"url": "http://localhost:4006/files/lesson-audio/7b55ba0a5de7bf0024e777fe3b15c5bb00f75eb86c80f4055019b2e0abe2d484.mp3", "hash": "d7198c98d08d72d66148a07163b7bfce02e9010c72d799cf8581f750dcdc04a4", "bytes": 68976, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7b55ba0a5de7bf0024e777fe3b15c5bb00f75eb86c80f4055019b2e0abe2d484.mp3", "duration_ms": 11440}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'es-MX', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "flash-match", "title": "Carrera de conceptos del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Relacionar palabras clave del puesto con sus ejemplos concretos", "Reconocer ahorro, costo y ganancia en situaciones del puesto de limonada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 0, "type": "flash_match", "hints": ["Piensa en lo que cada palabra significa en el puesto de limonada.", "El ahorro es lo que guardas, el costo es lo que pagas, la ganancia es lo que te sobra."], "title": "Conecta los conceptos", "payload": {"left": [{"id": "ahorro", "text_md": "Ahorro"}, {"id": "costo", "text_md": "Costo"}, {"id": "ganancia", "text_md": "Ganancia"}], "right": [{"id": "alcancia", "text_md": "Alcancía de Zara con 5 pesos"}, {"id": "limones", "text_md": "8 limones que Dina compró ayer"}, {"id": "sobra", "text_md": "2 pesos que Zara ganó por ayudar"}], "seconds": 30}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Ayer Zara negoció con Dina: ''Si te ayudo a vender, ¿me das 2 pesos de ganancia?'' Dina aceptó. Ahora Zara tiene 5 pesos guardados en su alcancía. ¿Qué significa cada palabra del puesto? Toca la palabra de la izquierda y luego su ejemplo de la derecha. ¡Rápido!", "difficulty": 1, "explanation_md": "Cada palabra del puesto tiene un ejemplo concreto: ahorro es la alcancía de Zara donde guarda 5 pesos, costo son los 8 limones que Dina compró ayer, y ganancia son los 2 pesos que Zara ganó por ayudar.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["ahorro", "alcancia"], ["costo", "limones"], ["ganancia", "sobra"]]}}', '{"units": {"s1-flash-match.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c27cb74228cc4d8a400506a13f37af34d4b8c4e05c441d296f33b6bd1dadbc2a.mp3", "hash": "9400f98f14526d1a8ca4982bed416e1e5c7eb07da0404ed0f43d294d4c2abbf3", "bytes": 22896, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/c27cb74228cc4d8a400506a13f37af34d4b8c4e05c441d296f33b6bd1dadbc2a.mp3", "duration_ms": 3760}, "s1-flash-match.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a9f520be53f96f9ecba66023bde25ce4c04ba6979184a97460bc7a313fcfb361.mp3", "hash": "d0450dc4641933291f5d99bcd4edf15462cb58dfea53e62dbfcbdf08d9a55f11", "bytes": 32976, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/a9f520be53f96f9ecba66023bde25ce4c04ba6979184a97460bc7a313fcfb361.mp3", "duration_ms": 5440}, "s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/bcc57f86166d528fd8a58b921708a97815dea8a10dcf30369672e73a57d7e3eb.mp3", "hash": "788161a04ca883502ef4007bb9f19bb0c57ff9f57ac6534b400a1b113f0e4083", "bytes": 99216, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/bcc57f86166d528fd8a58b921708a97815dea8a10dcf30369672e73a57d7e3eb.mp3", "duration_ms": 16480}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/720b82824d2e5b2d96ecf45e67ccd65253e5d421103a702131ba7f797d15405f.mp3", "hash": "5be6f04d61e886a2ef5fefe55d6b34b0f07ed7b21fdd0927b5a3699ee7a39768", "bytes": 80496, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/720b82824d2e5b2d96ecf45e67ccd65253e5d421103a702131ba7f797d15405f.mp3", "duration_ms": 13360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "coin-count", "title": "Contar moedas da venda", "locale": "pt-BR", "subject": "mixed", "objectives": ["Contar moedas de 1 e 2 reais para somar 5 reais exatos"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 10, "type": "coin_count", "hints": ["Conte as moedas de 2 primeiro, depois as de 1.", "Soma: 2 + 2 = 4, depois 4 + 1 = 5."], "title": "Dá para comprar o adesivo?", "payload": {"target": 5, "currency": "MXN", "denominations": [1, 2, 2]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina vendeu limonada e pagaram a ela com estas moedas. Ela quer comprar um adesivo de 5 reais. Lembre-se de que Liruf economizou até chegar a 80 na reta numérica. Agora Dina conta suas moedas para ver se já tem os 5 reais exatos. Dá para comprar o adesivo?", "difficulty": 1, "explanation_md": "Sim, dá! Dina tem 5 reais exatos: 2 + 2 = 4, mais 1 = 5. Com isso ela pode comprar o adesivo, assim como Liruf alcançou sua meta na reta numérica.", "audio_segment_id": "s1-coin-count.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}}', '{"units": {"s1-coin-count.hint.0": {"url": "http://localhost:4006/files/lesson-audio/889c0f469e738d3fccb51a3bd1dd35b32841b929a5e8a5a9c4b8e80bc2b18f0f.mp3", "hash": "07c31c801628e28dd98a97d281e8f04ccf42b8485c1e962485ec69a86b7e602e", "bytes": 21024, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/889c0f469e738d3fccb51a3bd1dd35b32841b929a5e8a5a9c4b8e80bc2b18f0f.mp3", "duration_ms": 3440}, "s1-coin-count.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b75070f07d4bf9dee43c15b4da3638684b8e7b9b520942a22a8b5a1716de569b.mp3", "hash": "01a4ad49f0f16e1bf14caae00503c8ce463a8790beb6af23ba8eb9c628ca75da", "bytes": 32976, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b75070f07d4bf9dee43c15b4da3638684b8e7b9b520942a22a8b5a1716de569b.mp3", "duration_ms": 5440}, "s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/a3e934d5721d98a3ec444e966debda542958fe98939d3793aae5f05faeff38bd.mp3", "hash": "b526d48761fb649fbf63041a5f7db582a189802717db5498955a0ec640d8bb52", "bytes": 112608, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a3e934d5721d98a3ec444e966debda542958fe98939d3793aae5f05faeff38bd.mp3", "duration_ms": 18720}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/51c7ce60816b0bddb1f5b272e69a5e966aa106650f9a4fc6ab80df0bbfac4842.mp3", "hash": "58100bfecb61f7138e5c237c46af97b2b1f84e9657fd89720f94b4356260d4b8", "bytes": 83376, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/51c7ce60816b0bddb1f5b272e69a5e966aa106650f9a4fc6ab80df0bbfac4842.mp3", "duration_ms": 13840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "piggy-split", "title": "Splitting the profit", "locale": "en-US", "subject": "money", "objectives": ["Splitting a profit of 10 pesos between two piggy banks: one for the guitar goal and one to restock ingredients."], "estimated_minutes": 4}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 15, "type": "piggy_split", "hints": ["If you put 3 in ingredients, how much is left for the guitar?", "The two numbers must add up to 10."], "title": "Splitting the profit", "payload": {"jars": [{"id": "guitar", "icon": "savings", "label": "Guitar piggy bank", "hint_md": "For the 80-peso guitar"}, {"id": "ingredients", "icon": "local_cafe", "label": "Ingredients piggy bank", "hint_md": "To restock lemons and cups"}], "step": 1, "unit": "MXN", "income": 10}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Yesterday Liruf gave you 15 pesos in change. Today he earned 10 more pesos. He needs to save at least 3 pesos to buy lemons tomorrow, and the rest for his 80-peso guitar. How much do you put in each piggy bank? You have to split all 10 pesos!", "difficulty": 2, "explanation_md": "You split 10 pesos: 3 for ingredients and 7 for the guitar. That way Liruf can buy lemons tomorrow and keep saving for his guitar.", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"guitar": {"max": 10, "min": 0}, "ingredients": {"max": 10, "min": 3}}, "rationale_md": "Los dos números deben sumar 10, y al menos 3 deben ir a ingredientes. Por ejemplo, 3 y 7 suman 10. Así Liruf asegura los limones y ahorra para la guitarra."}}', '{"units": {"s1-piggy-split.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0147f32dbdfa9fa408a77c4243ad993a1248803c46dfc8588752bf9c9cab4de8.mp3", "hash": "61f2a947dbef8813d7ee1029b48b43c82a8d085e155b2a8011177a5ec20e1213", "bytes": 19008, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0147f32dbdfa9fa408a77c4243ad993a1248803c46dfc8588752bf9c9cab4de8.mp3", "duration_ms": 3120}, "s1-piggy-split.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5acba3eb22f604b5368331e161e606ec5f374d3f57e40ba337bb13c6107f7bee.mp3", "hash": "7f6103c8daa18e70d3193ebb7a7ac99dde91d57692f4776d4c89cc239fc68a2b", "bytes": 13248, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5acba3eb22f604b5368331e161e606ec5f374d3f57e40ba337bb13c6107f7bee.mp3", "duration_ms": 2160}, "s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/02117d61910d1ff1f70a2734468ac8d5692e85906d221d46704ee8b13a2b248c.mp3", "hash": "52d10eabe5cc9eb470a189da899052a0eda42d0fd748277658e3a0ea2a66e32c", "bytes": 89568, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/02117d61910d1ff1f70a2734468ac8d5692e85906d221d46704ee8b13a2b248c.mp3", "duration_ms": 14880}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/7c0e3ac67592198faa80c905a740b988713fee22066d35be7fc66c162d754cd1.mp3", "hash": "97875b01eaeba347a7d2975c4f893bc6c15c43a1a47d9d642f20890b4ed279a9", "bytes": 48384, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/7c0e3ac67592198faa80c905a740b988713fee22066d35be7fc66c162d754cd1.mp3", "duration_ms": 8000}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'es-MX', '1', '{"meta": {"cast": ["rho"], "slug": "rank-choices", "title": "Ordena tus compras", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar de más a menos urgente en qué gastar la ganancia de hoy: reponer limones primero, luego vasos, y al final adornos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-compras", "xp": 15, "type": "rank_choices", "hints": ["Piensa: ¿qué necesita el puesto para seguir vendiendo limonada?", "Los adornos son bonitos, pero no urgentes."], "title": "¿Qué comprar primero?", "payload": {"items": [{"id": "limones", "text_md": "Reponer limones (cuestan 8 pesos)"}, {"id": "vasos", "text_md": "Comprar vasos nuevos (cuestan 5 pesos)"}, {"id": "adornos", "text_md": "Adornos para el puesto (cuestan 3 pesos)"}], "criterion_md": "Ordena del más urgente (arriba) al menos urgente (abajo)."}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho ganó 20 pesos en su puesto de limonada. Ayuda a Rho a decidir qué comprar primero. Toca los gastos para ordenarlos del más urgente al menos urgente.", "difficulty": 2, "explanation_md": "Rho necesita limones para hacer más limonada, luego vasos para servirla. Los adornos pueden esperar.", "audio_segment_id": "s1-ordenar-compras.prompt"}], "schema_version": 1}', '{"s1-ordenar-compras": {"order": ["limones", "vasos", "adornos"]}}', '{"units": {"s1-ordenar-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b2a8b08920ae67b27d15c7bea3a03217031f5d721cdffcd413d6e2a4b88a7b4f.mp3", "hash": "bde6e4e92862e6a9229b95358207c57174bd75165d7134dd3d8497b35ef5f70c", "bytes": 25776, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/b2a8b08920ae67b27d15c7bea3a03217031f5d721cdffcd413d6e2a4b88a7b4f.mp3", "duration_ms": 4240}, "s1-ordenar-compras.hint.1": {"url": "http://localhost:4006/files/lesson-audio/1594ece22a2b360c4626a4329650d92c27b5d61eabd9d01541f65fd9c321ab34.mp3", "hash": "adc032478a1755ba3e25ce16357e085e80e6a12487c4848658c2d67d48803757", "bytes": 19584, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/1594ece22a2b360c4626a4329650d92c27b5d61eabd9d01541f65fd9c321ab34.mp3", "duration_ms": 3200}, "s1-ordenar-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/f37ac24e05a4012f5d7840932d16d532d9173c50ce7b1910dc1211a001fcfcf1.mp3", "hash": "2cf545732110469f451cf9d4add986a4e3b947d513bfa8fe9b5f8b66688c49bf", "bytes": 78624, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/f37ac24e05a4012f5d7840932d16d532d9173c50ce7b1910dc1211a001fcfcf1.mp3", "duration_ms": 13040}, "s1-ordenar-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/8995ff6e993b4f32615422ce196d1a8ee6d17f7c7b3fe9453a5096318d41a20f.mp3", "hash": "3482d0ee93ae4d8232fcd852c3b9fca118798ff6c18303c2b180031de9bace23", "bytes": 51696, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/8995ff6e993b4f32615422ce196d1a8ee6d17f7c7b3fe9453a5096318d41a20f.mp3", "duration_ms": 8560}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Compare fornecedores de limões", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ler uma tabela de dois fornecedores e escolher o que dá mais por menos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 10, "type": "compare_table", "hints": ["Se fizer sol, Dina vende mais limonadas, então precisa de mais limões.", "Compare quantos limões cada fornecedor dá pelo mesmo preço."], "title": "Qual fornecedor é melhor para você?", "payload": {"cols": [{"id": "precio", "label": "Preço"}, {"id": "limones", "label": "Limões"}], "rows": [{"id": "proveedor-a", "label": "Fornecedor A"}, {"id": "proveedor-b", "label": "Fornecedor B"}], "tokens": [{"id": "t1", "text_md": "10 reais"}, {"id": "t2", "text_md": "20 limões"}, {"id": "t3", "text_md": "10 reais"}, {"id": "t4", "text_md": "30 limões"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Ontem, com sol, Dina vendeu 20 limonadas. Mas hoje está nublado e ela vendeu apenas 10. Dina lembra: quando faz sol, as pessoas compram mais, mesmo que o preço suba um pouco. Agora ela precisa escolher um fornecedor de limões para amanhã. Se fizer sol, ela quer muitos limões; se estiver nublado, não precisa de tantos. Veja a tabela dos dois fornecedores. Qual é melhor para ela se amanhã fizer sol? Toque em cada célula para ver os dados.", "difficulty": 1, "explanation_md": "Se fizer sol, Dina venderá muitas limonadas. O fornecedor B dá 30 limões por 10 reais, enquanto o A dá apenas 20. Com o B, ela obtém mais limões pelo mesmo dinheiro, exatamente o que precisa para um dia ensolarado.", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"proveedor-a:precio": "t1", "proveedor-b:precio": "t3", "proveedor-a:limones": "t2", "proveedor-b:limones": "t4"}}}', '{"units": {"s1-compare-table.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a452ce462e064daa47ae6c847a5242fd3652645eeadb5fbc382c293c48bb2232.mp3", "hash": "4d852a62dab8b1d2f0ccb24ef7e38a229d33f420bbf2c253de989a96c5b52fdc", "bytes": 32976, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a452ce462e064daa47ae6c847a5242fd3652645eeadb5fbc382c293c48bb2232.mp3", "duration_ms": 5440}, "s1-compare-table.hint.1": {"url": "http://localhost:4006/files/lesson-audio/aa9d585f6055ac08af81344878084f980e8c9ec8136c04f478be3361040b4e9d.mp3", "hash": "5ae4e1d5f1688bf1bf14fbc4997ebf45b4956ea5ec71dba069b9e93c6e405941", "bytes": 27216, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/aa9d585f6055ac08af81344878084f980e8c9ec8136c04f478be3361040b4e9d.mp3", "duration_ms": 4480}, "s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/5894fcbead108651d2b540014b0e29387a3b57f5bc285deff1e6f6bd975e0b16.mp3", "hash": "4aa2957f333bfd6d343d6504892bf67bc473cbf667c5884bbf7b7009ff1ca426", "bytes": 173664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5894fcbead108651d2b540014b0e29387a3b57f5bc285deff1e6f6bd975e0b16.mp3", "duration_ms": 28880}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/10a402282f14fd02758c991cb442d920ea783a8d76c196dcd86b37370684b27b.mp3", "hash": "69adc3c19f5a7d7dcdf78a7a9cc1979a11f1a89375672ce2cf95c81dbc879bd5", "bytes": 100224, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/10a402282f14fd02758c991cb442d920ea783a8d76c196dcd86b37370684b27b.mp3", "duration_ms": 16640}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Compare lemon suppliers", "locale": "en-US", "subject": "mixed", "objectives": ["Read a table of two suppliers and choose the one that gives more for less."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 10, "type": "compare_table", "hints": ["If it''s sunny, Dina sells more lemonades, so she needs more lemons.", "Compare how many lemons each supplier gives for the same price."], "title": "Which supplier is better for you?", "payload": {"cols": [{"id": "precio", "label": "Price"}, {"id": "limones", "label": "Lemons"}], "rows": [{"id": "proveedor-a", "label": "Supplier A"}, {"id": "proveedor-b", "label": "Supplier B"}], "tokens": [{"id": "t1", "text_md": "10 pesos"}, {"id": "t2", "text_md": "20 lemons"}, {"id": "t3", "text_md": "10 pesos"}, {"id": "t4", "text_md": "30 lemons"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Yesterday, with the sun, Dina sold 20 lemonades. But today it''s cloudy and she sold only 10. Dina remembers: when it''s sunny, people buy more, even if the price goes up a bit. Now she has to choose a lemon supplier for tomorrow. If it''s sunny, she wants lots of lemons; if it''s cloudy, she doesn''t need as many. Look at the table of the two suppliers. Which one is better for her if it''s sunny tomorrow? Tap each cell to see the data.", "difficulty": 1, "explanation_md": "If it''s sunny, Dina will sell many lemonades. Supplier B gives 30 lemons for 10 pesos, while Supplier A gives only 20. With B she gets more lemons for the same money, just what she needs for a sunny day.", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"proveedor-a:precio": "t1", "proveedor-b:precio": "t3", "proveedor-a:limones": "t2", "proveedor-b:limones": "t4"}}}', '{"units": {"s1-compare-table.hint.0": {"url": "http://localhost:4006/files/lesson-audio/28f7c4f250a9ef874d2f546f18d7fd32212600296f4c66ed32ed9ddfa604c8df.mp3", "hash": "59ebe2600cc579d8598ffa3ce8a4c1d1985ee64a137a789ee6307addac24aaf1", "bytes": 23328, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/28f7c4f250a9ef874d2f546f18d7fd32212600296f4c66ed32ed9ddfa604c8df.mp3", "duration_ms": 3840}, "s1-compare-table.hint.1": {"url": "http://localhost:4006/files/lesson-audio/3d82bf4e2b7b967d838b1fd13235f837d20785676962573754f3bb70562c8cfc.mp3", "hash": "bb70bca0ea00310c3749eef9341b624fa730b260c3a01ea4b26991607cd24892", "bytes": 20016, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3d82bf4e2b7b967d838b1fd13235f837d20785676962573754f3bb70562c8cfc.mp3", "duration_ms": 3280}, "s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/77a4bce04b176a6b3a0177d60ab2c7eb4493960296cde5329ce3c8ac00ef4862.mp3", "hash": "41d97784147c835507055086ae49278844fb8eb9e0187b739e495dc8fcb660a4", "bytes": 139536, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/77a4bce04b176a6b3a0177d60ab2c7eb4493960296cde5329ce3c8ac00ef4862.mp3", "duration_ms": 23200}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/f13231794c288683b17dfd8743ad8c0a7864199cd70069c50e3dbe738c062d53.mp3", "hash": "abde24977768cdd63ab2f94999d16c58168395cd0cf7ed45a0f476cf3293be21", "bytes": 68976, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f13231794c288683b17dfd8743ad8c0a7864199cd70069c50e3dbe738c062d53.mp3", "duration_ms": 11440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'es-MX', '1', E'{"meta": {"cast": ["dina"], "slug": "would-you-rather", "title": "Vivir el puesto en historias jugables", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir entre dos caminos del vendedor y defenderlo: ¿ganar 10 pesos hoy o 20 la próxima semana? No hay respuesta única, hay razones."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-would-you-rather", "xp": 0, "type": "would_you_rather", "hints": ["Calcula cuánto dinero da cada plan. ¿Cuál te da suficiente para la patineta?"], "title": "¿Ganar hoy o mañana?", "payload": {"a": {"icon": "local_cafe", "text_md": "Plan A: vender 3 vasos hoy a $5 cada uno"}, "b": {"icon": "calendar_month", "text_md": "Plan B: esperar una semana y vender 6 vasos a $4 cada uno"}, "followup_md": "¿Por qué elegiste ese plan? Cuéntale a Dina tu razón."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Ayer contaste vasos y cambios. Hoy Dina tiene dos planes para su puesto de limonada:\\n\\n**Plan A:** Vender 3 vasos HOY a $5 cada uno. ¡Dinero rápido!\\n**Plan B:** Preparar 6 vasos para la próxima semana a $4 cada uno. Más dinero, pero hay que esperar.\\n\\nDina quiere comprar un patineta que cuesta $20. ¿Qué plan la acerca más a su meta?", "difficulty": 1, "explanation_md": "El Plan A da $15, que no alcanza para la patineta de $20. El Plan B da $24, que sí alcanza y hasta sobra. Dina elige el Plan B porque la acerca a su meta.", "audio_segment_id": "s1-would-you-rather.prompt"}], "schema_version": 1}', '{"s1-would-you-rather": {"qualities": {"a": 0, "b": 100}, "reveal_md": "Dina sonríe: «¡Bien pensado! Usaste lo que aprendiste ayer de sumar vasos. El Plan B da $24, justo para la patineta. Si elegiste el Plan A, recuerda que $15 no alcanzan para la patineta; necesitas $5 más.»"}}', '{"units": {"s1-would-you-rather.hint.0": {"url": "http://localhost:4006/files/lesson-audio/43afa5ec9572799069e733dff985b7f0f7ca106ee4455482fd36090afcab8331.mp3", "hash": "234ec09a661a0f0929ba8cf1336857ed8d766483cb2c257050053630f2ac4ab6", "bytes": 31104, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/43afa5ec9572799069e733dff985b7f0f7ca106ee4455482fd36090afcab8331.mp3", "duration_ms": 5120}, "s1-would-you-rather.prompt": {"url": "http://localhost:4006/files/lesson-audio/269cb8afd59bc7ad8778d19cd9036d26b0a185a2cd6653e5890b4accfebe8387.mp3", "hash": "6858dbad87c85017dd909c8fdedf3cc1876eea692149d188b0c67aa6119918d3", "bytes": 140976, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/269cb8afd59bc7ad8778d19cd9036d26b0a185a2cd6653e5890b4accfebe8387.mp3", "duration_ms": 23440}, "s1-would-you-rather.choices": {"url": "http://localhost:4006/files/lesson-audio/a13b622177c139d9d2a28a40eecde64f5ff432cf1e00fab383d02632111b21f9.mp3", "hash": "bf1517fedc8c2491d7a3609902d2da409d3ff9b91a4e1e9723c50f4b0d2032cd", "bytes": 61776, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a13b622177c139d9d2a28a40eecde64f5ff432cf1e00fab383d02632111b21f9.mp3", "duration_ms": 10240}, "s1-would-you-rather.explanation": {"url": "http://localhost:4006/files/lesson-audio/ae9a0f6762a2bde877a4bf5652111b3e16ef35af054050518fb772d9a322824f.mp3", "hash": "e64bdd8b22ea0892dd0367b27c7cccc3ad5f78bab5ee5edd0dca58f91e65a86b", "bytes": 76608, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/ae9a0f6762a2bde877a4bf5652111b3e16ef35af054050518fb772d9a322824f.mp3", "duration_ms": 12720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "red-flags", "title": "Sinais de alerta na barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Detectar os sinais de alerta na oferta de um desconhecido: promessas boas demais não são confiáveis."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-red-flags", "xp": 10, "type": "red_flags", "hints": ["Pense: é normal ganhar 80 reais da noite para o dia sem trabalhar?", "Você conhece aquele vendedor? Por que ele estaria tão apressado?"], "title": "O negócio mágico", "payload": {"flags": [{"id": "f1", "text_md": "Promete muito dinheiro em muito pouco tempo"}, {"id": "f2", "text_md": "O vendedor é um desconhecido"}, {"id": "f3", "text_md": "O vendedor está muito apressado"}, {"id": "f4", "text_md": "Não explica como vai ganhar esse dinheiro"}], "artifact_md": "**Oferta relâmpago:** Me dê 20 reais hoje e amanhã te dou 100. Só hoje!", "artifact_kind": "ad"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Assim como você verificou o recibo para ver quanto custaram os limões, agora confira esta oferta para ver se algo não está certo. Um vendedor apressado diz a Liruf: ''Me dê seus 20 reais hoje e amanhã te dou 100. É um negócio mágico!'' Liruf está animado, mas você sabe que é preciso verificar com cuidado. Que sinais de alerta você vê nesta oferta?", "difficulty": 1, "explanation_md": "Promessas de ganhar muito dinheiro muito rápido sem esforço quase sempre são falsas. O vendedor desconhecido e apressado é um sinal de alerta.", "audio_segment_id": "s1-red-flags.prompt"}], "schema_version": 1}', '{"s1-red-flags": {"redflag_ids": ["f1", "f2", "f3", "f4"]}}', '{"units": {"s1-red-flags.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f15933317d2e613528ff8364972829a820e1fe4440acbf288b136503e36b2d35.mp3", "hash": "6707566eed1ce3d39a21ccf5da3d045bc5f3e2e554d4b19f4a48cfef2d4ac9ff", "bytes": 31536, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f15933317d2e613528ff8364972829a820e1fe4440acbf288b136503e36b2d35.mp3", "duration_ms": 5200}, "s1-red-flags.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c560abca1a533a12bc7002093885405cb423907ecf21b22ec41b0214d25a24e4.mp3", "hash": "5829edf2ac0dddc20df4e30b563de7e083b65af4dd21aec37c86a2ea06fbd261", "bytes": 26784, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c560abca1a533a12bc7002093885405cb423907ecf21b22ec41b0214d25a24e4.mp3", "duration_ms": 4400}, "s1-red-flags.prompt": {"url": "http://localhost:4006/files/lesson-audio/3c614f411d19f9f395058dba0ff72679cf353b2d77cc1afd8a3a62d39c7731a7.mp3", "hash": "11e554c81c12012a7fc437af728fe51b93c616fa5a5a123e32529deaf7cafd6a", "bytes": 152064, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3c614f411d19f9f395058dba0ff72679cf353b2d77cc1afd8a3a62d39c7731a7.mp3", "duration_ms": 25280}, "s1-red-flags.explanation": {"url": "http://localhost:4006/files/lesson-audio/bf44a7e4b6df05da242590151a1adb39fb9adb36977bef83a3cc77ddd5e2b152.mp3", "hash": "1051e1c5e2c8714c7961b814a667fdac712d7e9d603f772777047add5231e339", "bytes": 65664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/bf44a7e4b6df05da242590151a1adb39fb9adb36977bef83a3cc77ddd5e2b152.mp3", "duration_ms": 10880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "red-flags", "title": "Red flags at the stall", "locale": "en-US", "subject": "mixed", "objectives": ["Spot the red flags in a stranger''s offer: promises too good to be true can''t be trusted."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-red-flags", "xp": 10, "type": "red_flags", "hints": ["Think: is it normal to earn 80 pesos overnight without working?", "Do you know that seller? Why would he be in such a hurry?"], "title": "The magic deal", "payload": {"flags": [{"id": "f1", "text_md": "Promises a lot of money in very little time"}, {"id": "f2", "text_md": "The seller is a stranger"}, {"id": "f3", "text_md": "The seller is in a big hurry"}, {"id": "f4", "text_md": "Doesn''t explain how he will earn that money"}], "artifact_md": "**Flash offer:** Give me 20 pesos today and tomorrow I''ll give you 100. Today only!", "artifact_kind": "ad"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Just like you checked the receipt to see how much the lemons cost, now check this offer to see if something doesn''t add up. A hurried seller tells Liruf: ''Give me your 20 pesos today and tomorrow I''ll give you 100. It''s a magic deal!'' Liruf is excited, but you know you have to look carefully. What red flags do you see in this offer?", "difficulty": 1, "explanation_md": "Promises of making a lot of money very quickly with no effort are almost always false. The unknown, hurried seller is a red flag.", "audio_segment_id": "s1-red-flags.prompt"}], "schema_version": 1}', '{"s1-red-flags": {"redflag_ids": ["f1", "f2", "f3", "f4"]}}', '{"units": {"s1-red-flags.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5564b91ccb186bd507e7b3f1555c6b75514c8b603503d274ad108f4efdfd6587.mp3", "hash": "ca7239e5e47072a7a94fc623dadea9ffa20b8379ec950360058e917befb9bffe", "bytes": 24336, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5564b91ccb186bd507e7b3f1555c6b75514c8b603503d274ad108f4efdfd6587.mp3", "duration_ms": 4000}, "s1-red-flags.hint.1": {"url": "http://localhost:4006/files/lesson-audio/481c1b5f024b2e6acdb6ba4ecaf2abf3bd11830d4d6cc92a0aabe178afb2ac33.mp3", "hash": "35dd09be679c814f489a78b4cfec9a71f10b9befe529a07dcf2344ada70468e2", "bytes": 18576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/481c1b5f024b2e6acdb6ba4ecaf2abf3bd11830d4d6cc92a0aabe178afb2ac33.mp3", "duration_ms": 3040}, "s1-red-flags.prompt": {"url": "http://localhost:4006/files/lesson-audio/61edffc3c4417a50932140d916426a62bf3cbea7ef8f041c975c74f1783a6b80.mp3", "hash": "302508e3be5f49feaf8fa7de28f641aaa0ca6c20ee2339574e9c5e31127353e0", "bytes": 101664, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/61edffc3c4417a50932140d916426a62bf3cbea7ef8f041c975c74f1783a6b80.mp3", "duration_ms": 16880}, "s1-red-flags.explanation": {"url": "http://localhost:4006/files/lesson-audio/b17ea8c09bdd5c00b4a7ca2fe829f1e9e8570b9555ee558431948fb0e6c2c048.mp3", "hash": "e9c11b009d95f68f002fb2bef7f3d038cf15ec862d81b019360454236e8d7ef7", "bytes": 46368, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b17ea8c09bdd5c00b4a7ca2fe829f1e9e8570b9555ee558431948fb0e6c2c048.mp3", "duration_ms": 7680}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "evidence-hunt", "title": "Caça à evidência: o recibo do mercado", "locale": "pt-BR", "subject": "mixed", "objectives": ["Procurar no recibo do mercado a evidência exata de quanto custaram os limões"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 10, "type": "evidence_hunt", "hints": ["Procure no recibo a linha que diz ''limões''.", "Preste atenção no número ao lado de ''limões''."], "title": "O recibo amassado", "payload": {"claim_md": "Liruf diz: ''Gastei 20 pesos em limões.''", "sentences": [{"id": "s1", "text_md": "Limões: 15 pesos"}, {"id": "s2", "text_md": "Açúcar: 10 pesos"}, {"id": "s3", "text_md": "Total: 25 pesos"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Na semana passada você viu em um gráfico qual foi o melhor dia de vendas de limonada. Hoje, Liruf precisa de você: ele comprou limões e açúcar para fazer mais limonada, mas perdeu a conta. Só tem este recibo amassado. Ele diz: ''Gastei 20 pesos em limões.'' Mas o recibo diz outra coisa. Quanto custaram realmente os limões? Ajude Liruf a encontrar a evidência exata no recibo. Escolha a linha do recibo que mostra o custo real dos limões.", "difficulty": 1, "explanation_md": "O recibo mostra que os limões custaram 15 pesos, não 20. Liruf se enganou ao lembrar. A evidência está na linha ''Limões: 15 pesos''.", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1"]}}', '{"units": {"s1-evidence-hunt.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1ffda0d5cd615153142a5975437cab90fcc31d56cf2a56ac42e040273eecd438.mp3", "hash": "85d6c861c3179352bd51ba5422a2afbf0a76bd9fd13f64b9c6dbcdbfa087a53f", "bytes": 19008, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1ffda0d5cd615153142a5975437cab90fcc31d56cf2a56ac42e040273eecd438.mp3", "duration_ms": 3120}, "s1-evidence-hunt.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a07b65e38b610946d1aee1847357ff965f41f50061aed306ab0406310ece8dfe.mp3", "hash": "b58b73e96116e095fe955100082f164edce17259c489b99e4ad25360de1317ab", "bytes": 19584, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a07b65e38b610946d1aee1847357ff965f41f50061aed306ab0406310ece8dfe.mp3", "duration_ms": 3200}, "s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/31f4bf2e78765c5fa21099fe75dce8c4c8d17b50b7f59b3d41305252cb25cc68.mp3", "hash": "95f9fba38cd62d133ee73c9ef79b4c0ef41ea89199c32712ea2cecfa982e7898", "bytes": 196128, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/31f4bf2e78765c5fa21099fe75dce8c4c8d17b50b7f59b3d41305252cb25cc68.mp3", "duration_ms": 32640}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/5f0fdb137d59d9407d1105d1aa0881cf7ff1935d042e90d87abf27f611d89eff.mp3", "hash": "180350e754a648b8bf0e8dc9ef2920d4648ef419f7cace9f8091dc1215aadc07", "bytes": 66528, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5f0fdb137d59d9407d1105d1aa0881cf7ff1935d042e90d87abf27f611d89eff.mp3", "duration_ms": 11040}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "best-decision", "title": "A melhor decisão ao receber troco", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher a melhor decisão quando um cliente paga com nota de 20 por um copo de 5: contar o troco com calma"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-best-decision", "xp": 10, "type": "best_decision", "hints": ["Pense: se você pagou com 20 e custa 5, quanto devem te devolver?", "Vale mais a pena contar com calma ou adivinhar o troco?"], "title": "O troco de Liruf", "payload": {"options": [{"id": "contar", "text_md": "Contar o troco com calma: dar 15 reais", "rationale_md": "É a melhor decisão porque assim Liruf dá o troco exato e não se engana."}, {"id": "adivinar", "text_md": "Adivinhar o troco e dar 10 reais", "rationale_md": "Adivinhar pode fazer com que você dê menos troco e a cliente fique irritada, ou que dê mais e perca dinheiro."}, {"id": "quedarse", "text_md": "Dar troco rápido sem contar, apenas 5 reais", "rationale_md": "Dar troco rápido sem contar pode fazer com que você dê menos do que deve, e a cliente iria embora irritada."}], "scenario_md": "Liruf está em sua barraca de limonada. Uma cliente lhe dá uma nota de 20 reais por um copo de 5 reais. Liruf fica nervoso porque é a primeira vez que recebe uma nota grande. Ele lembra que os ingredientes custaram dinheiro, então precisa cuidar de seus lucros."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Agora que você sabe quais ingredientes custam dinheiro, Liruf já vendeu seu primeiro copo. Uma cliente paga com uma nota de 20 reais por um copo de 5 reais. O que Liruf deveria fazer para não perder dinheiro nem irritar a cliente?", "difficulty": 1, "explanation_md": "Liruf deve contar o troco com calma: 20 menos 5 são 15 reais. Assim ele garante dar o valor correto e não perder dinheiro. Se ele adivinhar, pode dar menos e a cliente ficaria irritada, ou dar mais e perder lucro.", "audio_segment_id": "s1-best-decision.prompt"}], "schema_version": 1}', '{"s1-best-decision": {"qualities": {"contar": 100, "adivinar": 30, "quedarse": 0}}}', '{"units": {"s1-best-decision.hint.0": {"url": "http://localhost:4006/files/lesson-audio/bae89011bdc96872d6659ee690530c48bde9697f46810be09265488e0f0181f5.mp3", "hash": "f2e0888e635ad162c26b1fdc1e7dc5c1a19e23766d0783503e3c80eeff0de2ec", "bytes": 29664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/bae89011bdc96872d6659ee690530c48bde9697f46810be09265488e0f0181f5.mp3", "duration_ms": 4880}, "s1-best-decision.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6fceb8d6e6edc8146cd99efdd5d3a73caf49c1eedcd955c6ab0b2d42950a5e77.mp3", "hash": "9da93759cea7fa9afa6f2cf2522329cf0b4197123211ccf4481a85c49702d9fb", "bytes": 22896, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6fceb8d6e6edc8146cd99efdd5d3a73caf49c1eedcd955c6ab0b2d42950a5e77.mp3", "duration_ms": 3760}, "s1-best-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/6d9636a153f275a7e876e845a1ba1965a6867e570fdf9f27cdfed7d20ac474e3.mp3", "hash": "9c4cb166182e84d99396b348aa53d3e079a0802a800c6b82dc6479ac1d28b5c3", "bytes": 95328, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6d9636a153f275a7e876e845a1ba1965a6867e570fdf9f27cdfed7d20ac474e3.mp3", "duration_ms": 15840}, "s1-best-decision.choices": {"url": "http://localhost:4006/files/lesson-audio/740c2fe370e621c827f56bfe51f24d33cf0fd003bb7b97d8765fb0de4813d125.mp3", "hash": "3347336b3a3ebdd53b13141a3c7c27a8d1c5741bd2e21b3a9e41e39ee6578473", "bytes": 64224, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/740c2fe370e621c827f56bfe51f24d33cf0fd003bb7b97d8765fb0de4813d125.mp3", "duration_ms": 10640}, "s1-best-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/8c0a6a02122e31e83c6bd03678a5caf9ee24dfcf6ced00fb074194179ef7e26f.mp3", "hash": "725febbc5da7b123d295abd0dc8e79a8fb3f94effadd190025e1d25ad7728d54", "bytes": 91584, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8c0a6a02122e31e83c6bd03678a5caf9ee24dfcf6ced00fb074194179ef7e26f.mp3", "duration_ms": 15200}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'en-US', '1', '{"meta": {"cast": ["rho"], "slug": "rank-choices", "title": "Order your purchases", "locale": "en-US", "subject": "mixed", "objectives": ["Order from most to least urgent what to spend today''s profit on: restock lemons first, then cups, and decorations last."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-compras", "xp": 15, "type": "rank_choices", "hints": ["Think: what does the stand need to keep selling lemonade?", "Decorations are nice, but not urgent."], "title": "What to buy first?", "payload": {"items": [{"id": "limones", "text_md": "Restock lemons (cost 8 pesos)"}, {"id": "vasos", "text_md": "Buy new cups (cost 5 pesos)"}, {"id": "adornos", "text_md": "Decorations for the stand (cost 3 pesos)"}], "criterion_md": "Order from most urgent (top) to least urgent (bottom)."}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho earned 20 pesos at his lemonade stand. Help Rho decide what to buy first. Tap the expenses to order them from most urgent to least urgent.", "difficulty": 2, "explanation_md": "Rho needs lemons to make more lemonade, then cups to serve it. Decorations can wait.", "audio_segment_id": "s1-ordenar-compras.prompt"}], "schema_version": 1}', '{"s1-ordenar-compras": {"order": ["limones", "vasos", "adornos"]}}', '{"units": {"s1-ordenar-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b78adf7c57019f9a9448c1a53e45c05ee809de7ca15aede2877cf8cffe7a5c8f.mp3", "hash": "2a573185079b80af4b6297b0723d1f262897a0bbaa56c1b8d9e01107785b15c6", "bytes": 22464, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/b78adf7c57019f9a9448c1a53e45c05ee809de7ca15aede2877cf8cffe7a5c8f.mp3", "duration_ms": 3680}, "s1-ordenar-compras.hint.1": {"url": "http://localhost:4006/files/lesson-audio/4ad5fb53ac1ea3f3be28506097125c91667d4db172c1203d3f7ca9df508469a8.mp3", "hash": "9ce026e1f275208a504938f6eee10e44b54bfb921c24f7b64c500dc4c2528faf", "bytes": 17136, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/4ad5fb53ac1ea3f3be28506097125c91667d4db172c1203d3f7ca9df508469a8.mp3", "duration_ms": 2800}, "s1-ordenar-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/026a85087ab8a8000dc5f33c526f29b3d6e97d876e969425daeca272532a830c.mp3", "hash": "bea601832380ab7323364f7334dfabcd5ef7f91ee722b5984cf3a4314cf084b1", "bytes": 66096, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/026a85087ab8a8000dc5f33c526f29b3d6e97d876e969425daeca272532a830c.mp3", "duration_ms": 10960}, "s1-ordenar-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/0d35d1e52a3c41bf6a20e55671bb9e43408c41e17c2f6b7b527210fce90fb819.mp3", "hash": "fe5bfd0960ea112839f24dd95c048f1fbc850aac47bf731df17f470190daad5e", "bytes": 41184, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/0d35d1e52a3c41bf6a20e55671bb9e43408c41e17c2f6b7b527210fce90fb819.mp3", "duration_ms": 6800}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "confidence-quiz", "title": "Confidence in your accounts", "locale": "en-US", "subject": "mixed", "objectives": ["Add two glasses of lemonade (5+5) and evaluate your confidence level in the result."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confianza", "xp": 10, "type": "confidence_quiz", "hints": ["Remember: only real coins count. The bottle cap is not money.", "Count the 5-peso coins: one is 5, two are..."], "title": "How much money did you earn?", "payload": {"options": [{"id": "opt-10", "text_md": "10 pesos", "rationale_md": "You added the two 5-peso coins and knew the bottle cap doesn''t count. Correct!"}, {"id": "opt-5", "text_md": "5 pesos", "rationale_md": "Maybe you only counted one coin and forgot the other. Liruf has two 5-peso coins, not one."}, {"id": "opt-15", "text_md": "15 pesos", "rationale_md": "Maybe you counted the bottle cap as if it were a 5-peso coin. But bottle caps are not money, only real coins count."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf has two coins in his hand. One is 5 pesos, the other is 5 pesos. But among his toys there is a bottle cap that looks like a coin. How much real money does Liruf have in his hand? Then choose how sure you are of your answer.", "difficulty": 1, "explanation_md": "Liruf has two 5-peso coins, so he has 10 pesos in total. The bottle cap is not worth money, even if it looks like one. Great job not being fooled!", "audio_segment_id": "s1-confianza.prompt"}], "schema_version": 1}', '{"s1-confianza": {"correct_option_id": "opt-10"}}', '{"units": {"s1-confianza.hint.0": {"url": "http://localhost:4006/files/lesson-audio/de2d9fc658585e590a4c0be3d72f45a0828bf1f6ea80cc69f59b4799648d28cd.mp3", "hash": "369e33e3270922c15314e050ffc1a1b8e329a17f9ff61bbf403b6a4e36daf79b", "bytes": 23328, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/de2d9fc658585e590a4c0be3d72f45a0828bf1f6ea80cc69f59b4799648d28cd.mp3", "duration_ms": 3840}, "s1-confianza.hint.1": {"url": "http://localhost:4006/files/lesson-audio/92df3999edfc6baec7119fc5106d55d74c805c74bd0e39d51a61ee19a4be75a7.mp3", "hash": "de6acc9c7ffe39dca47a2ab36226a45f55f543eb7ca1cff3f76a5e305f7a49e7", "bytes": 24336, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/92df3999edfc6baec7119fc5106d55d74c805c74bd0e39d51a61ee19a4be75a7.mp3", "duration_ms": 4000}, "s1-confianza.prompt": {"url": "http://localhost:4006/files/lesson-audio/b0644d96306580aa2a07a5f0c647e92c8cf0df7955f25df09cb916cb278a95c0.mp3", "hash": "86e8c172c131ae91b8c0091de5e61248e736e81a3031095681bb338978ec206d", "bytes": 78624, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b0644d96306580aa2a07a5f0c647e92c8cf0df7955f25df09cb916cb278a95c0.mp3", "duration_ms": 13040}, "s1-confianza.choices": {"url": "http://localhost:4006/files/lesson-audio/ee07d6b15894489c3626c5b28ca22d8aa73fcf6e7402039a8d8c47503780a0fa.mp3", "hash": "4f4b389db7b48c403478af4a9728db96b9029fa4b664575baab651e0b9eee14a", "bytes": 21456, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ee07d6b15894489c3626c5b28ca22d8aa73fcf6e7402039a8d8c47503780a0fa.mp3", "duration_ms": 3520}, "s1-confianza.explanation": {"url": "http://localhost:4006/files/lesson-audio/38dd8a525803badae710370a327750411ef9cfa601c8a82dfe4b74bf70457ee8.mp3", "hash": "687888fdc4fdced43c42eb72b274f908463e748977711b9b7635bc8615d28298", "bytes": 53136, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/38dd8a525803badae710370a327750411ef9cfa601c8a82dfe4b74bf70457ee8.mp3", "duration_ms": 8800}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "dialogue-choice", "title": "¿Me lo dejas en 3?", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir una respuesta amable pero firme ante un cliente que pide rebaja, sin regalar la ganancia."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-negocia-cliente", "xp": 15, "type": "dialogue_choice", "hints": ["Piensa: si le bajas mucho el precio, ¿cuánto ganas por vaso?", "El cliente se va contento si le ofreces algo justo, pero sin perder dinero."], "title": "El cliente pide rebaja", "payload": {"turns": [{"id": "t1", "npc_md": "—Hola, Liruf. ¿Me vendes un vaso de limonada? Pero… ¿me lo dejas en 3 pesos?", "replies": [{"id": "r1", "text_md": "—Claro, tómalo por 3 pesos."}, {"id": "r2", "text_md": "—Lo siento, el precio es 5 pesos. Pero puedo ofrecerte un vaso más pequeño por 4 pesos."}, {"id": "r3", "text_md": "—No, el precio es 5 pesos, ni un peso menos."}]}, {"id": "t2", "npc_md": "El cliente piensa un momento y responde:", "replies": [{"id": "r4", "text_md": "—Está bien, me llevo el vaso de 4 pesos. ¡Gracias!"}, {"id": "r5", "text_md": "—No, gracias, es muy caro. Me voy."}, {"id": "r6", "text_md": "—Está bien, me llevo el vaso de 4 pesos. ¡Gracias!"}]}], "persona": {"name": "Liruf", "role_md": "dueño del puesto de limonada", "character": "liruf"}, "opening_md": "Estás en tu puesto. Un cliente sonríe y dice:"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf está atendiendo su puesto de limonada. Un cliente se acerca y dice:", "difficulty": 2, "explanation_md": "Liruf ofreció un vaso a 5 pesos. Si lo deja en 3, gana solo 3 pesos, pero si ofrece 4, el cliente ahorra 1 peso y Liruf aún gana 4. ¡Todos ganan!", "audio_segment_id": "s1-negocia-cliente.prompt"}], "schema_version": 1}', '{"s1-negocia-cliente": {"turns": [{"turn_id": "t1", "qualities": {"r1": 20, "r2": 90, "r3": 30}, "reactions": {"r1": "El cliente se va feliz, pero Liruf ganó solo 3 pesos. Perdió 2 pesos de ganancia.", "r2": "El cliente duda, pero acepta la oferta. ¡Buen trato!", "r3": "El cliente se ofende y se va sin comprar. Liruf no vende nada."}}, {"turn_id": "t2", "qualities": {"r4": 100, "r5": 0, "r6": 100}, "reactions": {"r4": "¡Vendiste un vaso! Ganaste 4 pesos y el cliente se fue contento.", "r5": "El cliente se fue. No hubo venta. Tal vez otra oferta funcione mejor.", "r6": "¡Vendiste un vaso! Ganaste 4 pesos y el cliente se fue contento."}}]}}', '{"units": {"s1-negocia-cliente.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d604cb7a485ec88c12c8c81d787df1636b10ab7f64b7dd65343fbb9dc1a64adf.mp3", "hash": "c2d8ce4d48a3d8447792eea4a8d8e4f5cab21a38c521c4bb44fcc24417ca959a", "bytes": 27648, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d604cb7a485ec88c12c8c81d787df1636b10ab7f64b7dd65343fbb9dc1a64adf.mp3", "duration_ms": 4560}, "s1-negocia-cliente.hint.1": {"url": "http://localhost:4006/files/lesson-audio/218fb0e148c6f1fa02f77b4ddfb887e873700bd4907d78848227602baf5fc31b.mp3", "hash": "a37f723f0d7f63aab60cc25b9e0ffb4ca70df758fc23a4acc609820fdc89f2f0", "bytes": 30528, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/218fb0e148c6f1fa02f77b4ddfb887e873700bd4907d78848227602baf5fc31b.mp3", "duration_ms": 5040}, "s1-negocia-cliente.prompt": {"url": "http://localhost:4006/files/lesson-audio/129494778530a4daf561e4dfaeb60672e49cc0058c12b9795f6b738e46fa8c1d.mp3", "hash": "372c69f63b1ccc4be944190844c206a8e2351a6141e50acf17cb007381c76b18", "bytes": 30528, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/129494778530a4daf561e4dfaeb60672e49cc0058c12b9795f6b738e46fa8c1d.mp3", "duration_ms": 5040}, "s1-negocia-cliente.explanation": {"url": "http://localhost:4006/files/lesson-audio/294091bd1e3ede698b29b42d27657efb51cd14e47ebf6204a6949e722f9b15b9.mp3", "hash": "f02c1e7bad4d916cbcdd47cb72e3fc6ea0393a92a580121e622758d182253136", "bytes": 71424, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/294091bd1e3ede698b29b42d27657efb51cd14e47ebf6204a6949e722f9b15b9.mp3", "duration_ms": 11840}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'en-US', '1', E'{"meta": {"cast": ["dina"], "slug": "would-you-rather", "title": "Live the stand in playable stories", "locale": "en-US", "subject": "mixed", "objectives": ["Choose between two seller paths and defend it: earn 10 pesos today or 20 next week? There''s no single answer, there are reasons."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-would-you-rather", "xp": 0, "type": "would_you_rather", "hints": ["Calculate how much money each plan gives. Which one gives you enough for the skateboard?"], "title": "Earn today or tomorrow?", "payload": {"a": {"icon": "local_cafe", "text_md": "Plan A: sell 3 cups today at $5 each"}, "b": {"icon": "calendar_month", "text_md": "Plan B: wait a week and sell 6 cups at $4 each"}, "followup_md": "Why did you choose that plan? Tell Dina your reason."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Yesterday you counted cups and change. Today Dina has two plans for her lemonade stand:\\n\\n**Plan A:** Sell 3 cups TODAY at $5 each. Quick money!\\n**Plan B:** Prepare 6 cups for next week at $4 each. More money, but you have to wait.\\n\\nDina wants to buy a skateboard that costs $20. Which plan gets her closer to her goal?", "difficulty": 1, "explanation_md": "Plan A gives $15, which is not enough for the $20 skateboard. Plan B gives $24, which is enough and even leaves extra. Dina chooses Plan B because it gets her closer to her goal.", "audio_segment_id": "s1-would-you-rather.prompt"}], "schema_version": 1}', '{"s1-would-you-rather": {"qualities": {"a": 0, "b": 100}, "reveal_md": "Dina sonríe: «¡Bien pensado! Usaste lo que aprendiste ayer de sumar vasos. El Plan B da $24, justo para la patineta. Si elegiste el Plan A, recuerda que $15 no alcanzan para la patineta; necesitas $5 más.»"}}', '{"units": {"s1-would-you-rather.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4f9a63e914dfb7e887c9727f3a81a6c5c081ef9d71ff8179de3bc69322f0cc8d.mp3", "hash": "9ff177929dfb10e01a04d2a3d7dc4c86c020f27575600a8922d335a83b596553", "bytes": 30096, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4f9a63e914dfb7e887c9727f3a81a6c5c081ef9d71ff8179de3bc69322f0cc8d.mp3", "duration_ms": 4960}, "s1-would-you-rather.prompt": {"url": "http://localhost:4006/files/lesson-audio/e7a6a2f314772b6857f509cecb3d2ba6ef3ca17dfbcef99fbfa61eebdd300305.mp3", "hash": "0dc1be6d726b00ea8e7dc1f5ad5e529f077c226895a89b5d0becccc933d51903", "bytes": 118368, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e7a6a2f314772b6857f509cecb3d2ba6ef3ca17dfbcef99fbfa61eebdd300305.mp3", "duration_ms": 19680}, "s1-would-you-rather.choices": {"url": "http://localhost:4006/files/lesson-audio/d866a20de2208ae522ad41a5e86b9318d29ad17fe69ce3d8d9f666cd756243c4.mp3", "hash": "cf355dc98fe4318ca0f6979abbb36970af5827a0074f63540459696a1950f03a", "bytes": 44064, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d866a20de2208ae522ad41a5e86b9318d29ad17fe69ce3d8d9f666cd756243c4.mp3", "duration_ms": 7280}, "s1-would-you-rather.explanation": {"url": "http://localhost:4006/files/lesson-audio/65471d18cafc92b22ef2f3e879b00826a63809d980c8084dffc42d4a28e041bc.mp3", "hash": "54953bb3b6f53d22e22b4d0059d106eb9ef0b9ebc0f0851ef2f481286b5b26ea", "bytes": 66096, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/65471d18cafc92b22ef2f3e879b00826a63809d980c8084dffc42d4a28e041bc.mp3", "duration_ms": 10960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
